local Text_Voice = readonly({
  Voice_100335_AwakerVoiceContent = {
    Text = "ผู้พิทักษ์ สอบถามหน่อยว่าฉันจะไปชมสุสานของวิทยาลัยได้เมื่อไหร่? ที่นั่นมีวิญญาณอันยิ่งใหญ่ที่ฝังอยู่ ซึ่งจะมอบแรงบันดาลใจที่ไม่ธรรมดาให้กับฉัน! โปรดมั่นใจว่าฉันจะไม่ขุดศพเหล่านั้นขึ้นมาเพื่อดูอย่างใกล้ชิดอีก..."
  },
  Voice_100335_AwakerVoiceTitle = {
    Text = "พูดคุย: เกี่ยวกับนางแบบ"
  },
  Voice_100336_AwakerVoiceContent = {
    Text = "เดี๋ยวก่อน! ฉันนึกวิธีการแสดงออกใหม่ขึ้นมา จะต้องทำให้วงการศิลปะตกตะลึงแน่นอน!"
  },
  Voice_100336_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_100337_AwakerVoiceContent = {
    Text = "ฉันคือแสงและเงา ฉันคือสี ฉันคือ... การวาดภาพเอง!"
  },
  Voice_100337_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_100338_AwakerVoiceContent = {
    Text = "แค่...มันเป็นสีที่ฉันไม่เคยเห็นมาก่อน ส่องสว่างอยู่ในโลกจิตวิญญาณของคุณ...มันคืออะไร..."
  },
  Voice_100338_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_100338_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_100339_AwakerVoiceContent = {
    Text = "สีดำที่เยี่ยมยอด! ฉันเคยรวบรวมของเหลวการย่อยสลายมากมายเพื่อวาดภาพ,      อย่างไรก็ตามผลงานเหล่านั้นหายไปทั้งหมด สีจากจักรวาลดั้งเดิม,      ทุกภาพจะถูกกลืนกิน,      ไม่ได้ถูกจำไว้โดยใคร...ยอดเยี่ยมไม่ใช่เหรอ?!"
  },
  Voice_100339_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_100340_AwakerVoiceContent = {
    Text = "ให้ฉันเข้าใกล้...ให้ฉันดูมากกว่านี้! แสงเงาเหล่านี้ สีสันเหล่านี้ ท่าทางเหล่านี้... เมื่อเปรียบเทียบกับสิ่งเหล่านี้ สิ่งที่ฉันวาดเมื่อก่อนล้วนเป็นเศษกระดาษ..."
  },
  Voice_100340_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_100340_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_100341_AwakerVoiceContent = {
    Text = "ดูเล่เซลมักจะบอกฉันว่าอาหารของเขามีศิลปะขนาดไหน ให้ฉันดู, การกินกับศิลปะนั้นไม่เกี่ยวข้องกันเลย! ต้องเสียเวลาที่มีค่าที่จะทำงานที่ซับซ้อนพวกนั้น, ใช้เวลานานในการสร้างอาหารที่มีรูปลักษณ์และรสชาติที่ดี และยังต้องกัดและกลืนมันลงไป! มันถือเป็นอาชญากรรมต่อศิลปะ!"
  },
  Voice_100341_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_100342_AwakerVoiceContent = {
    Text = "อืม..."
  },
  Voice_100342_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_100343_AwakerVoiceContent = {
    Text = "นางแบบที่เลวร้าย..."
  },
  Voice_100343_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_100344_AwakerVoiceContent = {
    Text = "ไม่ได้ไม่ได้ อีกแล้วเป็นผลงานที่น่าห่วย... ต้องไปหาความแรงบันดาลใจที่ไหนนะ พื้นที่ฝังศพ? หรือสนามประหาร..."
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "แม้ว่าฉันคิดว่ารูปแบบศิลปะการแกะสลักนี้ค่อนข้างแข็งและเก่า แต่ช่างแกะสลักที่ชื่อว่า ซังก้า,     มีมีดแกะของเธอสามารถมีการแสดงออกที่เกินกว่าที่รูปแบบศิลปะนี้จะรับรองได้...จริงๆ เป็นอัจฉริยะที่หาได้ยาก！"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "พูดคุย: เกี่ยวกับส่งกา"
  },
  Voice_100345_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างกายที่ตื่นขึ้น「ซาน」"
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "เคยเห็นภาพนี้ไหม ผู้พิทักษ์? นี่คือภาพเหมือนของคุณที่ฉันวาด ดูคุณที่กำลังเคี้ยวชิ้นเนื้อ ดูน่าหลงใหลมาก! ฉันรู้ ว่าคนไม่ใช่ทุกคนที่สามารถเข้าใจผลงานของฉัน แต่ความงามบ้าคลั่งในภาพนี้ คุณต้องได้สัมผัสถึงมันใช่ไหม?! สำหรับฉัน นี่ถือเป็นสิ่งที่เพียงพอและสมบูรณ์แบบแล้ว..."
  },
  Voice_100346_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_100346_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "คุณเพิ่งกล่าวว่าต้องการซื้อภาพนี้... เป็นความจริงเหรอ?! ขอบคุณครับ ผู้พิทักษ์! มีคนเพียงไม่กี่คนที่สามารถชื่นชมสิ่งเหล่านี้..."
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_100347_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_100348_AwakerVoiceContent = {
    Text = "ผู้พิทักษ์ คุณยังมีเวลามาเป็นนางแบบให้ฉันอยู่หรือเปล่า? เทียบกับภาพที่เห็นบนตัวคุณครั้งก่อน นางแบบคนอื่นๆ ล้วนเป็นการเสียเวลาของฉัน..."
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "ในภาพวาดนี้, เห็นการเกิดใหม่!"
  },
  Voice_100349_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_100350_AwakerVoiceContent = {
    Text = "ดูเส้นสายที่มีชีวิตชีวานี้!"
  },
  Voice_100350_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_100351_AwakerVoiceContent = {
    Text = "ฉันมีความรู้สึกว่าสิ่งที่สร้างขึ้นโดยแปรงนี้จะทำให้ทุกคนประหลาดใจ!"
  },
  Voice_100351_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_100352_AwakerVoiceContent = {
    Text = "อ๊ะ！สีใหม่ที่น่าตื่นเต้น......ฉันจะทามันในตำแหน่งที่เหมาะสมที่สุด!"
  },
  Voice_100352_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_100353_AwakerVoiceContent = {
    Text = "นี่คือสถานที่ที่ทำให้แรงบันดาลใจพลุ่งพล่าน! ฉันมีความคิดสร้างสรรค์ใหม่ๆ คุณผู้พิทักษ์ มีเวลามาที่ห้องวาดภาพของฉันหรือเปล่า? มาเถอะ มาเถอะ!"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_100353_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "ใช่แล้ว, ใช่แล้ว! ชัยชนะที่รดน้ำด้วยเลือด! รูปแบบที่ดีเยี่ยมขนาดไหน!"
  },
  Voice_100354_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_100355_AwakerVoiceContent = {
    Text = "อืม..."
  },
  Voice_100355_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_100356_AwakerVoiceContent = {
    Text = "อา! เชิญนั่ง ผู้พิทักษ์ การเป็นนางแบบของฉันเป็นงานหนักมาก โปรดมั่นใจ ว่าฉันจะสร้างผลงานที่น่าทึ่งให้คุณได้แน่นอน"
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_100356_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "ศิลปินคนหนึ่งควรสนใจแค่ผลงานของตัวเอง ไม่ควรสนใจสายตาของคนอื่น แต่ฉันทำไม่ได้... ตั้งแต่วันแรกที่ฉันจับพู่กัน ฉันก็หวังที่จะนำความงามที่แท้จริงมาสู่ทุกคน."
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_100357_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "ที่นี่ทำให้ฉันนึกถึงเวลาที่เคยอยู่ที่วิทยาลัยศิลปะ แม้ว่าคณบดีและเพื่อนๆ ส่วนใหญ่จะเป็นคนที่ไม่เข้าใจศิลปะเลย แต่ก็จะมีบางคนที่มีปัญญา สามารถมองเห็นความงามที่ฉันเห็นจากผลงานของฉัน"
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "การแสดงที่ป่าเถื่อนนี้จะสร้างสรรค์ศิลปะที่บ้าคลั่งอะไรขึ้นมา?!!"
  },
  Voice_100359_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_100360_AwakerVoiceContent = {
    Text = "จานสีของฉัน!"
  },
  Voice_100360_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_100361_AwakerVoiceContent = {
    Text = "ความเจ็บปวดก็เป็นศิลปะ..."
  },
  Voice_100361_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_100362_AwakerVoiceContent = {
    Text = "อ๊ะ！ฉันเห็นมันแล้ว......ตาจากโลกที่ไม่มีตาที่ซ่อนอยู่ในเหวลึก สุดยอดภาพในจักรวาล ......โปรดรอสักครู่ ผู้พิทักษ์ เรากำลังจะทำมันให้สำเร็จ！"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_100362_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "แปรงของฉันทำจากกระดูกขา สีบนจานเหล่านี้คือสีที่ฉันเก็บรวบรวมจากสุสานในยี่สิบเมือง... และผ้าผิวหนังอันมีค่าของฉัน! ผู้พิทักษ์โปรดหยิบมันขึ้นมา วาดพอร์ตเทรตให้ฉันเถอะ! ไม่ ไม่ ไม่ นี่ไม่จำเป็นต้องมีทักษะการวาดภาพใดๆ... ฉันเชื่อว่าเมื่อความสั่นสะเทือนทางจิตใจนี้ปรากฏบนผืนผ้าใบ จะต้องเป็นอย่างที่ฉันไม่เคยจินตนาการมาก่อน...!"
  },
  Voice_100363_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_100363_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "ฉันคือแสงและเงา ฉันคือสี ฉันคือ... การวาดภาพเอง!"
  },
  Voice_100364_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_100365_AwakerVoiceContent = {
    Text = "ลองสีนี้ดูสิ!"
  },
  Voice_100365_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_100366_AwakerVoiceContent = {
    Text = "ธรรมชาติของศิลปะ คือ ความบ้าคลั่ง...!"
  },
  Voice_100366_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_100367_AwakerVoiceContent = {
    Text = "คุณหมายถึงว่าในครั้งถัดไปสามารถลองทำให้จุดนี้เป็นภาพใกล้ชิดได้ไหม? อืม... ฉันไม่เคยคิดถึงมันเลย! เป็นแนวคิดที่ยอดเยี่ยมจริงๆ!"
  },
  Voice_100367_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_100368_AwakerVoiceContent = {
    Text = "ระวัง!"
  },
  Voice_100368_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_100369_AwakerVoiceContent = {
    Text = "ธรรมชาติของศิลปะ คือ ความบ้าคลั่ง...!"
  },
  Voice_100369_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_100370_AwakerVoiceContent = {
    Text = "จานสีของฉัน!"
  },
  Voice_100370_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_100371_AwakerVoiceContent = {
    Text = "โอ้! ขากรรไกรที่ไหลลื่นนี้,      ดวงตาที่สว่างไสว,      รูปร่างที่สมบูรณ์แบบ,      และยัง,      ยังมีโลกจิตวิญญาณที่กว้างขวางดั่งท้องฟ้าเต็มไปด้วยดวงดาวนี้...ฉันคือจิตรกรพิคแมน,      สามารถขอเชิญคุณเป็นแบบให้กับฉันได้ไหม?"
  },
  Voice_100371_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_100372_AwakerVoiceContent = {
    Text = "แนวคิดศิลปะที่ฉันเชื่อมั่นนั้นมีความบ้าคลั่งและขี้เหร่ แตกต่างจากเสียงเพลงฮาเมลที่เคร่งครัดราวกับหลุมฝังศพที่น่าเบื่อหน่าย แต่ไม่รู้ทำไม ฉันสามารถเห็นความยุ่งเหยิงที่เข้มข้นที่สุดในจักรวาลในโน้ตที่เป็นระเบียบเหล่านั้น..."
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "พูดคุย: เกี่ยวกับฮาเมล"
  },
  Voice_100372_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างกายที่ตื่นขึ้น「แฮมลิน」"
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "ดูซิ ผู้พิทักษ์! ภาพลักษณ์แห่งความคงอยู่และความบ้าคลั่งบนผืนผ้าใบมีความน่าหลงใหลและน่าหดหู่เพียงใด! สิ่งที่บานสะพรั่งในความบ้าคลั่งและความเจ็บปวดอันสูงสุดนี้คือศิลปะเอง..."
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_100373_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "อ๊ะ！ขอโทษนะ ผู้พิทักษ์...... ฉันเห็นภาพที่ไม่เคยมีมาก่อนในตัวคุณ...... ที่น่าสยดสยองมากกว่าภายในเหวลึก ที่น่าหลงใหลกว่าภายในเหวลึก......"
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_100374_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "จริงๆ ไม่เข้าใจ หากมนุษย์มีโอกาส ทำไมถึงไม่ลองเป็นซอมบี้? ความงามอันบ้าคลั่งที่เต็มไปด้วยเลือดแบบนี้ไม่สนุกกว่าการเป็นมนุษย์ที่ไร้ไฟในบ้านหลังใหญ่หรือ?!"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_100376_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_100376_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_116964_AwakerVoiceContent = {
    Text = "ลงโทษอธรรม!"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "ลงโทษอธรรม!"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·2"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "ฉันยอมรับว่าความสามารถในการขโมยของเธอมีความสามารถ แต่คุณหญิงไม่จำเป็นต้องใช้กลเม็ดต่ำช้าแบบนี้สิ่งที่ฉันต้องการ ให้ทุกคน「สมัครใจ」มอบให้ฉันไม่ดีกว่าหรือ?"
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเจนกิน"
  },
  Voice_117791_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「เจนกิน」"
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "ฮ่าฮ่าฮ่า ขนมทั้งหมดของมีธากเป็นของฉันแล้ว! ยังรออะไรอยู่? ตามแม่มดไป, เตรียมตัวไปยึดร้านขนมในลอนเดเนียมกันเถอะ!"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_117792_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "ไม่ให้เหรอ? ถ้าอย่างนั้นแม่มดคนนี้ต้องลงมือจริงจังแล้ว!"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "คุณสงสัยว่าไส้ของลูกกวาดเหล่านี้ใส่เข้าไปอย่างไร หาไม่เจอรอยแตกหรือรูเลยนะ อยากให้คนที่ประดิษฐ์ลูกกวาดเหล่านี้ได้ไปทำงานที่ร้านอาหารมีธากทุกวันเลย ให้เขาสร้างขนมหวานใหม่ๆ ให้คุณผู้หญิง!"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_117795_AwakerVoiceContent = {
    Text = "คุณทำให้แม่มดโกรธ!"
  },
  Voice_117795_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_117796_AwakerVoiceContent = {
    Text = "ก่อนหน้านี้คิดว่า ขนมหวานน่ารักเกินไปเมื่อเทียบกับเค้ก ตอนนี้ดูเหมือนว่าฉันประเมินค่าของพวกมันต่ำไปนะ ที่อยู่ในพลาสติกหลากสีสันเหล่านั้น โดยเฉพาะเมื่อเปรียบเทียบกับเค้ก ขนมหวานสามารถเก็บได้นานกว่า นึกอยากจะเก็บมากเท่าไหร่ก็ไม่กลัวจะเสีย อยากจะซ้อนให้เต็มทั้งบ้านเลย!"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "คุณเจอลูกกวาดใหม่เหรอ? ให้ฉันดูหน่อย... อะไรเหรอ แหวนลูกกวาดนี่ดูตลกเกินไปนะ มีแหวนอัญมณีใหญ่ขนาดไข่ไก่ได้ไง! เดี๋ยวนะ ทำไมคุณถึงส่งแหวนให้ฉัน? อธิบายให้ชัดเจนหน่อย!"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_117797_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "ได้ยินว่าปีศาจมักมีแมวดำลึกลับอยู่ข้างๆ การเลือกแมวป่าในมหาวิทยาลัยค่อนข้างทำให้เสียเกียรติของผู้หญิงมาก ตัดสินใจแล้ว ให้เธอสวมที่คาดผมแมว เพื่อทำตัวเป็นแมวดำตัวน้อยของฉันเถอะ"
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_117798_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "การต่อต้านไม่มีประโยชน์."
  },
  Voice_117799_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_117800_AwakerVoiceContent = {
    Text = "นิดหน่อย!"
  },
  Voice_117800_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_117801_AwakerVoiceContent = {
    Text = "โลกมีแม่มดอยู่จริงไหม?พวกเธออาศัยอยู่ในป่าไม่มีคนแสงใดสิ่งใดเหลืออยู่เลย ใครจะทำอาหารหรือซักผ้าให้แม่มดได้?ถ้าไม่ได้กินน้ำชาช่วงบ่ายละ ชีวิตแบบนี้ไม่มีความหมาย แน่นอนว่าเสียใจกับมันมากทีเดียว."
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_117801_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "แม่มดมาแล้ว!"
  },
  Voice_117802_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_117803_AwakerVoiceContent = {
    Text = "คุณยังมีช็อคโกแลตในมือเหรอ? ดีเลย เอามาให้ฉันทั้งหมดเลย มีอะไรเหรอ? ของของคุณคือของของฉัน นี่ไม่ใช่เรื่องธรรมดาหรือ?"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_117803_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "คุณถามว่าฉันชอบขนมชนิดไหนมากที่สุด? ขอให้ฉันคิดก่อน, ขนมถั่วเฮเซลนัทรสอร่อยหวานหอม, ช็อกโกแลตคาราเมลก็อร่อย, เยลลี่สตรอเบอรี่และองุ่นมีรสสัมผัสที่น่าสนใจ, ยังมีมอลต์ที่ยาวมากมีสีเหมือนน้ำผึ้ง... ไม่ได้, เลือกไม่ถูก, ขนมแต่ละชนิดมีเอกลักษณ์ของตัวเอง, ตะกร้าฟักทองมีเยอะอยู่แล้ว, ฉันจะเอาทั้งหมด!"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_117804_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "เป้าหมายในชีวิตตอนนี้คือการชิมลูกกวาดทุกชนิดในโลก เพียงแค่คิดว่ามีลูกกวาดหลากหลายชนิดรอคอยอยู่ ฉันก็รู้สึกมีพลังในการตื่นเช้าในทุกวัน คุณพูดถึงเค้ก? เค้กคืออีกหนึ่งเป้าหมายในชีวิตของฉัน."
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_117805_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "อย่ามองว่าเขาหน้าตาเหมือนเด็ก แต่จริงๆ เขาอายุเยอะจนแทบจะเข้าหลุมแล้ว และไม่เอื้ออาทรต่อสิ่งที่คนมีชีวิตทุกคนชอบ ดังนั้น แทนที่จะให้ลูกกวาดที่คุณควรจะให้เขา ไม่ดีกว่าหรอถ้าส่งมันให้ฉันทั้งหมด ฉันคือคนที่ไม่ทำให้มันผิดหวังแน่นอน"
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับตูรู"
  },
  Voice_117806_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ตูรู」"
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "ถ้าฉันเป็นแม่มด ฉันจะต้องเป็นแม่มดที่อาศัยอยู่ในพระราชวังหรูหรา ในนั้นจะต้องมีความคึกคัก และหาทำอาหารที่ดีที่สุดสิบคนทำเค้กและลูกกวาดที่แตกต่างกันทุกวันสำหรับฉัน...คุณพูดว่าเรียกว่าเจ้าหญิงเหรอ? ทำไม ฉันสามารถเป็นเจ้าหญิงแม่มดได้นี่!"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_117807_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "เฮ้ เตรียมยาสีฟันหลายๆ อย่างไว้ให้ฉัน ไม่ ฉันไม่ได้กินลูกกวาดมากมาย ฉันไม่มีฟันผุ แค่รู้สึกเจ็บนิดหน่อยตอนนอนตอนกลางคืน..."
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "สนทนา·เกี่ยวกับขนม"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "แม้ว่ากฎของร้านอาหารมีธากจะทำให้ขุ่นเคืองบ่อย แต่ฝีมือการทำขนมหวานของพวกเขา เอ่อ...ก็ยังสามารถพอใช้ได้อยู่"
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "ในโลกนี้มีที่มืดมิดและน่าขนลุกมากมาย มีเวลาให้กังวลเกี่ยวกับการทำลายโลก น่าจะรีบกินขนมให้เยอะๆ ก่อนหน้าจะถึงเวลานั้น"
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_117811_AwakerVoiceContent = {
    Text = "โอ้! ปวดมาก!"
  },
  Voice_117811_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_117812_AwakerVoiceContent = {
    Text = "แม้จะไม่มีพรมขนแกะนั้น, สร้อยคอไข่มุกสีดำจากน่านน้ำไกล, ชุดเครื่องนอนจากเส้นไหมตะวันออก แต่ทุกวันตื่นขึ้นในห้องที่เต็มไปด้วยลูกอม และเข้าถึงตะกร้าฟักทองเต็มไปหมด อาจเป็นชีวิตที่มีความสุขที่ควรจะเป็น... หนอย, อย่าหัวเราะอย่างภูมิใจ ต้องรับใช้ฉันตลอดไป, คุณยังต้องพยายามต่อไป!"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_117812_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "มีธากที่น่ารังเกียจ กล้าขัดขวางฉันจากการหยิบลูกกวาด ยังไง มันไม่ถูกกินไปแล้วหรือ?"
  },
  Voice_117813_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_117814_AwakerVoiceContent = {
    Text = "ทำอะไร? อยากกินขนมของฉันไหม? ฮึฮึ, ไม่ใช่แพร่ ๆ ให้ แต่ก็พอมีเมตตาให้นิดหน่อยก็ได้ มาเลย, เรียกฉันว่าแม่มดที่เคารพสักครั้ง!"
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "นี่ไม่สามารถเรียกว่าโจรได้! ฉันเพียงแค่ใช้สิทธิอันทรงเกียรติของหญิงสาว"
  },
  Voice_117815_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_117816_AwakerVoiceContent = {
    Text = "แม่มดลูกอมแห่งความยุติธรรมมาถึงแล้ว ลูกอมที่เสียไปทั้งหมดควรกลับไปยังที่ที่ควรเป็น!"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "น่ารำคาญ ช่างขี้เหนียว ผู้หญิงแม่มดจะจดจำเธอ..."
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "ทำไมหนูตัวเล็กนั้นถึงสามารถเดินอย่างภาคภูมิใจในการค้นหาลูกกวาดได้ แต่ฉันกลับทำไม่ได้? นี่มันการเลือกปฏิบัติต่อคุณผู้หญิง! หมายถึงไม่เคารพ!"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "ไม่ให้เหรอ? ถ้าอย่างนั้นแม่มดคนนี้ต้องลงมือจริงจังแล้ว!"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "ฉันจะเลี้ยงขนมให้นะ!"
  },
  Voice_117820_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_117821_AwakerVoiceContent = {
    Text = "เมื่อเปรียบเทียบกับบริกรในร้านอาหารพวกนั้น คุณก็เข้าใจฉันได้ดีที่สุด รู้ว่าควรเตรียมขนมสำหรับฉันโดยเฉพาะ ทำแบบนี้ต่อไปนะ ผู้รับใช้เฉพาะของฉัน"
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_117821_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_117822_AwakerVoiceContent = {
    Text = "นิดหน่อย!"
  },
  Voice_117822_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_117823_AwakerVoiceContent = {
    Text = "เกินไปแล้ว!"
  },
  Voice_117823_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_117824_AwakerVoiceContent = {
    Text = "ทำไมคุณถึงมากั้นฉันในนี้? ในฐานะคนรับใช้ที่ซื่อสัตย์ของคุณ คุณไม่ควรช่วยฉันเอาลูกกวาดทั้งหมดมา...มาเถอะ?"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "หยุด! ปล้น! ขอโทษที ฉันขอแนะนำให้คุณรู้จักว่าควรเอาใจใส่บ้าง เก็บลูกอมทั้งหมดไว้ให้ดี ไม่เช่นนั้น ฮึ ฮึ..."
  },
  Voice_117825_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_117826_AwakerVoiceContent = {
    Text = "นุ่มๆ แข็งๆ เปราะๆ กรอบๆ รสช็อคโกแลต รสให้นม รสผลไม้ รสถั่ว...อ้า ทำไมโลกนี้ถึงมีขนมมากมายที่ฉันยังไม่เคยกิน? ตัดสินใจแล้ว ขอเสนอให้มีวันสหัสวรรษสัปดาห์ละครั้งกับมีธาก!"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_117827_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_117827_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_117828_AwakerVoiceContent = {
    Text = "แม่มดที่ยิ่งใหญ่จะต้องชนะ! พระเจ้าแห่งลูกกวาดอวยพรให้ฉัน ส่วนฉันจะอวยพรให้ลูกกวาดทั้งหมด! อะฮาฮาฮา!"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "การต่อต้านไม่มีประโยชน์."
  },
  Voice_117829_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_117830_AwakerVoiceContent = {
    Text = "ขนมหวานทั้งหมดจะต้องเป็นของฉัน!"
  },
  Voice_117830_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_117831_AwakerVoiceContent = {
    Text = "เด็กคนนั้นเชื่อฟังมากเกินไป แค่ขอขนมก็ให้มา ไม่ได้เก็บไว้กินเองเลย ทำให้รู้สึกแปลกใจ...อะแฮม, คือว่า ในเมื่อเธอมีความเข้าใจถึงขนาดนี้ แม่มดใจดีแน่นอนต้องทิ้งรางวัลให้เธอสักหน่อย"
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับลิลลี่"
  },
  Voice_117831_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「ลิลลี่」"
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "คุณทำให้แม่มดโกรธ!"
  },
  Voice_117832_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_117833_AwakerVoiceContent = {
    Text = "ฉันโกรธแล้ว!"
  },
  Voice_117833_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_117834_AwakerVoiceContent = {
    Text = "ขนมหวานทั้งหมดจะต้องเป็นของฉัน!"
  },
  Voice_117834_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_117835_AwakerVoiceContent = {
    Text = "คุณพูดว่า ลูกกวาดเหนียวนี้สามารถอบได้เหรอ? เอ๊ะ อุ่นและเหนียวแบบนี้จะอร่อยไหม? ให้ฉันลองหน่อย? อ๊ะ! เพราะฉะนั้นฉันจะลองสักคำ ถ้าคุณกล้าหลอกฉัน... อืม?! ความรู้สึกนุ่มนวลแบบนี้อร่อยมากเลยนะ!"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_117835_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "ความว่างเปล่า ความผิดเพี้ยน ทั้งหมดคือชะตากรรม!"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "ความว่างเปล่า ความผิดเพี้ยน ทั้งหมดคือชะตากรรม!"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "เพราะเคยเผชิญหน้ากับความสยองขวัญที่แท้จริง จึงไม่กลัวตัวตนที่แท้จริงของฉัน? ฮึ่ย เป็นคำตอบที่เจ้าเล่ห์จริงๆ แต่ก็ทำให้ฉัน... อยากรู้เกี่ยวกับคุณมากขึ้นเรื่อยๆ."
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_123312_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "โลกในตาของคุณเป็นอย่างไร? ขีดจำกัดที่น่ากลัวเหล่านั้นอยู่ที่ไหน? ไม่ ฉันไม่อยากฟังคุณเล่า ฉันอยากไปสัมผัสกับคุณ สัมผัสความบ้าคลั่ง ความตาย และความสยองขวัญ ฉันตัดสินใจแล้ว! ก่อนที่จะตอบสนองความอยากรู้ ฉันจะไม่ไปไหนจากคุณ."
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_123313_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "คนบ้าที่ไม่สามารถควบคุมได้? คุณพูดถูก ที่นี่ไม่ใช่โลกของฉัน ไม่มีข้อกฎหมายและกฎระเบียบที่น่าเบื่อ... ที่นี่ ฉันจะทำอะไรก็ได้ที่ฉันต้องการ ดังนั้น ผู้พิทักษ์ คุณต้องระวังให้ดี อย่าให้คนบ้าที่ไม่สามารถควบคุมได้กัดคุณนะ."
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_123314_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "เพื่อสุขภาพร่างกายและจิตใจของฉัน อยากจะพูดคุยอย่างลึกซึ้ง? เอาล่ะ งั้นเรามาเริ่มกันเร็วๆ สิ่งที่น่าเบื่อนี้ ยิ่งเริ่มเร็วก็ยิ่งจบเร็ว.."
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_123315_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "ฉันแค่แกล้งทำเป็นคนธรรมดาตอบคำถามของคุณ? อ๊ะ ถูกคุณค้นพบแล้ว——งั้นคุณเตรียมพร้อมที่จะเห็นหน้าตาที่แท้จริงของฉันหรือยัง?"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_123316_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "ฟันหัวคุณ."
  },
  Voice_123770_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_123771_AwakerVoiceContent = {
    Text = "ทุกเพศทุกวัยต่างชอบดู! แสงระยิบ☆พายุหมุน——!!"
  },
  Voice_123771_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_123772_AwakerVoiceContent = {
    Text = "คนที่ควรล้มไม่ใช่ฉัน..."
  },
  Voice_123772_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_123773_AwakerVoiceContent = {
    Text = "ผลกระทบจากพายุ!"
  },
  Voice_123773_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_123774_AwakerVoiceContent = {
    Text = "คุณอยากช่วยโลกที่บิดเบือนและสยองขวัญนี้เหรอ? ช่างเป็นวิธีตายที่บ้าคลั่งและน่าสนใจจริงๆ——ให้ฉันดูสิว่าคุณจะไปได้ไกลแค่ไหน."
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "เด็กน้อยทั้งหลาย อยากลองชิมขวานของฉันไหม? อย่าเพิ่งรีบ รอแป๊บเดียว..."
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "ผู้พิทักษ์ ดูเหมือนว่าฉันจะเห็นแสงแล้ว หรือว่านี่จะเป็นครั้งนี้... ไม่รู้ว่าคณะกรรมการสอบสวนเพื่อนร่วมงานเป็นยังไงบ้าง? อย่าให้มีงานกองโตมาทิ้งไว้ให้ฉันนะ ฉันไม่อยากทำงานล่วงเวลา."
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_123776_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "ผ่านพิธีนี้ฉันจะกลับบ้านได้เหรอ? คุณแน่ใจไหม? นี่เป็นครั้งที่เท่าไหร่แล้วที่ลองทำ... เอาล่ะ อย่างน้อยการลองก็ไม่มีอะไรเสียหาย."
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_123777_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "ฮาฮา แน่นอนว่าสิ่งนี้เหมาะกับฉันมากกว่าชีวิตประจำวันที่น่าเบื่อหน่ายที่ทำให้ระดับอะดรีนาลีนสูงขึ้น!"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_123779_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_123779_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_123780_AwakerVoiceContent = {
    Text = "คนที่ควรล้มไม่ใช่ฉัน..."
  },
  Voice_123780_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_123781_AwakerVoiceContent = {
    Text = "ประกาย☆ดาวฤกษ์ซูเปอร์นิวเคลียร์——ปล่อย!"
  },
  Voice_123781_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_123782_AwakerVoiceContent = {
    Text = "ทุกเพศทุกวัยต่างชอบดู! แสงระยิบ☆พายุหมุน——!!"
  },
  Voice_123782_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_123783_AwakerVoiceContent = {
    Text = "ตอนนี้ความรู้สึก...เหมือนกับว่าเข้าไปในหมอก พอพูดถึงหมอกก็ทำให้นึกถึงเจ้าตัวน้อยในหมอกอีกครั้ง เสียดายจริงๆ ที่ไม่สามารถระบายอารมณ์กับพวกมันได้ในตอนที่รู้สึกไม่ดี."
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_123783_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "เกลียดเหรอ? ฉันไม่พูดแบบนั้นหรอก ฉันแค่หวังอย่างจริงใจว่า การประชุมที่น่าเบื่อ การเข้าสังคม และค่านิยมทั่วไปจะหายไปทั้งหมดแค่นั้น."
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "ก็เป็นแบบนี้แหละ...ฉันรู้สึกได้ว่าฉันเข้าใกล้ 「ตัวตนที่แท้จริง」 มากขึ้นเรื่อยๆ.."
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "อ้า ความล้มเหลวที่คาดไว้ ชีวิตก็เป็นแบบนี้ขึ้นๆ ลงๆ จนชินแล้ว... แต่ก็ขอบคุณสำหรับความพยายามในครั้งนี้นะ."
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_123786_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "เหมือนกับภัยหมอก ฉันไม่รู้เกี่ยวกับการหลอมกร่อนเลย นี่แหละคือสิ่งที่ทำให้มันน่าหลงใหล ไม่ใช่เหรอ?"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "โมช่า คณะกรรมการสอบสวน... โอ้ไม่ ตอนนี้ไม่ใช่แนวหน้าของคณะกรรมการสอบสวนแล้ว งั้นให้ฉันแนะนำตัวใหม่อีกครั้ง—ฉันชื่อโมช่า แค่เด็กหญิงน่ารักคนหนึ่ง~"
  },
  Voice_123788_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_123789_AwakerVoiceContent = {
    Text = "ไปให้พ้น!"
  },
  Voice_123789_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_123790_AwakerVoiceContent = {
    Text = "ที่นี่ใกล้กับที่อยู่อาศัยของมนุษย์เกินไป มีแต่ผู้ใหญ่ที่น่าเบื่อไปทั่ว... เคยคิดไหมว่าจะย้ายโรงเรียนไปอยู่ในป่าลึกที่ไม่มีคน?"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_123791_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_123791_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_123792_AwakerVoiceContent = {
    Text = "ฉันเริ่มจะหลงรักความรู้สึกที่ล่องลอยในโลกอื่นนี้แล้ว ผู้ปลุกตื่นที่ทรงพลัง การย่อยสลายที่น่ากลัว และเทพเจ้าที่ไม่รู้จัก! อ๊ะ ทุกอย่างมันช่างสบายห่างไกลจากสังคมธรรมดา!"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "ยังมีอีกไหม? ฉันกำลังสนุกอยู่เลย—เร็ว,      ใครให้ฉันฟันอีกที."
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_123794_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_123794_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_123795_AwakerVoiceContent = {
    Text = "ความล้มเหลวครั้งเดียวไม่ได้หมายความว่าอะไร... นั่นแหละ! พวกคุณต้องทำความสะอาดคอของคุณรอฉันได้เลย!"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "มีภารกิจเหรอ? ครั้งหน้าไม่ต้องทักทาย เราคุ้นเคยกันจนไม่จำเป็นต้องแสดง 「ขั้นตอนการพบปะทางสังคม」 แล้ว."
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "การสละชีวิตเพื่อผู้อื่นเป็นความคิดที่โง่เขลาและน่ารำคาญ ไม่มีใครสามารถเรียกร้องให้คนอื่นทำเช่นนั้นได้ แม้แต่พระเจ้าก็ไม่สามารถทำได้."
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "เรื่องทั่วไป：เกี่ยวกับซัลวาดอร์"
  },
  Voice_123797_UnlockDesc = {
    Text = "ปลดล็อคเมื่อได้รับ「เอลซัลวาดอร์」ร่างกายที่ตื่นขึ้น"
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "ไม่เลวเลยนะ——"
  },
  Voice_123798_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_123799_AwakerVoiceContent = {
    Text = "ในที่สุดก็ไม่ต้องเสแสร้งอีกต่อไป... ต่อไปนี้ให้เรามาสนุกกันเถอะ."
  },
  Voice_123799_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_123800_AwakerVoiceContent = {
    Text = "พิธียังไม่เสร็จเหรอ? อยากรีบกลับไปทานปลาต้มของเรเวนลอค ชาเฮเซลนัทคาวาร้อน ๆ แน่นอนว่าชาดำเกาะสีหลันและชิลีกั่วที่นี่ก็ดีเหมือนกัน."
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_123800_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "พัฒนาความสามารถของฉันตลอดเวลา คุณไม่กลัวเหรอว่าฉันจะควบคุมไม่ได้ในสักวัน... ฮ่าฮ่า ล้อเล่นน่า."
  },
  Voice_123801_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_123802_AwakerVoiceContent = {
    Text = "จริงๆ แล้วการอยู่ในโลกนี้ชั่วคราวก็ไม่เลว ฉันจะจดจำทุกสิ่งที่เกิดขึ้นที่นี่อย่างดี เขียนมันลงไป แล้วเมื่อกลับไปจะได้แบ่งปันให้ทุกคนที่นั่น อืม ชื่อก็เรียกว่า「การผจญภัยในโลกอีกใบของโมชา」 ฟังดูดีใช่ไหม?"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_123802_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "ฉันยอมรับว่าเธอน่ารัก... อืม ใช่แล้ว ดูเธอวิ่งไล่และต่อสู้กับแมวจรจัดที่อยู่ในมหาวิทยาลัยก็น่ารักจริงๆ."
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "เรื่องทั่วไป：เกี่ยวกับเมอร์ฟี่"
  },
  Voice_123803_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「มอร์ฟี่」ร่างกายที่ตื่นขึ้น"
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "ถึงแม้ว่าพละกำลังเหล่านี้จะไม่สามารถทำให้ฉันกลับไปสู่โลกของตัวเองได้ แต่การแข็งแกร่งขึ้นก็ยังเป็นสิ่งที่ดีเสมอ."
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "แม่บ้านอา ฉันก็เคยทำมาก่อน หาเวลามาให้เธอดูวิธีที่ฉันพัฒนา ใช้เครื่องดูดฝุ่นในการต่อสู้!"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "เรื่องราว：เกี่ยวกับคาเรน"
  },
  Voice_123805_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างที่ถูกปลุก「คาเรน」"
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "ฮาฮา แน่นอนว่าสิ่งนี้เหมาะกับฉันมากกว่าชีวิตประจำวันที่น่าเบื่อหน่ายที่ทำให้ระดับอะดรีนาลีนสูงขึ้น!"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "ฆ่าให้ตายในการโจมตีเดียว."
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·2"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "เข้าแถวทีละคนให้เรียบร้อย."
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_124769_AwakerVoiceContent = {
    Text = "จงพินาศไป!"
  },
  Voice_124769_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "อย่าคิด อย่ารบกวน ฟังอย่างไร้เสียง อย่าไปสนใจสิ่งที่ไม่สำคัญ!"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "อย่าคิด อย่ารบกวน ฟังอย่างไร้เสียง อย่าไปสนใจสิ่งที่ไม่สำคัญ!"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "คุณถามพวกเขาว่าทำไมในหัวถึงว่างเปล่า? อืม บางทีอาจเกิดมาแบบนี้."
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "วางโกรธวางความเกลียดชัง ทุกสิ่งกลายเป็นศูนย์."
  },
  Voice_126949_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_126950_AwakerVoiceContent = {
    Text = "ความเอาใจใส่เช่นนี้ จะทำให้ข้าหยุดไม่ได้ที่จะอยากแกล้งท่านมากขึ้น."
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_126951_AwakerVoiceContent = {
    Text = "อุ๊ย!"
  },
  Voice_126951_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_126952_AwakerVoiceContent = {
    Text = "คุณกำลังรอคอยให้ข้าสวยงามมากขึ้น หรือว่ากลัวมากขึ้น?"
  },
  Voice_126952_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_126953_AwakerVoiceContent = {
    Text = "เจ้าหญิงที่เกิดจากความสุข เธอสวมชุดที่ปักด้วยด้ายทอง ผิวของเธอเหมือนกับงาช้าง กลิ่นของไม้หอมลอยอยู่รอบตัวเธอ และแววตาของเธอทำให้ผู้คนหลงใหล."
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_126953_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "ไม่นานเธอก็เบื่อหน่ายกับความสนุกสนานนี้ ผู้ศรัทธาของเธอเพียงแต่ทำซ้ำๆ เหมือนเดิม ติดอยู่กับความรักที่เกิดจากความปรารถนา หรือเกิดจากความปรารถนาที่จะรัก เพราะการสูญเสียและการหักหลังทำให้เจ็บปวดจนไม่อยากมีชีวิตอยู่ ความโง่เขลาของพวกเขาทำให้เธอเบื่อหน่าย น้ำตาของพวกเขาก็ทำให้เธอเบื่อหน่ายเช่นกัน."
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_126954_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "สายตาของพวกเจ้าที่ต่ำต้อย ทำให้ข้ารู้สึกรำคาญจริงๆ."
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = "ท่านนั้นนางแดงเคยส่งจดหมายเชิญไปงานซาลอนมาหลายครั้ง.\nรสชาติของขนมจากต่างประเทศก็ดีอยู่ แต่...\nเธอควรบอกข้าก่อนว่า ในบ้านของเธอ ขนมหวานและเซิร์ฟแวนท์ไม่ใช่ความหมายเดียวกัน."
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับโซเรล"
  },
  Voice_126956_UnlockDesc = {
    Text = "เปิดใช้งานหลังจากได้รับร่างกายที่ตื่นขึ้น「โซเรล」"
  },
  Voice_126958_AwakerVoiceContent = {
    Text = "ไม่ใช่ความรักหรือ? แล้วทำไมถึงกลัวเมื่อถูกล้อมรอบ? ไม่ใช่ความรังเกียจหรือ? ทำไมถึงร้องไห้เมื่อมันไม่สามารถกลับไปได้อีก? \n อ๊ะ ตอนนี้ท่านกลัวเงาของข้าหรือ? กลิ่นหอมของดอกไม้ขาวได้กลายเป็นความหวานที่ท่านไม่สามารถเข้าใจได้แล้วหรือ?"
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_126958_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_126959_AwakerVoiceContent = {Text = "อืม!"},
  Voice_126959_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_126960_AwakerVoiceContent = {
    Text = "อ้าว? คุณถามว่าทำไมพวกเธอถึงมีลวดลายแบบนั้นที่รักแร้เหรอ? คุณไม่รู้สึกว่ามันสนุกมากเหรอ?"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับกลุ่มคนอ้วน"
  },
  Voice_126961_AwakerVoiceContent = {
    Text = "อุ๊ย!"
  },
  Voice_126961_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_126963_AwakerVoiceContent = {
    Text = "เมื่อเปรียบเทียบกับการถวายของผู้ศรัทธา สิ่งเหล่านี้กลับตรงใจข้าซะมากกว่า."
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "ก่อนอื่นคือท่าทาง ต่อมาคือรูปร่าง จนกระทั่งพวกเขาก็มีดวงตา... หรือพูดได้ว่าเหลือเพียงแค่ดวงตาที่สวยงามและดึงดูดใจ—เหมือนกับดวงตาของข้าเอง."
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_126964_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = "วันนี้ข้าน่าเบื่อมากจริงๆ ท่านไม่มีความปรารถนาอะไรที่ต้องการให้เป็นจริงเหรอ?\nน่าเสียดายจริงๆ ที่มีคนมากมายยินดีที่จะยกเคียวขึ้นมาเพื่อมอบเลือดและอาหารให้ข้าเพียงเพื่อวัตถุประสงค์ที่น่าเบื่อเหล่านี้.\nแต่ถ้าเป็นท่านล่ะ..."
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_126965_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "ทำไมพวกยงหรงจงถึงติดตามข้าน้อย และก่อตั้งขึ้นมาด้วยเหตุใดหรือ? คำถามที่น่าสนใจ ท่านเคยมีคนที่ปรารถนาแต่ไม่อาจได้ครอง หรือความเสียใจที่เกินกำลังจะแก้ไขบ้างไหม?\n\nอืม ดูเหมือนจะไม่มีนะ น่าเสียดายจัง\n\nสีหน้าที่ดิ้นรนในความสิ้นหวังนั้น หากปรากฏบนใบหน้าของท่าน จะต้องน่าสนใจมากๆ～มากๆ เลยล่ะ"
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_126966_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "...ถ้าคุณยังทำเกินเลยเช่นนี้อีก ข้าจะใช้วิธีการที่แตกต่างไปในการเผชิญหน้ากับท่านแล้วล่ะ."
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "เรื่องราวของเธอ ข้าพเจ้าได้ลืมไปเกือบหมดแล้ว แต่เป็นเรื่องราวเกี่ยวกับความสุข เรื่องราวเกี่ยวกับความโหดร้าย เรื่องราวที่เริ่มต้นด้วยการถูกทอดทิ้งและการตอบแทน ต่อมาคือเรื่องราวเกี่ยวกับการสละชีพและการตามอย่างตาบอด."
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_126968_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "ทำให้ข้าพอใจ ในความเจ็บปวดและความกลัวที่ฆ่าฟันกันเองเถอะ~"
  },
  Voice_126969_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_126970_AwakerVoiceContent = {
    Text = "...นี่ทำให้ข้ารู้สึกสนใจขึ้นมาบ้างแล้ว."
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "ทุกคนจะเห็นใบหน้าของคนที่ตนรักที่สุดใต้พัดของข้า ข้าจะมอบพลังนี้ให้แก่ผู้ที่อ่อนแอ เพื่อให้กลายเป็นคมดาบ เพื่อความสนุกสนาน \n แต่บางที ข้าอาจแค่พูด บางที \n หากท่านยินดีที่จะหลงใหล ข้าจะรู้สึกถึงความสุขที่แท้จริงและสูงสุด."
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_126971_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = "ไม่ต้องกังวล คุณไม่เหมือนพวกเขาที่เป็นคนธรรมดา \n ชู ช่วยอย่ามองที่ด้านหลังของข้า อย่าสนใจการสัมผัสที่มองไม่เห็น——มองไปที่ดวงตาของข้า."
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_126972_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "*หัวเราะเบาๆ ท่านกล้าจ้องมองใบหน้าที่แท้จริงของข้าหรือ?"
  },
  Voice_126973_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_126975_AwakerVoiceContent = {
    Text = "เสียงอึกทึก"
  },
  Voice_126975_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_126976_AwakerVoiceContent = {
    Text = "ทำไม? อีกแล้วเหรอที่จ้องพัดของข้า ติดใจแล้วหรือ?\nฮ่าๆ ไม่ว่าท่านจะอยากเห็นใบหน้าของใครใต้พัด ข้าจะทำให้ท่านพอใจ...... มา เข้าใกล้หน่อย——\nเอ๊ะ ไม่ต้องเหรอ? พูดคำที่เย็นชาขนาดนี้ แต่สีหน้าก็น่ารักเหลือเกิน......"
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_126976_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "ท่านไม่ฝันถึงบ้าน อยากจะตามหาอะไร?"
  },
  Voice_126977_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_126978_AwakerVoiceContent = {
    Text = "วางโกรธวางความเกลียดชัง ทุกสิ่งกลายเป็นศูนย์."
  },
  Voice_126978_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_126979_AwakerVoiceContent = {
    Text = "ห้ามไร้มารยาท."
  },
  Voice_126979_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_126980_AwakerVoiceContent = {Text = "อืม!"},
  Voice_126980_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_126981_AwakerVoiceContent = {
    Text = "ข้าก็เคยมีเด็กสาวที่สวยงามและลังเลแบบนี้อยู่คนหนึ่ง \n ดอกตูมที่สะดุดตา แน่นอนว่าต้องมีหนามแหลมเพิ่มเข้าไปด้วย ไม่สามารถใส่ลงในแจกันได้."
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับลิลลี่"
  },
  Voice_126981_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「ลิลลี่」"
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "สถาบันปฏิเสธคำขอของฉันที่จะไปทำงานที่ห้องปรึกษาทางจิตใจอย่างเด็ดขาด มันแปลกจริงๆ ว่ามีอะไรไม่เหมาะสมกันแน่?"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = "ทุกสิ่งสุดท้ายจะกลับคืนสู่สุญญตา ทำไมไม่มาหาความสนุกกับข้าบ้าง?\nโปรดวางใจ หากวันใดท่านไม่สามารถต้านทานได้ ข้าจะไม่ให้มันพรากท่านไปก่อน."
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_126984_AwakerVoiceContent = {
    Text = "ไม่น่าสนใจ"
  },
  Voice_126984_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_126985_AwakerVoiceContent = {
    Text = "ท่านช่างเป็นคนที่แปลกประหลาด ในโลกที่ถูกกำหนดให้พินาศ กลับยุ่งอยู่กับเรื่องนอกตัวมากมาย \n ทำให้ข้าก็อดใจไม่ไหวที่จะรู้สึกสนใจขึ้นมาแล้ว."
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_126985_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_126986_AwakerVoiceContent = {
    Text = "อย่าเข้าใกล้!"
  },
  Voice_126986_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_126988_AwakerVoiceContent = {
    Text = "ข้าคือเจ้าแห่งความไม่ฝัน ซู หากท่านในใจมีคนที่อยากพบแต่ไม่สามารถพบได้ ข้ายินดีที่จะปัดพัดให้ท่านได้เห็นสักครั้ง."
  },
  Voice_126988_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_127088_AwakerVoiceContent = {
    Text = "ลูกหลานของสิ่งมีชีวิตทั้งหมดนั้นน่ารำคาญ \n เล็ก นุ่ม และเสียงดัง โดยไม่ตั้งใจทำให้ทุกสิ่งรอบตัวหมุนวนไปหมด ข้าชอบความครึกครื้น แต่ไม่ชอบความครึกครื้นแบบนี้ ขอให้ท่านช่วยให้พวกมันอยู่ห่างๆ หน่อย."
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = "ดอกมะลิของข้า ที่รักของข้า ข้ารู้สึกหวานเหมือนน้ำผึ้งเมื่ออยู่ในบ้านตุ๊กตานี้~\nอา มีคำพูดไร้สาระที่มีอารมณ์ดีบางอย่าง คุณไม่ต้องกังวลเลย."
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "ในตำนานของอาณาจักรฟ้า นกยูงเป็นสัตว์ร้ายที่สวยงามและโอ้อวด.\nสวยงามและมีพิษภัย ฟังแล้วทำให้รู้สึกหัวใจเต้นแรง หากว่ามีรูปร่างอัปลักษณ์แต่มีความดี จะดูน่าเบื่อหน่อยนะ."
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "กินหมด กินหมด ทั้งหมดเลย"
  },
  Voice_129651_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_129652_AwakerVoiceContent = {
    Text = "โครก โครก~"
  },
  Voice_129652_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_129653_AwakerVoiceContent = {
    Text = "ลูกถ่านขนาดเล็ก ฉัน กินข้าว ด้วยกันไหม? ด้วยกัน!"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_129653_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "มอส! แข็งแกร่งมาก!"
  },
  Voice_129654_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_129655_AwakerVoiceContent = {
    Text = "เหว! เกลียว! ล่มสลาย! ทั้งหมด——กลายเป็นวังวนเถอะ!"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_129656_AwakerVoiceContent = {
    Text = "เจ็บ!"
  },
  Voice_129656_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_129657_AwakerVoiceContent = {
    Text = "อย่าจับฉัน! อย่าจับฉัน! เสียหายแล้ว!"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_129657_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "เปลือกหอย ระยิบระยับ! ระยิบระยับ สวยงาม ให้คุณ!"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_129658_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "เย็นยะเยือก น่ากลัว มอส รีบซ่อนตัว!"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับดอร์"
  },
  Voice_129659_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ดอร์」"
  },
  Voice_129660_AwakerVoiceContent = {
    Text = "ยะฮู!"
  },
  Voice_129660_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "ล่า น่ารังเกียจ! เสียหาย! มอส จัดการพวกเขา เสียหาย!"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "สนุกมาก! ครั้งหน้า! ยังอยากเล่นอีก!"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_129662_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "ลูบ ล่ะ! มอส เธอ ลูบ!"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "ไม่ ไม่เอา! ลูกถ่านขนาดเล็ก มอส ปกป้อง!"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "อีกครั้ง? ขออีกครั้ง!"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "ฮิฮิ มอส อยากเล่น!"
  },
  Voice_129666_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_129667_AwakerVoiceContent = {
    Text = "คลื่นใหญ่มาแล้ว!"
  },
  Voice_129667_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_129668_AwakerVoiceContent = {
    Text = "ทิ้ง!"
  },
  Voice_129668_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_129669_AwakerVoiceContent = {
    Text = "เจ็บ!"
  },
  Voice_129669_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_129670_AwakerVoiceContent = {
    Text = "อุ๊ย!"
  },
  Voice_129670_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_129671_AwakerVoiceContent = {
    Text = "พิธี?! พาฉันไปด้วย!"
  },
  Voice_129671_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_129671_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_129672_AwakerVoiceContent = {
    Text = "วังวน! พละกำลัง! แท่ง!"
  },
  Voice_129672_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_129672_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_129673_AwakerVoiceContent = {Text = "ปัง!"},
  Voice_129673_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_129674_AwakerVoiceContent = {Text = "เย้!"},
  Voice_129674_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_129675_AwakerVoiceContent = {
    Text = "ฮูลา ฮูลา~"
  },
  Voice_129675_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_129676_AwakerVoiceContent = {
    Text = "ต่อสู้!"
  },
  Voice_129676_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับโกลิอัท"
  },
  Voice_129676_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「โกลิอัท」"
  },
  Voice_129677_AwakerVoiceContent = {
    Text = "เจอเยอะเลย แวววาว!"
  },
  Voice_129677_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_129677_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_129678_AwakerVoiceContent = {
    Text = "เหว! เกลียว! ล่มสลาย! ทั้งหมด——กลายเป็นวังวนเถอะ!"
  },
  Voice_129678_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_129679_AwakerVoiceContent = {
    Text = "ว้าวโฮ่!"
  },
  Voice_129679_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_129680_AwakerVoiceContent = {
    Text = "อุ๊ย!"
  },
  Voice_129680_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_129681_AwakerVoiceContent = {
    Text = "มอส! แข็งแกร่งมาก!"
  },
  Voice_129681_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_129682_AwakerVoiceContent = {
    Text = "กินหมด กินหมด ทั้งหมดเลย"
  },
  Voice_129682_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_129683_AwakerVoiceContent = {
    Text = "นอติลุส，นอติลา，ลูกถ่านขนาดเล็ก!สว่างระยิบระยับ!"
  },
  Voice_129683_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_129684_AwakerVoiceContent = {
    Text = "มอส โหลดกระสุน!"
  },
  Voice_129684_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นที่สอง·การบรรจุหนึ่ง"
  },
  Voice_129685_AwakerVoiceContent = {
    Text = "มอส รีบไป!"
  },
  Voice_129685_AwakerVoiceTitle = {
    Text = "ทักษะ·II·การบรรจุ·สอง"
  },
  Voice_129686_AwakerVoiceContent = {
    Text = "กอด! มอส! ชอบ!"
  },
  Voice_129686_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_129686_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_129687_AwakerVoiceContent = {
    Text = "ลูกถ่านขนาดเล็ก เพื่อน! มอส ตลอดไป!"
  },
  Voice_129687_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_129688_AwakerVoiceContent = {
    Text = "เร็วหน่อย เร็วหน่อย!"
  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_129688_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_129689_AwakerVoiceContent = {
    Text = "มอส! ลูกถ่านขนาดเล็ก! มาร่วมกันตลอดไป? ตลอดกาล!"
  },
  Voice_129689_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_129689_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_129690_AwakerVoiceContent = {
    Text = "โฮ่ โฮ่~ คลื่นใหญ่โหมกระหน่ำขึ้นมา!"
  },
  Voice_129690_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_129690_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "เพื่อน! เยอะมาก! ชอบ!"
  },
  Voice_129691_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_129692_AwakerVoiceContent = {
    Text = "มอส! เก่งจัง!"
  },
  Voice_129692_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_129693_AwakerVoiceContent = {
    Text = "นอติลา,     อยากเจอ.เอ,     นอติลา,     มอส,     มอส!"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับนอติลา"
  },
  Voice_129693_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับ「นอร์ดิลา」"
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "แข็งแกร่งขึ้นแล้ว!"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "ฉัน! มอส! สวัสดี!"
  },
  Voice_129695_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_130511_AwakerVoiceContent = {
    Text = "ฮื้อ——"
  },
  Voice_130511_AwakerVoiceTitle = {
    Text = "ทักษะ·II·การบรรจุสาม"
  },
  Voice_133720_AwakerVoiceContent = {
    Text = "ความผิดพลาดจะถูกแก้ไข"
  },
  Voice_133720_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_133721_AwakerVoiceContent = {
    Text = "โศกนาฏกรรมที่ท่านเห็น เป็นเพียงแวบหนึ่งจากความเป็นไปได้นับหมื่นพัน เปิดม่านแห่งโชคชะตาออก ข้าเห็นเวทีมืดมิดนั้น ไฟดับ ผู้คนจากไป สรรพสิ่งกลับคืนสู่ห้วงอลวน แต่... ทั้งหมดมิใช่บทอวสาน เจตจำนงของข้ายังคงอยู่ เพียงพอที่จะค้ำจุนงานหนักอันไร้ผลนี้ รอคอยแสงสว่างดวงถัดไปจุดขึ้น"
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "ชะตากรรมของผู้คนล้วนถูกชักนำด้วยสายด้าย... แต่ชะตากรรมของท่าน เป็นบทละครที่ข้าไม่อาจอ่านเข้าใจได้ ข้าตั้งตารอคอย... ว่าท่านจะนำการแสดงสดอันแสนวิเศษเช่นไรมาสู่โลกใบนี้?"
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "หุ่นเชิดตัวเอก จงก้าวขึ้นสู่เวทีที่เป็นของเจ้าเถิด"
  },
  Voice_133723_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_133724_AwakerVoiceContent = {Text = "หืม?"},
  Voice_133724_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_133725_AwakerVoiceContent = {
    Text = "สิ่งที่ผ่านมาทั้งหมด ล้วนเป็นเพียงบทนำ บทใหม่ของเราทั้งสอง กำลังรอคอยให้ท่านเขียนขึ้น ผู้พิทักษ์ความลับ"
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_133725_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "หากท่านชื่นชอบสุขนาฏกรรม «ฝันกลางคืนกลางฤดูร้อน» เป็นตัวเลือกที่ดี ข้าชื่นชอบถ้อยคำเจ้าเล่ห์ของพัคเป็นพิเศษ ในเสียงหัวเราะของเหล่าภูตพราย มักซ่อนความลับที่โชคชะตาเผยออกมาโดยไม่ตั้งใจ"
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_133726_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "ปฏิบัติตามนี้"
  },
  Voice_133727_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_133728_AwakerVoiceContent = {
    Text = "กงล้อปั่นด้าย หมุนเวียน ณ ที่นี้"
  },
  Voice_133728_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_133729_AwakerVoiceContent = {
    Text = "เจ้านักโทษผู้น่าสมเพชแห่งโชคชะตา จงรับคำพิพากษาที่ถูกกำหนดไว้ให้เจ้าเถิด"
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "แม้จะเป็นผู้เฝ้ามองที่หยั่งรู้สรรพสิ่ง ก็เป็นเพียงนักแสดงที่เงอะงะในบทละครของตนเอง ครอบครองข่ายใยแห่งโชคชะตา แต่สุดท้ายก็ถูกพันธนาการด้วยสายด้าย ในสถานการณ์ที่ถูกกำหนดไว้นี้ เราเดินบนเส้นทางที่ต่างกัน แต่ไม่เคยยอมละทิ้งการแสวงหาที่ไร้ผลเหล่านั้น จะโง่เขลาก็ดี จะหลงใหลก็ดี ข้าเป็นเช่นนี้ เธอก็เช่นกัน"
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "เรื่องเล่า: เกี่ยวกับทาวี"
  },
  Voice_133730_UnlockDesc = {
    Text = "ปลดล็อคเมื่อได้รับร่างกายที่ตื่นขึ้น「ทาวี」"
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "จุดพลิกผันที่คาดไม่ถึง?"
  },
  Voice_133731_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_133732_AwakerVoiceContent = {
    Text = "ขอบคุณที่ท่านร่วมเดินทางมาตลอดระหว่างม่านเปิดและม่านปิด ในอนาคต ข้าจะไม่ทำให้ท่านผิดหวัง และจะนำเสนอค่ำคืนแห่งการละครที่สะเทือนใจยิ่งกว่าเดิมแด่ท่าน"
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_133732_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "นักร้องผู้มีพรสวรรค์เช่นนี้ เสียงที่สวรรค์ประทานให้ ใสกระจ่างแต่เร่าร้อน ราวกับหลั่งไหลมาจากเสียงแห่งโชคชะตา... หากเชิญมาที่โรงละครของข้าได้ เชื่อว่าแม้แต่ผู้ชมที่จู้จี้ที่สุดก็ต้องประหลาดใจ"
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "เรื่องเล่า: เกี่ยวกับทิงเคิร์ต"
  },
  Voice_133733_UnlockDesc = {
    Text = "หลังจากได้รับร่างกายที่ตื่นขึ้น 「ทิงค์เทต」แล้ว จะปลดล็อก"
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "ท่านกับข้า เส้นด้ายแห่งโชคชะตาสองเส้นที่ไม่อาจมองเห็น ได้พันเกี่ยวกันแน่นหนาจนแยกไม่ออก ถักทอเป็นทั้งกรงขังและเส้นทาง ข้าไม่อาจมองเห็นขอบเขตของกรงขัง และไม่อาจมองเห็นจุดสิ้นสุดของเส้นทาง นี่คือส่วนที่น่าหลงใหลที่สุดของเรื่องราวนี้"
  },
  Voice_133734_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_133734_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "เส้นด้ายแห่งโชคชะตา ได้ทอดลงมาแล้ว"
  },
  Voice_133735_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_133736_AwakerVoiceContent = {
    Text = "เธอมักมานั่งในโรงละครของข้าเสมอ... แต่ข้ารู้ดีว่า เธอไม่ได้มาเพื่อดูละคร หากแต่ยืมเวทีแห่งนี้เพื่อสะท้อนรสนิยมของตนเอง อย่างไรก็ตาม ฝีมือการแสดงอันยอดเยี่ยมเช่นนั้น หากเป็นเพียงผู้ชม ก็น่าเสียดายยิ่งนัก มันควรจะเบ่งบานภายใต้แสงสปอตไลท์ มิใช่ซ่อนตัวอยู่ในเงามืดของที่นั่งผู้ชม"
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับโซเรล"
  },
  Voice_133736_UnlockDesc = {
    Text = "เปิดใช้งานหลังจากได้รับร่างกายที่ตื่นขึ้น「โซเรล」"
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "ข้าเคยได้ยินการบรรเลงของเขา ท่วงทำนองอันไพเราะนั้น ทำให้วิญญาณสั่นสะท้าน... บางที ควรเชิญเขามาประพันธ์ซิมโฟนีแห่งโชคชะตาสักบทให้กับละครเรื่องใหม่ของข้า?"
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "พูดคุย: เกี่ยวกับฮาเมล"
  },
  Voice_133737_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างกายที่ตื่นขึ้น「แฮมลิน」"
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "อีกหนึ่งเรื่องราวที่สมบูรณ์ ม่านได้ปิดลงแล้ว"
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "ข่ายแห่งโชคชะตาอันไม่สิ้นสุด ข้าได้เห็นภาพทั้งหมดแล้ว"
  },
  Voice_133739_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_133740_AwakerVoiceContent = {
    Text = "หากท่านอนุญาต... ข้าอยากถักทอละครสองคนที่เป็นของท่านและข้าเพียงเท่านั้น ไม่ต้องมีผู้ชม ไม่ต้องซ้อม... ข้าเพียงแค่ตั้งตารอ เมื่อท่านยืนอยู่ใต้แสงไฟ เส้นด้ายที่ข้าไม่อาจมองเห็นนั้น จะมีการเต้นระบำที่น่าอัศจรรย์เพียงใด"
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_133740_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "นักเต้นผู้โชคร้าย ข้าได้เห็นจังหวะเต้นของเธอแล้ว นั่นคือความงามที่ใกล้จะถึงจุดพินาศ ทุกรอบหมุนจุดประกายเปลวไฟสีเขียว พยายามเผาผลาญสายด้ายแห่งโชคชะตาให้มอดไหม้ แต่น่าเสียดาย สุดท้ายก็จะถูกสายด้ายเหล่านั้นตัดฉีกออกเป็นภาพที่งดงามแต่โศกสลด หากมีโอกาส ข้าอยากเขียนบัลเลต์สักเรื่องที่เป็นของเธอเพียงผู้เดียว"
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "เรื่องเล่า: เกี่ยวกับลิซ"
  },
  Voice_133741_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างกายที่ปลุก「ลิซ」"
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "ถักทอ ณ ที่นี้ ชั่งตวง ณ ที่นี้ ตัดสิน ณ ที่นี้"
  },
  Voice_133742_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_133743_AwakerVoiceContent = {
    Text = "สงบลงเถิด..."
  },
  Voice_133743_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_133744_AwakerVoiceContent = {
    Text = "เส้นด้ายอีกเส้น ชัดเจนขึ้นแล้ว"
  },
  Voice_133744_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_133745_AwakerVoiceContent = {
    Text = "ม่านได้เปิดออกเพื่อท่านแล้ว บทละครแห่งโชคชะตารอคอยการเริ่มต้น บอกข้าเถิด ท่านปรารถนาจะก้าวเข้าสู่เส้นทางชะตากรรมใด? บทอวสานแห่งโศกนาฏกรรม หรือบทเริ่มต้นแห่งสุขนาฏกรรม?"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_133745_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "ข้าหลงใหลในการถักทอที่ซ้ำแล้วซ้ำเล่าวันแล้ววันเล่าจริงๆ... ในการลากจูงที่ซ้ำซากและเงียบสงบ คาดการณ์จุดเริ่มต้นและจุดจบของเรื่องราวนับพัน เฝ้าดูม่านปิดของทุกชะตากรรม ราวกับว่าได้อยู่เหนือโชคชะตาแล้ว แต่ตาข่ายแห่งโชคชะตาหลีกเลี่ยงไม่ได้ การเป็นเพียงผู้เฝ้าดูย่อมเปล่าเปลี่ยวในที่สุด ดังนั้น ข้าจึงก้าวเข้าสู่โรงละคร ในการแสดงบทบาท ลิ้มรสความสุขทุกข์ที่ข้าถักทอขึ้นด้วยมือตนเอง แต่ไม่เคยได้สัมผัสด้วยตนเอง"
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_133747_AwakerVoiceContent = {
    Text = "อืม..."
  },
  Voice_133747_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_133748_AwakerVoiceContent = {Text = "หึ..."},
  Voice_133748_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_133749_AwakerVoiceContent = {
    Text = "ถักทอ ณ ที่นี้ ชั่งตวง ณ ที่นี้ ตัดสิน ณ ที่นี้"
  },
  Voice_133749_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_133750_AwakerVoiceContent = {
    Text = "เสียงกระซิบแห่งโชคชะตา ใกล้เข้ามาแล้ว"
  },
  Voice_133750_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_133751_AwakerVoiceContent = {
    Text = "โรงละครจัดแสดงละครตลกโรแมนติกเรื่องใหม่ ข้าได้สำรองที่นั่งว่างไว้มุมหนึ่งบนแถวที่โชคชะตากำหนด เพื่อท่าน ข้าจะรอคอยแสงดาวแห่งการพบพานกับท่าน ในทุกค่ำคืนอันยาวนานที่โชคชะตาพันเกี่ยว"
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_133751_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "หมกมุ่นกับการดีดเส้นด้ายแห่งโชคชะตาถึงเพียงนี้... ท่านก็ปรารถนาจะเห็นบทที่เป็นของตนเองหรือ?"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "อนาคตมาถึงแล้ว"
  },
  Voice_133753_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_133754_AwakerVoiceContent = {
    Text = "หากท่านปรารถนาจะก้าวเข้าสู่ห้องโถงแห่งโศกนาฏกรรม โปรดอนุญาตให้ข้านำเสนอ «แอนติโกเน» แด่ท่าน ท่ามกลางการเผชิญหน้าระหว่างกฎแห่งทวยเทพและโลกมนุษย์ ทุกก้าวของนางเหยียบอยู่บนเส้นด้ายที่โชคชะตาถักทอ จนกระทั่งก้าวเข้าสู่เงามืดอันลึกล้ำของสุสานหิน เพราะพันธนาการนี้ไม่อาจหลุดพ้น เจตจำนงที่ปะทุจากร่างกายอันเล็กกระจ้อยของนาง จึงเจิดจ้าดั่งเปลวไฟโดดเดี่ยวในค่ำคืนอันยาวนาน"
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_133754_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "จากบทสรุปที่ไร้ความแน่นอน หนีไม่พ้นข่ายแห่งเหตุและผล..."
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "บนเส้นด้ายแห่งการปั่นทอ ข้าเห็นสีสันรุ้งงามหมุนเวียนเปลี่ยนผัน—— มันเชื่อมร้อยตาข่ายอันไม่มีที่สิ้นสุด แผ่กว้างสู่โลกอันไร้ขอบเขต ขยายออกเป็นความเป็นไปได้อันไม่มีที่สุด และท้ายที่สุดถักทอเป็นลวดลายที่งดงามวิจิตรที่สุดในโลก ไม่ว่าจะเป็นเทพหรือมนุษย์ วีรบุรุษหรือวายร้าย ล้วนถูกเส้นด้ายบางเบาเส้นนั้นบงการ วิ่งตรงสู่บทอวสานของตนอย่างไม่หวนกลับ ภายใต้สายตาจ้องมองของโชคชะตา"
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "ข้าเคยคิดว่าไม่มีทางเลือกใดในโลกนี้จะทำให้ข้าประหลาดใจได้อีก... รสนิยมด้านการละครของท่าน ทำให้ข้าประทับใจยิ่งนัก"
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_133757_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "เส้นด้ายแห่งโชคชะตามักเชื่อมต่อกันในที่มืด... ท่านได้สั่นสะเทือนเส้นด้ายนี้ และสั่นสะเทือนข้าด้วยเช่นกัน"
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_133758_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "ข้าไม่เคยอยากเห็นการแสดงที่ซ้ำซากจำเจเหมือนแบบพิมพ์เดิมๆ ความหมายของการก้าวเข้าสู่โรงละคร อยู่ที่การได้สัมผัสช่วงเวลาจริงที่ไม่อาจจำลองขึ้นมาใหม่ได้ หากทุกรอบการแสดงเป็นเพียงการทำซ้ำอย่างเครื่องจักร เวทีก็จะกลายเป็นกรงขังอันวิจิตร และการชมละครก็จะกลายเป็นเพียงการแสวงบุญที่เหนื่อยหน่ายต่อบทสรุปที่รู้อยู่แล้ว การแสดงเช่นนั้น ต่อให้หรูหราเพียงใด ก็สูญสิ้นวิญญาณไปแล้ว ท่านคิดเห็นอย่างไรกันล่ะ?"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "เส้นด้ายแห่งโชคชะตาเคยไหลเวียนอย่างเป็นระเบียบในอุ้งมือของข้า... จนกระทั่งท่านปรากฏตัว ทำให้วิถีของมันเกิดระลอกคลื่นที่ไม่เคยคาดคิด"
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_133760_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "เจ้านักโทษผู้น่าสมเพชแห่งโชคชะตา จงรับคำพิพากษาที่ถูกกำหนดไว้ให้เจ้าเถิด"
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "ข้าถักทอเส้นทางเพียงหนึ่งเดียว ท่ามกลางเส้นด้ายที่ไม่มีวันสิ้นสุด"
  },
  Voice_133762_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_133763_AwakerVoiceContent = {
    Text = "บนเวทีแห่งโชคชะตา สรรพชีวิตรอคอยการขึ้นเวทีในเหตุและผลของตน ความสุขทุกข์นานาถูกร้อยเรียงอย่างเงียบงันในจังหวะหมุนของฟันเฟือง... ม่านได้เปิดขึ้นแล้ว ผู้พิทักษ์ความลับ เรื่องราวระหว่างเราจะเริ่มต้น ณ บัดนี้"
  },
  Voice_133763_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_133764_AwakerVoiceContent = {
    Text = "ความขัดแย้งมาถึงแล้ว ท่านจะรับบทเป็นวีรบุรุษผู้ฉีกข่าย หรือตัวประกอบผู้ยอมจำนนต่อโชคชะตา?"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "การต่อต้านที่ไร้ผล"
  },
  Voice_133765_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_139865_AwakerVoiceContent = {
    Text = "ขอบคุณ ฉันจะดูแลของขวัญนี้ให้ดี"
  },
  Voice_139865_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_139866_AwakerVoiceContent = {
    Text = "ฉันเรียนรู้เรื่องโครงสร้างของผู้ตื่นมาเยอะมาก ถือว่าเป็นผู้เชี่ยวชาญได้แล้วนะ แต่สิ่งที่เรียกว่า「จิตวิญญาณ」ในแกนเงินนั้น ยังไม่ค่อยเข้าใจเท่าไหร่..."
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_139866_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "นี่แหละ... จุดเริ่มต้นของโลกใหม่..."
  },
  Voice_139867_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_139868_AwakerVoiceContent = {
    Text = "ฉันทำแบบนั้นได้นะ ไม่ว่าจะเป็นการปรับโครงสร้างร่างกายของสิ่งมีชีวิตอื่น หรือการปรับแต่ง..."
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_139868_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "จะปรับแต่งตรงไหนอย่างไร แต่ละสายพันธุ์ก็แตกต่างกันไป ถ้าไม่ตั้งใจเรียนรู้ก็ไม่ได้นะ"
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_139869_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "ไม่น่ากลัวเหรอ รูปร่างของฉัน? เอ๊ะ น่าเบื่อนิดหน่อยนะ..."
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "จะไม่ปล่อยให้ใครมาขัดขวางพวกเราหรอก"
  },
  Voice_139871_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_139872_AwakerVoiceContent = {
    Text = "ฉันพร้อมแล้วนะ"
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "สิ่งมีชีวิตเต็มไปด้วยความหลากหลายจริงๆ เลยนะ อยากรู้เพิ่มเติมอีก!"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "อยากมาเล่นกับซายะไหม?"
  },
  Voice_139875_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_139876_AwakerVoiceContent = {Text = "อ๊ะ!"},
  Voice_139876_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_139877_AwakerVoiceContent = {
    Text = "นี่แหละ... จุดเริ่มต้นของโลกใหม่..."
  },
  Voice_139877_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_139878_AwakerVoiceContent = {
    Text = "อิ่มแล้ว ขอบคุณสำหรับอาหาร!"
  },
  Voice_139878_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_139880_AwakerVoiceContent = {
    Text = "ผู้พิทักษ์ เธอเคยรักใครสักคน คิดถึงใครสักคนไหม?"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_139880_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_139881_AwakerVoiceContent = {Text = "อี้!"},
  Voice_139881_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_139882_AwakerVoiceContent = {
    Text = "ที่นี่ใช่ไหม?"
  },
  Voice_139882_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_139883_AwakerVoiceContent = {
    Text = "เหนื่อยแล้วนะ! ได้ผลดีไหม?"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "หลังจากทดสอบหลายอย่างแล้ว ก็เข้าใจโดยรวมแล้วนะ「จิตวิญญาณ」ที่ผู้ตื่นแต่ละคนมีนั้นแตกต่างกันโดยสิ้นเชิง แล้วจิตวิญญาณในแกนเงินของฉันดูเหมือนจะเป็น「ความรัก」นะ"
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_139884_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "เป็นไง ตกใจเลยใช่ไหม?"
  },
  Voice_139885_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_139886_AwakerVoiceContent = {
    Text = "นี่คือของขวัญชิ้นสุดท้ายที่มอบให้เธอ"
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = "「บนดาวดวงใดดวงหนึ่งในบรรดาดาวเหล่านี้ ดอกไม้ของฉันกำลังเบ่งบาน...」เขาพูดแบบนั้นนะ\nเธอก็เคยพูดอะไรคล้ายๆ กันใช่ไหมล่ะ"
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_139887_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "สิ่งที่เรียกว่า「แกนเงิน」ดูเหมือนจะเชื่อมต่อกับเจตจำนงที่อยู่ไกลแสนไกล น่าอัศจรรย์จริงๆ นะ..."
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_139888_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "นี่คือของขวัญชิ้นสุดท้ายที่มอบให้เธอ"
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_139891_AwakerVoiceContent = {Text = "ว้า!"},
  Voice_139891_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_139892_AwakerVoiceContent = {
    Text = "เจ้าชายน้อยบอกว่า การที่เขาดูแลกุหลาบต่างหาก ที่ทำให้กุหลาบดอกนั้นแตกต่างจากดอกอื่น... เธอก็คิดแบบนั้นเหรอ?"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_139892_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "เมื่อวานฉันเห็นหนังสือเล่มหนึ่งชื่อ«เจ้าชายน้อย»ในชั้นหนังสือของลิลี่ ฉันยืมมาแล้ว จะมาอ่านด้วยกันไหม?"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_139893_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "อืม ฉันก็ได้ศึกษาโครงสร้างของแกนเงินด้วย เริ่มเข้าใจภาพรวมของผู้ตื่นมากขึ้นเรื่อยๆ แล้วนะ"
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_139895_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_139896_AwakerVoiceContent = {Text = "ว้า!"},
  Voice_139896_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_139897_AwakerVoiceContent = {
    Text = "เฮ้ย!"
  },
  Voice_139897_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_139899_AwakerVoiceContent = {
    Text = "ฝากเนื้อฝากตัวด้วยนะ!"
  },
  Voice_139899_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_139900_AwakerVoiceContent = {
    Text = "สวัสดี!...พูดแบบนี้ถูกไหม?\nฉันชื่อซายะ อืม...ฝากตัวด้วยนะ——"
  },
  Voice_139900_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_139901_AwakerVoiceContent = {
    Text = "มีดอกไม้ชนิดหนึ่งเรียกว่าแดนดิไลออน มันจะปล่อยเมล็ดให้ลอยไปตามสายลม เมล็ดปุยนุ่มถูกลมพัดพาไป จากบ้านเกิดไกลแสนไกล บางทีอาจตกลงในทะเลทรายที่ไม่มีต้นหญ้าแม้แต่ต้นเดียว ตอนแบบนั้น เมล็ดเล็กๆ เมล็ดนั้นจะคิดอะไรอยู่นะ..."
  },
  Voice_139901_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_139901_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_139902_AwakerVoiceContent = {
    Text = "ทำกี่ครั้งก็สนุกทุกครั้ง!"
  },
  Voice_139902_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_139903_AwakerVoiceContent = {
    Text = "เฮ้——"
  },
  Voice_139903_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_139906_AwakerVoiceContent = {
    Text = "อันตรา——"
  },
  Voice_139906_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_140533_AwakerVoiceContent = {
    Text = "ชอบอาหารอร่อยมากๆ เลย! ก็ชอบคนที่อ่อนโยนกับซายะด้วย ถ้าถูกปฏิบัติอย่างอ่อนโยน มีความสุขจริงๆ เลยนะ——"
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "นั่นคือคนที่ปลุกฉันตื่นเหรอ? รู้สึกเจิดจ้ามากเลยนะ... อืม~ แล้ว เธอช่วยเธอหาพี่สาวเจอแล้วหรือยัง?"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "เรื่องเล่า: เกี่ยวกับทิงเคิร์ต"
  },
  Voice_140534_UnlockDesc = {
    Text = "หลังจากได้รับร่างกายที่ตื่นขึ้น 「ทิงค์เทต」แล้ว จะปลดล็อก"
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "ทุกครั้งที่ซายะอยากจะครอบครองผู้พิทักษ์คนเดียว ก็จะมีคนแปลกๆ มารุมล้อมเต็มไปหมดเลย ชอบตอนอยู่ในมิจิงมากกว่า——"
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "เป็นอย่างนั้นเอง เข้าใจแล้ว!"
  },
  Voice_140536_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_140537_AwakerVoiceContent = {
    Text = "ผู้พิทักษ์ การเชื่อมต่อ ร่างตื่นรู้ เป็นความสัมพันธ์ที่เธอบอกฉันใช่ไหม รู้สึกได้ว่าจิตวิญญาณของสองคนเชื่อมต่อกัน... ผ่านเส้นใยสีเงิน? อะไรประมาณนั้น อืม—— รู้สึกว่าอะไรๆ ก็ยากจะเข้าใจไปหมดเลยนะ..."
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "ใช้เลือดเนื้อขนส่งเมล็ดพันธุ์เหรอ? อืม~ เป็นอย่างนั้นเหรอ สนใจแกะของเธอนิดหน่อยนะ"
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "เรื่องทั่วไป：เกี่ยวกับคนไทย"
  },
  Voice_140538_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「ไทอีส」"
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "วิกฤตบางอย่างที่คุกคามโลกนี้ ความมืดที่จะทำให้การดำรงอยู่สูญสลาย ใช่ไหม? ฉันรู้นะ ได้ยินเรื่องมากมายจากศาสตราจารย์ดอร์ลเลย"
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "ไม่ชอบคนหยาบกระด้าง ทำให้รู้สึกไม่สบายใจ..."
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "เผ่าพันธุ์ของเธอ ดูเหมือนก็อาศัยการแย่งชิงจากกลุ่มอื่นเพื่อให้ได้โอกาสขยายพันธุ์บนดาวดวงใหม่เหมือนกันนะ อืม~ เป็นอย่างนั้นเหรอ..."
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "เรื่อยเปล่า: เกี่ยวกับวินเคิล"
  },
  Voice_140541_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับ「เวินเคอร์」"
  },
  Voice_141963_AwakerVoiceContent = {
    Text = "เด็กดี."
  },
  Voice_141963_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·2"
  },
  Voice_141964_AwakerVoiceContent = {Text = "เอ้!"},
  Voice_141964_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·สาม"
  },
  Voice_141965_AwakerVoiceContent = {Text = "อืม!"},
  Voice_141965_AwakerVoiceTitle = {
    Text = "ถูกโจมตี·ห้า"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "น่าเสียดายจริงๆ, เมื่อใดที่คุณเปลี่ยนใจ, คุณรู้ว่าต้องหาฉันได้ที่ไหน."
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_143501_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_143502_AwakerVoiceContent = {
    Text = "น่ารำคาญ..."
  },
  Voice_143502_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_143503_AwakerVoiceContent = {
    Text = "ผิวหนัง, กล้ามเนื้อ, เส้นประสาท, กระดูก, ทั้งหมดจะถูกสร้างขึ้นใหม่, กลับมาสมบูรณ์แข็งแรง, กลับมาเปี่ยมชีวิตชีวาอีกครั้ง."
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_143503_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "เบื้องหน้ามหาสมุทร, ไม่มีศัตรูใดที่ทำลายไม่ได้!"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = "งานเลี้ยง, การไล่ล่า, ที่พักพิง?\nสวดภาวนาต่อข้า น้ำทะเลที่เก่าแก่ที่สุดจะบอกชื่อของข้าแก่เจ้า.\nข้าคือเจ้าแห่งเหวลึก, ปอนทอส."
  },
  Voice_143505_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_143506_AwakerVoiceContent = {
    Text = "โอโฮ, คิดถึงช่วงเวลาในเอโปยันส์อยู่ใช่ไหม...\nมันอยู่ในร่างกายนี้, ยินดีต้อนรับคุณกลับมาเสมอ."
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "แม้ข้าจะไม่ได้ทำเช่นนั้น, หากวันใดเจ้าได้ยินเสียงน้ำทะเลและเสียงกระพือปีกในหู, อย่าวิตก, นั่นเป็นเรื่องปกติ."
  },
  Voice_143507_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_143508_AwakerVoiceContent = {
    Text = "มอบประสาทสัมผัสของเจ้ามาให้, แล้วสำนึกผิดชั่วนิรันดร์ในเหวลึก!"
  },
  Voice_143508_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_143509_AwakerVoiceContent = {
    Text = "ฉันชอบคนหนุ่มสาวที่มีชีวิตชีวา, น่าเสียดาย, มิซากะควบคุมการสังสรรค์เข้มงวดเกินไป, แม้แต่สนามล่าสัตว์ที่ดีพอก็ยังไม่มี.\nยิ่งไปกว่านั้น, ข้างในยังมีสิ่งสกปรกที่กล้าเดินอวดโฉมต่อหน้าธารกำนัล แถมยังแขวนป้ายตำแหน่งศาสตราจารย์อีก."
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_143510_AwakerVoiceContent = {Text = "อึก!"},
  Voice_143510_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_143511_AwakerVoiceContent = {
    Text = "ฉันทำมากขนาดนี้, คุณยังไม่ยอมเรียกฉันว่าลุงอีกสักครั้ง, ช่างน่าปวดหัวจริงๆ."
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "ไม่ต้องรีบ, ความมืดในส่วนลึกที่สุดของมหาสมุทรจะกลืนกินพวกเจ้าอยู่ดี."
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "คุกเข่าลง, จงเป็นเสบียงของเอโปยันส์."
  },
  Voice_143514_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·สาม"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "สำหรับสิ่งที่เลือกฉัน... บอกได้แค่ว่าทั้งเป็นมิตรและโหดร้ายในเวลาเดียวกัน.\nจะตกลงที่ไหนนั้นขึ้นอยู่กับอารมณ์ทั้งสิ้น, แน่นอนว่าจะช่วยให้คุณรอดพ้นจากอันตราย, แต่ที่นั่นจะเป็นอันตรายอีกอย่างหนึ่งหรือไม่, นั่นไม่ใช่สิ่งที่ต้องคิดในระหว่าง「การเดินทาง」ครั้งนี้.\nช่างน่าสนใจ, ช่างคาดเดาไม่ได้, ฉันกำลังพิจารณาที่จะสืบทอดประเพณีนี้ต่อไป."
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_143515_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "ฉันมีความสัมพันธ์พิเศษบางอย่างกับเอโปยันส์, หรือจะพูดว่า, ฉันคือเอโปยันส์, เอโปยันส์ดำรงอยู่ผ่านฉัน, มีอยู่ได้ด้วยร่างกายของฉัน."
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับเอโปยันส์"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "เงยหน้าขึ้น, เปิดเผยลำคอของเจ้ามา."
  },
  Voice_143517_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_143518_AwakerVoiceContent = {
    Text = "ลบความทรงจำ, ลบการมีอยู่. ช่างคุ้นเคย... คุณเข้าใจความหมายของฉัน, แม้จะมาจากแหล่งกำเนิดที่ต่างกัน แต่ดูเหมือนพวกท่านจะเติบโตจากความมืดมิดเสมอ."
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "พวกเจ้าไม่ควรโง่พอที่จะล่วงล้ำศักดิ์ศรีของข้า."
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_143520_AwakerVoiceContent = {
    Text = "อ่อนแอจริงๆ"
  },
  Voice_143520_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_143521_AwakerVoiceContent = {
    Text = "ณ เอโปยันส์, งานรื่นเริงจะไม่มีวันหยุด, และศัตรูของเอโปยันส์ก็จะไม่มีวันได้สงบสุขเช่นกัน."
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_143521_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = "อ๋อ, ฉันเข้าใจความสั่นสะท้านของคุณดี แต่มันไม่จำเป็นเลย เพื่อนหนุ่มของฉัน.\nจงยอมรับความกลัวต่อความธรรมดาและการถูกกัดกร่อน, มองดูฉัน, คุณจะเข้าใจว่าคุณมีทางเลือกอื่นเสมอ."
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_143522_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = "ถูกต้อง, ฉันรู้ว่าภัยพิบัตินั้นไม่ได้เกิดจากการสั่งการโดยตรงของเขา, แค่เป็นเรื่องบังเอิญระหว่างการสนุกสนาน, แต่นั่นยิ่งทำให้ฉันอยากฆ่าเขามากขึ้นเท่านั้น.\nหมอกดำนั้นอย่าได้อยู่คนเดียว, และอย่าให้ฉันจับได้."
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "พวกคนปลาเหนียวๆ เหล่านั้นไม่ใช่เพื่อนของฉัน แต่เป็นศัตรูของฉัน. แปลกใจไหม? มหาสมุทรไม่เคยเป็นของพวกมันตั้งแต่แรก."
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_143524_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "จงคงอยู่ที่นี่ชั่วนิรันดร์!"
  },
  Voice_143525_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_143526_AwakerVoiceContent = {
    Text = "พร้อมแล้วหรือยัง, บรรดาเหยื่อ!"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "จิตวิญญาณก่อให้เกิดร่างกายใหม่, ร่างกายถูกเติมเต็มด้วยสติปัญญาที่ไม่สลักสำคัญ, แล้วบรรดาปัจเจกที่งดงามและมีชีวิตชีวาเหล่านั้นจะมารวมกันชั่วนิรันดร์ในที่แห่งเดียว.\nยังจำที่ข้าพูดได้ไหม, ส่วนลึกที่สุดของมหาสมุทรรองรับทุกสิ่ง...และเก็บรักษาทุกสิ่งไว้."
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_143527_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "ฝันร้าย, สกัดกั้นพวกมันไว้."
  },
  Voice_143528_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_143529_AwakerVoiceContent = {
    Text = "หวังว่าสิ่งเล็กๆ พวกนี้จะไม่กินจนเจ้าหมดตัว, เจ้าก็รู้นะ, การเลี้ยงดูครอบครัวใหญ่ๆ นั้นไม่ใช่เรื่องง่ายเลย."
  },
  Voice_143529_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_143530_AwakerVoiceContent = {
    Text = "ในกาลครั้งหนึ่งนานมาแล้ว ก่อนที่แผ่นดินจะลอยขึ้นเหนือมหาสมุทร, ดาวดวงนี้ได้ปลุกวิญญาณพิเศษบางอย่างขึ้นมา. ทรงพลัง, ยิ่งใหญ่, ไม่อาจการสอดแนมได้.\nพวกท่านไม่อาจถูกนิยามว่าเป็นปฏิปักษ์หรือมิตร, มนุษย์ก็เหมือนสิ่งมีชีวิตนับไม่ถ้วนในอดีต, ไม่มีความสำคัญสำหรับพวกท่าน, จะถูกปัดทิ้งเหมือนฝุ่น หรือจะได้รับการปกป้องพร้อมกับดินแดน."
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_143530_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "มีแค่ความชราเท่านั้นที่เป็นการผจญภัยที่คุณต้องเผชิญคนเดียว, เป็นทั้งเพื่อนที่ดีที่สุดและศัตรูที่น่ากลัวที่สุดของคุณ, แสงสว่างของเอโปยันส์จะขับไล่มันออกไปจนหมดสิ้น... แค่ความทรงจำบางอย่างที่ไม่สำคัญ, คุณไม่จำเป็นต้องถูกยึดติดกับมัน."
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_143531_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "ละทิ้งภาพลวงตาแห่งการหลบหนีเสียเถิด."
  },
  Voice_143532_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "เจ้าจะกลายเป็นผงเถ้าสีขาวซีด."
  },
  Voice_143533_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_143534_AwakerVoiceContent = {Text = "ฮ่อ!"},
  Voice_143534_AwakerVoiceTitle = {Text = "ตี"},
  Voice_143535_AwakerVoiceContent = {
    Text = "ฉลาดมากเลยนะ เด็กน้อย, ผู้ศรัทธาของมอนสเตอร์ต่างถิ่นมักโง่พอที่จะโยนศพลงทะเล, นั่นไม่ถือเป็นของขวัญหรอก, ใช่ไหม?"
  },
  Voice_143535_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_143536_AwakerVoiceContent = {
    Text = "เจ้าถูกจับตามองแล้ว."
  },
  Voice_143536_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·2"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "แม้จะไม่อยากยอมรับ, บางครั้งที่นานๆ ครั้ง, ฉันรู้สึกว่าความชราไม่ใช่สิ่งเดียวที่เวลานำมา แต่เป็นเพียงสัญลักษณ์อย่างหนึ่ง.\nดังนั้น, ฉันจึงยอมให้มันดำรงอยู่บนตัวฉัน. แน่นอน—เพียงแค่รูปลักษณ์ภายนอกเท่านั้น."
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "การสวดมนต์นั้นได้ผล, ลองนึกภาพดูสิ, แม้แต่แมลงที่เรียงตัวเป็นอักษรรูนต่อหน้าคุณ, คุณก็ยังจะพิจารณาตอบสนองต่อคำร้องของมัน."
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_143539_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = "ฮ่าๆๆๆ, โอเค, อย่าทำสีหน้าแบบนั้นเลย, เพื่อนน้อยของฉัน.\nนั่นแค่ธรรมเนียมที่พวก「เทพเจ้าเก่า」ต้องปฏิบัติตาม, ส่วนคุณ, ไม่ต้องการเงื่อนไขหรือราคาที่ต้องจ่ายใดๆ ทั้งนั้น, ฉันจะยืนอยู่ข้างคุณตลอดไป."
  },
  Voice_143540_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_143540_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = "ฮึ, มอนสเตอร์ตัวน้อยที่สมคบกับมอนสเตอร์ต่างถิ่น.\nมีสิ่งโง่เขลาบางอย่างกล้าเอาฉันกับมันไว้บนแท่นบูชาเดียวกัน, ช่างเป็นการดูหมิ่นอย่างแท้จริง!"
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับธูลู"
  },
  Voice_143554_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ตูรู」"
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "ศัตรูของศัตรูคือมิตร, ถ้ามีโอกาส, ฉันไม่รังเกียจที่จะทำดีลแย่งของเล่นโปรดของคู่อาฆาตไป."
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับไรเกอร์"
  },
  Voice_143555_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「เลค」"
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "โอ้? อยากมาต่อสู้กับฉันที่นี่หรือ? ฉันไม่ขัดข้อง."
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "มากกว่านี้ ให้พละกำลังแก่ฉันมากกว่านี้!"
  },
  Voice_146159_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_146160_AwakerVoiceContent = {
    Text = "ฉันไม่ชอบคนที่ไม่บริสุทธิ์ เพราะความไม่บริสุทธิ์มักหมายถึงความอ่อนแอ. แต่คุณเป็นข้อยกเว้น. ฉันเคยคิดว่าคนที่แบกรับสิ่งต่างๆ มากมายไว้บนบ่า ไม่สามารถก้าวไปข้างหน้าได้ไกลกว่านี้. แต่เส้นทางที่คุณเดินอยู่ แม้แต่ฉันก็ยังรู้สึกประหลาดใจ... บางที คนที่เดินบนเส้นทางที่แตกต่างออกไป อาจเป็นเป้าหมายที่คู่ควรแก่การบ่มเพาะและท้าทายมากกว่า. คุณว่าไหม, 「คู่ต่อสู้」?"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "วาฬท่องเที่ยวแห่งท้องฟ้าดาว จงกลืนกินทุกสิ่ง!"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "จงภูมิใจที่ได้เป็นคู่ต่อสู้ของฉัน!"
  },
  Voice_146162_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_146163_AwakerVoiceContent = {
    Text = "ให้ห้วงดาว เป็นพยานแห่งการล่มสลาย!"
  },
  Voice_146163_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_146164_AwakerVoiceContent = {
    Text = "ยังไม่พอ ไม่พอเลยสักนิด..."
  },
  Voice_146164_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_146165_AwakerVoiceContent = {Text = "หึ"},
  Voice_146165_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_146166_AwakerVoiceContent = {Text = "หึ"},
  Voice_146166_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_146167_AwakerVoiceContent = {
    Text = "ฉันไม่แคร์ต่อการสูญสลายของสิ่งใดทั้งนั้น แต่ฉันจะไม่ยอมให้มันกลายเป็นอุปสรรคบนทางแห่งการแสวงหาพละกำลังของฉัน."
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "เพราะการทำลายล้างที่หลีกเลี่ยงไม่ได้ที่กำลังจะมาถึง ก็เริ่มสงสัยในความหมายของการมีอยู่ของทุกสิ่ง... ฉันไม่มีความสนใจที่จะเข้าร่วมการโต้เถียงไร้สาระแบบเด็กๆ เช่นนี้. ไม่แคร์ต่อการล่มสลาย และไม่จำเป็นต้องบันทึกไว้. พละกำลังในตัวมันเอง คือความหมาย."
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับดอลล์: มลายทราม"
  },
  Voice_146168_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างกายที่ตื่นขึ้น 「เมลต์·ดอร์」"
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "ในดวงตาของคุณ ฉันเห็นเจตจำนงที่ไม่ได้เป็นของที่นี่ มันไม่บริสุทธิ์ แต่แข็งแกร่งเพียงพอ มาเลย พิสูจน์ให้ฉันเห็นว่า คุณอาศัยพละกำลังและความปรารถนาเช่นใด จึงยืนอยู่ตรงหน้าฉันได้."
  },
  Voice_146169_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_146170_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_146170_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_146171_AwakerVoiceContent = {
    Text = "จงภูมิใจที่ได้เป็นคู่ต่อสู้ของฉัน!"
  },
  Voice_146171_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_146172_AwakerVoiceContent = {
    Text = "กลิ่นอายของเคออส คิดถึงจริงๆ... นับตั้งแต่ช่วงเวลาที่ถือกำเนิดจากสุญญตาแห่งนี้ สิ่งที่ฉันแสวงหา ไม่เคยเปลี่ยนแปลงเลย."
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_146172_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "อยากท้าทายฉันหรือ? ฉันชื่นชมความกล้าหาญของคุณ และยินดีมอบเกียรติแห่งการพ่ายแพ้ให้แก่คุณ. นี่คือความเคารพของฉันที่มีต่อ「ผู้พิทักษ์แห่งมิซากะ」."
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_146173_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "ในยูโทเปียอันเป็นเท็จแห่งนี้ เต็มไปด้วยคนอ่อนแอ, คนขี้ขลาด และคนโง่ที่หลอกตัวเอง. แต่ก็ไม่เป็นไร ที่นี่สามารถมอบศัตรูที่กระตุ้นฉันได้มากที่สุด แค่นั้นก็เพียงพอแล้ว."
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "มีพละกำลังอันยิ่งใหญ่อยู่ในมือ แต่กลับกักขังความสามารถของตัวเองไว้ในความฝันอันยาวนานข้างใน เพราะความกลัว, ความรู้สึกผิด และความเหนื่อยล้า ช่างสิ้นเปลืองเสียจริง."
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับธูลู"
  },
  Voice_146175_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ตูรู」"
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "อ่อนแอเกินไป."
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "ผนึกหลวมลงบ้างแล้ว... พละกำลังจากห้วงลึกของห้วงดาวกำลังพุ่งขึ้นมา. ฉันไม่ได้รู้สึกแบบนี้มานานมากแล้ว..."
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_146177_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "วาฬท่องเที่ยวแห่งท้องฟ้าดาว จงกลืนกินทุกสิ่ง!"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_146179_AwakerVoiceContent = {
    Text = "...สะใจ."
  },
  Voice_146179_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_146180_AwakerVoiceContent = {
    Text = "ฉันล่องลอยอยู่ในห้วงดาวมานับไม่ถ้วนปี และส่งผู้ที่อ้างตนว่าเข้มแข็งลงสู่ห้วงเหวด้วยมือของตัวเอง. คุณมีความพิเศษในแบบของคุณเอง แต่หากต้องการเดินเคียงข้างฉัน ก็จงเรียนรู้ที่จะเงยหน้าขึ้นต่อหน้าฉันก่อน. เพื่อนร่วมทางที่ขี้ขลาด ฉันไม่ต้องการ."
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_146180_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "กล้าหาญ, ขี้ขลาด, เข้มแข็ง, แตกหัก... ฮ่า ไม่, ฉันไม่แคร์ว่าคู่ต่อสู้จะเป็นคนแบบไหน. ไม่ว่าจะเป็นคู่ต่อสู้ที่มีความสามารถแบบใด ก็ทำให้ฉันรู้สึกพึงพอใจได้ทั้งนั้น."
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "อ่อนแอ. ในโลกนี้มีสิ่งน่าขยะแขยงมากมายนับไม่ถ้วน แต่ความอ่อนแอคือบาปกำเนิดที่น่าอับอายที่สุด. ทุกคนมาสู่โลกนี้พร้อมกับดาบ ไม่มีใครมีสิทธิ์ปล่อยมือหลวมก่อนถึงจุดสิ้นสุด แล้วก้าวขึ้นสู่สนามรบที่ถูกกำหนดไว้พร้อมความคิดแห่งความพ่ายแพ้. นั่นคือการดูหมิ่นทั้งคู่ต่อสู้และตัวเองด้วย."
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "ซากดาวที่เน่าเปื่อย จงตื่นขึ้น——"
  },
  Voice_146183_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_146184_AwakerVoiceContent = {
    Text = "ฮึ... คู่ต่อสู้ที่น่ากระตุ้นใจ. ครั้งหน้า ฉันจะไม่ยั้งมืออีกแล้ว."
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "กระดูกของฉันกำลังสั่นสะเทือนด้วยความปีติยินดี... ความพยายามที่คุณทุ่มเท ฉันได้เห็นแล้ว นี่คือหลักฐานที่พิสูจน์ว่าคุณมีสิทธิ์ยืนเคียงข้างฉัน, ผู้พิทักษ์."
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_146185_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "ฮึ... คุณมองเห็นได้ชัดเจนมาก ผู้พิทักษ์. พันธนาการแห่งพละกำลัง มีไว้เพื่อทุบทำลายทิ้ง!"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_146186_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_146187_AwakerVoiceContent = {Text = "หืม?"},
  Voice_146187_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_146188_AwakerVoiceContent = {Text = "หืม?"},
  Voice_146188_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_146189_AwakerVoiceContent = {
    Text = "อยู่ข้างหน้านั้นแล้ว... จุดสิ้นสุดของพละกำลังที่ฉันแสวงหามาตลอดชีวิต... ผู้ที่ติดตามฉันมาตลอดและนำพาฉันมาถึงที่นี่ คือคุณ. ฉันตื่นเต้นมากที่จะได้เป็นพยานต่อวันแห่งจุดสูงสุดนั้นร่วมกับคุณ!"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_146189_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "บางทีคำพูดของฉันก่อนหน้านี้อาจเบาเกินไปสักหน่อย... ความเร็วในการเติบโตของคุณ รวมถึงพละกำลังที่ซ่อนอยู่ในตัวคุณ ล้วนเกินความคาดหมายของฉัน. ฉันเคยเห็น HP มากมายที่ถูกทำลายล้างไปตามกาลเวลา แต่คุณ... แตกต่างอย่างแท้จริง. ฉันอยากรู้มากว่า ความลับของพละกำลังในตัวคุณนั้น มาจากที่ใดกันแน่?"
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_146190_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "ปากแห่งนรก จงเปิดออกเพื่อฉัน!"
  },
  Voice_146192_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_146193_AwakerVoiceContent = {
    Text = "อา ฉันเห็นแล้ว... จุดสิ้นสุดของพละกำลัง ไม่เคยมีอยู่จริง... ความท้าทายที่แท้จริง เพิ่งเปิดรับฉันในตอนนี้! คือคุณที่พาฉันมาถึงที่นี่ และทำให้ฉันมองเห็นทุกสิ่งอย่างชัดเจน. ในไม่ช้า ฉันจะนำนักรบที่สมบูรณ์แบบยิ่งกว่าเดิมมาปรากฏต่อหน้าคุณ. หวังว่าในเวลานั้น ฉันจะได้เห็นคุณที่สมบูรณ์แบบยิ่งขึ้นเช่นกัน, 「คู่ต่อสู้」ของฉัน."
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_146193_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "แค่กลอุบายเล็กน้อย."
  },
  Voice_146194_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_146195_AwakerVoiceContent = {
    Text = "พละกำลังเดือดพล่านอยู่ในไขกระดูก!"
  },
  Voice_146195_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_146196_AwakerVoiceContent = {
    Text = "กลืนกินให้สิ้นซาก!"
  },
  Voice_146196_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_146197_AwakerVoiceContent = {
    Text = "ความเมตตา, ความอ่อนแอ, ความสับสน... ดวงตาของคุณเต็มไปด้วยสิ่งเจือปน. คนที่ไม่บริสุทธิ์เพียงพอ จะไม่มีวันเข้าใจได้ว่าพละกำลังคืออะไร."
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_146197_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "พละกำลังที่แท้จริงนั้น ไม่เคยเกี่ยวข้องกับการแก้แค้นหรือการ์เดียนเลย. พละกำลังก็เพียงแค่พละกำลัง, อีกตัวตนหนึ่งของฉันไม่เคย「จริงๆ」เข้าใจความจริงข้อนี้. นั่นคือแหล่งกำเนิดที่ทำให้เธอไม่เข้มแข็งพอ."
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับโลทัน"
  },
  Voice_146198_UnlockDesc = {
    Text = "ปลดล็อกหลังจากรับร่างกายที่ตื่น「โรแทน」"
  },
  Voice_146199_AwakerVoiceContent = {
    Text = "ฟังให้ดี ฉันจะพูดเพียงครั้งเดียว：\nฉัน, โลทัน, ยอมรับว่าคุณคือคู่ต่อสู้ที่คู่ควรแก่การเฝ้ารอ.\nก่อนที่คุณจะไปถึงจุดสูงสุด ฉันจะเป็นดาบที่คุณไว้วางใจได้มากที่สุด. คำสัญญาและความภักดีของฉันไม่เกี่ยวกับอารมณ์. คุณคือคู่ต่อสู้ที่ทำให้ฉันพึงพอใจที่สุด ฉันจะไม่มีวันยอมให้คุณล้มลงระหว่างทาง."
  },
  Voice_146199_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_146199_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "มาเลย สังหารฉัน หรือไม่ก็ถูกฉันสังหาร."
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "ปากแห่งนรก จงเปิดออกเพื่อฉัน!"
  },
  Voice_146201_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_146521_AwakerVoiceContent = {
    Text = "ทุกสิ่งแตกสลายต่อหน้าคมกระดูก!"
  },
  Voice_146521_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "พละกำลัง...ไม่มีวันสิ้นสุด!"
  },
  Voice_147047_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·2"
  },
  Voice_147493_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_147493_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "(เสียงร้องที่แหบและนุ่มนวล)"
  },
  Voice_147494_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_147495_AwakerVoiceContent = {
    Text = "ผู้ชม ต้องการผู้ชมมากกว่านี้.."
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "ทราย... ทะเลทรายสีขาว... ที่นี่อันตรายมาก รีบหนีไปกับฉันเร็ว"
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_147496_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "ฉันยังจำแผนที่ของบ้านใหม่ได้ สีสันสดใส สวยงามมาก นี่คือสถานที่ที่เราควรไป เราสามารถร้องเพลง และรู้สึกถึงความสุขได้"
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_147498_AwakerVoiceContent = {Text = "อ้า"},
  Voice_147498_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_147499_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_147499_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_147500_AwakerVoiceContent = {
    Text = "เอ๋...?"
  },
  Voice_147500_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_147501_AwakerVoiceContent = {
    Text = "นั่นคือ...เสียงแห่งดาราจักร..."
  },
  Voice_147501_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_147502_AwakerVoiceContent = {
    Text = "เธอกลับมาอีกแล้วเหรอ เหมือนทุกครั้ง นั่งข้างฉันแล้วรอไปพร้อมกันเถอะ รออะไร? ก็แค่รอ นั่นแหละ"
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "การซ้อมที่สมบูรณ์แบบ ฉันคิดว่าฉันพร้อมที่จะขึ้นเวทีแล้ว."
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_147503_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_147504_AwakerVoiceContent = {
    Text = "ตกลงไปเถอะ."
  },
  Voice_147504_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_147505_AwakerVoiceContent = {
    Text = "แด่ความร้างลาและความตาย"
  },
  Voice_147505_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_147506_AwakerVoiceContent = {
    Text = "ฉันไม่ใช่คนบ้า และไม่เคยรู้สึกเศร้าเลย โปรดอย่าเชื่อข่าวลือที่ไร้สาระ."
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "แปลกจริง พวกเขาดูเหมือนจะกลัวเสียงร้องของฉัน.."
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_147508_AwakerVoiceContent = {
    Text = "ชู่..."
  },
  Voice_147508_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_147509_AwakerVoiceContent = {
    Text = "ชุดการแสดงที่สวยงามจริงๆ ระยิบระยับ.."
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_147509_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_147510_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_147511_AwakerVoiceContent = {
    Text = "แสงสีของดวงดาวที่ยังคงเหลืออยู่จนถึงบัดนี้"
  },
  Voice_147511_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_147512_AwakerVoiceContent = {
    Text = "ร้องเพลงเถอะ."
  },
  Voice_147512_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_147513_AwakerVoiceContent = {
    Text = "การฝึกเสียงที่ถูกต้อง...? แต่ฉันพอใจกับเสียงของตัวเองในตอนนี้นะ"
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_147513_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_147514_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "เสียงดูเหมือนจะมีการเปลี่ยนแปลงบางอย่าง.."
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_147515_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "เป็นอย่างไรบ้าง เสียงร้องของฉันเพราะไหม?"
  },
  Voice_147516_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_147517_AwakerVoiceContent = {
    Text = "หลับให้สบาย.."
  },
  Voice_147517_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_147518_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_147519_AwakerVoiceContent = {Text = "ได้"},
  Voice_147519_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_147520_AwakerVoiceContent = {Text = "อ้า"},
  Voice_147520_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_147521_AwakerVoiceContent = {
    Text = "ขอบคุณ... ฉันควรจะพูดว่าขอบคุณไหม?"
  },
  Voice_147521_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_147522_AwakerVoiceContent = {
    Text = "ฮือ..."
  },
  Voice_147522_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_147523_AwakerVoiceContent = {
    Text = "ส่องประกายออกมาเลย"
  },
  Voice_147523_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_147524_AwakerVoiceContent = {
    Text = "ความรู้สึกที่ห่างหายไปนาน... ในที่สุดก็ได้กลับมาสู่เวทีอีกครั้ง ขอบคุณคุณ ผู้พิทักษ์"
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_147524_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "ขอโทษที่รบกวน... ช่วยปล่อยฉันลงจากต้นไม้ได้ไหม? ฉันจำไม่ได้ว่าทำไมถึงปีนขึ้นไป อาจจะเป็นเพราะว่าเมฆบนท้องฟ้าดูชวนให้นึกถึงบางสิ่ง..."
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "คนในเผ่าของฉันไม่เคยจากไป พวกเขาเพียงแค่ไปยังที่ไกลมาก ๆ"
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับชาวเผ่า"
  },
  Voice_147527_AwakerVoiceContent = {
    Text = "ได้ยิน?"
  },
  Voice_147527_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_147528_AwakerVoiceContent = {Text = "อ๋อ"},
  Voice_147528_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_147529_AwakerVoiceContent = {
    Text = "เธอดูเหมือนจะวนเวียนอยู่รอบตัวฉันตลอด... ฉันเข้าใจแล้ว เธอต้องเป็นแฟนเพลงของฉันแน่ๆ"
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_147529_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "ลาลาลา~ อะไรนะ ที่นี่มีภัยพิบัติที่จะทำลายโลกหรือ? อา... งั้นฉันต้องจัดแต่งผมให้ดี แล้วก็ต้องไปหาพี่สาว.."
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "ชู่... อย่าพูดนะ มีคนไม่ดีมาแล้ว พวกเขาจะมาจับฉันกับพี่สาวไป และยังไม่ให้พวกเราขึ้นเรือ.."
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับความปลอดภัย"
  },
  Voice_147532_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_147532_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "เมื่อฉันตื่นขึ้นมา ดาวเคราะห์กำลังถูกทำลาย ฉันเห็นท้องฟ้ายามราตรีถูกแยกออกเป็นเส้นๆ โลกกลายเป็นผืนผ้าใบที่ถูกแรงลมพัดเข้าใส่ ก่อนจะบิดเบี้ยว จากนั้นจึงถูกฉีกขาดและแตกสลาย."
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_147533_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "นี่คือโปสเตอร์พร้อมลายเซ็นของฉัน ที่นายพิกแมนวาดให้ฉัน ฉันมอบมันให้กับคุณ"
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับฟีนต์"
  },
  Voice_147534_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ปลุก「ฟีนต์」"
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "อืม อืม? อยากรู้มากเหรอ? คลังสมบัติของเจ้าแม่ไม่ใช่จะให้คนนอกดูได้ง่ายๆ นะ ถ้าอยากรู้ว่าข้างในอัดแน่นไปด้วยอะไร ทำไมไม่มาเข้าร่วมลัทธินางฟ้าเดี๋ยวนี้เลยล่ะ ฮิ้ว?"
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "เธอไม่เชื่อข้อสรุปของคาราบู? อ๊ะ อ๊ะ ปิดบังยากจริงๆ เลยนะ... ความจริงแล้วฉันเป็นลูกสาวนอกสมรสของโบเฮมอนด์ที่หกแห่งอาณาจักร@1 ต้องปลอมตัวใช้ชีวิตในโลกมนุษย์ แกล้งทำเป็นนางฟ้าเพื่อหนีการไล่ล่าของศัตรู... ฉันบอกความลับสำคัญที่สุดให้เธอแล้วนะ เธอจะไม่เชื่อฉันได้ยังไงล่ะ?"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_149668_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_149669_AwakerVoiceContent = {
    Text = "เจ็บจังเลย~"
  },
  Voice_149669_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_149670_AwakerVoiceContent = {
    Text = "กินลูกอมเยอะเกินไปเหรอ? ไม่ไม่ไม่ นี่คือความลับที่ทำให้เจ้าแม่ยิ้มได้ตลอดเวลานะ จะหยุดเพราะเรื่องเล็กน้อยอย่างฟันผุได้ยังไงล่ะ? ~~"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "มานี่เลย มายืนข้างๆ นางฟ้าได้เลย อะไรนะ? ทุกคนแบ่งกันกินเครื่องบูชาด้วยกัน? ...โอ้เคย ถ้านั่นเป็นกฎของมิซากะ... ฉัน... ฉันไม่มีข้อโต้แย้งใดๆ ทั้งนั้นนะ มาเลย ทุกคนมาสนุกด้วยกัน!"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_149671_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "อ๊ายยา ช่างเป็นลูกแกะที่ศรัทธาจริงๆ เลยนะ."
  },
  Voice_149672_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_149673_AwakerVoiceContent = {
    Text = "ต้องมากกว่านี้อีกนิด นางฟ้าถึงจะประทานพรให้นะ?"
  },
  Voice_149673_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_149674_AwakerVoiceContent = {
    Text = "พวกเจ้ายังอ่อนเกินไปนะ~"
  },
  Voice_149674_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_149676_AwakerVoiceContent = {
    Text = "พิธีบูชาครั้งนี้ยิ่งใหญ่กว่าทุกครั้งที่ผ่านมา และจำนวนเครื่องบูชาก็มากกว่าเดิม... อ๊ะ แน่นอนว่าไม่ใช่คนหรอกนะ ฉันเป็นนางฟ้าใจดี จะไม่ทำร้ายใครทั้งนั้น~"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_149676_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = "ผู้รักษาความลับ คุณพร้อมฟังคำพูดจากใจของคาราบูแล้วหรือยัง?\nคาราบูมาจากไหนนั้นไม่สำคัญเลย สิ่งสำคัญคือ คุณคือของขวัญล้ำค่าที่สุดที่ฟ้าประทานให้ฉัน คาราบูตัดสินใจแล้วว่าจะอยู่เคียงข้างท่านผู้มีบุญนี้ตลอดไป ตลอดไป\nคุณคิดว่านี่ก็เป็นส่วนหนึ่งของแผนเพื่อให้คุณหยุดสืบสวนใช่ไหม? ฮิ้ว ลองเดาดูสิ?\nอย่างไรก็ตาม เพื่อเป็นรางวัลที่พูดความจริงออกมา ขอลูกอมรสแอปเปิ้ลสักเม็ดได้ไหม?"
  },
  Voice_149677_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_149677_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_149678_AwakerVoiceContent = {
    Text = "ฮิฮิ~"
  },
  Voice_149678_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_149680_AwakerVoiceContent = {
    Text = "ไม่เป็นไรหรอก ครั้งหน้าให้ความสำคัญกับการปกป้องนางฟ้าก็จะไม่แพ้แล้วล่ะ~"
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "อย่าคิดจะหลอกฉัน!"
  },
  Voice_149682_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_149683_AwakerVoiceContent = {
    Text = "โอ้โห มีของถวายเยอะขนาดนี้เลยเหรอ... เอ้อ, ฮึ่มๆ ทำได้ดีมาก สมควรได้รับรางวัล! มานี่เลย นางฟ้าจะมอบจูบแห่งนางฟ้าให้! คิดอะไรอยู่นะ แน่นอนว่าจูบที่หน้าผากสิ!"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_149683_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "ขอบคุณทุกท่านที่ศรัทธาถวายสิ่งของ! เจ้าแม่ผู้เข้าอกเข้าใจจะสร้างรูปปั้นทองคำแท้ให้ท่านไว้ในวิหาร อ๊ะ แต่เพื่อให้รูปปั้นนั้นสะท้อนถึงท่วงท่าอันสง่างามและงดงามของท่าน ยังต้องหาของมาเพิ่มอีกสักหน่อยนะ~"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_149684_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "เธอเหรอ? ...เธอเป็นสมาชิกในคริสตจักรของเราที่ยังไม่ตื่นรู้ คาราบูจะรอคอยอย่างอดทนจนถึงวันที่เธอเข้าใจความจริงแท้ของโลก ถึงวันนั้น อย่าลืมถวายร่างกาย ความจงรักภักดี และทรัพย์สินแด่ประมุขแห่งศาสนจักรด้วยนะ ฮิ้ว."
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "ของในรายการ... ได้ครบแล้วเหรอ? ความมั่งคั่งของมิซากะนั้นหยั่งไม่ถึงจริงๆ... รู้งี้ฉันก็... อืม? ฉันบ่นอะไรอยู่นะ? แค่กำลังขอบคุณความใจกว้างของลอร์ดเดกสเตอร์เท่านั้นเอง ฮิฮิ~"
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_149686_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "สิ่งที่เกลียดที่สุด? แน่นอนว่าพวกพ่อมดที่ไม่มีจิตสำนึกเรื่องสัญญาสิ มีความลับจะบอกเธอแบบเงียบๆ ว่า จริงๆ แล้วพ่อมดทุกคนเป็นนักต้มตุ๋นทั้งนั้น คำทำนายและคำสาปทุกอย่างที่พวกเขาพูดล้วนมีไว้เพื่อหลอกให้เธอหมดตัว! ส่วนวิธีป้องกัน... แค่ให้เงินของเธอได้รับพรจากนางฟ้าก็พอ!"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "พบกันครั้งแรก ฉันคือนางฟ้าผิวซีดจากดินแดนไกลโพ้น สนใจจะรู้จักกันไหม? พรจากนางฟ้ามีความเข้มข้นต่างกันตามระดับค่าสมาชิกนะ ฮิฮิ~"
  },
  Voice_149688_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_149689_AwakerVoiceContent = {
    Text = "ในพิธีบูชาที่ผ่านมา นอกจากขั้นตอนการสักการะเจ็ดชั้นและการสาบานสามครั้งแล้ว บรรดาผู้ศรัทธายังจะสร้างวิหารใหม่เพื่อฉันเป็นพิเศษและถวายเครื่องบูชาอันอุดมสมบูรณ์อีกด้วย นี่คือรายการ!"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_149689_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "มาเลย นำสิ่งที่อยากปล่อยวางไปฝังไว้ในหิมะลึก..."
  },
  Voice_149690_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_149691_AwakerVoiceContent = {
    Text = "ได้ยินว่าเธอกำลังสืบเสาะเรื่องต้นกำเนิดของฉัน ฮิ้ว นั่นเป็นความลับของเจ้าแม่นะ แต่ถ้าเธอยืนกรานจะสืบสวน ในลัทธินางฟ้ามีชีวประวัติที่ฉันเขียนเองเก็บไว้ แค่ยื่นเงินใจหนึ่งแสนเหรียญก็อ่านได้แล้ว อยากลองไหม?"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_149691_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "ดีมากเลย ที่นี่มีเด็กๆ น่ารักมากมายและเงินช่วยเหลือค่าครองชีพที่ใจดีจนน่าตกใจ ด้วยพวกเขา ไม่ช้าก็เร็วฉันจะเก็บเงินค่าเดินทางไปทางตะวันออกได้ครบ..."
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "อย่าลืมมาสักการะเจ้าแม่นะ ฮิฮิ."
  },
  Voice_149693_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_149694_AwakerVoiceContent = {
    Text = "ขอโทษนะ ดินแดนของนางฟ้านั้นศักดิ์สิทธิ์มาก ไม่รับมนุษย์หมาป่าแปลกๆ... อะไรนะ มีกลิ่นโกหกในอากาศ? คงแค่จมูกเขาทำงานผิดปกติแน่ๆ?"
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "คุยเล่น：เกี่ยวกับไรเกอร์"
  },
  Voice_149694_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「เลค」"
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "อ้าว มีคนบอกว่าฉันเป็นนางฟ้าปลอม... โดนจับได้แล้วสินะ ฮิ้ว ฉันรู้ว่าเธอไม่ได้ใส่ใจหรอก ใช่ไหม?"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "คุยเล่น·เกี่ยวกับข่าวลือ"
  },
  Voice_149696_AwakerVoiceContent = {
    Text = "อืมม อร่อยจัง~"
  },
  Voice_149696_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_149697_AwakerVoiceContent = {
    Text = "วางใจได้~"
  },
  Voice_149697_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_149698_AwakerVoiceContent = {
    Text = "ลูกแกะที่หลงทางทั้งหลาย นางฟ้าจะมาชำระบาปของพวกเจ้า ฮิ~"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "ยังไม่ยอมแพ้อีกเหรอ? โอ้เคย งั้นให้คาราบูบอกเองเลยแล้วกัน ความจริงแล้วคาราบูเป็นลูกสาวของเทพธิดาอุมาปตีแห่งภูเขาหิมะสูงตระหง่านทางทิศตะวันออก... อืมม เธอบอกว่าเทพธิดาองค์นั้นมีแค่ลูกชายสองคนไม่มีลูกสาว? บันทึกเกี่ยวกับเทพเจ้ามักจะมีส่วนที่ขาดหายไปเสมอแหละ."
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_149699_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "เจิ้งเจิ้ง~ แสงสว่างของนางฟ้าส่องมาถึงตัวเจ้าแล้ว ไปเลย!"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "โอเค โอเค อย่าสืบต่อแล้วได้ไหม? เพื่อเป็นการชดเชยที่เธอหยุดพฤติกรรมล่วงเกินนี้อย่างว่าง่าย ฉันจะแอบแบ่งลูกอมที่มีค่าที่สุดให้เธอครึ่งหนึ่ง รู้ไว้เลยนะ บนสนามรบของกองทัพสงครามครูเสด ลูกอมหวานๆ นั้นหายากมากเลย."
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_149701_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "พรของคาราบูสามารถรักษาโรคทุกชนิดในโลกได้ แน่นอนว่ารักษาโรคระบาดสีดำนี้ได้ด้วย... แน่นอนว่าจริงสิ แค่เธอมีความศรัทธาและไว้วางใจคาราบูมากพอก็พอแล้ว ฮิ้ว."
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_149703_AwakerVoiceContent = {
    Text = "น่ารำคาญ!"
  },
  Voice_149703_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_149704_AwakerVoiceContent = {
    Text = "แสงสว่างของนางฟ้า~"
  },
  Voice_149704_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_149705_AwakerVoiceContent = {
    Text = "สักการะเจ็ดชั้น สาบานสามครั้ง ใช้มันแลกกับการอภัยโทษจากนางฟ้าเถิด!"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_150079_AwakerVoiceContent = {
    Text = "รู้สึกมันซะ!"
  },
  Voice_150079_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_150104_AwakerVoiceContent = {
    Text = "อ้าว โอเกียร์ปล่อยให้คุณเข้ามาได้ยังไง? ไม่ได้ตกลงกันไว้ว่าจะกันทุกคนออกไปเหรอ? คุณเป็นเจ้านายของเขา...? เด็กที่ไม่น่าไว้ใจช่างน่าปวดหัวจริงๆ เพื่องานชุมนุมครั้งนี้ ฉันทุ่มเทเตรียมการมาไม่น้อยเลยนะ งั้น... แบ่งของถวายที่ได้รับกันคนละครึ่ง แล้วคุณช่วยเมตตาฉันหน่อยได้ไหม?"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "คุยเล่น: เกี่ยวกับโอเกียร์"
  },
  Voice_150104_UnlockDesc = {
    Text = "เมื่อได้รับร่างกายที่ตื่นขึ้น「โอกีล」จะปลดล็อก"
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "รีบทำให้เสร็จเถอะ อย่าอยู่บนถนนนานเกินไป"
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "เขาเข้าร่วมกับคณะในช่วงที่ฉันหลับใหล ฉันกับเขาแทบไม่มีปฏิสัมพันธ์อะไรกันเลย \n แต่ได้ยินมาว่าเขาเป็นคนมาหาเราเอง อยากจะละทิ้งร่างมนุษย์และกลายเป็น「ผู้เหยียบทะเล」อย่างสมบูรณ์... ฮึ่ม อีกคนที่ถูกพละกำลังทำให้มัวเมาจนโง่งมงาย"
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเคคอส"
  },
  Voice_36679_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวนดำเนินการ」บทที่ 6 จึงจะปลดล็อก"
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "โกลิอัทไม่เคยเป็นลูกหมาที่ซื่อสัตย์เลย ไม่เข้าใจจริงๆ ว่าทำไมมิลียาห์มถึงได้ให้ความสำคัญกับเขาขนาดนี้... ถ้าไม่ถูกล่ามโซ่ไว้ คนแรกที่จะหนีไปก็คงเป็นเขา"
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับโกลิอัท"
  },
  Voice_36680_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวนดำเนินการ」บทที่ 6 จึงจะปลดล็อก"
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "ผู้เหยียบทะเลไม่ได้เกิดมาเป็นแบบนี้ตั้งแต่แรก เพื่อซ่อนตัวในกลุ่มคน ครึ่งแรกของชีวิตพวกเขาเหมือนมนุษย์ทั่วไป...\nเธอควรระวังไว้หน่อย อาจจะเป็นไปได้ว่าเจ้าของร้านเค้กที่เธอชอบที่สุด ก็เป็นหนึ่งในพวกเขานะ?"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับผู้เหยียบทะเล"
  },
  Voice_36681_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวนดำเนินการ」บทที่ 6 จึงจะปลดล็อก"
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "เพลงเรือที่เพี้ยนของฮิลีย์สเตอร์ อาหารจานเด็ดของกัปตันคือเบคอนตุ๋นกับปลาสด ผ้าห่มที่ถูกสายลมทะเลทำให้เหม็นคาวและแข็ง... แม้อันตรายและตึงเครียด แต่ช่วงเวลาหลายเดือนที่เราลี้ภัยอยู่ในทะเลกับพวกเขา ผมจะไม่มีวันลืมไปตลอดชีวิต"
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับ「เรือผี」"
  },
  Voice_36682_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวนดำเนินการ」บทที่ 6 จึงจะปลดล็อก"
  },
  Voice_36683_AwakerVoiceContent = {
    Text = "แม้ว่าทุกคนในโรงเรียนจะดูยุ่งอยู่แต่...\nแต่ที่นี่ มีความสงบสุขแบบที่ฉันไม่เคยสัมผัสมาก่อนเลย\nความรู้สึกของการรวมตัวเพื่อเป้าหมายเดียวกันและพยายามทำมันร่วมกัน...ฮึ ถือว่าไม่เลวนะ"
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับมหาวิทยาลัยมิซากะ·II"
  },
  Voice_36683_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวนดำเนินการ」บทที่ 6 จึงจะปลดล็อก"
  },
  Voice_36684_AwakerVoiceContent = {
    Text = "เตียงแข็งเกินไป อากาศหนาวเกินไป ชาดำยามบ่ายก็ชงออกมาเหมือนน้ำล้างหญ้า... ข้าน้อยมีเหตุผลไม่ชอบที่นี่เป็นพันข้อ \n แต่แค่เพียงเพราะ「เธอมีเธออยู่ที่นี่」 ข้าก็ไม่ถึงกับทนอยู่ไม่ได้หรอกนะ.."
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับผู้พิทักษ์·III"
  },
  Voice_36684_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวนดำเนินการ」บทที่ 6 จึงจะปลดล็อก"
  },
  Voice_36685_AwakerVoiceContent = {
    Text = "ขอบคุณ, ขอบคุณ... เอ๊ะ? ทำไมฉันต้องขอบคุณเธอด้วย? นี่, นี่มันชัดเจนอยู่แล้วไม่ใช่เหรอ! แน่นอนว่าเป็นเพราะทุกอย่างที่เธอทำให้ฉันในทะเล...\nเดี๋ยวนะ, ทำไมเธอยิ้ม? เธออยากเห็นฉันขายขี้หน้าใช่ไหม!"
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "เกร็ดเล่า·เกี่ยวกับผู้พิทักษ์·II"
  },
  Voice_36685_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวนดำเนินการ」บทที่ 6 จึงจะปลดล็อก"
  },
  Voice_36686_AwakerVoiceContent = {
    Text = "ฉันเคยคิดว่าระหว่างฉันกับเธอมีความผูกพันแบบครอบครัว...\nแต่หลังจากนั้น ฉันถึงรู้ว่าบางที ความอบอุ่นเหล่านั้นอาจเป็นเพียงความคิดฝ่ายเดียวของฉัน...\nส่วนเรื่องที่เธอจะทำยังไงกับเธอนั้น เป็นเรื่องของพวกคุณ แค่อย่าให้เธอมายุ่งกับฉันอีกก็พอ"
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับมิลียาห์ม II"
  },
  Voice_36686_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวนดำเนินการ」บทที่ 6 จึงจะปลดล็อก"
  },
  Voice_36687_AwakerVoiceContent = {
    Text = "รู้สึกแปลก... นี่มันรู้สึกแปลกมากหรือ?，\nปอดมันก็หยุดเต้นไปแล้ว แต่ทำไมร่างกายกลับร้อน... เฮ้คุณ มาลองว่าเอามือผมหน่อยสิ ดูซิ"
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับ「ร่างที่ฟื้นคืน」"
  },
  Voice_36687_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวนดำเนินการ」บทที่ 6 จึงจะปลดล็อก"
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "แม้ว่าข้าอาจไม่ได้เกิดในราชอาณาจักรเลโอ แต่โบสถ์ใหญ่คือสถานที่ที่ข้าได้รับชีวิตใหม่ ดังนั้น การถือว่าที่นี่เป็นบ้านเกิดของข้า จะมีอะไรผิดไปจากนี้เล่า?"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับบ้านเกิด"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "หลังจากที่โรคระบาดที่มองไม่เห็นได้แพร่กระจายมานานหลายปี เทพผู้เป็นบิดาก็ได้ยินคำอธิษฐานของข้าในที่สุด และประทาน 「พร」 นี้แก่ข้า ซึ่งสามารถต่อสู้กับความทุกข์ยากได้ มันสามารถมอบชีวิตให้จริงๆ แต่มันก็ต้องการการแลกเปลี่ยนเช่นกัน \n ข้าในฐานะผู้ปฏิบัติแทน ย่อมต้องแบกรับแทนผู้ที่ได้รับพรนั้น"
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับ「พร」"
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "สำหรับข้าแล้ว สถานะของร่างกายที่ตื่นขึ้นนี้เป็นพรจากพระผู้สร้างที่ประทานแก่วิญญาณในอ้อมกอด นี่คือชีวิตครั้งที่สอง และเป็นโอกาสในการแก้ไขความผิดพลาดในอดีต \n ข้าจะเดินตามทางของพระผู้สร้าง ทำหน้าที่ผู้แทนอย่างสุดความสามารถ เพื่อลดความทุกข์ให้มากยิ่งขึ้น"
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับ「ร่างที่ฟื้นคืน」"
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "ขออนุญาตแสดงความขอบคุณอีกครั้ง ผู้พิทักษ์ ท่านเคารพในความคิดเห็นของฉัน และช่วยเก็บรักษาความลับนี้ไว้ไม่ให้คณะกรรมการตรวจสอบเข้ามาแทรกแซง หากพวกเขาเข้ามา คงจะไม่อนุญาตให้ฉันทำหน้าที่รับใช้ในโบสถ์แห่งนี้ต่อไป"
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับผู้พิทักษ์·Ⅱ"
  },
  Voice_45156_UnlockDesc = {
    Text = "ปลดล็อกหลังผ่านบันทึกหน่วยปฏิบัติการพิเศษ「สีแห่งเลือด」"
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "เด็กคนนั้นมีความจริงใจ แน่วแน่ และใจดี เป็นวิญญาณที่สดใสและหายาก ครั้งสุดท้ายที่ฉันเห็นคนแบบนี้ ย้อนกลับไปในชีวิตแรกของฉันแล้ว"
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับโอกีล"
  },
  Voice_45157_UnlockDesc = {
    Text = "ปลดล็อกหลังผ่านบันทึกหน่วยปฏิบัติการพิเศษ「สีแห่งเลือด」"
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "การสูญเสียการมองเห็นไม่ได้หมายความว่าฉันจะกลายเป็นคนตาบอดไปตลอด พระบิดาได้ทรงให้ความมืดปรากฏตัวแก่ข้าพเจ้า ในขณะเดียวกันก็ทำให้ข้าพเจ้าสามารถมองเห็นแสงเรืองของวิญญาณได้"
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับการมองเห็น"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "ในตอนนั้น แม้ฉันจะได้รับ「พร」แต่ก็เป็นเพียงคนธรรมดาเท่านั้น คนที่ต้องทนทุกข์มีมากเหลือเกิน และคนที่ต้องการ「พร」ก็มากมาย ฉันปรารถนาจะช่วยพวกเขาทั้งหมดไว้ แต่สุดท้ายก็ทำไม่สำเร็จ\nนี่คือความเสียใจที่ยิ่งใหญ่ที่สุดของฉัน และเป็นความละอายที่ฝังลึกอยู่ในใจตลอดกาล"
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับชีวิตครั้งแรก"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "ภายในโบสถ์มีหลายคนเชื่อว่า “เปลวไฟสีขาว” ที่ถูกกล่าวถึงใน「คัมภีร์ศักดิ์สิทธิ์」หมายถึงแสงจันทร์：ทูตแห่งแสงจันทร์จะปรากฏจากแสงจันทร์และนำพาเราออกจากความทุกข์ยาก.\nแต่ข้ารู้ว่าเปลวไฟที่แท้จริงคือวิญญาณที่ลุกโชนอยู่ในใจของท่านและข้า."
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับ「เปลวไฟซีด」"
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "ที่จริงแล้ว การปกปิดตัวตนของข้าเป็นความประสงค์ของท่านอาร์คบิชอป ท่านไม่ได้อธิบายเหตุผลโดยละเอียด เพียงแค่เตือนข้าว่า แม้ในสถานที่บริสุทธิ์ที่สุดก็อาจมีเงามืดแฝงอยู่ การทำความดีก็ต้องระมัดระวังให้มาก\nแน่นอน สำหรับเธอนั้น ข้าไว้วางใจอย่างเต็มที่"
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "เกร็ดความรู้·เกี่ยวกับการปกปิดตัวตน"
  },
  Voice_45161_UnlockDesc = {
    Text = "ปลดล็อกหลังผ่านบันทึกหน่วยปฏิบัติการพิเศษ「สีแห่งเลือด」"
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "เพลงที่ฉันร้อง ช่วยคุณได้ไหม?"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "น่ารังเกียจ เขาเองก็เป็นแค่เด็กเหมือนกัน ทำไมพวกเธอถึงได้เคารพเขาขนาดนั้น! แสดงท่าทีแบบเดียวกันกับฉันบ้าง รู้ไหม!"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับตูรู"
  },
  Voice_4909_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ตูรู」"
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "เฮ้ คุณรู้ไหมว่าร่างกายที่ตื่นขึ้นคนอื่นๆ ปกติแล้วทำอะไรอยู่? อย่าเข้าใจผิดนะ ฉันไม่ได้อยากจะเป็นเพื่อนหรอก แค่อยาก... ใช่ ฉันแค่มาตรวจสอบดู!"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับชีวิตประจำวัน"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "แย่จริงๆ แย่จริงๆ แย่จริงๆ! ครั้งหน้าจะต้องเอาศพพวกนั้นไปให้แมงมุมกินให้ได้!"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_4912_AwakerVoiceContent = {
    Text = "ความไพเราะที่ยังหลงเหลืออยู่"
  },
  Voice_4912_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_4913_AwakerVoiceContent = {
    Text = "จังหวะ."
  },
  Voice_4913_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_4914_AwakerVoiceContent = {
    Text = "ความพยายามที่กล้าหาญ"
  },
  Voice_4914_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_4915_AwakerVoiceContent = {
    Text = "ไม่จำเป็นต้องรีบร้อนขนาดนั้น... มีอะไรที่ข้าพเจ้าสามารถช่วยท่านได้ไหม?"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_4916_AwakerVoiceContent = {
    Text = "กล้ามากจริงๆ"
  },
  Voice_4916_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_4917_AwakerVoiceContent = {
    Text = "(การซักถามอย่างสนใจ)"
  },
  Voice_4917_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_4918_AwakerVoiceContent = {
    Text = "ธรรมชาติคือสิ่งที่ประทานความเป็นเกียรติอันสูงสุดแก่ข้า คิดว่ามันไม่ใช่ตัวฉันใช่ไหม?"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_4919_AwakerVoiceContent = {
    Text = "ทำอะไร?"
  },
  Voice_4919_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_4920_AwakerVoiceContent = {
    Text = "ฉันทำได้ดีใช่ไหม? แล้วค่าตอบแทนล่ะ —— อะไรนะ ไม่มีอาหารกลางวันฟรีในโลกนี้หรอก!"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_4921_AwakerVoiceContent = {
    Text = "ไปให้พ้น!"
  },
  Voice_4921_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_4922_AwakerVoiceContent = {
    Text = "ระวัง!"
  },
  Voice_4922_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_4923_AwakerVoiceContent = {
    Text = "ชัยชนะที่งดงามจริงๆ... ฉันจะจารึกช่วงเวลานี้ให้เป็นนิรันดร์"
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "รู้สึกได้ถึงแหล่งที่มาของความไม่บริสุทธิ์......เข้าใกล้ตัวตนที่แท้จริงอีกก้าวหนึ่ง......อาาา! ให้ฉันฉีกโลกนี้ออกเป็นชิ้นๆ เลย!"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_4924_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "เรา...พร้อมแล้ว.โปรดสั่งการได้เลย,     ผู้พิทักษ์."
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_4925_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "ท่านผู้เจริญ ท่านเป็นคนใจดีจริงๆ น่าเสียดายที่ข้าไม่มีอะไรจะตอบแทนท่านได้ ข้าเป็นแค่คนไร้ค่าอย่างแท้จริง......"
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_4926_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "......ก้าวไปอีกก้าวหนึ่ง ก็จะสามารถแยกจาก「พวกเธอ」ได้อย่างสิ้นเชิงแล้วหรือ?"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_4927_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "เอ๊ะ ฉันยังมีชีวิตอยู่......คุณจะไม่ขโมยอวัยวะของฉันหรือจับฉันไปทดลองใช่ไหม?"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_4928_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "เชื้อชาติเดิมของเวินเค่มีความสามารถในการเข้าสู่สมองของสิ่งมีชีวิต ความตั้งใจจากดินแดนภายนอกหวาดกลัวเธอมาก แต่อย่างไรก็ตาม ตอนนี้เธอก็เป็นเพียงวิญญาณที่น่าสงสารซึ่งถูกขังอยู่ในเปลือกนอกเท่านั้น"
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเวินเค่อ"
  },
  Voice_4929_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับ「เวินเคอร์」"
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "ทุกสิ่งทุกอย่าง ไอจิสรู้สึกชอบมาก เมื่อถึงเวลาทานอาหาร ทุกคนล้อมโต๊ะและทำการสวดมนต์ก็ดี เวลาที่ผู้พิทักษ์ออกไปปฏิบัติภารกิจ และทุกคนรอคอยคุณกลับมาก็ดี... ในอากาศมักจะเต็มไปด้วยกลิ่นอายของความสุข... คนอย่างฉันสมควรได้รับสิ่งเหล่านี้หรือไม่?"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_4931_AwakerVoiceContent = {
    Text = "จมลงเถอะ"
  },
  Voice_4931_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_4932_AwakerVoiceContent = {
    Text = "บานเถอะ."
  },
  Voice_4932_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_4933_AwakerVoiceContent = {
    Text = "「ความไว้วางใจ」,     「เชื่อฟัง」,     「ทาส」,     「ความสัมพันธ์เชิงชู้สาว」,     「เคารพ」... โมดูลภาษาอยู่ในระหว่างการสร้างและเรียนรู้ใหม่ ยังไงก็ขอฝากผู้พิทักษ์ช่วยแนะนำด้วยครับ."
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_4933_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "เอริกาอยู่ในสถานะพักเครื่อง ตัวเครื่องจะเสร็จสิ้นการระบายความร้อนในอีก 1 ชั่วโมง 15 นาที <Del:หากต้องการเริ่มระบบ ก็แลกเปลี่ยนด้วยหัวใจของคุณ> จะเริ่มระบบฉุกเฉินหรือไม่?...กำลังตรวจสอบสิทธิ์... การตรวจสอบสิทธิ์ขั้นสูงสุดของผู้พิทักษ์เสร็จสิ้น สวัสดี ผู้พิทักษ์"
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_4934_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "ภารกิจสอบสวนมีดัชนีความอันตรายเฉลี่ยอยู่ที่ 7,     การสูญเสียทางการแพทย์เฉลี่ยอยู่ที่น้ำยาเสริมการหลอม 8 ขวด,     เวลาเฉลี่ยในการจัดการศพอยู่ที่สิบชั่วโมง.\nสรุป：งานของผู้พิทักษ์มีความอันตรายอย่างมาก,     กรุณาให้ความสำคัญกับความปลอดภัยระหว่างปฏิบัติการ."
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_4935_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "กำลังค้นหาโปรไฟล์ของอาจารย์: เอริกา เรย์ฟิลด์, อาจารย์ภาควิชาเครื่องกลและระบบอัตโนมัติเงินใจ, ถึงแก่กรรมแล้ว —— นี่ไม่ใช่สิ่งที่คุณต้องการค้นหาใช่ไหม? ได้ค่ะ, กำลังค้นหาคำหลัก「เอริกา」ใหม่"
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_4936_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "หากต้องการค้นหาข้อมูล กรุณาระบุชื่อไฟล์อย่างครบถ้วน ฟังก์ชันค้นหาแบบคลุมเครือยังไม่สามารถใช้งานได้ในขณะนี้"
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_4937_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_4938_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_4938_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_4939_AwakerVoiceContent = {Text = "อ้า"},
  Voice_4939_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_4940_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_4940_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_4941_AwakerVoiceContent = {Text = "อ้า"},
  Voice_4941_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_4942_AwakerVoiceContent = {
    Text = "พลังชาร์จเต็มแล้ว เตรียมพร้อมสำหรับการระเบิด"
  },
  Voice_4942_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_4943_AwakerVoiceContent = {
    Text = "พลังชาร์จเต็มแล้ว เตรียมพร้อมสำหรับการระเบิด"
  },
  Voice_4943_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_4944_AwakerVoiceContent = {
    Text = "ในอนาคต ไม่จำเป็นต้องมารบกวนการพักผ่อนขององค์หญิงแล้ว"
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "ฉันจะปกป้องคุณเหมือนที่ปกป้องทิงค์เทต."
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "ข้าไม่ใช่ใครที่สำคัญอะไร เพียงแค่เป็นหยดน้ำเล็กๆ ท่ามกลางผู้ศรัทธามากมาย... ขอเพียงแค่ได้รับใช้ท่านผู้นั้น ให้ท่านเหลียวมองข้าสักครั้ง ข้ายินดีถวายทุกอย่างทั้งกำลังและจิตใจของข้า.."
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับอดีต"
  },
  Voice_4946_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ตูรู」"
  },
  Voice_4947_AwakerVoiceContent = {
    Text = "มองฉัน!"
  },
  Voice_4947_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_4948_AwakerVoiceContent = {
    Text = "มองฉัน!"
  },
  Voice_4948_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_4949_AwakerVoiceContent = {
    Text = "...ก็ช่างเถอะ ตราบใดที่ไม่ต้องถูกรบกวนด้วยการบูชาอย่างบ้าคลั่งของพวกเขา ก็พอจะอยู่ร่วมกันได้"
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับผู้เหยียบทะเล"
  },
  Voice_4949_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างกายที่ตื่นขึ้น「มิลียาห์ม」「โกลิอัท」「เคคอส」「ซาน」「ฟาร์โรส」อย่างใดอย่างหนึ่ง"
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "ฉันเกลียดความรู้สึกมืดมนแบบนั้น มันเหมือนกับว่าภายในจิตใจถูกทำให้ว่างเปล่า ความรู้สึกที่ไม่ได้รับการเติมเต็มทำให้รู้สึกคันทั่วตัว.."
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "อย่า อย่า อย่า อย่า อย่า อย่า พูดถึง.."
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_4953_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_4953_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_4954_AwakerVoiceContent = {Text = "อืม!"},
  Voice_4954_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_4955_AwakerVoiceContent = {
    Text = "นักประวัติศาสตร์ที่กล้าอ้างว่าสวรรค์ได้ล่มสลายไปแล้ว พูดจาโอ้อวดอย่างไม่ละอายจนน่ารำคาญ... แต่ไม่เป็นไร คำพูดไม่อาจขัดขวางสวรรค์จากการฟื้นคืนสู่ความรุ่งโรจน์ได้"
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "ความจริงแล้ว... แอบบอกคุณนะ ฉันไม่ค่อยพอใจกับมอเตอร์ไซค์ปัจจุบันเท่าไหร่ — ไม่ใช่ว่าฉันไม่ชอบมัน! เพียงแต่ว่า ฉันรู้สึกว่า มันเหมือนขาดอะไรบางอย่างไป.."
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_4957_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_4957_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_4958_AwakerVoiceContent = {
    Text = "หั่นให้ละเอียด!"
  },
  Voice_4958_AwakerVoiceTitle = {
    Text = "ทักษะ·สอง·บ้าคลั่ง"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "ขอโทษ... ฉันไม่อยากให้เป็นแบบนี้เลย.."
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "ทักษะ·สอง·เศร้าใจ"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "(ครางด้วยความสนอกสนใจอย่างลึกซึ้ง)"
  },
  Voice_4960_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_4961_AwakerVoiceContent = {
    Text = "@1@2ปี นายวาลด์ ฟิลลิปส์, เคลราลค์ช์ และทาวี สามคนได้ร่วมกันก่อตั้งสถาบันมิซากะ จากนั้นผ่านการพัฒนามายาวนาน จึงได้ก่อกำเนิดมหาวิทยาลัยมิซากะในที่สุด<Del:คุกบ้านี่>"
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "ความยุติธรรม ความจงรักภักดี ความอดทน และวินัย ทั้งหมดนี้ได้ถูกตราตรึงในใจของฉันมานานแล้ว"
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "ฉันจะทำสิ่งที่คุณมอบหมายให้ดีที่สุด"
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "พ่อแม่ที่ไม่มีความรับผิดชอบขนาดไหน ถึงจะตั้งชื่อลูกสาวของตัวเองว่าโล่แห่งยักษ์หญิง? เธอบอกว่าเด็กคนนั้นไม่มีพ่อแม่เหรอ? ฮืม... การสนทนานี้ของเรา ไม่มีความจำเป็นที่จะให้เธอรู้หรอก"
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับไอจิส"
  },
  Voice_4964_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ไอจิส」"
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "ถ้าเบื่อล่ะก็ ทำไมไม่มาที่เขาวงกตแล้วมา“อยู่เป็นเพื่อนฉัน”ล่ะ ชีวิตไร้ความหวังของเธอกับเขาวงกตที่ไม่มีที่สิ้นสุดนั้น แทบจะไม่ต่างกันเลย！"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับเขาวงกต"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "ในช่วงเวลาที่ดอร์อยู่ ประสิทธิภาพของผู้ตรวจสอบเพิ่มขึ้นเฉลี่ย 78,312% แต่ในขณะเดียวกันก็มีคนจำนวนมากขึ้นที่จมอยู่ในภาวะซึมเศร้า อ้างคำพูดของเธอหนึ่งประโยค：ถ้าบางคนสามารถควบคุมคำพูดได้ โลกจะดำเนินไปอย่างราบรื่นมากขึ้น"
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับดอร์"
  },
  Voice_4966_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ดอร์」"
  },
  Voice_4967_AwakerVoiceContent = {
    Text = "จงปรากฏตัว!"
  },
  Voice_4967_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_4968_AwakerVoiceContent = {
    Text = "อย่างไร?"
  },
  Voice_4968_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_4969_AwakerVoiceContent = {
    Text = "ทำไมถึงมีคนไม่ชอบการผจญภัยล่ะ? ลึกเข้าไปในดินแดนลึกลับที่ไม่มีใครเคยไป เยือนสิ่งที่ไม่รู้จัก สร้างเรื่องราวของตัวเอง... น่าตื่นเต้นจริงๆ!"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับการผจญภัย"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "สวัสดีค่ะ ข้าคือหนิงเฟย่าจากเฟฟเฟอร์ ท่านได้มอบร่างกายนี้ให้ข้าสามารถหายใจได้อย่างอิสระ... ข้าควรทำอะไรเพื่อเป็นการตอบแทนท่านดีคะ?"
  },
  Voice_4970_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_4971_AwakerVoiceContent = {
    Text = "เมื่อครู่นี้ฉันเหมือนได้ยินเสียงร้องโหยหวนอย่างเจ็บปวดของพวกคนที่อ้างว่าเป็นเจ้านายของฉันอีกแล้ว——ช่างน่าฟังเหลือเกิน"
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_4971_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "สามารถไม่กินผักได้ไหม? แม้ว่าทิงค์เทตจะเคยบอกว่าห้ามเลือกกิน แต่ฉันไม่ชอบสีของพวกมัน.."
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "พระเจ้าผู้สร้างตรัสว่า สิ่งที่เป็นทุกข์ไม่ใช่สิ่งสร้างของข้า จงแบกรับและขจัดมันเสียเถิด ผู้แทนของข้า จงสร้างอาณาจักรที่ปราศจากทุกข์บนโลกนี้ เพื่อสิ่งนี้ข้ายินดีเสียสละทุกอย่าง รวมถึงชีวิตของข้าด้วย"
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_4973_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "ต่อหน้าคำสาปที่ทำลายล้างทุกสิ่ง ความทุกข์ยากอื่นๆ ล้วนจืดจางไป หากแม้ฉันไม่สามารถรับคำสาปแทนผู้อื่นได้ ก็จะพยายามอย่างเต็มที่เพื่อบรรเทาความเจ็บปวดให้พวกเขา"
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_4974_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "ในตอนนี้ ข้าเพียงพอแล้วหรือยังที่จะบรรเทาความเจ็บปวดบนตัวพวกเขา และปลอบประโลมวิญญาณของพวกเขา?"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_4975_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "เช่นนั้น ข้าจึงสามารถแบกรับความทุกข์ของสรรพสิ่ง และปูทางไปสู่ดินแดนที่ไม่มีความทุกข์สำหรับสรรพชีวิตทั้งมวล"
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_4976_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "ความอบอุ่นในวิญญาณ... ขอบคุณที่มอบสิ่งนี้ให้กับฉัน เปลวไฟซีด ด้วยพละกำลังนี้ บางทีฉันอาจจะสามารถปฏิบัติหน้าที่ของผู้แทนได้สำเร็จ และช่วยเหลือคนจำนวนมากขึ้น"
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_4977_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "ฉันกินได้มากขนาดนี้จริงๆ หรือ?"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_4978_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "หึหึ...นั่นไม่ใช่ความตาย แต่มันคืออนาคตของเธอ อนาคตของฉัน และอนาคตของโลกใบนี้"
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "ทิงค์เทต... เมื่อได้ยินเสียงร้องอันโหยหวนของเธอ อดไม่ได้ที่จะอยากเต้นตาม.."
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับทิงค์เทต"
  },
  Voice_4980_UnlockDesc = {
    Text = "หลังจากได้รับร่างกายที่ตื่นขึ้น 「ทิงค์เทต」แล้ว จะปลดล็อก"
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "การฝึกฝนที่ธรรมดาสามัญก็สามารถปลุกคุณค่าของสายเลือดได้หรือ? นี่เป็นสิ่งที่อยู่นอกเหนือความคาดหมายของข้า"
  },
  Voice_4981_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_4982_AwakerVoiceContent = {
    Text = "อาวุธใช้งานได้คล่องมือขึ้น"
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "อย่าคิดว่าแค่นี้ฉันจะขอบคุณเธอ พวกเรารับไม่ได้เด็ดขาด"
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_4984_AwakerVoiceContent = {Text = "อืม!"},
  Voice_4984_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_4985_AwakerVoiceContent = {
    Text = "ผู้ชายคนนั้น... เฮ้ รอฉันก่อน การพนันของเรายังไม่จบใช่ไหม?"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับคนอื่นๆ"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "ฉันชอบเครื่องบันทึกของสถาบันมาก ถ้าสามารถดัดแปลงให้เป็นเวอร์ชั่นพกพาที่เตือนฉันแบบเรียลไทม์ว่าลืมอะไรไปก็คงจะดี.."
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "ทั่วทุกหนแห่งมีแต่แมลงตัวเล็กๆ... ไม่สิ แม้แต่แมลงตัวเล็กๆ ก็ไม่ใช่ เพียงแค่เศษขนมปังที่ไร้ค่าเท่านั้น ซึ่งจะมอบสารอาหารเพื่อการเสด็จมาของพระองค์"
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "เสบียงอยู่ที่นี่."
  },
  Voice_4988_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_4989_AwakerVoiceContent = {
    Text = "เสบียงอยู่ที่นี่."
  },
  Voice_4989_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_4990_AwakerVoiceContent = {
    Text = "อืม... แรงหน่อย ใช่แล้ว! ก็แบบนี้แหละ..."
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "ยังไม่ได้การตื่นรู้อย่างเต็มที่ ก็สามารถเอาชนะได้อย่างง่ายดาย."
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "อ้าว หมวกเอียงแล้ว... แบบนี้พอดีไหม? ดีจริงๆ!"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_4992_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "“ด้วยความสามารถเช่นนี้ ฉันยังคงเป็นมนุษย์อยู่จริงๆ หรือ?” ตั้งแต่เริ่มฝึกฝนการต่อสู้มา ฉันถามตัวเองทุกวันแบบนี้ ฉันรักโลกใบนี้ แม้มันจะมืดหม่น สกปรก และไร้ความหมาย แต่การที่พวกคุณอยู่ที่นี่ทำให้มันเปล่งประกายเหมือนเพชรที่ซ่อนอยู่ในกองทราย\nครั้งหนึ่งฉันเคยกลัวว่า เมื่อพละกำลังของฉันเติบโตขึ้น ตำแหน่งของฉันในฐานะมนุษย์อาจเปลี่ยนไป... ตอนนี้ ฉันดีใจมากที่มีคุณอยู่เคียงข้าง ความเข้าใจระหว่างเรากำลังผูกฉันไว้กับโลกของมนุษย์แน่นหนา ในวันข้างหน้า ก็ขอฝากตัวด้วยนะ ผู้พิทักษ์"
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_4993_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "อา... คุณมีข้อกังวลก็เป็นเรื่องธรรมดา นี่เป็นความผิดของฉันเองที่ไม่ได้พิจารณาให้รอบคอบ ในฐานะคู่หู ฉันควรจะอธิบายให้คุณฟังตั้งแต่แรกแล้ว อย่างที่คุณเห็น ร่างกายของฉันมีบางอย่างที่แตกต่างจากคนปกติ ซึ่งอาจเกี่ยวข้องกับภูมิหลังของฉัน การบอกว่าไม่สงสัยเลยนั้น เป็นไปไม่ได้ใช่ไหม? แต่การที่ฉันได้มีที่พักพิงในสถาบันแห่งนี้ถือเป็นโชคดีของฉัน ดังนั้น ฉันจึงเลือกที่จะไม่เปิดเผยชะตากรรมของตัวเอง"
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_4994_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "นายเคยเจอผู้หญิงคนนั้นแล้วใช่ไหม? ผู้หญิงที่สวมผ้าคลุมหัวสีขาว ร่างกายที่ตื่นขึ้นนั่นแหละ เธอเป็นหนึ่งในรากฐานของการก่อตั้งมหาวิทยาลัยนี้...\nแต่พูดตามตรงนะ ฉันไม่ชอบเธอเลย ท่าทางทำเหมือนไม่สนใจอะไรทั้งโลกแบบนั้นมันน่าโมโหจริงๆ... อ๋า นายบอกว่าฉันหน้าเหมือนเธอเหรอ? งั้นฉันพาไปตรวจสายตาที่โรงพยาบาลของมหาวิทยาลัยนะ?"
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_4995_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "เธอกำลังสงสัยเกี่ยวกับความสัมพันธ์ระหว่างฉันกับศาสตราจารย์ใช่ไหม? มันไม่ใช่ความลับอะไร บอกเธอไปก็ไม่เป็นไร เดกสเตอร์ ศาสตราจารย์คือพ่อเลี้ยงของฉัน ส่วนแม่เลี้ยง... ฉันเติบโตในโรงเรียนและได้รับการดูแลจากคุณครูทุกคน แต่เมื่อเปรียบเทียบแล้ว ฉันจะสนิทกับดอร์มากกว่า"
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_4996_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "ไม่ว่าจะเป็นขั้นตอนการดำเนินการของแผนกบริหารร่างกายที่ตื่นขึ้น หรือวันที่จัดส่งอาหารอินเดียในโรงอาหาร ทุกเรื่องในสถาบัน ผมสามารถตอบคำถามให้คุณได้ —— ไม่ต้องกังวลว่าจะรบกวนผม ผมดูเหมือนคนที่ไม่มีมนุษยธรรมขนาดนั้นเลยหรือ?"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_4997_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "กระจกเวทมนตร์ ใครคือผู้ใช้เวทมนตร์ที่เก่งที่สุดในโลก? ฉันเอง? ตอบถูกแล้ว!"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_4998_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_4999_AwakerVoiceContent = {
    Text = "ก็ไม่เลวเลย."
  },
  Voice_4999_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5000_AwakerVoiceContent = {
    Text = "ดีจริงๆ"
  },
  Voice_5000_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5001_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_5001_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5002_AwakerVoiceContent = {
    Text = "สำเร็จ...แล้วหรือยัง? ฉันช่วยคุณได้หรือเปล่า?"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5003_AwakerVoiceContent = {
    Text = "ไม่มีประโยชน์!"
  },
  Voice_5003_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5004_AwakerVoiceContent = {
    Text = "(Endurance)"
  },
  Voice_5004_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5005_AwakerVoiceContent = {
    Text = "มองมาทางนี้!"
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "ให้ที่นี่กลายเป็นทะเลแห่งความครึกครื้นของทุกคนกันเถอะ!"
  },
  Voice_5006_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5007_AwakerVoiceContent = {
    Text = "ต้องการให้คุ้มกันไปด้วยหรือไม่? หากสิ่งที่คุณแสวงหานั้นเป็นความยุติธรรม ฉันจะช่วยคุณ."
  },
  Voice_5007_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5008_AwakerVoiceContent = {
    Text = "เผาไม่หมด"
  },
  Voice_5008_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5009_AwakerVoiceContent = {
    Text = "เผาไม่หมด"
  },
  Voice_5009_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5010_AwakerVoiceContent = {
    Text = "ต้องการกอดหรือเปล่า?"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "ดูพวกกุญแจมือบนตัวฉันสิ——มันไม่ใช่เครื่องประดับ แต่เป็นการเตือนใจ ให้ฉันไม่ลืมรสชาติของการถูกทรยศและถูกเหยียบย่ำ"
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "ถ้าอยากรู้เกี่ยวกับประวัติของสถาบัน ผมแนะนำให้คุณไปค้นหาข้อมูลที่หอจดหมายเหตุ\nได้โปรดเถอะ รวมถึงประวัติของสถาบันก่อนหน้านี้ด้วย นั่นคือประวัติศาสตร์ยาวนานถึง 300 ปี! คุณไม่ได้คาดหวังให้ผมเล่าทีละปีจริงๆ ใช่ไหม?"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "นี่เป็นการท้าทายฉันเหรอ? พร้อมเสมอ!"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "ทะเลลึกจะมอบการหลับใหลชั่วนิรันดร์ให้กับคุณ।"
  },
  Voice_5014_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5015_AwakerVoiceContent = {
    Text = "ทะเลลึกจะมอบการหลับใหลชั่วนิรันดร์ให้กับคุณ।"
  },
  Voice_5015_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5016_AwakerVoiceContent = {
    Text = "จมลง，ลุกโชนเถอะ! การเต้นรำแห่งความตาย!"
  },
  Voice_5016_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5017_AwakerVoiceContent = {
    Text = "ขอมอบให้กับการเต้นรำแห่งความตายของเปลวไฟเขียวอมตะ!"
  },
  Voice_5017_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5018_AwakerVoiceContent = {
    Text = "คุณหนูที่เหมือนประภาคารนั่น... ในการเดินทางยังคืนนิรันดร์ หากฉันสามารถมองเห็นแสงสว่างที่เจิดจรัสเช่นนั้น บางทีฉันอาจไม่หลงทางไปแบบนี้.."
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับฟาร์โรส"
  },
  Voice_5018_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับ「ฟาร์โรส」"
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "คุณควรพิสูจน์ให้เห็นถึงคุณค่าที่ทำให้ฉันยอมออกจากห้องทดลองได้ ผู้พิทักษ์คนใหม่"
  },
  Voice_5019_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5020_AwakerVoiceContent = {
    Text = "ฉันคือเจ้านาย และเจ้าเป็นเพียงคนรับใช้! ทุกสิ่งที่ข้าปรารถนาต้องมาอยู่ในมือข้าทันทีที่ต้องการ อะไรนะ? เจ้า คนรับใช้เช่นเจ้ายังกล้าขอรางวัลอีกหรือ? เอาเถอะๆ ข้าจะมอบให้ก็ได้!"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5021_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_5021_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5022_AwakerVoiceContent = {
    Text = "ความอับอาย ข้าจะล้างมันด้วยกระบวนท่านี้!"
  },
  Voice_5022_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5023_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_5023_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5024_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_5024_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5025_AwakerVoiceContent = {
    Text = "การให้คือการได้รับ."
  },
  Voice_5025_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5026_AwakerVoiceContent = {
    Text = "การให้คือการได้รับ."
  },
  Voice_5026_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5027_AwakerVoiceContent = {
    Text = "จะเจ็บนะ!"
  },
  Voice_5027_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5028_AwakerVoiceContent = {
    Text = "อย่าเข้ามา!"
  },
  Voice_5028_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5029_AwakerVoiceContent = {
    Text = "ฉันชอบแสงจันทร์สีทองในคืนพระจันทร์เต็มดวง มันลึกลับ อ่อนโยน และเมื่อลมพัด ผิวทะเลจะระยิบระยับด้วยแสงสีทองเหมือนฝันโรแมนติก"
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "หากบ้านเกิดของเราไม่เกิดการหลอมกร่อน ฉันและทิงค์เทตก็คงจะไม่แยกจากกัน... ฉันเกลียดการหลอมกร่อนมากกว่าเกลียดผักเสียอีก"
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "ข้างหน้าจะเป็นสมบัติหรือท่าเรือ สำหรับฉันแล้วไม่มีความแตกต่าง ภารกิจของฉันคือดูแลคุณให้กลับมาอย่างปลอดภัย"
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5031_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "ตามเส้นทางของนกสวรรค์ไปเถอะ จุดหมายปลายทางอยู่เบื้องหน้าที่เต็มไปด้วยสีครามสดใส"
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5032_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "ฉันมักจะมองออกไปยังเส้นขอบฟ้าของทะเล จินตนาการถึงทิวทัศน์อีกฟากหนึ่งของเส้นขอบฟ้า นั่นคือดินแดนไกลโพ้นที่ฉันเข้าใกล้มากขึ้นเรื่อยๆ แต่ไม่มีวันไปถึง หากมีวันนั้นจริง ขอให้คุณไปกับฉันดูสักครั้งเถอะ"
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5033_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "ด้วยพระคุณของท่าน บัดนี้ แม้แต่ทะเลพายุอันบ้าคลั่ง ข้าก็ยังมีความกล้าที่จะมอบพรอันบริสุทธิ์และแน่วแน่ไปให้แด่ท่าน"
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5034_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "ราวกับได้ยินบทเพลงของคนพายเรือ กลิ่นคุ้นเคยของบ้านเกิด"
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5035_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "คุณมาช่วยฉันใช่ไหม? จากยุคสมัยที่เน่าเปื่อย จากความเกลียดชังที่ซึมซาบเข้าดวงตา จากเปลวไฟสีเขียวอมตะ.."
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "ผู้ไม่เคารพ!"
  },
  Voice_5037_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5038_AwakerVoiceContent = {
    Text = "ฉันถือว่านี่เป็นสัญลักษณ์ของการเข้าร่วมหรือคำสาบานของคุณแล้ว"
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5038_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "ลองดูบทเรียนนี้!"
  },
  Voice_5039_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5040_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5040_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5041_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5041_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5042_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5042_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5043_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5044_AwakerVoiceContent = {
    Text = "ลองลิ้มรสความเก่งกาจของหนูสิ!"
  },
  Voice_5044_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5045_AwakerVoiceContent = {
    Text = "ลองลิ้มรสความเก่งกาจของหนูสิ!"
  },
  Voice_5045_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5046_AwakerVoiceContent = {
    Text = "ลูกเต๋าได้ถูกโยนแล้ว เอาล่ะ รีบตัดสินใจกันเถอะ."
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "ฉันจะเพิ่มชื่อของคุณในคำกล่าวขอบคุณ คุณคือผู้ที่ทำให้เท้าซึ่งถูกเลือดดำทำให้แปดเปื้อน ได้กลับมาสู่โลกแห่งบัลเลต์อีกครั้ง ต่อจากนี้ไป ขอให้คุณเฝ้าดูฉันเต้นรำด้วยเถอะ ผู้พิทักษ์"
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5047_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "ไม่ว่าจะดิ้นรนอย่างไร ก็ยังไม่อาจขัดขืนชะตากรรมได้ แต่แสงสว่างชั่วขณะนั้น จะกลายเป็นนิรันดร์"
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5048_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "คุณว่าควรจะทำอย่างไรกับพวกที่แพ้เหล่านี้นะ?"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "แม้ว่าในใจจะไม่มีความปรารถนาก็ตาม ฉันก็ยังจะแสดงบทบาทของหงส์ผู้สง่างามให้ดี"
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5050_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "หลับตา แล้วบอกฉันว่า คุณเห็นอะไร? แสงจันทร์ที่ไร้ที่ติ พื้นผิวของทะเลสาบที่สงบนิ่ง.."
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5051_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "ภัยพิบัติที่นำมาซึ่งการทำลายและความโชคร้าย ทำไมถึงได้พันธนาการฉันและพี่สาวของฉันกัน?"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "รับความรักของฉันไว้เถอะ."
  },
  Voice_5053_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5054_AwakerVoiceContent = {
    Text = "รับความรักของฉันไว้เถอะ."
  },
  Voice_5054_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5055_AwakerVoiceContent = {
    Text = "รู้สึกโล่งอกขึ้นมาก ขอบคุณ"
  },
  Voice_5055_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5056_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5056_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5057_AwakerVoiceContent = {
    Text = "หากเป็นไปได้ ฉันขอถวายดอกบัวสีม่วงละมุนเป็นของตอบแทน"
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "ฉันก็สามารถแข็งแกร่งขึ้นได้ไหม?"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5059_AwakerVoiceContent = {
    Text = "จะเริ่มแล้ว...!"
  },
  Voice_5059_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5060_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5060_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5061_AwakerVoiceContent = {
    Text = "ขาที่บาดเจ็บนี้เหรอ? ไม่คิดว่าเธอจะสนใจเรื่องนี้ นี่คือบาดแผลที่เหลือจากสนามรบในชีวิตก่อน\nไม่ต้องเป็นห่วง หลังจากกลายเป็นร่างกายที่ตื่นขึ้น มันจะไม่รบกวนการต่อสู้ของฉันอีกแล้ว\nความเจ็บปวด? ไม่ ฉันไม่เคยคิดถึงปัญหานี้"
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5061_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "ซิลเวียถามเกี่ยวกับสภาพจิตใจของฉัน คุณเป็นคนเรียกเธอมาใช่ไหม? ฉันยอมรับว่าความเจ็บปวดจากแขนเทียมจะเกิดขึ้นเป็นครั้งคราว แต่ไม่ต้องใส่ใจความรู้สึกของฉัน ฉันคือมีดของคุณ คือลูกศรของคุณ ตราบใดที่ยังสามารถต่อสู้เพื่อความยุติธรรม ความเจ็บปวดเล็กน้อยจะไม่มีผลกระทบใดๆ."
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5062_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "จัดงานน้ำชา จัดงานน้ำชากันเถอะ! ฉันได้ชาและของหวานมากมายจากเซอร์เวียเลยนะ! อืม ใช้การเต้นฟอร์ดวอเคนแลกมา!"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "คำทักทายของฉัน? คุณสนใจเรื่องส่วนตัวของฉันจริงหรือ? แค่ต้องการพูดคุยกัน...ก็ได้\nในกองทัพ เราไม่แยกแยะเพื่อนร่วมทีมด้วยเพศ รวมถึงพลังและความเร็ว แน่นอนว่ายังรวมถึงทรงผมและการเรียกชื่อ\nเมื่อเวลาผ่านไป ก็ชินกับการแสดงออกแบบนี้แล้ว"
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5064_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "น่าสนใจ......เธอไม่กลัวหรือว่าหลังจากที่ฉันได้รับพละกำลังแล้วจะฉีกเธอเป็นชิ้นส่วนไปให้ปลาแดกกินเหรอ?"
  },
  Voice_5065_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5066_AwakerVoiceContent = {
    Text = "เพื่อที่จะกลายเป็นผู้พิทักษ์ที่คู่ควรกับฉัน เธอก็พยายามอย่างมากเหมือนกันนะ!"
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "ถึงเวลาแล้วที่จะขย้ำคอของพวกอ่อนแอสองสามคนมาลองดู"
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "การเต้นรำนั้นบริสุทธิ์ คำพูดอาจนำมาซึ่งความเข้าใจผิด แต่ท่าทางการเต้นไม่มีวันทำให้เกิดความเข้าใจผิด"
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับการเต้นรำ"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "ฉันเกลียดทะเล มันคงเป็นเรื่องปกติใช่ไหม ทะเลกลืนกินทุกสิ่งที่ฉันรัก.."
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "ลืมก็ได้ สูญเสียก็ได้ ครั้งนี้เราต้องกลับมาแน่นอน！"
  },
  Voice_5070_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5071_AwakerVoiceContent = {
    Text = "ลืมก็ได้ สูญเสียก็ได้ ครั้งนี้เราต้องกลับมาแน่นอน！"
  },
  Voice_5071_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5072_AwakerVoiceContent = {
    Text = "กรุณา, กรุณาอย่าเข้ามาใกล้ฉันอีกเลย มันอันตรายมาก"
  },
  Voice_5072_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5073_AwakerVoiceContent = {
    Text = "สัมผัสไปเรื่อยๆ... พวกนี้คือแผลเป็นที่เหลือจากสนามต่อสู้เมื่อสมัยก่อน ตราแห่งเกียรติยศของผู้ชาย！"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "(เสียงร้องด้วยความเจ็บปวด)"
  },
  Voice_5074_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5075_AwakerVoiceContent = {
    Text = "โอ๊ย ปวดมาก ๆ!"
  },
  Voice_5075_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5076_AwakerVoiceContent = {
    Text = "(เสียงครางด้วยความเจ็บปวด)"
  },
  Voice_5076_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5077_AwakerVoiceContent = {
    Text = "(เสียงครางหงุดหงิด)"
  },
  Voice_5077_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5078_AwakerVoiceContent = {
    Text = "ในร่างกายเหมือนมีอะไรบางอย่างกำลังเดือดพล่าน นี่คือความรู้สึกของการตื่นพลังใช่ไหม."
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5078_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "นี่คือเทคโนโลยีใหม่หรือเปล่า? แขนเทียมของฉันดูเบาขึ้นมาก"
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5079_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "ได้กลิ่นเกลือจากลมทะเลแล้ว น่าจะใกล้ถึงประเทศของฉันแล้ว"
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5080_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "เพื่อนร่วมชาติที่จากไป จะสามารถตามแสงนี้กลับมาได้หรือไม่."
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5081_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "ข้าได้ค้นหามาแล้วนับหมื่นนับพันปี ไม่เห็นต้องรีบร้อนกับเวลาเพียงชั่วพริบตาหนึ่งร้อยปี ในเมื่อยังไม่ถึงฝั่งของท่าน ข้าจะยังคงช่วยเหลือท่านต่อไป"
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5082_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "ฉันจะส่องแสงเพียงเพื่อประเทศบ้านเกิดของฉัน คุณ.."
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5083_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "ฉันรู้สึกถึงสายลม มันพัดพาทรายละเอียดผ่านพ้นฝ่าเท้าของฉัน"
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5084_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "พละกำลังที่ข้าสามารถอุทิศให้ท่านก็ถึงเพียงเท่านี้ ความโลภมากเกินไปไม่ดีเลยนะ?"
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5085_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "เมื่อพูดถึงตรงนี้ ท่านอยากให้ผมตอบแทนอะไรบ้าง? เพียงแค่การต่อสู้หรือเปล่า?"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5086_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "ศีรษะแห่งความรัก ศีรษะแห่งความแค้น ศีรษะแห่งความเกลียดชัง ศีรษะแห่งความปรารถนา... โอ้ คุณมาอีกแล้วเหรอ?"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5087_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "เนื่องจากเป็นการทำธุรกิจ ข้าพเจ้าก็ไม่ควรรับของท่านโดยไม่ให้อะไรตอบแทน ท่านสนใจเลือกซื้ออะไรจากร้านนี้ไหมครับ?"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5088_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "ฉันจะสอนคุณเกี่ยวกับความสุข ความสนุกสนาน และความรู้สึกพึงพอใจเมื่อไปถึงจุดสูงสุด... ในทางกลับกัน คุณต้องเปิดเผยความปรารถนาของตัวเองอย่างซื่อสัตย์ด้วยนะ?"
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับผู้พิทักษ์ 2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "ข้าคือต้นแม่ ต้นแม่ก็คือข้า น้ำนมของต้นไม้ไหลเวียนอยู่ในสายเลือดของข้า ความตั้งใจของต้นไม้ล่องลอยอยู่ในทะเลแห่งจิตของข้า..."
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับต้นแม่พันธุ์แห่งความอุดมสมบูรณ์"
  },
  Voice_50899_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวน」บทที่ 7 แล้วปลดล็อก"
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "จงชดใช้ราคาที่ต้องจ่ายสำหรับการทรยศนี้!"
  },
  Voice_5089_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_50900_AwakerVoiceContent = {
    Text = "เมื่อครู่นี้ขณะที่ฉันกำลังหาสถานที่ซ่อนเร้นอยู่ในสุสานกุญแจ ดูเหมือนว่าฉันจะเห็นหลุมศพของคุณ... มัมมี่ของฉันจะถูกฝังอยู่ที่นี่ด้วยหรือเปล่า? จะไม่ใช่เหรอ? น่าเสียดายจริงๆ."
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับกุญแจสุสาน"
  },
  Voice_50900_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวน」บทที่ 7 แล้วปลดล็อก"
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "พี่ชายหมาป่า... เขาและคุณ N นั้นมีความสัมพันธ์ที่ไม่อาจอธิบายได้อย่างชัดเจน.."
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเลค"
  },
  Voice_50901_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「เลค」"
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "เข้ามาใกล้ฉัน,      กอดฉัน,      ลิ้มรสฉัน... อย่าลืมฉัน."
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับผู้พิทักษ์ 3"
  },
  Voice_50902_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวน」บทที่ 7 แล้วปลดล็อก"
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "นั่นเป็นเด็กที่ขยันและระมัดระวังเกินไป ฉันแน่นอนว่าจะไม่ตำหนิเธอ~ หากไม่มีเธอ เผ่าพันธุ์ที่ทำตามใจชอบคงจะล่มสลายไปพร้อมกับการเปลี่ยนแปลงแล้วกระมัง?"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับเอลวา"
  },
  Voice_50903_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「เอลวา」"
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "เกิดจากพื้นทรายเหลือง และกลับคืนสู่พื้นทรายเหลืองอีกครั้ง ในช่วงการเดินทางอันสั้นนี้ คุณควรจะทิ้งอะไรบางอย่างไว้ และหว่านอะไรบางอย่างไว้ เป็นอย่างไรบ้าง?"
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับทะเลทราย"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "ความปรารถนาล้วนเกิดจากความรัก ความรักคือเมล็ดแรก ก่อนจะเติบโตเป็นต้นไม้ใหญ่ที่สูงตระหง่าน."
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "เรื่องราวเกี่ยวกับความปรารถนา"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "อุ๊ย หนูน้อยน่ารักวิ่งผ่านไปแล้ว... ฉันเคยได้ยินว่าหนูชอบขโมยของกิน แต่น่าเสียดาย ตัวนี้ยังเล็กเกินไป ยังอยู่ในวัยแบเบาะ.."
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเจนกิน"
  },
  Voice_50906_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「เจนกิน」"
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "พวกเขาสืบทอดกระดูกและเลือดเนื้อของข้า กลายเป็นแม่น้ำที่เชี่ยวกรากคุ้มครองเลิมวาฮิ... ต่อจากนี้ไป ข้าขอฝากความหวังไว้กับท่าน เพื่อสืบเชื้อสายและดำรงต่อไป.."
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับอารัน"
  },
  Voice_50907_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวน」บทที่ 7 แล้วปลดล็อก"
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "แมงมุม... แมงมุม~ ฮืม~ ฉันชอบแมงมุม พวกมันเพิ่งลืมตาดูโลกก็สามารถเคลื่อนไหวได้ทันที ความสามารถในการสืบพันธุ์และความแข็งแกร่งในการเอาชีวิตรอดของพวกมันช่างน่าอิจฉาจริงๆ.."
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับอักกริปปา"
  },
  Voice_50908_UnlockDesc = {
    Text = "เมื่อได้รับตัวปลุก「อักกริปปา」จะปลดล็อก"
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "สรรพชีวิตทั้งมวลที่ไหลเวียนไปด้วยเลือดของต้นไม้ล้วนเป็นบุตรของข้า แม้แต่ท่านที่กลืนเมล็ดพันธุ์ของต้นไม้ก็เช่นกันนะ?"
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับลูกหลาน"
  },
  Voice_50909_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวน」บทที่ 7 แล้วปลดล็อก"
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "สินค้าที่ฉันขายหรือ? สามารถพูดได้ว่ามีครบครัน ตอบสนองความปรารถนาทั้งหมดของคุณ... เพียงแต่ต้องจ่ายราคาที่ต้องจ่ายที่สมน้ำสมเนื้อ"
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5090_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "โอ้ ต้องยอมรับว่าฉันแพ้เธอครั้งหนึ่งแล้ว... โชคดีที่คุณซึ่งถูกเธอเลือก ก็จะดื่มน้ำจากต้นไม้ศักดิ์สิทธิ์ และนำเลือดกับเมล็ดพันธุ์ของฉันไปสู่โลกใบใหม่ใช่ไหม?"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับทาวี"
  },
  Voice_50910_UnlockDesc = {
    Text = "ปลดล็อคเมื่อได้รับร่างกายที่ตื่นขึ้น「รามอน่า」"
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "เป็นหนึ่งในสามของโปรโตพลาสต์เช่นเดียวกัน ผู้นั้นเป็นปริศนาที่ยากจะหยั่งถึง ท่านอย่าได้หลงเชื่อคำหวานของเขาเป็นอันขาด ไม่อย่างนั้นข้าคงต้องเจ็บปวดใจไม่น้อย.."
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับN"
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "สิ่งที่มีความรู้สึกก็ย่อมมีความปรารถนา แม้แต่สิ่งมีชีวิตเชิงกลก็คงไม่มีข้อยกเว้นใช่ไหม?"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "เรื่องราวเล็กน้อย·เกี่ยวกับเอริกา"
  },
  Voice_50912_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「เอริกา」"
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "จงชดใช้ราคาที่ต้องจ่ายสำหรับการทรยศนี้!"
  },
  Voice_5091_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5092_AwakerVoiceContent = {
    Text = "ยินดีต้อนรับสู่ดินแดนอัศจรรย์!"
  },
  Voice_5092_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5093_AwakerVoiceContent = {
    Text = "(เสียงต่ำ)"
  },
  Voice_5093_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5094_AwakerVoiceContent = {
    Text = "ข้าคุ้นเคยกับความเจ็บปวดจากการแกะสลัก และความร้อนแรงจากความเปลี่ยนแปลง แต่ทั้งหมดนี้ เมื่ออยู่หน้าความงามแห่งนิรันดร์ กลับเล็กน้อยดุจฝุ่นละออง"
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5094_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5095_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5096_AwakerVoiceContent = {
    Text = "คำพูดที่ไม่เคยเอ่ยออกมา ฉันจะบอกเล่าให้คุณฟังผ่านผลงานของฉันนะ"
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5096_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5097_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_5097_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5098_AwakerVoiceContent = {
    Text = "ผู้ปกครองที่หลับใหลพึมพำในหูของฉัน ซากปรักหักพังใต้ทะเลลึกกำลังรวมตัวใหม่ตรงหน้าของฉัน...... ภาพที่ปรากฏในความฝันนับครั้งไม่ถ้วน กำลังจะกลายเป็นจริงแล้วหรือ?"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5098_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "ขอบคุณที่เตรียมสตูดิโอให้ฉัน ที่นี่ทุกอย่างดูอบอุ่นไปด้วยแสงแดด เหมือนว่าผลงานทุกชิ้น มีดแกะสลักทุกเล่ม ต่างก็เปล่งประกายเป็นแสงสีทอง โอ้ ฤดูใบไม้ผลินี้ช่างงดงามราวกับถูกแต่งแต้มด้วยสีทองจริงๆ"
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5099_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "แม้จะมีนิสัยที่แตกต่างกัน แต่ฉันชอบเด็กคนนั้นมาก เธอมีความกล้าหาญที่เพียงพอจะหลุดพ้นจากปัญหาและข้อผูกมัดทั้งหมด หากฉันกล้าและเข้มแข็งเช่นนั้น บางทีฉันอาจจะไม่เลือกจบชีวิตด้วยการมอบตัวให้กับทะเลหรอก.."
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับมอร์ฟี่"
  },
  Voice_5100_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「มอร์ฟี่」ร่างกายที่ตื่นขึ้น"
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "คุณนายแดงแตกต่างจากเจ้านายคนไหนๆ ที่ฉันเคยรับใช้... ไม่สิ ฉันไม่ได้เกลียดเธอ เพียงแต่ว่า, เพียงแต่ว่ามันยากจะรับมือ.."
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับโซเรล"
  },
  Voice_5101_UnlockDesc = {
    Text = "เปิดใช้งานหลังจากได้รับร่างกายที่ตื่นขึ้น「โซเรล」"
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "โอบกอดความบ้าคลั่ง！"
  },
  Voice_5102_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5103_AwakerVoiceContent = {
    Text = "ประคองชีวิตอย่างยากลำบาก"
  },
  Voice_5103_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5104_AwakerVoiceContent = {
    Text = "กำจัดให้หมดสิ้น!"
  },
  Voice_5104_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5105_AwakerVoiceContent = {
    Text = "คุณไม่จำเป็นต้องทำเช่นนี้.."
  },
  Voice_5105_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5106_AwakerVoiceContent = {
    Text = "ใจเป็นเหวที่ไม่มีก้น ไม่มีวันเติมเต็มได้"
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "ไม่มีผลกระทบอะไรมาก แต่...ก็ยังรู้สึกขอบคุณอยู่ดี"
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "อ่า... คุณกำลังพูดกับฉันอยู่หรือเปล่า? ขอโทษนะ ฉันเพิ่งนึกถึงภาพที่เห็นบนยอดเสาเมื่อกี้ คุณช่วยพูดคำถามของคุณซ้ำอีกครั้งได้ไหม?"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับอดีต"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "เป็นทั้งเจ้าของและแม่."
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "โอกาสที่จะใช้ประโยชน์ได้!"
  },
  Voice_5110_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5111_AwakerVoiceContent = {
    Text = "โอกาสที่จะใช้ประโยชน์ได้!"
  },
  Voice_5111_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5112_AwakerVoiceContent = {
    Text = "เตรียมพร้อม——"
  },
  Voice_5112_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5113_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_5113_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5114_AwakerVoiceContent = {
    Text = "ลองใช้แรงมากกว่านี้หน่อย~"
  },
  Voice_5114_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5115_AwakerVoiceContent = {
    Text = "ความรักที่ร้อนแรง!"
  },
  Voice_5115_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5116_AwakerVoiceContent = {
    Text = "ปรากฏการณ์หลอมกร่อน... ผมไม่สามารถบอกคุณมากนัก แต่สิ่งนี้ปรากฏขึ้นเร็วกว่าที่พวกคุณคิดมาก..."
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5118_AwakerVoiceContent = {
    Text = "อืม——"
  },
  Voice_5118_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5119_AwakerVoiceContent = {Text = "อืม"},
  Voice_5119_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5120_AwakerVoiceContent = {
    Text = "ออกเดินทางกันเถอะ"
  },
  Voice_5120_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5121_AwakerVoiceContent = {
    Text = "หึ เจ้าหญิงหุ่นเชิดของเรา กำลังร้องไห้อีกแล้วหรือ ขวดนมไม่เข้าปากหรือเพลงกล่อมเด็กไม่เพราะ?"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับมอร์ฟี่"
  },
  Voice_5121_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「มอร์ฟี่」ร่างกายที่ตื่นขึ้น"
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "ฮือๆ... ฉันไม่อยากเผชิญหน้ากับสิ่งเหล่านั้น.."
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "ตอนนี้ ถึงตาฉันตอบแทนคุณแล้ว."
  },
  Voice_5123_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5124_AwakerVoiceContent = {
    Text = "ความรู้สึกพละกำลังเพิ่มขึ้น ราวกับเปลวไฟที่ร้อนแรงจนแทรกซึมเข้ากระดูก."
  },
  Voice_5124_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5125_AwakerVoiceContent = {
    Text = "อา...ขอโทษนะ อย่าขยับไปไหน!"
  },
  Voice_5125_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5126_AwakerVoiceContent = {
    Text = "อุณหภูมิที่เอื้อมถึงได้.."
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "กุหลาบในสวนกำลังบาน"
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "ทำได้ดีมาก ยังไหวอยู่ไหม? ไปต่อเลยดีไหม?"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "อัศวินเป็นสิ่งที่ไม่มีรูปร่าง ความจงรักภักดี ความกล้าหาญ และคุณธรรมได้มอบรูปร่างให้กับมัน เช่นเดียวกับอาวุธของข้า เจตนาปกป้องได้มอบรูปแบบของหอกและโล่ให้กับมัน"
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับอัศวิน"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "เจนกิน, ไดอาน่า, ไมค์, เทียก, บราวน์... ว้า! ขอโทษนะ, ฉันแค่พูดคนเดียว! คุณถามว่าทำไมฉันถึงพูดชื่อพวกนี้เหรอ? เพราะไอจิสไม่อยากลืมทุกคน.."
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับเพื่อน"
  },
  Voice_5131_AwakerVoiceContent = {
    Text = "อย่าเข้ามา!"
  },
  Voice_5131_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5132_AwakerVoiceContent = {
    Text = "เกลียดจริงๆ!"
  },
  Voice_5132_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_5133_AwakerVoiceContent = {
    Text = "อ้า~เฮ้！"
  },
  Voice_5133_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5134_AwakerVoiceContent = {
    Text = "อ้า~เฮ้！"
  },
  Voice_5134_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5135_AwakerVoiceContent = {
    Text = "ขอบคุณที่เรียกหาผม หากมีโอกาสที่ต้องใช้เสียงของผม รบกวนแจ้งให้ทราบล่วงหน้า"
  },
  Voice_5135_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5137_AwakerVoiceContent = {
    Text = "นั่นคือ... ของเหลวสีดำที่ไหลเวียนในเส้นเลือด กำลังอันทรงพลังที่กลืนกินเสียงครวญครางทั้งมวล! 「ข้า」ได้ถือกำเนิดจากสิ่งนี้ เพื่อการทำลายล้างโดยเฉพาะ! ฮ่าฮ่าฮ่า!"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "เรียกฉันออกมาเพื่อจะเสี่ยงโชคเหรอ? ...อะไรนะ การสืบสวน? ไม่เอาหรอก ใช้โชคไปกับเรื่องแบบนี้ไม่คุ้ม.."
  },
  Voice_5138_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5139_AwakerVoiceContent = {
    Text = "การเรียนทฤษฎีน่าเบื่อมาก ตอนเรียนฉันมักจะแอบอ่านบันทึกการสอบสวนอยู่ด้านหลังของห้องเรียน บอกแค่คุณคนเดียว thôi อย่าให้ดอร์รู้นะ"
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "ลองลิ้มรสผลของความหายนะนี่สิ!"
  },
  Voice_5140_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5141_AwakerVoiceContent = {
    Text = "ลองลิ้มรสผลของความหายนะนี่สิ!"
  },
  Voice_5141_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5142_AwakerVoiceContent = {
    Text = "ฉันไม่เคยตำหนิยูลีเอตเลย เธอก็เป็นเพียงเหยื่อของความทุกข์ยากสีดำเท่านั้น แต่... เธอดูเหมือนจะไม่อยากฟังฉันพูดเรื่องนี้ คุณช่วยบอกเธอแทนฉันได้ไหม ผู้ส่งสาร?"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับยูลีเอต"
  },
  Voice_5142_UnlockDesc = {
    Text = "เสียงพูดที่ยังไม่พร้อมใช้งาน"
  },
  Voice_5143_AwakerVoiceContent = {
    Text = "ช้าลงหน่อย."
  },
  Voice_5143_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5144_AwakerVoiceContent = {Text = "อืม"},
  Voice_5144_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5145_AwakerVoiceContent = {
    Text = "เฮ้! หยุดจับได้แล้ว ทำให้มันเละเทะไปหมดแล้ว! ...ช่างมันเถอะ ข้าก็ใจดีนี่นา"
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5146_AwakerVoiceContent = {
    Text = "ไม่ต้องการ!"
  },
  Voice_5146_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5147_AwakerVoiceContent = {Text = "ชิ!"},
  Voice_5147_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5148_AwakerVoiceContent = {
    Text = "ตั้งแต่วันที่คุณปลุกฉันจากความมืดมน ฉันก็แน่ใจแล้วว่า คุณสามารถนำพาสรรพสิ่งให้หลุดพ้นจากความสิ้นหวังอันเรียกว่าการหลอมกร่อน สู่แดนศักดิ์สิทธิ์อันบริสุทธิ์ผุดผ่อง ฉันเฝ้ารอวันนั้นด้วยใจจดจ่อ"
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับผู้พิทักษ์·Ⅰ"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "ได้กลิ่น... กลิ่นเลือด."
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "เป้าหมายอยู่ที่ไหน? ขอบคุณที่ปลุกฉัน ฉันจะจัดการอีกฝ่ายให้คุณ"
  },
  Voice_5150_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5151_AwakerVoiceContent = {
    Text = "หมวกของฉันแทบรอไม่ไหวแล้ว!"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "ร่างนี้ไม่ควรหวั่นไหวเพราะสิ่งอื่นนอกเหนือจากพระองค์... แต่อุณหภูมิของท่าน.."
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "อะไรนะ อยากสู้กันหน่อยเหรอ?"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5154_AwakerVoiceContent = {
    Text = "ผู้กระทำให้แปดเปื้อน.."
  },
  Voice_5154_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5155_AwakerVoiceContent = {
    Text = "ไม่สามารถให้อภัยได้"
  },
  Voice_5155_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5156_AwakerVoiceContent = {
    Text = "เอริกา ปัจจุบันทำงานปกติ เชื่อมต่อกับอุปกรณ์ไฟฟ้าภายในมหาวิทยาลัยมิซากะได้ดี ต้องการให้ฉันเปิดไฟในหอพักหรือไม่?"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "เรื่องราวเล็กน้อย·เกี่ยวกับเอริกา"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "ต่อไปถึงเวลาทานอาหารแล้ว ฮิฮิ.."
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "อย่าให้ผู้หญิงที่ใส่หมวกปีกกว้างสีม่วงเข้าใกล้เวที! ไม่มีเหตุผลอะไรหรอก แค่ถ้าคุณไม่อยากให้มีของเหลวสีเทาเหนียวๆ ไหลออกมาจากหมวกทรงสูงล่ะก็ อย่าให้เธอเข้ามา!"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "เรื่องราวเกี่ยวกับดาฟเดล"
  },
  Voice_5159_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「ดาฟเดล」ที่ถูกปลุก"
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "คุณเป็นแบบนี้มาตลอดหรือเปล่า? มอบหลังให้ทุกคน และก็มอบความไว้วางใจ? ช่างเป็นเรื่องที่ไร้เดียงสาจริงๆ."
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "ความเกลียดชังอาจบรรเทาได้ แต่ไม่มีทางกำจัดไปได้"
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "ร่างกายที่ตื่นขึ้น? อืม... เป็นแบบนี้ค่ะ เวลาเจ็ดโมงเป็นเวลาที่ดีที่สุดในการปลุก! พรุ่งนี้เช้าเราไปเก็บหอยริมทะเลตอนเจ็ดโมงกันเถอะ!"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "บทสนทนาสบายๆ·เกี่ยวกับร่างกายที่ตื่นขึ้น"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "ให้เจ้ามีชีวิตนิรันดร์!"
  },
  Voice_5163_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5164_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_5164_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5165_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_5165_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5166_AwakerVoiceContent = {
    Text = "ขอโทษจริงๆ ถ้าไอจิสอยู่ที่นี่จะทำให้คุณรู้สึกไม่สบายใจ ฉันจะจากไปทันที！"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5166_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "คุณให้ที่พักพิงแก่ฉัน ฉันรู้สึกขอบคุณมาก แต่โปรดอภัยให้ด้วย ฉันไม่ควรขึ้นเวทีอีกแล้ว"
  },
  Voice_5167_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5168_AwakerVoiceContent = {
    Text = "ขอบคุณที่อนุญาตให้ฉันอยู่ที่นี่ หากมีอะไรที่สามารถตอบแทนท่านได้ ไอจิสยินดีทำทุกอย่างเลยค่ะ ต้องการให้ชงชาให้ไหมคะ?"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5168_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "เพราะมันอบอุ่นมาก เลยไม่อยากจากไป ตอนอยู่คนเดียว มันช่างมืด หนาว และกลัวจริงๆ.."
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5169_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "ไอจิส... จริงๆ แล้วฉันจะกลับไปใช้ชีวิตอยู่ในหมู่คนอื่นได้ไหม? ฉันยังไม่พร้อม แต่คุณกลับยอมรับฉันแล้ว... หากเป็นเช่นนั้น ต่อไปก็, ฝากตัวด้วยนะคะ... ผู้พิทักษ์"
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5170_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "นึกออกแล้ว ฉันนึกออกแล้ว...! เลือดสกปรกของมนุษย์มันขังฉันไว้... ฉัน ฉันไม่สามารถแปลงร่างได้! ทำไม ฉันจะ... ครีบของฉันล่ะ? ทำไมมันถึงไม่ขยับ? ทำไม!"
  },
  Voice_5171_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5172_AwakerVoiceContent = {
    Text = "ฉันชอบกินปลาหมึกย่าง ปลาหมึกลวก ปลาหมึกทอด...บางคนคิดว่าฉันกำลังลบหลู่เทพเจ้า ขอโทษนะ เพราะปลาหมึกอร่อยจริงๆ ฮ่าฮ่าฮ่าฮ่า!"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "หนอน.ดวงดาว.ข้าคือ...ยูวฮะชิ！ฆ่า...ให้ข้าได้ฆ่า！"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5173_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "ลำตัวสีแดงเข้ม เต็นท์ที่เคลื่อนไหวอย่างต่อเนื่อง ขากรรไกรที่เคลื่อนไหวไม่หยุด... ดีมาก ดีมาก! ฉันแทบรอไม่ไหวแล้วที่จะบดขยี้ลำคอของศัตรู!"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5174_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "ฮ่าฮ่าฮ่าฮ่า นี่แหละความรู้สึกที่ว่า! ให้ฉันอีกหน่อย... สองเท่ายังน้อยไป! สิบเท่าเข้าไปเลย!"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5175_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "ฉันจะทนต่อไปเรื่อยๆ"
  },
  Voice_5176_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5177_AwakerVoiceContent = {
    Text = "ความรู้สึกมหัศจรรย์นี้...ไม่เลวเลย ดีกว่าเบลลาดอนนาของพ่อมดลิแวนต์เสียอีก"
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5177_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "เพื่อนร่วมทาง? ฮึ...ไม่ต้องการเพื่อนร่วมทางหรอก ฉันจะไม่ยอมให้ภาระแบบเดิมมาทำให้ตัวเองลำบากซ้ำสองแน่"
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5178_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "จะร่วมมือกับเธอก็เพราะเธอแสดงให้เห็นถึงพละกำลังที่คู่ควรกับฉัน อย่าลืม สัญญานี้จะสิ้นสุดลงเมื่อเธออ่อนแอลง และในตอนนั้น ฉันจะไม่ลังเลที่จะลงมือ"
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5179_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "ข้าเห็นจากดวงตาคู่นั้นของเจ้า... แสงเรืองที่ส่องประกายออกมา นั่นคือไฟแห่งความทะเยอทะยานและความปรารถนา เจ้ามนุษย์ เจ้าจงรู้จักตนเอง! เราทั้งสองต่างก็เป็นคนประเภทเดียวกัน."
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5180_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "รู้จักนกอัลบาทรอสไหม? พวกมันไม่เคยสนใจมนุษย์เลย มีแต่กระพือปีกอย่างแรงกล้า เผชิญหน้ากับพายุฝน แต่เมื่อถูกเนรเทศลงสู่พื้นดิน ตกอยู่ท่ามกลางเสียงเยาะเย้ยถากถาง ปีกใหญ่ที่ห้อยลงกลับกลายเป็นอุปสรรคอันน่าสมเพช\nเรื่องนี้ไม่ได้มีความหมายลึกซึ้งอะไรหรอก แค่อยู่กับเธอแล้วรู้สึกผ่อนคลาย เลยพูดคุยไปเรื่อยเท่านั้นเอง"
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5181_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "บางที ยุคสมัยอาจเปลี่ยนไปแล้วจริงๆ ในตอนนี้ แม้แต่ผู้ที่ดูเหมือนจะอ่อนแอ ก็สามารถข้ามโขดหิน ทะยานเหนือคลื่นทะเล และกลายเป็นราชาแห่งท้องฟ้ากว้างใหญ่ได้\nมนุษย์ธรรมดา เราเฝ้ารอวันที่เจ้าจะสร้างประวัติศาสตร์ใหม่ เมื่อนั้น ข้าจะเป็นเกียรติอย่างยิ่งที่ได้เป็นดาบใหญ่ในมือของเจ้า!"
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5182_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "อัตราการแปลงต่ำเกินไป พรุ่งนี้มารายงานตัวที่สำนักงานฉันเพื่อเข้ารับการฝึกอบรมใหม่"
  },
  Voice_5183_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5184_AwakerVoiceContent = {
    Text = "คุณได้พบกับดอร์อีกคนแล้วหรือยัง? สิ่งที่เรียกว่า 「ความจริงของโลก」 นั้น สามารถเปลี่ยนดอร์ที่เคยสงบและมีเหตุผลกลายเป็นคนละคนได้... ในที่สุด คุณและฉันจะกลายเป็นแบบนั้นหรือเปล่า?"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับ@2"
  },
  Voice_5184_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างตื่น@2"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "เจ้านาย... ข้าต้องการคำสั่ง โปรดสั่งข้าเถอะ"
  },
  Voice_5185_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5186_AwakerVoiceContent = {
    Text = "ประสิทธิภาพของเครื่องจักรได้รับการปรับปรุงแล้ว"
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5189_AwakerVoiceContent = {
    Text = "อืมฮึมฮึม!"
  },
  Voice_5189_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5190_AwakerVoiceContent = {
    Text = "เพื่อนร่วมทางมากขึ้น!"
  },
  Voice_5190_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5191_AwakerVoiceContent = {
    Text = "เพื่อนร่วมทางมากขึ้น!"
  },
  Voice_5191_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5192_AwakerVoiceContent = {
    Text = "ขอโทษนะ ฉันไม่สามารถออกจากเปลได้...แบบนี้จะบังสายตาของทุกคนใช่ไหม ดังนั้นฉันอยู่แถวหลังสุดของห้องเรียนก็พอแล้ว"
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "อะไรนะ! ไม่ได้ซื้อพรมจากคอนสแตนติโนเปิล ชาดำจากเกาะสีหลัน หรือชิลีกั่วจากอันดาลูเซียเลยเหรอ?! ฮือ...ผู้หญิงคนนั้นหาของพวกนี้ได้อย่างง่ายดาย ฉันคิดว่ามันเป็นเรื่องปกติธรรมดาซะอีก.."
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "ยังไกลจากตัวฉันในตอนแรกๆ อยู่มาก"
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5194_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "เร่งรีบเช่นนี้ สำหรับยอดคนเช่นคุณแล้ว ดูเหมือนจะหยาบคายไปหน่อย"
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "ไม่ว่าจะพัฒนามากแค่ไหน รูปลักษณ์ของสัตว์ตัวนี้ก็จะไม่เปลี่ยนแปลง แต่ท้ายที่สุดแล้ว มันเป็นเพียงการสะท้อนของพละกำลังของฉันเท่านั้น"
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5196_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "รู้สึกเหมือนกลับไปอยู่ในมหาสมุทรแห่งความวุ่นวายอีกครั้ง แต่ก็ไม่เลว"
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5197_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "ดูในความพยายามอย่างเต็มที่ของเธอ ฉันจะยอมรับเธอเป็นผู้ร่วมทางอย่างไม่เต็มใจก็แล้วกัน"
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5198_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "เหมือนกับการทำลายกำแพงเขาวงกต ให้ทำลายกำแพงแห่งพละกำลังนั้นเสีย."
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5199_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "ห้ามฉีกอาหารโดยไม่ระมัดระวัง และห้ามนั่งหรือกดเก้าอี้ในโรงอาหารจนเสียหาย... ได้ค่ะ ลิลลี่จะไม่ทำแบบนั้นอีกแล้ว"
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5200_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "ฉันเรียกคุณว่าแม่ได้ไหม?"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5201_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = "มีคำสั่งอะไรให้ทำไหมคะ เจ้านาย?\n「อย่าพาพวกมันเดินข้างนอกเลย ทุกคนจะกลัว」?\nลิลลี่เข้าใจแล้ว ลิลลี่จะซ่อนพวกมันเดี๋ยวนี้"
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5202_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "กลายเป็นร่างกายที่ตื่นขึ้น ที่แท้ก็เป็นแบบนี้นี่เองนะ"
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5203_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "แม่ หนูนอนข้างแม่ได้ไหมคะ? เวลาอยู่คนเดียว หนูจะฝันร้ายที่มืดมิด แขนและขาของลิลลี่หลุดออก แล้วเจ็บจริงๆ.."
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5204_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "อ๊ะ! ขอบคุณท่านมากค่ะ คาเรนเป็นแค่สาวใช้ต้อยต่ำ..."
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5205_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5206_AwakerVoiceContent = {
    Text = "หึหึ~"
  },
  Voice_5206_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5207_AwakerVoiceContent = {
    Text = "ฉันต้องรวบรวมวัสดุแกะสลักบางอย่าง ยิ่งสดใหม่มากเท่าไหร่ยิ่งดี."
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "กรุณาเงียบสักหน่อย"
  },
  Voice_5208_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5209_AwakerVoiceContent = {
    Text = "ผู้ที่ดื้อรั้น ทำสิ่งที่ไร้ประโยชน์อย่างต่อเนื่อง"
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5209_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "ถึงขั้นนี้แล้ว ข้าพเจ้าเข้าใจความตั้งใจของท่านบ้างแล้ว ไม่มีปัญหา ดำเนินการต่อเลย"
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5210_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "ยูเห็นถึงความมุ่งมั่นของท่านแล้ว ก่อนจะหลับลึกอีกครั้ง ยูจะเป็นพยานให้ท่าน ในฐานะบุตรแห่งมนุษย์ผู้ต่อต้านชะตากรรม แต่ตอนนี้ ข้าต้องการเวลาพักผ่อนสักหน่อย"
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5211_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "ทำตามชะตากรรม ไม่ดีหรือ? ทำไมต้องต่อต้านความประสงค์ของโชคชะตา."
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5212_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "เพื่อให้ความปรารถนาเป็นจริง คุณกลับสามารถเสียสละได้มากขนาดนี้.."
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5213_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "หะ? ไม่รำคาญเหรอ? อย่ามาวุ่นวายกับฉันเรื่องของคนนั้นอีกเลย! ...ช่างเถอะ ทำตามใจพวกเธอก็แล้วกัน ถือซะว่าเป็นการผ่านเวลาละกัน"
  },
  Voice_5214_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5215_AwakerVoiceContent = {
    Text = "การหลอมกร่อน... ของเหลวสีดำที่สกปรกเหล่านั้นมักจะรบกวนความฝันของยูเสมอ จนทำให้รู้สึกไม่สบายใจเป็นอย่างมาก."
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "อำนาจเป็นดาบสองคม ข้าจะไม่เข้าใจได้อย่างไร... เพียงแต่ว่าข้าตระหนักถึงมันช้าเกินไป ช้าเกินไปแล้ว เมื่อใดที่ข้าปล่อยมือ พวกมันจะพุ่งเข้าใส่และฉีกข้าออกเป็นชิ้นส่วน... หากข้าตั้งแต่แรกมีความแจ่มชัดเช่นท่าน ก็คงจะไม่จบลงด้วยวิธีที่น่าเศร้าเช่นนั้น อะ เอ๋? ท่านบอกว่า ข้าสามารถจัดงานเลี้ยงในห้องพักผ่อนได้หรือ?! นี่มัน... นอกจากจะได้รับใช้ท่านด้วยตัวเองแล้ว ข้ายังจะตอบแทนท่านได้อย่างไรอีก.."
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5216_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "ท่านเป็นแขกที่ดื้อรั้นจริงๆ ต้องให้ข้าพเจ้าต้อนรับท่านอย่างไร ท่านถึงจะยอมมอบสิทธิพิเศษในมือของท่านให้? อำนาจมักนำพาปัญหามาด้วย หลักการง่ายๆ แบบนี้ ท่านคงไม่ถึงกับไม่เข้าใจใช่ไหม?"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5217_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "ก่อนที่งานเลี้ยงจะเริ่ม คุณอยากฟังเรื่องราวไหม? เรื่องราวของเด็กสาวชนบทคนหนึ่งที่คว้ามงกุฎแห่งอำนาจมาได้อย่างไร... จะเริ่มจากตรงไหนดี ควรเริ่มจากตอนที่พ่อแม่บังคับให้เธอแต่งงานกับชายชราหรือเปล่า หรือคุณอยากฟังตอนที่เธอเปล่งประกายในสวนของขุนนางมากกว่า?"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5218_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "ในอดีต ผู้มาเยือนมักเรียกข้าว่า 「คุณนายแดง」 แน่นอนว่าท่านสามารถเรียกข้าว่า 「โซเรล」 ก็ได้ เพราะท่านเป็นแขกรับเชิญคนพิเศษที่สุดของข้า.."
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5219_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "ในฐานะเจ้าของร้าน การทำให้แขกทุกคนพึงพอใจคือหน้าที่ของฉัน"
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5220_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5221_AwakerVoiceContent = {Text = "อ้า"},
  Voice_5221_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5222_AwakerVoiceContent = {
    Text = "ท่านเจ้า? มีปัญหาอะไรกับท่าทางการยืนของข้าหรือเปล่า?"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5223_AwakerVoiceContent = {
    Text = "อุ๊ย!"
  },
  Voice_5223_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5224_AwakerVoiceContent = {
    Text = "โชคไม่ดี~"
  },
  Voice_5224_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5225_AwakerVoiceContent = {Text = "อ้า"},
  Voice_5225_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5226_AwakerVoiceContent = {
    Text = "ฉันจำความรู้สึกนี้ได้ ช่วงเวลาที่เต็มไปด้วยเกียรติยศกำลังจะมาถึงแล้ว.."
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5226_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "แม้ว่าร่องเหงือกยังไม่ปรากฏ แต่ฉันก็ไม่รู้สึกกังวลเกี่ยวกับเรื่องนี้อีกแล้ว ปีกใบนี้จะเปลี่ยนเป็นโล่ที่ปกป้องคุณนะ ผู้พิทักษ์"
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5227_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "เธอ... อดทนมากกว่ามนุษย์คนอื่นๆ... ที่ให้ฉันใช้ทรัพยากรพวกนี้ คุณไม่เกลียดฉันใช่ไหม?"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5228_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "อ๊ะ? พิธีสิ้นสุดแล้ว ทำไมฉันยังไม่สามารถงอกเหงือกได้? การเปลี่ยนร่างล้มเหลวอีกแล้วหรือ! ให้ตาย! ช่างมันจริงๆ! ทำไม่ได้เลย!"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5229_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "เสียงนั้นเรียกหาฉันอีกแล้ว... เสียงไพเราะจากทะเลลึก!"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5230_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "เดา——ผิด——แล้ว——"
  },
  Voice_5231_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5232_AwakerVoiceContent = {
    Text = "ซาน ผู้แกะสลักจากสีไค ขอถวายมีดแกะสลักให้ท่าน แม้ท่านอาจเต็มไปด้วยข้อบกพร่อง แต่ยังคงคู่ควรแก่การแกะสลัก"
  },
  Voice_5232_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5238_AwakerVoiceContent = {
    Text = "เด็กๆ ที่ดื้อๆ มารวมกันเร็ว~"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "ศิลปะที่แท้จริงไม่ต้องการคำอธิบาย."
  },
  Voice_5239_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5240_AwakerVoiceContent = {
    Text = "ศิลปะที่แท้จริงไม่ต้องการคำอธิบาย."
  },
  Voice_5240_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5241_AwakerVoiceContent = {
    Text = "ออรีตา ช่วยได้ไหม?"
  },
  Voice_5241_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5242_AwakerVoiceContent = {
    Text = "เป่าแตร!"
  },
  Voice_5242_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5243_AwakerVoiceContent = {
    Text = "ไม่คำนึงถึงต้นทุน!"
  },
  Voice_5243_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5244_AwakerVoiceContent = {
    Text = "ความรู้สึกที่ได้สัมผัสแสงแดด... อบอุ่นและนุ่มนวลเช่นนี้ ทำให้อยากจะหลั่งน้ำตา"
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5244_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "เพื่อแสดงความขอบคุณ...... ผมจะสร้างแท่นบูชาลับไว้ในความลึกของความทุกข์ เพื่ออุทิศให้กับคุณ"
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5245_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "เนื้อและเลือดของพี่ชายและร่างกายของฉัน ประสานกันอย่างแนบแน่นมากขึ้นแล้ว......"
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5246_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "ฉันแข็งแกร่งกว่าที่คุณคิดนะ ดังนั้นตอนใช้ฉัน สามารถออกแรงมากกว่านี้ได้เลย ไม่ต้องเกรงใจหรอก"
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5247_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "เป็นแค่ความผิดของฉันหรือเปล่า? ความกระหิวเลือดดูเหมือนจะลดลงบ้างแล้ว"
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5248_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "ตั้งแต่ยังไม่ได้เข้าเรียนอย่างเป็นทางการ ผมก็เฝ้ารอคอยการปรากฏตัวของคุณ ตอนนี้ดูเหมือนว่าเราจะทำงานร่วมกันได้ไม่เลวเลยนะ? เพื่อนร่วมทีม"
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "ไม่น่าดูเลย"
  },
  Voice_5250_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5251_AwakerVoiceContent = {Text = "ยะ!"},
  Voice_5251_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5252_AwakerVoiceContent = {
    Text = "ฮ่าฮ่าฮ่าฮ่า!"
  },
  Voice_5252_AwakerVoiceTitle = {
    Text = "โจมตี · บ้าคลั่ง"
  },
  Voice_5253_AwakerVoiceContent = {
    Text = "อืม.."
  },
  Voice_5253_AwakerVoiceTitle = {
    Text = "โจมตี·เศร้าใจ"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "ทำลายฉันให้เต็มที่เลย!"
  },
  Voice_5254_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5255_AwakerVoiceContent = {
    Text = "ไอจิสกลัว ไม่ใช่กลัวพวกคุณหรอก แต่กลัวว่าตัวเองจะทำให้พวกคุณต้องหวาดกลัวและเศร้าโศกอีกครั้ง"
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "หนังสือเทพนิยายในยุคนี้น่าสนใจกว่าที่ฉันเคยอ่านเมื่อก่อนมากเลย! อาๆ! ท่านเจ้านายอย่าเข้าใจผิดนะ! ฉันเลยวัยที่จะฟังเรื่องราวตอนก่อนนอนไปแล้ว!"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "ทำลายฉันให้เต็มที่เลย!"
  },
  Voice_5257_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5258_AwakerVoiceContent = {
    Text = "ฮื้อ... ไอจิสไม่ได้สร้างปัญหาให้กับทุกคนใช่ไหม?"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "เธออยู่ข้างฉันด้วยความเชื่อมั่นที่ดูน่าเอ็นดูมาตลอด...ก็ได้ บางที การใช้เธอก็อาจไม่ใช่เรื่องแย่ แต่เธอจงจำไว้ ฉันทนไม่ได้กับการทรยศใดๆ โดยเฉพาะจากเธอ"
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5259_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "ฉันเสียใจแค่เพียงอย่างเดียวที่ตอนนั้นไม่ได้ตอกโครงกระดูกของพวกมันไว้บนเสา แล้วแขวนบนกำแพงเมือง! ทุกคนที่การทรยศฉัน เหยียบย่ำฉัน ดูถูกฉัน ฉันจะไม่ปล่อยให้ใครหลุดไปได้แม้แต่คนเดียว!"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5260_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "ใช่แล้ว ฉันเองก็เคยประจบสอพลอต่อหน้าคนพวกนั้น ไม่มีอะไรต้องปฏิเสธหรอก พวกเขาใช้ความไร้เดียงสาของฉัน แต่ฉันก็ทำให้พวกเขาต้องจ่ายราคาที่ต้องจ่ายเช่นกัน"
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5261_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "คุณคิดว่าคำพูดหวานๆ ไม่กี่คำและการดูแลเอาใจใส่ที่ไม่จริงใจแค่ไม่กี่วัน จะทำให้ฉันยอมใส่กุญแจมืออีกครั้งและกลายเป็นเครื่องมือของคุณได้หรือ?"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5262_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "ทุกคนที่พยายามควบคุมฉัน ใช้ประโยชน์จากฉัน ล้วนถูกฉันส่งไปยังยมโลกด้วยมือของฉันเอง——ฉันไม่ขัดข้องที่จะส่งเธอไปด้วย"
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5263_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "อา...ขอโทษนะ อย่าขยับไปไหน!"
  },
  Voice_5264_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5265_AwakerVoiceContent = {
    Text = "อย่าแตะต้องฉัน!"
  },
  Voice_5265_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5266_AwakerVoiceContent = {
    Text = "ไม่เคารพ！"
  },
  Voice_5266_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5267_AwakerVoiceContent = {
    Text = "ยอมแพ้ซะ... ยินดีต้อนรับสู่ดินแดนแห่งความสุขและความฝัน..."
  },
  Voice_5267_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5268_AwakerVoiceContent = {
    Text = "นี่คือเมืองที่วิญญาณของผู้ตายหลายพันหลงทาง ไร้ซึ่งบ้านเกิด"
  },
  Voice_5268_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5269_AwakerVoiceContent = {
    Text = "ไอจิสจะพยายามอย่างเต็มที่!"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "นั่น... ฉันไม่สามารถควบคุมการดูดซึมพลังชีวิตได้ ดังนั้นกรุณาอย่าเอามือยื่นเข้าไปในเปลเด็ดขาด การทำแบบนั้นจะทำให้คุณป่วยได้"
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "หวังว่าในระหว่างที่เรากำลังทำการสนทนาอยู่นี้ ระบบของเธอจะไม่เกิดข้อผิดพลาดขึ้นมา ผู้ช่วยที่น่ารักแต่น่าตำหนิของฉัน ตอนนี้ไม่มีห้องทดลองเหลือให้เธอทำลายอีกแล้ว"
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "เรื่องราวเล็กน้อย·เกี่ยวกับเอริกา"
  },
  Voice_5271_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「เอริกา」"
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "แขนก็เป็นปัญหา แขนพวกนี้ชอบดึงผมของฉันอยู่เรื่อย! แม้แต่มือของตัวเองก็ควบคุมไม่ได้ ฉันช่างไร้ประโยชน์จริงๆ... หรือว่า..."
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับตัวเอง"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "ขอบคุณสำหรับคำแนะนำ ฉันเข้าใจแล้วฟีนต์การเลือก ฉันถือว่าทั้งหมดนี้เป็นเรื่องธรรมดา ไม่คิดว่าจะทำให้เธอมีภาระทางจิตใจมากขนาดนั้น จากนี้ไป ฉันจะพยายามใช้ชีวิตเพื่อตัวเอง.."
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5274_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "ในช่วงเวลาที่ยาวนานแสนนาน ฟีนต์และฉันมีแค่กันและกัน... แต่ตอนนี้ ฉันมีคนสำคัญคนใหม่แล้ว... ผู้พิทักษ์ ขอถอนคำพูดเดิมของฉันนะคะ คุณไม่เหมือนพวกเขา คุณไม่ได้สนใจแค่เสียงเพลงและการแต่งกายของฉัน แต่คุณมองมาที่ฉัน ดังนั้น ฉันก็จะมองไปที่คุณเช่นกัน"
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5275_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "ดวงดาวในความฝันที่หลับลึก ไปยังที่ควรไป และชี้ทางสู่ดินแดนสวรรค์!"
  },
  Voice_5276_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5277_AwakerVoiceContent = {
    Text = "ทำไมข้าจึงสวมชุดนี้ตลอดเวลา? เพื่อที่จะได้พร้อมร้องเพลงจากใจให้ท่านฟังในทุกโอกาส"
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5277_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "สิ่งที่ฉันอยากทำเองหรือ? ...ขอโทษนะ ฉันไม่เข้าใจว่าคุณหมายถึงอะไร... ที่จริงแล้ว ฟีนต์ก็ถามฉันเกี่ยวกับเรื่องนี้หลายครั้งแล้ว แต่ฉันแค่หวังว่าเธอจะหายดีในเร็ววัน.."
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5278_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "ในช่วงเวลาที่อยู่บนดาวร้าง ความกรุณาของเหล่าผู้มีอำนาจได้มอบทรัพยากรให้เราสองพี่น้องเพื่อการอยู่รอด และในที่สุด ก็เป็นพวกเขาที่มอบโอกาสให้ผมหนีออกจากดาวร้าง แม้ว่าจะจำกัดแค่คนเดียวก็ตาม พวกเขาทุกคนคือผู้มีพระคุณของผม เหมือนดั่งผู้พิทักษ์ที่มอบที่พักพิงให้กับผมเช่นกัน"
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5279_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "ท่านคือผู้ใจดีที่ให้ที่พักแก่ฉัน ไอจิสจะเชื่อฟังคำสั่งของท่าน ถ้าหากไอจิสสามารถมีประโยชน์มากกว่านี้ก็คงจะดี.."
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "อย่าลืมเตรียมสถานที่นะ สถานที่ที่คุณจองไว้จะไม่เล็กกว่าที่เอลวอสหรอกใช่ไหม?"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5281_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "ดีมาก คาเรนตอนนี้มีแรงจูงใจมากขึ้นแล้ว สามารถทำความสะอาดบ้านได้ยี่สิบห้องในหนึ่งวัน！"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5282_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "นี่คือดนตรีที่เก่าแก่พอๆ กับสายน้ำ ดนตรีของ「พวกเรา」 เจ้านาย เชิญมาร่วมเต้นรำกันเถอะ！ก่อนที่เสียงของคาเรนจะถูก「พระองค์นั้น」พรากไป……"
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5283_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "เจ้านาย! เสียงของคาเรน... กำลังหายไป... ช่วย..."
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5284_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "คาเรนมองเห็นได้ดีขึ้น... เจ้าคะ นายท่าน ท่านลืมหวีผมอีกแล้วใช่ไหม!"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5285_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "แม้ว่าจะแข็งแกร่งขึ้น แต่คาเรนก็ไม่ได้อยากแก้แค้นเลย คาเรนแค่อยากร้องเพลง เต้นรำ และจัดปาร์ตี้"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5286_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "เพื่อที่จะคงอยู่ในโลกนี้แม้หลังจากทุกสิ่งถูกทำลายไป ข้าได้มอบวิญญาณและเลือดให้กับคนจำนวนมหาศาล พละกำลังของข้าในตอนนี้ แตกต่างไปจากเมื่อครั้งแรกที่ข้ารับความตั้งใจนี้มากอย่างมาก.."
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับอดีต"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "อย่าหวังว่าจะเจอฉันในตึกเรียน ที่นี่เต็มไปด้วยกลิ่นเหม็นของพวกนักวิชาการแก่ๆ ที่โบราณและไร้ชีวิตชีวา ฉันทนอยู่ที่นี่ได้แค่วันเดียว"
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5289_AwakerVoiceContent = {
    Text = "อย่าหนี."
  },
  Voice_5289_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_5290_AwakerVoiceContent = {
    Text = "ประเทศบ้านเกิดของข้าศรัทธาต่อ「เทพเจ้า」 และพระราชาที่ข้าติดตามก็เป็น「ผู้สื่อสารกับเทพเจ้า」โดยธรรมชาติ"
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับดินแดนนิรันดร์"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "ที่นี่ของคุณกลับมีผู้มีความสามารถมากมาย สมควรจัดงานเลี้ยงสังสรรค์ครั้งใหญ่... วางใจได้ เดี๋ยวคำเชิญจะถูกส่งถึงมือคุณโดยผู้ติดตามของฉันแน่นอน"
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5292_AwakerVoiceContent = {
    Text = "มาเลย!"
  },
  Voice_5292_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5293_AwakerVoiceContent = {
    Text = "ถ้ามีเพื่อนร่วมทางมากกว่านี้.."
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "ฉันไม่เหมือนกับคนนั้นนะ ที่เธอให้ไปมีแต่ความหวาดกลัวและหนาวสั่นเพราะความเป็นศัตรู แต่สิ่งที่ฉันให้คือการสัมผัสที่ใกล้ชิดและอบอุ่น ความเจ็บปวดที่หวานชื่นและร้อนแรงพร้อมกับความรักนะ?"
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับวันดา"
  },
  Voice_5294_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างกายที่ตื่นขึ้น「วันดา」"
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "อย่าคิดว่าจะปล่อยผ่านไปง่ายๆ! ความอับอายครั้งนี้ ฉันจะเอาคืนทุกอย่าง!"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "มือของคุณอบอุ่นดั่งวิญญาณของคุณ เปลวไฟซีด ข้า... ขอบคุณสำหรับการสัมผัสของท่าน"
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "การเล่นไพ่บริดจ์ในห้องเรียนมีอะไรไม่ดี? มีโต๊ะ มีคน แล้วฉันก็นำไพ่มา แบบนี้ก็แปลว่า “เกมเริ่มแล้ว”!"
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5299_AwakerVoiceContent = {
    Text = "อย่า.."
  },
  Voice_5299_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5300_AwakerVoiceContent = {
    Text = "จ้องมองเหว."
  },
  Voice_5300_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5301_AwakerVoiceContent = {
    Text = "จ้องมองเหว."
  },
  Voice_5301_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5302_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5302_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5303_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5303_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5304_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5304_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5305_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5305_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5306_AwakerVoiceContent = {
    Text = "อาบแสงเทพ!"
  },
  Voice_5306_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5307_AwakerVoiceContent = {Text = "เฮ้!"},
  Voice_5307_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5308_AwakerVoiceContent = {
    Text = "วิญญาณที่อ่อนแออยู่รวมกัน นอกจากจะทำให้เสียงดังรบกวนแล้ว ยังจะมีประโยชน์อะไรได้อีกล่ะ เฮ้อ.."
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "สงครามมักจะนำมาซึ่งความทุกข์เสมอ การทนทุกข์เป็นหน้าที่ของนักรบ แม้ว่าฉันจะสูญเสียมือทั้งสอง สูญเสียเท้าทั้งสอง สูญเสียทุกอย่าง ฉันก็ยังคงต่อสู้เพื่อคุณ，และเพื่อความยุติธรรมของโลก"
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "นี่คือเครื่องบรรณาการที่เธอถวายแด่พระองค์?"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "คุณคิดว่าแค่นี้ก็สามารถเปลี่ยนแปลงอนาคตได้หรือ?"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5314_AwakerVoiceContent = {
    Text = "การตั้งครรภ์ของพระองค์... ในท้องของข้า.."
  },
  Voice_5314_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5315_AwakerVoiceContent = {
    Text = "หึ นับว่ารู้เรื่อง"
  },
  Voice_5315_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5316_AwakerVoiceContent = {
    Text = "การมอบของให้เจ้านายเป็นเรื่องที่สมควรอยู่แล้ว"
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "เธอลองเอาใจฉันดูน่ารักดีนะ"
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "เค้กบราวน์,      คาราเมลพุดดิ้ง,      ซาฮาร์เค้ก,      ช็อกโกแลตมูส,      คุกกี้... ต้องมีทุกโต๊ะ！"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5318_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "ช่วยดูให้หน่อยสิ ว่าชุดกระโปรงของฉันจัดเตรียมเรียบร้อยแล้วหรือยัง? ห้ามมีรอยยับ ห้ามมีที่หลวม...? เอ๊ะ ทำไม? เธอมีอะไรไม่พอใจหรือเปล่า?"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5319_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "ยินดีต้อนรับสู่พิธีการตื่นพลังครั้งสุดท้ายของข้า! ทั้งหมดนี้เป็นแผนการที่ข้าออกแบบอย่างพิถีพิถัน เจ้าผู้พิทักษ์ก็มีส่วนช่วยบ้าง แต่เพียงเล็กน้อย.."
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5320_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "โต๊ะและเก้าอี้ต้องตกแต่งด้วยลูกไม้ที่เข้ากับบุคลิกของฉัน ต้นไม้ในกระถางต้องเป็นต้นไม้แขวนสีแดง... รีบไปเตรียมมา!"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5321_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "ไปจองแขกสิ! ทำไมเรื่องแค่นี้ยังทำไม่ได้?"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5322_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "ไม่มีทางหนี!"
  },
  Voice_5323_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5324_AwakerVoiceContent = {
    Text = "ไม่มีทางหนี!"
  },
  Voice_5324_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5325_AwakerVoiceContent = {
    Text = "ฉันจะพยายามอย่างเต็มที่! เพื่อไม่ให้ผิดหวังในความคาดหวังของท่านเจ้าข้า"
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5325_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "ฉันค่อนข้างชอบผู้หญิงคนนั้นนะ เราเข้าใจกันได้ดี... ใช่! เข้าใจกันได้ดี!"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับวันดา"
  },
  Voice_5326_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างกายที่ตื่นขึ้น「วันดา」"
  },
  Voice_5327_AwakerVoiceContent = {
    Text = "คนไร้มารยาท!"
  },
  Voice_5327_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5328_AwakerVoiceContent = {
    Text = "คนไร้มารยาท!"
  },
  Voice_5328_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5329_AwakerVoiceContent = {
    Text = "กลายเป็นซาก"
  },
  Voice_5329_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_5330_AwakerVoiceContent = {
    Text = "ทำลายมันซะ."
  },
  Voice_5330_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5331_AwakerVoiceContent = {
    Text = "ทะลวงกำแพงของความเป็นจริงเลย!"
  },
  Voice_5331_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5332_AwakerVoiceContent = {
    Text = "คุณมีแผนจะข้ามทะเลในเร็วๆ นี้ไหม? คุณสามารถตอบรับคำขอร้องที่ไม่สมควรของฉันได้ไหม ให้ฉันไปด้วย? ขอแค่ให้ฉันได้ออกไปสู่ท้องทะเล.."
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5332_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "หากท่านยังเชื่อมั่นในตัวข้า โปรดอนุญาตให้ข้าเป็นเครื่องหมายนำทางของเส้นทางนี้ อย่างไรก็ตาม แม้จะเป็นงานที่ง่ายดายเพียงนี้ ข้าก็เคยพลาดพลั้งในการปฏิบัติหน้าที่มาก่อน..."
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5333_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "ไม่อยากไปทะเลใหญ่หรือเปล่า? ให้ฉันดูแผนที่ทะเลปัจจุบันก่อน... ละติจูดใต้ 47 องศา 9 ลิปดา ลองจิจูดตะวันตก 126 องศา 43 ลิปดา ตรงนี้แหละ"
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5334_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "ในอดีต ฉันเคยก่อให้เกิดภัยพิบัติหลายครั้ง  thậm chíเกือบทำลายล้างบางอารยธรรม... ฉัน... หากจะบอกว่าไม่ได้ตั้งใจ นั่นจะสายเกินไปแล้วหรือเปล่า?"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5335_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = "ข้าคือผู้ที่ประจำการอยู่ที่ทางเข้าสู่อาณาจักรนิรันดร์ เพื่อชี้แนะทิศทางแก่ผู้ที่หวนคืนสู่บ้านเกิด น่าขันจริงๆ ผู้ที่มีหน้าที่เช่นนี้ กลับลืมไปว่าบ้านเกิดของตนอยู่แห่งใด...\nท่าน...จะกลายเป็นประภาคารของข้าหรือไม่?"
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5336_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "กระจุกดาว."
  },
  Voice_5337_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5338_AwakerVoiceContent = {Text = "อ้า"},
  Voice_5338_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5339_AwakerVoiceContent = {
    Text = "หมอกหนา."
  },
  Voice_5339_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5340_AwakerVoiceContent = {Text = "หึ"},
  Voice_5340_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5341_AwakerVoiceContent = {
    Text = "ผู้คุ้มครองส่วนใหญ่ไม่แตกต่างกัน แต่ผู้หญิงคนนั้นเป็นข้อยกเว้น หากเป็นไปได้ ขอเส้นทางอื่นแทนได้ไหม"
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "เรื่องราว, เกี่ยวกับมิลียาห์ม"
  },
  Voice_5341_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「มิลียัม」"
  },
  Voice_5342_AwakerVoiceContent = {Text = "อ้า"},
  Voice_5342_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5343_AwakerVoiceContent = {
    Text = "ไม่เป็นไร"
  },
  Voice_5343_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5344_AwakerVoiceContent = {
    Text = "เอามือออก"
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "ก่อนที่ฉันจะกลับไปยังพระราชวังใต้ทะเล ขอยืมพละกำลังจากทะเลลึกให้คุณชั่วคราวเท่านี้พอ"
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5346_AwakerVoiceContent = {Text = "มา!"},
  Voice_5346_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5347_AwakerVoiceContent = {
    Text = "ชอบเหรอ?ฉันชอบความเจ็บปวด ชอบผิวหนังที่บวมแดงและร้อน ชอบเสียงครางที่ผสมระหว่างความสุขและความเจ็บปวด ความเจ็บปวดนี่แหละคือความปรารถนาที่ดั้งเดิมและแท้จริงที่สุดใช่ไหม?"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "เข้าร่วมกับออรีตา!"
  },
  Voice_5348_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5349_AwakerVoiceContent = {
    Text = "เข้าร่วมกับออรีตา!"
  },
  Voice_5349_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5350_AwakerVoiceContent = {
    Text = "พี่สาวคนนั้นจ้องฉันอย่างดุดันเสมอ แต่ไม่รู้ทำไม ฉันมักจะรู้สึกคุ้นเคย เป็นเพราะเธอเหมือนแม่ไหม?"
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับชิโล"
  },
  Voice_5350_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับ「ชิโล」ร่างกายที่ตื่นขึ้น"
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "สมองรู้สึกว่องไวกว่าเดิม รู้สึกดี"
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5351_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "ผมชอบทำงานในห้องทดลองมากกว่าการออกไปปฏิบัติงาน—หรือคุณคิดว่าเครื่องมือผู้ช่วยพวกนั้นลอยขึ้นมาจากทะเลหรือไง?"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5352_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "ไม่ว่าจะเป็นสกรูหรือตะปู ก็ยิ่งมากยิ่งดีอยู่แล้ว"
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "ร่างกายเริ่มรับพละกำลังนี้ไม่ไหวแล้ว แต่ยังไม่ถึงเวลาเปลี่ยนตุ๊กตาใหม่ มาช่วยผมประคองขาข้างนี้หน่อย ผมต้องปรับให้เหมาะสมอีกนิด"
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5354_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "ภาระแห่งการนำทางแสงสว่างสามารถทำให้ผู้บริสุทธิ์ที่สุดทรุดลงได้ หากเจ้ารู้สึกเหนื่อยล้า เปลวไฟขาวของข้า โปรดบอกข้าด้วย ข้าจะทำทุกอย่างเท่าที่จะทำได้เพื่อช่วยบรรเทาความทุกข์ของเจ้า และแบ่งปันน้ำหนักแห่งความเป็นสิริมงคลนับหมื่น"
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับความเหนื่อยล้า"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "ความเห็นชอบของท่านคือเหตุผลที่ข้าพเจ้าดำรงอยู่ในฐานะอัศวิน"
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5356_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "ได้รับการปกคลุมด้วยแสงเรืองของเทพเจ้า นี่คือพลังศักดิ์สิทธิ์ที่พระเจ้าของข้าทรงมีหรือไม่? ช่างยิ่งใหญ่และศักดิ์สิทธิ์จริงๆ"
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5357_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "ประตูของเทพเจ้า,     อยู่ใกล้แค่เอื้อมแล้ว."
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5358_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "สว่างขึ้นเรื่อยๆ ชัดเจนขึ้นเรื่อยๆ.."
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5359_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "สามารถฟื้นคืนร่างให้สมบูรณ์อีกครั้ง... ข้าได้ยินแล้ว เสียงศักดิ์สิทธิ์จากสวรรค์กำลังบรรเลงเพื่อข้า.."
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5360_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "พระองค์จะนำข้าเข้าสู่โบสถ์ ประทานที่พักผ่อนให้ข้า.."
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5361_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "โปรดวางใจเถอะ พวกเรามีประโยชน์ทุกคน ฉันสามารถเย็บผ้าและทำความสะอาดได้ ฉันอีกคนหนึ่งถนัดการต่อสู้ และคนอื่นๆ..."
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "ฉันเกลียดสิ่งที่สว่างและนุ่มนวล ความอ่อนโยนเหมือนกระจกเงา ความน่าเกลียด ความโลภ และความเปราะบางทั้งหมดจะไม่มีที่ซ่อนเมื่ออยู่หน้ามัน"
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "อยากจับบราวน์ไหม? ฉันไม่สามารถตัดสินใจให้เธอได้ คุณควรไปถามเธอด้วยตัวเอง"
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "อยากเอาใจฉันเหรอ? งั้นคุกเข่าลง เอาคอของเธอออกมา และแน่ใจว่าอยู่เงียบ ๆ จนกว่าฉันจะดื่มเลือดเธอจนพอใจ"
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5366_AwakerVoiceContent = {
    Text = "ดื่ม!"
  },
  Voice_5366_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5367_AwakerVoiceContent = {
    Text = "เมื่อคืนฉันฝันว่า นั่นเป็นจุดเริ่มต้นของการที่ฉันได้ล่องลอยไปในหมู่ดาว"
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5367_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "ไอจิส สามารถช่วยได้ไหม?"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5368_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5369_AwakerVoiceContent = {
    Text = "รู้สึกได้เลย~"
  },
  Voice_5369_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5370_AwakerVoiceContent = {Text = "ตุบ!"},
  Voice_5370_AwakerVoiceTitle = {
    Text = "ทักษะ·3"
  },
  Voice_5371_AwakerVoiceContent = {
    Text = "ระวัง!"
  },
  Voice_5371_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5372_AwakerVoiceContent = {
    Text = "ถอยหลัง."
  },
  Voice_5372_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5373_AwakerVoiceContent = {
    Text = "ไม่มีใครจะได้รับความเสียหาย...ในโลก.."
  },
  Voice_5373_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5374_AwakerVoiceContent = {
    Text = "(ทำเสียงอ้อน)"
  },
  Voice_5374_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5375_AwakerVoiceContent = {
    Text = "โปรดอนุญาตให้ข้าวางแท่นบูชาของพระผู้เป็นเจ้าของข้า นี่คือรูปเคารพที่แกะสลักด้วยแรงศรัทธา จะไม่ก่อให้เกิดคำสาปใดๆ แก่ท่าน"
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "แค่นิดเดียว.."
  },
  Voice_5376_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5377_AwakerVoiceContent = {
    Text = "ประแจของฉันยังไม่พร้อม!"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "เคมี, ฟิสิกส์, การประยุกต์ใช้เงินใจ... ในยุคนี้ไม่จำเป็นต้องเรียนรู้ทักษะทั้งเจ็ดของอัศวินแล้วหรือ? เข้าใจแล้ว ถ้าอย่างนั้น ขอให้ท่านจัดหลักสูตรที่เหมาะสมให้ข้าด้วย!"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "ออรีตาเคยเดินทางมาแล้ว! ไม่ได้ลอยไปกับคลื่น แต่เป็นการเดินทางด้วยรถม้าใหญ่!"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5379_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "แมงกะพรุนไฟฟาโรห์, แมงกะพรุนมงกุฎ, และแมงกะพรุนพีช ทุกคนอยู่รวมกันเป็นกลุ่มๆ เสมอ และแน่นอน ออรีตาก็เช่นกัน! ออรีตาต้องอยู่กับทุกคนด้วย!"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5380_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "เรื่องในอดีตเหรอ? จำไม่ค่อยได้แล้ว... แต่ออรีตาจำได้ว่าเคยทำงานที่พิพิธภัณฑ์สัตว์น้ำมาก่อนนะ! ค่าจ้างรายวันคือ 2 ชิ้นส่วน!"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5381_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "บอกคุณเบาๆ นะ ออรีตาจริงๆ แล้วเป็นพวกใต้ทะเล อย่างอารัน, ทรานส์... เอ่อ สรุปคือ ออรีตาเป็นคนใต้ทะเลนะ! ถ้าออรีตาเชื่อฟัง กินผักเยอะๆ และมีเพื่อนมากๆ พวกอาร์เทสก็จะต้อนรับออรีตา!"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5382_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "บ้านของออรีตา เพื่อนที่พิพิธภัณฑ์สัตว์น้ำ แมงกะพรุนที่ออรีตารักที่สุด ทุกคนหายไปแล้ว... คุณจะหายไปด้วยหรือเปล่า? ไม่สามารถอยู่เล่นกับออรีตาตลอดไปได้หรือ?"
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5383_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "ชนะแล้วเหรอ? ดีจริงๆ.."
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5387_AwakerVoiceContent = {
    Text = "เพื่อสันติภาพ"
  },
  Voice_5387_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5388_AwakerVoiceContent = {
    Text = "เพื่อความยุติธรรมที่แท้จริง"
  },
  Voice_5388_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5389_AwakerVoiceContent = {
    Text = "ฉันรู้ว่าเธออยู่ในตัวฉัน!"
  },
  Voice_5389_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5390_AwakerVoiceContent = {
    Text = "มนุษย์ เทียมเทพ ร่างกายที่ตื่นขึ้น รวมถึง การหลอมกร่อน... ทุกสิ่งในโลกล้วนจะกลายเป็นฐานรากสำหรับการสร้างดินแดนนิรันดร์ของข้าใหม่"
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "ตื่นเถอะ ตื่นเถอะ ฉันรู้ว่าเธออยู่ในตัวฉัน!"
  },
  Voice_5391_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5392_AwakerVoiceContent = {
    Text = "ยูวฮะชิ... เขาเหมือนพี่ชายของฉันนิดหน่อย ทำให้ฉันนึกถึงวันที่เศร้าหมอง เงียบเหงา และนอนไม่หลับเหล่านั้น"
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับยูวฮะชิ"
  },
  Voice_5392_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ยูวฮะชิ」"
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "ความสัมพันธ์ของเราเหมือนเชอร์ล็อก โฮล์มส์และดร.วัตสันใช่ไหม?คุณได้ติดตามนิตยสารที่กำลังเป็นที่นิยมในช่วงนี้บ้างหรือเปล่า?"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "คลานเข้าสู่ความงามเถอะ"
  },
  Voice_5394_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5395_AwakerVoiceContent = {
    Text = "คลานเข้าสู่ความงามเถอะ"
  },
  Voice_5395_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5396_AwakerVoiceContent = {
    Text = "ความรู้สึกเกลียดชัง เป็นคำวิเศษณ์ หมายถึงการรู้สึกไม่ชอบสิ่งใดสิ่งหนึ่ง รู้สึกไม่พอใจ เป็นกริยา หมายถึงความรู้สึกไม่ชอบและหลีกเลี่ยงสิ่งนั้น ความขุ่นเคือง เป็นคำนาม หมายถึงความรู้สึกไม่พอใจ <Del:ความรู้สึกไม่พอใจที่ถูกกดดัน ให้ฉันทำลาย ให้ฉันทำลาย ให้ฉันทำลาย> —— ขอโทษนะ ฉันเกรงว่าฉันไม่เข้าใจว่าอะไรคือ「ความรู้สึกไม่พอใจ」"
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "สุดท้ายก็.."
  },
  Voice_5397_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "เปลี่ยนไปมากกว่าเดิม"
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "จงจำชื่อของข้าไว้ โกลิอัท ชื่อนี้มีชะตาที่จะเหยียบย่ำประวัติศาสตร์อันไม่สำคัญของมนุษยชาติให้ราบคาบ"
  },
  Voice_5399_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5400_AwakerVoiceContent = {
    Text = "กรุณาอย่ากังวล"
  },
  Voice_5400_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5401_AwakerVoiceContent = {
    Text = "หวังว่าคุณจะไม่ทำให้ศักยภาพของตัวเองและคำคาดหวังของมนุษยชาติสูญเปล่า ผู้พิทักษ์คนใหม่."
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5402_AwakerVoiceContent = {
    Text = "เกินพิกัด"
  },
  Voice_5402_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5403_AwakerVoiceContent = {
    Text = "ทำงานเร่งสปีด"
  },
  Voice_5403_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5404_AwakerVoiceContent = {
    Text = "อืม รูปที่คุณพบในกระเป๋าเงินน่ะเหรอ? อา นั่นคือฉันเมื่อก่อน ส่วนลักษณะตอนนี้เป็นเพราะเพื่อนนักพนันและคู่แข่งของฉันทำให้เป็นแบบนี้แหละ"
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5404_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "พอดีเลย——จะมาเล่นพนันสักตากไหม? ถ้าชนะฉันจะบอกความลับให้ฟังหนึ่งข้อ? \nแต่ระวังไว้ อย่าให้เอลวาจับได้นะ~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5405_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "นายสนใจขนของตัวเองมากไหม? อยากลองลูบดูไหม? ไม่ต้องห่วงนะ ฉันใจดีมาก!"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5406_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "แน่นอนว่าย่อมมีข้อดีเหมือนกัน ข้าไม่ได้พบกับหวั่นของข้าแล้วหรือ? เมื่อเปรียบเทียบกับเรื่องนี้ ความเป็นความตายและการเปลี่ยนแปลงของรูปลักษณ์ล้วนไม่มีความหมาย ใช่ไหม?"
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5407_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "คุณถามว่าฉันจะเสียใจไหม? ไม่มีทางเลย ถ้าชีวิตราบรื่นไปทุกอย่าง มันคงน่าเบื่อมากเลยใช่ไหม?"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5408_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "ในยุคของฉัน โรงเรียนเป็นสถานที่ฝึกนักรบ ตอนนี้ก็ยังคงเป็นเช่นนั้น"
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "เมสัน... ไม่เลย แบบนี้ก็ดีแล้ว อย่างน้อยเราก็ได้อยู่ด้วยกันอีกครั้ง 「24」"
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับ「24」"
  },
  Voice_5410_UnlockDesc = {
    Text = "เมื่อได้รับร่างกายที่ตื่นขึ้น「24」จะปลดล็อก"
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "ฉันทำได้ดีใช่ไหม? แล้วค่าตอบแทนล่ะ —— อะไรนะ ไม่มีอาหารกลางวันฟรีในโลกนี้หรอก!"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "ฉันมาจากสีไค ในที่นั้น ทุกคนอยากเป็นนักแสดง ไม่มีใครยอมเป็นแค่ผู้ชม ความจริงแล้ว เราทุกคนเป็นเพียงเชิงอรรถที่น่าเศร้าของเมืองนี้เท่านั้น"
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับอดีต"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "คุณเคยเห็นการแกะสลักหินโบราณหรือไม่? พวกมันหลอมรวมกับภูเขา พึ่งพาธรรมชาติเพื่อหลีกเลี่ยงการถูกทำลายโดยกาลเวลา ช่างเป็นสิ่งสร้างที่งดงามจริงๆ... แต่น่าเสียดาย ยังคงไม่พอ.."
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "นกพิราบ ไม่ได้บินกลับมาเลย.."
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5415_AwakerVoiceContent = {
    Text = "ถอยไป!"
  },
  Voice_5415_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_5416_AwakerVoiceContent = {Text = "หึ!"},
  Voice_5416_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5417_AwakerVoiceContent = {
    Text = "ดำเนินการตามคำสั่ง!"
  },
  Voice_5417_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5418_AwakerVoiceContent = {
    Text = "คนโง่"
  },
  Voice_5418_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5419_AwakerVoiceContent = {
    Text = "...อะ? เรียกฉันเหรอ? ฉันกำลังซ่อมมอเตอร์ไซค์อยู่ ไม่ได้ยินเลย... เอ้อ คนแปลกหน้าที่ใจดี คุณเห็นประแจของฉันไหม?"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5419_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "ความทรงจำของฉันมักจะพร่ามัว สามารถโฟกัสได้แค่สิ่งที่เกิดขึ้นในตอนนี้เท่านั้น แต่ฉันจะพยายามอย่างเต็มที่เพื่อจดจำชื่อของคุณ... ชื่ออะไรนะ?"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5420_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "คุณดูคุ้นหน้าอยู่นะ แต่ผมจำชื่อคุณไม่ได้แล้ว... คุณเป็นผู้ช่วยของผมใช่ไหม? ถ้าใช่ช่วยหยิบแป้นเกลียวให้ผมเจ็ดตัวได้ไหม?"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5421_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "ฉันแกะชื่อของคุณลงบนเรือมายา วันหนึ่งเมื่อเราออกไปผจญภัยด้วยกัน ฉันจะได้ไม่ลืมว่าต้องเรียกคุณว่าอะไร."
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5422_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "คุ้นเคยมาก เราต้องเคยเกิดอะไรบางอย่างระหว่างเราใช่ไหม? ให้ฉันใช้เวลาครู่หนึ่งเพื่อระลึกถึง... อ๋า เป็นคุณนี่เอง ผู้พิทักษ์!"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5423_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "คุณเป็นเด็กที่ไม่ค่อยซื่อสัตย์เลย แต่โชคดีที่ฉันมีเวลาและความอดทนมากพอที่จะรอคุณ.."
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "“ทุกคนมีความสุข” หรือไม่"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "ได้ล่าหัวที่ไม่เลวเลย... แม้มันจะยังไม่สามารถเทียบกับคอลเลกชันที่ดีที่สุดของฉันได้ แต่การเดินทางเพื่อหาของสะสมใหม่ๆ ก็ยังน่าตื่นเต้นเสมอ ครั้งหน้าก็ชวนฉันไปด้วยนะ"
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5427_AwakerVoiceContent = {
    Text = "เอิ่ม.."
  },
  Voice_5427_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5428_AwakerVoiceContent = {
    Text = "แม่บ้านมืออาชีพจะช่วยเจ้านายจัดการทุกอย่าง รวมถึงผู้ไม่หวังดีด้วยนะ~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "ตอนนี้เราถือว่าเป็นพวกเดียวกันแล้วนะ ถ้าวันไหนนายต้องนอนข้างถนน ฉันจะไม่ยอมให้นายต้องกินของเหลือหรอก"
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5430_AwakerVoiceContent = {
