  },
  Voice_5434_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5435_AwakerVoiceContent = {
    Text = "อย่าเข้ามาใกล้ฉันเด็ดขาด"
  },
  Voice_5435_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5436_AwakerVoiceContent = {
    Text = "อย่าเข้ามาใกล้ฉันเด็ดขาด"
  },
  Voice_5436_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5437_AwakerVoiceContent = {
    Text = "ฉันต้องกล่าวโทษคุณ ผู้พิทักษ์ คุณใจดีกับฉันเกินไป จนทำให้ฉันรู้สึกไม่มั่นคง——สำหรับฉันแล้ว ความเจ็บปวดทางร่างกายเท่านั้นที่เป็นความจริงและยืนยาวตลอดไป"
