  Voice_5439_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5440_AwakerVoiceContent = {
    Text = "พูดมาเลย ต้องการรางวัลอะไร?"
  },
  Voice_5440_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "อุ๊ย! ทั่วพื้นเต็มไปด้วยสิ่งสกปรกและเละเทะ... เท้าของข้าไม่มีที่จะวางเลย งั้นก็จงมอบหลังของเจ้ามาเถิด มนุษย์ผู้น้อย"
