  },
  Voice_5444_AwakerVoiceContent = {
    Text = "ถ้าเป็นงานรักษาความปลอดภัยอาจจะยากไปหน่อย แต่งานส่งของหรือรับ-ส่งจดหมาย ผมสามารถทำได้ทั้งหมด"
