  },
  Voice_5444_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5445_AwakerVoiceContent = {
    Text = "ดูสิ นายทำท่าทางยังไงตอนเจอ บราวน์ \n ... ฮี่ฮี่ คืนนี้ท่านบราวน์จะจัดการกับพวกขี้ขลาด สงสัยจริงๆ ว่าใครจะโชคร้ายขนาดนั้น?"
