  },
  Voice_54628_AwakerVoiceContent = {
    Text = "เปลือกหอยทั้งหมดอยู่ที่นี่แล้ว!"
  },
  Voice_54628_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "เปลือกหอยทั้งหมดอยู่ที่นี่แล้ว!"
  },
  Voice_54629_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_5462_AwakerVoiceContent = {
    Text = "พลังอันยอดเยี่ยม ไม่ใช่สิ่งที่ร่างกายแห่งทะเลลึกจะสามารถทนได้ คุณคงอิจฉาฉัน lắmสินะ ฮ่าฮ่า การเกิดมาเป็นมนุษย์ที่อ่อนแอไม่ใช่ความผิดของคุณหรอก สบายๆ นะ"
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5462_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "преклонись перед моей юбкой и поцелуй мои носки!"
  },
  Voice_54630_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_5463_AwakerVoiceContent = {
    Text = "สามารถใช้พวกที่พ่ายแพ้เหล่านี้เป็นทาสของฉันได้ไหม?"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5464_AwakerVoiceContent = {Text = "หึ"},
  Voice_5464_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5465_AwakerVoiceContent = {
    Text = "แค่นี่แหละ"
  },
  Voice_5465_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5466_AwakerVoiceContent = {Text = "อ้า"},
  Voice_5466_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5467_AwakerVoiceContent = {Text = "อ้า"},
  Voice_5467_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5468_AwakerVoiceContent = {
    Text = "หากฉันรู้เร็วกว่านี้ ว่าคนพวกนั้นในอดีตต้องทนทุกข์ทรมานเพราะคำสาปที่ทำลายล้างทุกอย่างนี้ ฉัน... ไม่ ตอนนี้รู้ก็ยังไม่สาย ฉันจะต้องกำจัดมันให้สำเร็จ กำจัดความทุกข์ทั้งหมด แม้ว่าฉันจะต้องเสียสละชีวิตอีกครั้ง"
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "อย่าท้อแท้เลย ทะเลจะโอบอุ้มทุกคนไว้"
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "ร่างกายแบบนี้ยังอ่อนแอเกินไปที่จะเป็นเพื่อนร่วมทางของฉัน เอาล่ะ ข้าจะพาเจ้าไปชมสโมสรกีฬาของสถาบัน เพื่อให้เจ้าได้เห็นอะไรใหม่ๆ และฝึกฝนให้แข็งแกร่งขึ้น!"
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "คนน่าสงสารที่ให้พละกำลังกับฉัน เธอโดนการหลอมกร่อนทรมานหนักมากเลย... ทำไมเธอทำสีหน้าแบบนั้น? อย่าคิดมาก! ฉันจะไม่บอกเธอหรอกว่าเธออยู่ที่ไหน!"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "หากคุณโชคดีมากพอ คุณก็สามารถเอาชนะทุกอย่างได้"
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "จะรุนแรงเกินไปไหม?"
  },
  Voice_5473_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5474_AwakerVoiceContent = {
    Text = "เอ๊ะ ที่นี่ส่วนใหญ่ยังเป็นเด็กอยู่เลย คุณสุภาพบุรุษคนนั้นสูงอายุแล้ว ส่วนชายหนุ่มใบหน้าเย็นชาคนนั้นแขนขาดไปข้างหนึ่ง ไม่มีใครเหมาะสมเลย... น่าปวดหัวจริงๆ"
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "จะรุนแรงเกินไปไหม?"
  },
  Voice_5475_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5476_AwakerVoiceContent = {
    Text = "รูนที่วาดอย่างประณีต เทวรูปที่แกะสลักด้วยความศรัทธา น้ำยาข้อห้ามที่กลั่นซ้ำแล้วซ้ำเล่า... ล้วนขาดไม่ได้"
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5476_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "บัลลังก์ควรสร้างจากหินสีเขียวโบราณที่ถูกขุดจากทะเลลึก บนแท่นบูชาควรทาด้วยเลือดของสัตว์บูชายัญ... ยังไม่ไปเตรียมอีกหรือ?"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5477_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "เรียกพวกนั้นมาทั้งหมดเถอะ พวกเขาควรจะสั่นสะท้านด้วยความเคารพและคุกเข่าลงต้อนรับการปรากฏตัวของพระองค์"
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5478_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "ฉันจะมุ่งหน้าไปยังซากปรักหักพังในทะเลลึก เพื่อชำระร่างกายด้วยน้ำทะเลที่พระองค์ทรงบังเกิด.."
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5479_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "ยินดีต้อนรับสู่พิธีการประสูติของพระองค์ พร้อมกันเป็นสักขีพยานในวันประสูติของพระองค์... อะไรนะ? เจ้าบอกว่าการสิ้นไปของพระองค์ก็เป็นชะตากรรมที่หลีกเลี่ยงไม่ได้หรือ?... ไม่ นั่นเป็นไปไม่ได้เด็ดขาด... ข้าได้เสียสละอะไรมามากมายแล้ว.."
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5480_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "ปฏิบัติตามคำสั่งสอนของพระเจ้า"
  },
  Voice_5481_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5482_AwakerVoiceContent = {
    Text = "ข้างกายคุณจะเป็นที่พักพิงของฉันและฟีนต์หรือเปล่า?"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5482_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5483_AwakerVoiceContent = {
    Text = "อืม ตอนนั้นฉันเสียงหายไป เป็นเพราะท่านช่วยให้มันกลับมาเป็นปกติ"
  },
  Voice_5483_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5483_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5484_AwakerVoiceContent = {
    Text = "ปฏิบัติตามคำสั่งสอนของพระเจ้า"
  },
  Voice_5484_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5485_AwakerVoiceContent = {
    Text = "จักรวาลอันกว้างใหญ่ ห้วงอวกาศอันไร้ขอบเขต การเดินทางที่ไม่มีที่สิ้นสุด เคยทำให้ฉันหลงทาง.."
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5485_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "วิธีการยกระดับโดยใช้วิธีลัด แต่การฝึกฝนทักษะก็ห้ามละเลยเช่นกัน"
  },
  Voice_5486_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5487_AwakerVoiceContent = {
    Text = "ที่แท้วิธีนี้ก็ใช้ได้กับฉันเหมือนกัน.."
  },
  Voice_5487_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5488_AwakerVoiceContent = {
    Text = "ความรู้สึกที่น่าอัศจรรย์"
  },
  Voice_5488_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5492_AwakerVoiceContent = {
    Text = "การปรากฏตัวของพระองค์จะทำให้ความทุกข์ที่เกิดจากความตายสีดำนี้สิ้นสุดลง ใช่ไหม?"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "สวัสดีตอนกลางวัน ท่านผู้บัญชาการ หากท่านจะออกไปสอบสวน ขออนุญาตให้ข้าพเจ้าได้ร่วมเดินทางคุ้มกันท่านด้วย"
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5493_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "ทำอะไรดี? ถ้าเบื่อก็ไปเขียนรายงานการดำเนินการครั้งนี้ซะ."
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "จะเริ่มแล้วหรือ? สัตว์เลี้ยงตัวน้อยของฉันหิวมานานมากแล้ว.."
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "พละกำลังของโลหิตกำลังไหลทะลัก."
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "...เดี๋ยวก่อน ฉันเคยเห็นสิ่งนี้มาก่อน พวกเขาให้ฉันดื่มน้ำที่มีเมือกสีดำแบบนี้ บางทีพละกำลังแห่งเปลวไฟสีเขียวที่ฉันได้รับอาจเกี่ยวข้องกับสิ่งนี้? ก็นับว่าเป็นผลดีจากโชคชะตาเลวร้ายแล้วล่ะ"
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "รามอน่า·เดกสเตอร์ เรียกฉันว่ารามอน่าก็พอ หวังว่าจะได้ร่วมงานกับคุณในอนาคต ผู้พิทักษ์."
  },
  Voice_5498_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5499_AwakerVoiceContent = {Text = "ใช่."},
  Voice_5499_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_5500_AwakerVoiceContent = {
    Text = "ได้รับคำสั่งแล้ว"
  },
  Voice_5500_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5501_AwakerVoiceContent = {
    Text = "ฮึ่ม คนที่ไม่มีความเคารพ ข้าจะลงมือเล่นด้วยพวกเจ้าเอง"
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "สิ่งที่น่ารำคาญ? ท่อสูบยาสูบที่เพิ่งหมดพอดี รถม้าที่ไม่ได้ขึ้นทัน ฝนที่ตกลงมาตอนใส่รองเท้าหนังใหม่ เอาเป็นว่า โชคร้ายทุกอย่างนั้นน่ารำคาญไปหมด"
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "ประแจขันน็อต ประแจปรับได้ ประแจหกเหลี่ยม ไขควงปากแบน ไขควงแฉก สกรูหัวจม สกรูหัวกลม... อะไรก็ตามที่ใช้ซ่อมของเสียได้ ฉันชอบทั้งนั้น"
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = "เอ๊ะ~ โดนจับได้แล้วสินะ~ \n ไม่เป็นไรหรอก พลังจิตของร่างกายที่ตื่นขึ้นมีมากมาย อย่างน้อยก็ต้องขโมยอีก 365 ครั้ง พวกเธอถึงจะกลายเป็นหุ่นยนต์ที่ไร้ความรู้สึกนะ~ ทำไม่ได้เหรอ? โอเค คราวหน้าฉันจะระวังแน่นอน! ใช่แล้ว แค่ขโมยความกลัวนิดหน่อยตอนที่ร่างกายถูกตัดออก คงไม่เป็นไรใช่ไหม!"
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5504_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "เฮ้ คุณคงรู้ความลับของเวทมนตร์คาเซียแล้วใช่ไหม? หืม เพื่อป้องกันไม่ให้คุณเปิดเผยความลับ ไม่ว่าจะไปแสดงที่ไหน คุณก็ต้องตามฉันไปด้วยนะ~ ฮ่าๆ คุณบอกว่าฉันทำไปเพราะอยากเก็บอารมณ์ของคุณ? แน่นอน ไม่มีความลับอะไรที่ปิดบังคุณได้!"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5505_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = "เธอ มาเป็นผู้ช่วยนักมายากลของคาเซียสิ! อย่ากลัวนะ~ เพียงแค่เข้าไปในกล่องมายากลของฉันแป๊บเดียวก็พอ \n\nซ่อนดีแล้วหรือยัง? ฉันจะเสียบดาบเข้าไปแล้วนะ~ จริงๆ ข้างในไม่มีอะไรเลย~"
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5506_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "มาเลย ใส่หมวกทรงนี้สิ! แล้วพูดออกมาว่าของขวัญที่คุณต้องการที่สุดคืออะไร โอเค แบบนั้นน่ะเหรอ ฉันเข้าใจแล้ว! ตอนนี้ ลองลูบด้านในของหมวกสิ——"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5507_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "มันทำให้ฉันรู้สึกกังวลนิดหน่อย เด็กๆ พวกนั้นมาดูการแสดงทุกครั้ง สต็อกของฉันจะหมดเร็ว ๆ นี้... เอ่อ นักมายากลห้ามแสดงกลเดิมซ้ำกับผู้ชมกลุ่มเดิม การสร้างกลใหม่เหรอ? ขอโทษนะ ฉันไม่มีความสามารถแบบนั้น ที่ฉันถนัดคือการเลียนแบบเท่านั้น"
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5508_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "สถาบันนี้ทรุดโทรมมาก ห้องพักของอาจารย์ใหญ่เป็นที่เดียวที่พอจะดูดีหน่อย คุณคิดว่าอย่างไร?"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5509_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "พวกผู้หยิ่งยโสและชั่วร้ายทั้งหมด จะต้องกลายเป็นวิญญาณผู้ตายภายใต้เงื้อมมือของข้า"
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "คมของความแค้น ยิ่งแหลมคมขึ้น"
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "ร้านเสริมสวยที่เต็มไปด้วยความลึกลับของฉันไม่ได้งดงามและไร้เดียงสาเหมือนงานเต้นรำ คุณพร้อมหรือยัง?"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5512_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "ร้านเสริมสวยของฉันคือดิน เป็นสวนที่ความงามและอำนาจอันน่าหลงใหลจะบานสะพรั่ง.."
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5513_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "ผ้าไหมนุ่ม, ชาดำ, ขนมมาการอง (macaron)... ยังต้องการดอกกุหลาบสดที่มีน้ำค้างเกาะบนกิ่งในยามเช้าเพื่อตกแต่งห้องรับรองของฉัน"
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5514_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "ไม่สามารถหาทางผ่อนผันให้แขกที่อยู่ข้างนอกเข้ามาในสถาบันได้หรือ?"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5515_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "การดำเนินการผิดพลาด, ข้อผิดพลาด, ข้อผิดพลาด, ข้อผิดพลาด.."
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "อ๊า! ตอนนี้กี่โมงแล้ว! ขอโทษค่ะ...คาเรนไม่ควรเผลอใจลอยไปแบบนี้เลย! แต่รู้สึกง่วงจนทนไม่ไหว..."
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "ฉันทำได้แค่รอความตายหรือเปล่า? จะมีใครสักคนช่วยฉันได้ไหม? ฉันจะสามารถต่อต้านการควบคุมของพวกเขาได้หรือเปล่า? ทุกวันฉันเคยถามตัวเองแบบนี้ แต่คำตอบจริง ๆ แล้วอยู่ในหัวของฉันมาตลอด เพียงแต่ฉันไม่กล้าเผชิญหน้ากับมัน... หากเธอไม่ปรากฏตัวขึ้น ฉันไม่แน่ใจว่าตัวเองจะมีความกล้าหาญพอที่จะต่อต้านจนถึงที่สุดหรือเปล่า \n ขอบคุณนะ — อย่าเข้าใจผิดนะ นี่ไม่ใช่คำสารภาพรักอะไรแบบนั้น!"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5518_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "ฉันใช้ชีวิตอยู่ในความฝันที่หลอกลวงของพวกเขา ถูกคำทำนายที่น่าขันพรากสิทธิ์ของการเป็นคนธรรมดาไปจากฉัน แม้แต่สิทธิ์ในการเลือกก็ไม่เคยมี... เพื่อหลีกหนีจากชีวิตแบบนี้ ฉันยอมทำทุกอย่าง"
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5519_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = "“ดอกบัวที่โค้งต่ำทอดถอนใจรอบๆ,     \nในดงไม้พี้ที่หลับลึก เธอสะดุ้งตื่นเป็นครั้งคราว,     \nนกตัวหนึ่งสั่นไหวเบาๆ ในรัง,     \nเสียงเพลงลึกลับลอยลงมาจากดวงดาวทอง.”\nโอ้ คุณได้ยินหรือเปล่า? ขอโทษนะ นี่คือประโยคที่ฉันชื่นชอบมาก... คุณอยากอ่านด้วยกันไหม?"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับการอ่าน"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "อย่าเข้าห้องของผู้หญิงโดยพลการ และอย่าวิจารณ์ท่าทางของข้า รีบออกไปเดี๋ยวนี้ ข้าจะพักผ่อนแล้ว"
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5521_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "คุณอย่าพยายามวางท่ากับฉันเลย จงรู้ว่าตัวเองเป็นใคร และลืมตาดูให้ชัดว่าใครกันแน่ที่เป็นนายที่แท้จริง"
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5522_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "อ้าว ต้องแสดงสินค้าไหม?"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "ทำได้ยอดเยี่ยม! ถึงเวลาเปิดถังรัมฉลองชัยชนะแล้ว!"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5525_AwakerVoiceContent = {
    Text = "จางหายไปเถอะ"
  },
  Voice_5525_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_5526_AwakerVoiceContent = {
    Text = "ไว้ใจฉันเถอะ!"
  },
  Voice_5526_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5527_AwakerVoiceContent = {
    Text = "รสชาติที่โดนฉันเหยียบไว้ใต้เท้า คงจะรู้สึกยอดเยี่ยมไม่น้อยเลยใช่ไหม?"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5528_AwakerVoiceContent = {
    Text = "ทนไว้นะ!"
  },
  Voice_5528_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5529_AwakerVoiceContent = {
    Text = "อยากรู้ใช่ไหมว่าใต้ผ้าปิดตาเป็นยังไง? ในโอกาสที่เหมาะสมกว่านี้ ฉันจะให้คุณดูเอง อย่าใจร้อนเกินไปนะ"
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "จบลงเร็วขนาดนี้แล้วเหรอ? ...ความสนใจของฉันเพิ่งเริ่มต้นเอง"
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "เฮ้ อย่ามาจับฉันนักเลย นักรบตัวจริงไม่พึ่งพาสิ่งภายนอกหรอก"
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5531_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "ไอจิสแข็งแกร่งขึ้นแล้ว... ฉันจะใช้ดวงตาคู่นี้ทำให้ศัตรูขยับไม่ได้!"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "มหาวิทยาลัยมิซากะและกองกำลังไม่ต่างกัน เราทุกคนต่างรักษาตำแหน่งแนวหน้า ขัดอาวุธให้เงางาม พร้อมต่อสู้"
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5534_AwakerVoiceContent = {
    Text = "สมบูรณ์แบบ!"
  },
  Voice_5534_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5535_AwakerVoiceContent = {
    Text = "สมบูรณ์แบบ!"
  },
  Voice_5535_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5536_AwakerVoiceContent = {
    Text = "ฉันสามารถถูกใส่กุญแจมือ ถูกลากผมให้คุกเข่าต่อหน้าคุณ เป็นทาสของคุณ เรื่องเหล่านี้ไม่มีปัญหาเลย—แค่ให้ฉันฆ่าคน ช่างปั้น นักถือโคม ผู้หญิงแก่ที่เป็นโรคหืดที่เดินผ่านมา... ใครก็ได้ ฉันสัญญาว่าจะช่วยคุณฉีกคอพวกเขาและดื่มเลือดของพวกเขาจนหมด."
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5536_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "สิ่งที่ไหลออกมาจากบาดแผลจากการหลอมกร่อน นอกเหนือไปจากของเหลวสีดำเหนียวข้นแล้ว ยังมีแรงบันดาลใจที่ไม่หยุดยั้งอีกด้วย ถ้าพูดจริงๆ ผมไม่คิดจะปฏิเสธหากอยากได้อีกหน่อย"
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "กลัวเหรอ? ฮ่าๆๆๆ ถูกต้องแล้ว！ให้ทุกอย่างไปลงนรกเถอะ ฉันแค่อยากลิ้มลองความกลัวของพวกเธอน่ะ"
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5538_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "น่าสนใจ รสชาติของเลือดคุณ... หวานหอมเหมือนไวน์น้ำผึ้ง"
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5539_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "ในตอนนั้น ผู้คนนับหมื่นต่างพากันโห่ร้องชื่อของฉัน มหาสมุทรที่ชื่อว่า「ยูวฮะชิ」ได้ท่วมทุกอย่าง เพื่อเฉลิมฉลองที่ฉันเพิ่งบิดคอของไอ้หัวล้านขี้แพ้ มันเป็นความรู้สึกที่ยอดเยี่ยมจริงๆ ในฐานะเพื่อนของฉัน เธอจะต้องเข้าใจแน่"
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5540_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5541_AwakerVoiceContent = {
    Text = "เดี๋ยว, เดี๋ยวก่อน!"
  },
  Voice_5541_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5542_AwakerVoiceContent = {
    Text = "อย่า!"
  },
  Voice_5542_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5543_AwakerVoiceContent = {
    Text = "โอ๊ย!"
  },
  Voice_5543_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5544_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5544_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5545_AwakerVoiceContent = {
    Text = "กำลังค้นหา \"การหลอมกร่อน\"ในเอกสารเขตข้อมูลกว้าง... ไม่ต้องการใช่ไหม? คุณอยากรู้ว่าฉันมีท่าทีอย่างไรต่อการหลอมกร่อนหรือเปล่า? ฉันเข้าใจแล้ว กำลังปลุกการค้นหา \"อาวุธต่อต้านการหลอมกร่อน\"ในระบบส่วนตัว... ผลลัพธ์คือ: 「0」."
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "ของปลอมนั้นเปราะบางเหมือนควันและฝุ่น สายลมเพียงเบาๆ ก็สามารถพัดให้หายไปได้.."
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับมอร์ฟี่"
  },
  Voice_5546_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「มอร์ฟี่」ร่างกายที่ตื่นขึ้น"
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "เสียงดังเล็กน้อย น่าจะเป็นนักเรียนใช่ไหม?\nพวกเขาเหมือนอัลบาทรอสเลย เธอรู้จักนกชนิดนั้นไหม? พวกมันเต็มไปด้วยพลังงานที่ไม่มีวันหมด ราวกับการเดินทางจะไม่มีวันสิ้นสุด.."
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5548_AwakerVoiceContent = {Text = "ฮะ"},
  Voice_5548_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5549_AwakerVoiceContent = {Text = "หึ"},
  Voice_5549_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5550_AwakerVoiceContent = {
    Text = "ในสถาบันก็มีแค่รามอน่าที่น่าสนใจ เธอเก่งเรื่องดาบมาก ส่วนที่เหลือก็ล้วนเป็นพวกยึดติดกับกฎเกณฑ์... หรือว่าเธอจะเป็นแบบนั้นด้วย? เธอคิดจริงๆ หรือว่าการเขียนรายงานการดำเนินการมันสนุก?"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "ไม่คุ้มค่าที่จะกล่าวถึง"
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = "แม่แต่ละคนไม่เหมือนกัน มีแม่ที่ดี และก็มีแม่ที่ไม่ดี \nคุณนายเป็นแม่ที่ดี"
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5552_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "เป็นเพราะข้าไม่สามารถปกป้องท่านได้.."
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "จองสถานที่ไว้หรือยัง? ต้องการสวนที่ใหญ่กว่า 150 ตารางเมตรนะ!"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5554_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "เลือดของคนที่กำลังจะตายเป็นของเหลวที่ลื่นไหล เพียงแค่กรีดเบาๆ ที่ลำคอ เลือดก็จะไหลผ่านระหว่างซี่ฟันกลายเป็นเส้นบางๆ อุ่นๆ ค่อยๆ ไหลเข้าสู่ท้องของฉัน......ฮื้อ ช่างอร่อยจริงๆ"
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับเลือด"
  },
  Voice_5556_AwakerVoiceContent = {Text = "ยะ"},
  Voice_5556_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_5557_AwakerVoiceContent = {Text = "เฮ้!"},
  Voice_5557_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_5558_AwakerVoiceContent = {
    Text = "เอ๊ะ"
  },
  Voice_5558_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "ขอบคุณสำหรับความเมตตาของท่าน ที่มอบที่พักพิงให้กับข้า หวังว่าข้าจะไม่เป็นเหตุให้ท่านต้องพบกับชะตากรรมอันโศกเศร้า.."
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "ฉันมาจากดาวเคราะห์ไกลโพ้น ที่นั่นพายุหิมะโหมกระหน่ำ เป็นสถานที่หนาวเย็นจัด แต่ไม่เป็นไร ในคฤหาสน์ของฉันมีผู้รับใช้มากกว่าหนึ่งพันคน การโอบกอดและความใกล้ชิดของพวกเขานั้นทำให้รู้สึกอบอุ่นอย่างมาก"
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับอดีต"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "ก่อนที่คุณจะกลับมา ฉันยังไม่อาจล้มลงที่นี่ได้"
  },
  Voice_5561_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5562_AwakerVoiceContent = {
    Text = "ก่อนที่คุณจะกลับมา ฉันยังไม่อาจล้มลงที่นี่ได้"
  },
  Voice_5562_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5563_AwakerVoiceContent = {
    Text = "อุ๊ย โลกนี้จะมีแขกที่หยิ่งผยองแบบนี้ได้อย่างไร ต้องการ「อาวุธที่ดีที่สุดในโลก」? ข้าบอกเขาว่าต้องแลกเปลี่ยนด้วยหัวที่เต็มไปด้วยความเกลียดชัง เขาก็เลยจากไปอย่างไม่สบอารมณ์.."
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับโกลิอัท"
  },
  Voice_5563_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「โกลิอัท」"
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "ท่าทางของเธอดูมุ่งมั่น ราวกับพร้อมจะเสียสละตัวเองเพื่อ「ช่วยโลก」อยู่ตลอดเวลา แค่เห็นก็ทำให้คนรู้สึกรำคาญตามข้อต่อไปทั่ว"
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5564_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "ก่อนที่พวกคุณจะประกาศห้ามการวิจัย ฉันเกือบจะทำให้การล้างบางปกคลุมที่หลบภัยการหลอมกร่อนแล้ว... น่าเสียดาย น่าเสียดายจริงๆ"
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5565_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "ใช่แล้ว ฉันมีร่างกายสำรองนับไม่ถ้วน และมีโอกาสหลบหนีจากการหลอมกร่อนมากมาย แต่เมื่อเส้นทางสู่ความจริงถูกปูออกเบื้องหน้า นักวิชาการใดๆ ก็ตามย่อมไม่อาจปฏิเสธได้ ฉันตอบสนองต่อความปรารถนาภายในใจ และเพราะเหตุนี้ ฉันจึงไม่รู้สึกเสียใจฯ"
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5566_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "ความจริงของโลก จุดเริ่มต้นของโลก จุดสิ้นสุดของโลก ทั้งหมดนี้ล้วนเป็นสิ่งที่ไม่มีความหมาย หากเจ้าก็ปรารถนาที่จะเดินไปบนเส้นทางสู่ความจริง ข้าไม่ขัดข้องที่จะเป็นผู้นำทางให้แก่เจ้า... เหมือนอย่างที่เราเคยทำมาก่อน"
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5567_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "พวกเจ้าอาจสามารถหยุดข้าได้ แต่จุดจบนั้นไม่อาจหลีกเลี่ยงได้... ข้าจะทิ้งโรงเรียนแห่งนี้ และทิ้งเจ้าไว้จนถึงวาระสุดท้าย เราจะขึ้นไปยังหอคอย สัมผัสยามสนธยาของกาลเวลา และเฝ้ามองการล่มสลายของอารยธรรม... อย่างไรล่ะ การทำเช่นนี้ ไม่ถือว่าทำร้ายความสัมพันธ์ระหว่างเรากันใช่ไหม?"
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5568_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5569_AwakerVoiceContent = {
    Text = "ก็ได้"
  },
  Voice_5569_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5570_AwakerVoiceContent = {
    Text = "จางหายไปเถอะ"
  },
  Voice_5570_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_5571_AwakerVoiceContent = {
    Text = "ขอให้การสวดมนต์ของฉันกลายเป็นเสียงระฆังยามเช้าที่ปลุกบ้านเกิดของฉัน.."
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "ฉันไม่เคยคิดเลยว่าจะมีใครนอกจากทิงค์เทตที่เต็มใจยอมรับฉัน ฉันรู้สึกโชคดีมากที่ได้พบกับคุณ ผู้พิทักษ์ ฉันจะพยายามอย่างเต็มที่เพื่อเรียนรู้การควบคุมพละกำลังของตัวเอง เพื่อที่เวลาฉันกอดคุณ จะได้ไม่ดูดชีวิตจากคุณจนหมด... กอดใช่ไหม? วิธีการแสดงความขอบคุณของมนุษย์?"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5572_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "ฉันอยู่ที่นี่ ไม่จำเป็นต้องจ่ายอะไรเป็นค่าตอบแทนใช่ไหม? ฉันสามารถช่วยเพิ่มสถานะของคุณที่นี่ได้ เพียงแค่ขู่ว่าจะดูดชีวิตพวกเขาให้หมด ก็ง่ายมาก เหมือนตอนที่ฉันเคยช่วยทิงค์เทต... อ๊ะ! เรื่องนี้, ห้ามบอกใครเด็ดขาด!"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5573_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "ขอโทษนะ ฉันแตกต่างจากพวกเดียวกัน เป็นของที่ไม่ดีเท่าคนอื่น.."
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5574_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "สาวใช้ที่ยอดเยี่ยมสามารถเพิ่มสีสันให้กับห้องรับรองได้มาก แต่สาวใช้สีเขียวอมฟ้า... ขอผมพิจารณาอีกครั้ง.."
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับคาเรน"
  },
  Voice_5575_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างที่ถูกปลุก「คาเรน」"
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "ทิงค์เทตเป็นน้องสาวฝาแฝดของฉัน แตกต่างจากฉัน เธอมักจะเปล่งประกายเสมอ...\nถ้าไม่มีฉันคอยเป็นภาระ เธอจะต้องมีอนาคตที่สดใสกว่านี้แน่ๆ เสียงเพลงของเธอจะดังก้องไปทั่วทั้งกาแล็กซี่.."
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5576_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "ในเปลนอนแออัดมาก ไม่สามารถยืดร่างกายได้... แต่ทิงค์เทตบอกว่า เพื่อความปลอดภัยของทุกคน เธอให้ฉันอยู่ในเปลนอน... ถ้าเธอหวังแบบนี้ ฉันก็ยินดีทำตาม"
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5577_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "ฉันมักจะรู้สึกว่าตัวเองอยู่ระหว่างชีวิตและความตาย เพียงแค่ที่ที่ฉันดำรงอยู่ ความเศร้าโศกล้นหลามเหมือนคลื่นทะเล และโศกนาฏกรรมก็ปรากฏพร้อมกัน ถึงอย่างนั้น เธอก็ยังอยากให้ฉันเขียนบทกวีให้เธองั้นหรือ ฮืม... อาจจะดีนะ บางทีเธออาจคู่ควรกับบทกวีที่หวานที่สุด.."
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5578_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "“กุหลาบยังไม่ผลิบาน แต่รุ่งอรุณกำลังจะมาแล้ว”"
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5579_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "คุณปรารถนาอะไร? ใช่ความงามของถ้อยคำที่ลึกซึ้ง ชื่อเสียงที่เลื่องลือไปทั่ว หรือว่าความจริงใจที่เจ็บปวดถึงขีดสุด?"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5580_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "ด้วยหมึกที่มองไม่เห็น แกะสลักดอกตูมที่บิดเบี้ยว... กิ่งก้านของดอกกุหลาบล่องลอยเหมือนวิญญาณนี้ กลับสามารถจุดประกายแรงบันดาลใจทางบทกวีได้.."
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5581_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "ฟังพระดำรัสของท่านผู้เป็นเจ้า"
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "การตื่นรู้แห่งวิญญาณ·ภาคที่สอง"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "พลีชีพ! สร้างใหม่สวรรค์——"
  },
  Voice_55826_AwakerVoiceTitle = {
    Text = "การตื่นรู้แห่งวิญญาณ·สาม"
  },
  Voice_5582_AwakerVoiceContent = {
    Text = "หากท่านยืนยัน ข้าจะก้าวสู่แสงแดดอีกครั้ง... แสงแดดที่ไม่ต่างจากวันที่ข้าจากสีไคไป..."
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5582_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "ฮี่ฮี่ คุณอยากเห็นจักรวาลที่ถูกทำลายไหม? เอ๊ะ ตอนนี้จะเสียใจก็สายไปแล้ว!"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5583_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "ดื่มมันเถอะ ความตายที่หอมหวานและงดงาม"
  },
  Voice_5584_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5585_AwakerVoiceContent = {
    Text = "ดื่มมันเถอะ ความตายที่หอมหวานและงดงาม"
  },
  Voice_5585_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5586_AwakerVoiceContent = {
    Text = "ถึงแค่นี้!"
  },
  Voice_5586_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5587_AwakerVoiceContent = {
    Text = "อย่า.."
  },
  Voice_5587_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5588_AwakerVoiceContent = {
    Text = "จงเป็นพยานแห่งความเกรียงไกรของหยูเถิด."
  },
  Voice_5588_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5589_AwakerVoiceContent = {
    Text = "อากาศในมหาวิทยาลัยช่วงตี 4 สดชื่นมาก ดีใจที่คุณเต็มใจมาออกกำลังกายกับฉัน ต้องบอกเลยว่า การทำรูปปั้นนี่ใช้แรงเยอะจริงๆ."
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับเช้า"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "พละกำลังนี้ใช้แล้วรู้สึกดีมาก."
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5590_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "ฉันเกลียดคนที่ซื้อของแล้วไม่จ่ายเงิน แค่เปิดร้านมานานพอ ก็คงต้องเจอเรื่องแบบนี้บ้างแหละ ทำไงได้ล่ะ ลงมือเองเลย ไปเก็บเงินคืนให้ได้~"
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "ทรมานช้าๆ"
  },
  Voice_5592_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5593_AwakerVoiceContent = {
    Text = "ทรมานช้าๆ"
  },
  Voice_5593_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5594_AwakerVoiceContent = {
    Text = "บรรทุก."
  },
  Voice_5594_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5595_AwakerVoiceContent = {
    Text = "เปิดใช้งาน"
  },
  Voice_5595_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5596_AwakerVoiceContent = {
    Text = "ให้ที่นี่กลายเป็นทะเลแห่งความครึกครื้นของทุกคนกันเถอะ!"
  },
  Voice_5596_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5597_AwakerVoiceContent = {
    Text = "ทำไม คิดว่าฉันจะขอบคุณเธองั้นหรือ?"
  },
  Voice_5597_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5598_AwakerVoiceContent = {
    Text = "ในฐานะของเครื่องบรรณาการแล้ว มันไม่ผ่านเกณฑ์เลย... แต่ดูจากความจริงใจของคุณแล้ว ผมจะยอมรับมันแบบยากลำบากแล้ว"
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "คุณคิดว่าแค่นี้ฉันจะเชื่อฟังคุณงั้นหรือ?"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5600_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_5600_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5601_AwakerVoiceContent = {
    Text = "ขึ้นไป!"
  },
  Voice_5601_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5602_AwakerVoiceContent = {
    Text = "สัตว์ประหลาดที่เนรคุณ นักฆ่าทั้งหลาย เจ้าคิดว่าพวกนี้มีค่าพอหรือไม่? คนแปลกประหลาด!"
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5602_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "ไม่ว่าจะมีเบาะรองนั่งมากแค่ไหน บัลลังก์หินลาพิสลาซูลีก็ยังไม่สู้เตียงขนนุ่มได้ ในแง่นี้ ที่นี่ของพวกท่านก็มีข้อดีอยู่"
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "การลงโทษเล็กน้อย"
  },
  Voice_5604_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5605_AwakerVoiceContent = {
    Text = "ฉันเกลียดความเหงา เกลียดที่ต้องกังวลว่าคนอื่นจะรู้สึกอย่างไรในความมืดมิดที่ไม่มีที่สิ้นสุด... ดังนั้น โปรดอย่าทิ้งฉันไว้คนเดียวได้ไหม?"
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "ถ้าฉันเป็นคุณ ฉันจะขังร่างกายที่ตื่นขึ้นทั้งหมดไว้ในกรง! หมาบ้าที่หลุดจากกรง มักจะหันมากัดเจ้าของก่อนเสมอ"
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5606_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "ฉันมาสายหนึ่งชั่วโมงสำหรับการพบปะครั้งนี้——ต้องโทษพวกคนที่ทำลายระบบทาสเหล่านั้น ตอนนี้ไม่มีใครหวีผมให้ฉันแล้ว!"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5607_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "ยากที่จะจินตนาการได้ว่าบ้านเกิดของฉันกลับถูกทำลายลงเช่นนี้... นั่นคือกรุงโรมที่ยิ่งใหญ่！ไม่มีทางที่เธอจะไม่เคยได้ยินชื่อเสียงของมัน！"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5608_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "มาเลย ชนะให้ได้ตั้งแต่เริ่ม!"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "นี่คือ พรจากเจ้านายของข้า."
  },
  Voice_5610_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5611_AwakerVoiceContent = {
    Text = "เก็บสายตาเวทนาของคุณไว้เถอะ ฉันไม่ชอบและไม่ต้องการให้ใครมาสงสาร ถ้าคุณยังจ้องมองฉันแบบนี้ ฉันจะอดไม่ได้ที่จะทรมานคุณอย่างหนัก... คุณเองก็ไม่อยากให้เรื่องมันบานปลายใช่ไหม งั้นก็เชื่อฟังฉันหน่อย ทำตัวดีๆ แล้วเป็นนักสู้ของฉันอย่างว่าง่าย.."
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5611_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "อย่า*ปิดเสียง*ถามอีกเลย ฉันพลาดไป ประมาทไป จนทำให้เหล่ากลาดิเอเตอร์หนีไปได้ และครอบครัวของฉันต้องตายทั้งหมด! เหมือนโรมในยุคปัจจุบันที่ถูกทำลายจนไม่เหลืออะไรเลย!"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5612_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "เมื่อเปรียบเทียบกับพวกที่มีพรสวรรค์ต่างๆ นิมเฟียก็แค่เป็นมนุษย์สามัญที่ไม่มีการสร้างผลงานหรือคุณค่าใดๆแค่ปุถุชนธรรมดา\nบางที สิ่งที่ทำให้ฉันตื่นขึ้น อาจเป็นเพียงความปรารถนาเล็กๆที่ต่ำต้อย..."
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "วันนี้ฉันทำผิดกฎของโรงเรียนอีกแล้ว มาเรียนสายห้านาที... ดังนั้น ฉันจึงขอรับการลงโทษที่รุนแรงที่สุด และหากเป็นไปได้ ขอให้ผู้พิทักษ์เป็นคนลงโทษก็จะดีมาก"
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "เครื่องมือก็ต้องการการบำรุงรักษาเช่นกัน ชุดเครื่องมือที่ถนัดนั้นคือวิญญาณของช่าง."
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5615_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "(ความอดทนอย่างไม่ใส่ใจ)"
  },
  Voice_5616_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5617_AwakerVoiceContent = {
    Text = "ถ้ามีครั้งหน้าอีก ผมจะขอให้มีการตักเตือนและพักการเรียนไว้"
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "นอกจากการต่อสู้แล้ว ฉันก็ยังมีงานอื่นที่ต้องทำ แม้ในยุคไพรออซอยด์ ฉันก็ไม่ได้อยู่ว่างๆ เลย... เฮ้ คุณคงไม่คิดจริงๆ ใช่ไหมว่าฉันเป็นแค่คนเถื่อนที่รู้จักแต่การต่อยตี!"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับงาน"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "เมื่อผู้คนเข้ามาใกล้ฉัน พวกเขามักจะระลึกถึงประสบการณ์ที่เศร้าที่สุดในชีวิต และน้ำตาก็ไหลออกมาอย่างไม่รู้ตัว อย่างนี้ฉันก็สามารถเติบโตได้หรือเปล่า?"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5619_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5620_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5621_AwakerVoiceContent = {
    Text = "แบบนี้ใช่ไหม?"
  },
  Voice_5621_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5622_AwakerVoiceContent = {
    Text = "ที่นี่ดีกว่าคุกซินเหมินที่สกปรกและเหม็นมากเลย! ไม่ว่าจะนอนบนโซฟาหรือพิงมุมผนังก็สบายทั้งนั้นนะ?"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5623_AwakerVoiceContent = {
    Text = "บราวน์...！"
  },
  Voice_5623_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5624_AwakerVoiceContent = {
    Text = "เปลือกหอยไปไหนแล้ว.."
  },
  Voice_5624_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5625_AwakerVoiceContent = {
    Text = "เจ้าเล่ห์!"
  },
  Voice_5625_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5626_AwakerVoiceContent = {
    Text = "เปลือกหอยไปไหนแล้วนะ!"
  },
  Voice_5626_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5627_AwakerVoiceContent = {
    Text = "ทางช้างเผือกที่ไหลริน.."
  },
  Voice_5627_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5628_AwakerVoiceContent = {
    Text = "ออรีตาไม่ชอบเพื่อนที่จากไปอย่างกะทันหัน... แต่ถ้าเขายังจะกลับมา ออรีตาก็จะให้อภัยเขา!"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "ผู้หญิงที่สามารถแล่นเรือข้ามทะเลเพียงลำพัง นอกจากจะเป็นเทพธิดาแล้ว ก็ยังอาจเป็นผู้หญิงบ้าได้ เมื่อก่อนฉันคิดว่ามิลียาห์มเป็นเทพธิดา นั่นเป็นความผิดพลาดอย่างใหญ่หลวง"
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "เรื่องราว, เกี่ยวกับมิลียาห์ม"
  },
  Voice_5629_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「มิลียัม」"
  },
  Voice_5630_AwakerVoiceContent = {Text = "อืม!"},
  Voice_5630_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "ฉันแอบไปดูมายากลของคุณหนูคาเซีย การแสดงของเธอทำให้ผู้ชมมีความสุขมากมาย แต่ฉันกลับมักจะนำความเศร้ามาให้ทุกคน... ท่านบอกว่า น้ำตาและความยิ้มนั้น เป็นสิ่งที่มีค่าเท่ากันใช่ไหม? บางที.."
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับคาเซีย"
  },
  Voice_56313_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับตัวปลุก「คาเซีย」"
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "บทกวี, ไฟ, และความเศร้าเป็นสิ่งที่คล้ายคลึงกัน พวกมันจะกลืนกินคุณอย่างไม่รู้ตัว... เมื่อคุณรู้สึกตัวอีกที คุณได้จมอยู่ในโลกของบทกวีแล้ว.."
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "ให้บทกวีจากอดีตปลุกสวนที่ซ่อนอยู่ในใจ."
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "บทกวีและดอกไม้ น่าจะเป็นสิ่งเดียวกันใช่ไหม? ทั้งสองอย่างล้วนสั้น ngủย และตราตรึง ในโลกอันไร้ขอบเขตนี้ เพียงพื้นที่เล็กๆ ก็สามารถบรรจุช่วงเวลาที่สะเทือนอารมณ์ที่สุดได้... ผมคิดว่า ทุกคนเคยเงียบงันเพราะบทกวีหนึ่ง เหมือนกับการหยุดยืนเพื่อชมการบานของดอกไม้"
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับบทกวี"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "ฉันเกือบจะลืมแล้ว... ในฤดูกาลนี้ สีไค จะบานเป็นดอกไม้แบบไหนกันนะ?"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับสีไค"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "ท่านทำให้หมึกในปากกาของข้ากลับมาไหลเป็นสายธารเล็กๆ อีกครั้ง ข้าก็จะเขียนบทกวีต่อให้กับเรื่องราวของท่าน"
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "เกร็ดเล็กเกร็ดน้อย·เกี่ยวกับผู้พิทักษ์1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "ความงดงามของการบานของดอกไม้นั้นช่างยิ่งใหญ่เพียงใด การเฉาไปของมันก็ช่างน่าเศร้าใจเพียงนั้น แต่ไม่ว่าจะเศร้ากี่ครั้ง ฉันก็อดไม่ได้ที่จะหยุดพักและไว้อาลัยให้กับดอกไม้เหล่านั้น หากเพราะความกลัวความเจ็บปวดแล้วเราจะทำเป็นมองไม่เห็นพวกมัน ดอกไม้เหล่านี้คงจะเสียใจมากแค่ไหนกันนะ.."
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับความเจ็บปวด"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "เพื่อทำการวิจัยโครงสร้างภายในของร่างกายขณะที่เอริกา「นอนหลับ」เวินเค่อขอให้ฉันไปพักผ่อนในออฟฟิศของเธอตอนกลางคืน \n ควรบอกหรือไม่ว่า เอริกายังคงมีสติอยู่บางส่วนขณะพักผ่อน?"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเวินเค่อ"
  },
  Voice_5631_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับ「เวินเคอร์」"
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "คุณผู้หญิงชุดแดงคนนั้นช่างงดงามจริงๆ ความแข็งแกร่งและมั่นใจของเธอ รอยยิ้มอันสง่างามที่เธอมีต่อชะตากรรม รวมถึงชีวิตของเธอที่เหมือนกับดอกกุหลาบสีแดง ซึ่งรุ่งโรจน์และเด็ดเดี่ยว ทำให้ฉันรู้สึกอิจฉาอย่างมาก.."
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับโซเรล"
  },
  Voice_56320_UnlockDesc = {
    Text = "เปิดใช้งานหลังจากได้รับร่างกายที่ตื่นขึ้น「โซเรล」"
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "เมื่อวานนี้ฉันเพิ่งเขียนบทกวีใหม่ ยังไม่ได้ให้ใครดูเลย เขียนได้ไม่ค่อยดีหรอก แต่ว่า... ผู้พิทักษ์, ผู้พิทักษ์ จะยินดีดูไหม?"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับผู้พิทักษ์ 2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "นักเรียนชมรมกวีหวังให้ฉันเป็นผู้ชี้แนะของพวกเขา... ฉันไม่สามารถตอบตกลงได้ ฉันไม่อยากทำลายความสนุกของคนหนุ่มสาว,     แต่ฉันจะนำพาความท้อแท้และเศร้าหมองมาให้พวกเขาเท่านั้น."
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "ในโลกนี้ไม่มีสิ่งใดที่น่ารังเกียจ ยุคสมัยแห่งทองคำควรค่าแก่การสรรเสริญ ส่วนความชราภาพควรค่าแก่ความสงสาร; เสื้อผ้าอันหรูหราของวัยเยาว์เป็นที่อิจฉา ขณะที่เสื้อผ้าขาดรุ่ยของความเสื่อมโทรมชวนให้คิดถึง"
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "ทุกครั้งที่เห็นคุณหนิงเฟย่า ฉันมักจะนึกถึงภาพวาดดอกบัวที่กำลังหลับใหล เธอเหมือนดั่งดอกบัว สงบเงียบและเปี่ยมไปด้วยความขมขื่นที่แฝงความหอมละมุน... ไม่รู้ว่าโลกในสายตาของเธอจะเป็นอย่างไร"
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับหนิงเฟย่า"
  },
  Voice_56324_UnlockDesc = {
    Text = "เมื่อได้รับร่างกายที่ตื่นขึ้น「หนิงเฟย่า」จะปลดล็อก"
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "ตั้งแต่อดีต ฉันรู้สึกได้ว่ามี “ผี” อยู่รอบตัว เหมือนกับการสิงสู่หรือปรากฏการณ์ลึกลับบางอย่างที่ยากจะอธิบาย ซึ่งทำให้ฉันค่อยๆ สูญเสียความหวังในโลกนี้ไป แต่ถ้าเป็นผีจริงๆ แล้ว น้ำนมและน้ำเปล่าที่หายไปโดยไม่มีเหตุผลล่ะ จะอธิบายอย่างไร.."
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับผี"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "ร่างกายของฉันไม่ได้ถูกการหลอมกร่อนเข้าแทรก ของเหลวสีดำนั่นก็แค่หมึกเข้มเท่านั้น แต่อย่างไรก็ตาม แม้จะไม่มีการหลอมกร่อน การมีอยู่ของสิ่งต่างๆ ก็จะกลายเป็นความว่างเปล่า ใช่ไหม?"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "ในสุสานของยาวยุ่น ฉันเห็นชื่อของผู้พิทักษ์... ความทรงจำในอดีตเต็มไปด้วยความเจ็บปวด แต่ฉันไม่เคยคิดจะลืมมันเลย สำหรับผู้พิทักษ์แล้ว ความทรงจำที่หายไปนั้น คงมีค่ามากแน่ๆ?"
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับความทรงจำ"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "หากบทกวีเกิดขึ้นเพื่อสรรเสริญความงาม การมีอยู่ของเธอก็เหมือนกับตัวบทกวีเอง เมื่อเธอเริ่มร้องเพลง ฉันก็เข้าใจทันทีว่าทำไมคนรุ่นก่อนถึงได้เปรียบเสียงของเธอกับเสียงไนติงเกล.."
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับทิงค์เทต"
  },
  Voice_56328_UnlockDesc = {
    Text = "หลังจากได้รับร่างกายที่ตื่นขึ้น 「ทิงค์เทต」แล้ว จะปลดล็อก"
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "นักเต้นผู้งดงาม... ไฟสีเขียวมรกตที่ลุกโชนบนเรือนร่างของเธอ ช่างเย้ายวนจนยากจะต้านทาน แม้ว่าจะต้องถูกเผาผลาญจนหมดสิ้นก็ตาม.."
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับลิซ"
  },
  Voice_56329_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างกายที่ปลุก「ลิซ」"
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "ใช้วิธีนี้แทนการดูดซับพลังชีวิตหรือไม่?"
  },
  Voice_5632_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5633_AwakerVoiceContent = {
    Text = "อร่อยมาก จริงๆ"
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "ท่านผู้มาเยือน ท่านต้องการรางวัลแบบใดกันแน่?"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "รีบทำให้เสร็จเถอะ อย่าอยู่บนถนนนานเกินไป"
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "การเสียสละที่หลีกเลี่ยงไม่ได้"
  },
  Voice_5636_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5637_AwakerVoiceContent = {
    Text = "(เสียงครางด้วยความอดทน)"
  },
  Voice_5637_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_56386_AwakerVoiceContent = {
    Text = "การป้อนกระแสไฟฟ้าเสร็จสิ้น.ปล่อยกระแสไฟฟ้า."
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "อย่าดูถูกหัวขโมยอันดับหนึ่งของถนน!"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "ถวายคำสรรเสริญเพื่อเปิดงาน!"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "พันหน้ามายาที่ปรากฏขึ้นตรงนี้!"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_5638_AwakerVoiceContent = {
    Text = "ใกล้เข้ามาแล้ว.."
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5638_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "จมลง，ลุกโชนเถอะ! การเต้นรำแห่งความตาย!"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "นี่คือเมืองที่วิญญาณของผู้ตายหลายพันหลงทาง ไร้ซึ่งบ้านเกิด"
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "ก็ให้ฉันมอบให้เธอก็แล้วกัน พลังย้ายถิ่นที่เหลืออยู่เพียงน้อยนิดของฉัน...!"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "อย่าดูถูกหัวขโมยอันดับหนึ่งของถนน!"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = "เป็นศัตรูหรือเปล่า? โปรดให้คำสั่งโจมตีฉันหน่อย \nเมือกสีดำคือศัตรู... ลิลลี่ก็เป็นศัตรูด้วยหรือ?"
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "ตุ๊กตาอัตโนมัติ เอริกา หมายเลขลำตัว EA307881 หมายเลขมอเตอร์ MF311028 ยินดีที่ได้รับใช้คุณ."
  },
  Voice_5640_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5641_AwakerVoiceContent = {
    Text = "ก่อนที่ศัตรูจะพ่ายแพ้อย่างสิ้นเชิง ให้ต่อสู้อย่างเต็มที่！"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "สวัสดี ฉันคือ... คุณสามารถบอกฉันได้ไหมว่าฉันชื่ออะไร?"
  },
  Voice_5642_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5643_AwakerVoiceContent = {
    Text = "เมื่อมาถึงโรงเรียน ฉันจึงเข้าใจโรคที่ตัวเองติดเชื้อ ซึ่งมีชื่อว่าการหลอมกร่อน ตอนที่ยังมีชีวิตอยู่ พ่อแม่มักจะหวังให้ฉันอยู่ห่างจากทะเล แต่ตอนนี้ดูเหมือนว่าการติดเชื้อนี้อาจเกี่ยวข้องกับการที่ฉันเคยเข้าใกล้ทะเลจริงๆ.."
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "เอาล่ะ ฉันจะไม่ทำให้คุณ “ผิดหวัง” แน่นอน"
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "ลมหายใจที่ร้อนระอุนี้——"
  },
  Voice_5645_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5646_AwakerVoiceContent = {
    Text = "ไปเถอะ."
  },
  Voice_5646_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5647_AwakerVoiceContent = {
    Text = "หมุนเลย"
  },
  Voice_5647_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_5648_AwakerVoiceContent = {Text = "เฮ้!"},
  Voice_5648_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5650_AwakerVoiceContent = {
    Text = "วันนี้มาถึงในที่สุด..."
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5651_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_5651_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5652_AwakerVoiceContent = {
    Text = "ฉันยังไม่สะใจเลย... ทำไมไม่ลุกขึ้นมาให้ฉันฆ่าอีกทีล่ะ ไงล่ะ?"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "ผู้พิทักษ์, ผมต้องคุยกับคุณก่อน เราไม่ควรปล่อยให้บางคนใช้ชีวิตฟุ่มเฟือยเช่นนี้ ก่อนที่เราจะได้รับชัยชนะครั้งสุดท้าย โปรดทราบว่า ผมไม่ได้ต่อสู้เพื่อชีวิตของชนชั้นสูงแบบนั้น"
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับโซเรล"
  },
  Voice_5654_UnlockDesc = {
    Text = "เปิดใช้งานหลังจากได้รับร่างกายที่ตื่นขึ้น「โซเรล」"
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "หากถูกจับเป็นเชลยศึกแล้วพาตัวไป ชะตากรรมโหดร้ายแบบไหนกำลังรอฉันอยู่นะ?"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5656_AwakerVoiceContent = {
    Text = "รับมือให้ดี!"
  },
  Voice_5656_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5657_AwakerVoiceContent = {Text = "หึ!"},
  Voice_5657_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5658_AwakerVoiceContent = {
    Text = "ฮือ——ง่วงจังเลย ก่อนจะพักผ่อน พวกคุณเตรียมของว่างและชาไว้สำหรับผ่อนคลายหรือยัง?"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "แม่ คุณอยากลูบพวกมันไหม? ได้ยินว่านุ่มมาก"
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5659_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "ฮัมฮัมฮัม ลัลลาล่า~ ทำความสะอาดกันเถอะ ฉันชอบการทำความสะอาดจริงๆ รู้สึกดีมากๆ เลย~"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับงาน"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "(เสียงครวญครางที่ทนไม่ไหว)"
  },
  Voice_5661_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5662_AwakerVoiceContent = {
    Text = "เออ... ดีนะ"
  },
  Voice_5662_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5663_AwakerVoiceContent = {
    Text = "(เสียงครวญครางที่ทนไม่ไหว)"
  },
  Voice_5663_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5664_AwakerVoiceContent = {
    Text = "(เสียงครวญครางที่ทนไม่ไหว)"
  },
  Voice_5664_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5665_AwakerVoiceContent = {
    Text = "ไฟแห่งความโกรธลุกโชน!"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "ฉันเห็นหลายคนบ้าไปเลยเพราะการหลอมกร่อน พูดตามตรง ฉันบ้าพอแล้ว การหลอมกร่อนสำหรับฉันน่าจะไม่มีผลกระทบอะไร"
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5667_AwakerVoiceContent = {
    Text = "หึ~ฮ่าฮ่าฮ่า!"
  },
  Voice_5667_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5668_AwakerVoiceContent = {
    Text = "เครื่องมือที่ดีคือครึ่งหนึ่งของความสำเร็จ!"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "รู้สึกเหมือนฟื้นคืนชีวิต"
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5670_AwakerVoiceContent = {
    Text = "ดีเลย"
  },
  Voice_5670_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "ฟันได้แรงขึ้นแล้ว"
  },
  Voice_5671_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5672_AwakerVoiceContent = {
    Text = "ต้องรักษาอัตราการเข้าร่วม ต้องดูแลความคืบหน้าของการวิจัย และยังมีภารกิจการสอนที่ต้องทำให้เสร็จ ดูเหมือนว่าถึงเวลาต้องเริ่มการทดลองย้อนเวลาแบบบีบอัดแล้ว."
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5672_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "ใกล้จะเริ่มการผจญภัยอย่างเป็นทางการอีกก้าว"
  },
  Voice_5673_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5674_AwakerVoiceContent = {
    Text = "อย่าให้ใครเข้าใกล้น้ำนะ เดี๋ยวเปลวไฟรักของคุณจะมอดดับหรือเปล่า?"
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "การต่อสู้จนจบ!"
  },
  Voice_5675_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5676_AwakerVoiceContent = {
    Text = "เธอนี่ช่างกล้าหาญจริงๆ ดูสิ เจ้าหนวดพวกนี้ เธอไม่กลัวหรือว่าจะถูกความบ้าคลั่งกลืนกินไปหรือ?"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5676_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5677_AwakerVoiceContent = {
    Text = "โอ๊ย!"
  },
  Voice_5677_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5678_AwakerVoiceContent = {
    Text = "ปวด.."
  },
  Voice_5678_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5679_AwakerVoiceContent = {
    Text = "กรุณาหยุด!"
  },
  Voice_5679_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5680_AwakerVoiceContent = {
    Text = "อยากลองสัมผัสดูไหม? หัวใจของฉันกำลังเต้นเพราะการมีคุณอยู่ตรงนี้."
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5680_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "พวกมันพูดจุ๊กจิ๊กๆ ดูมีความสุขมากเลย ขอบคุณค่ะ คุณ"
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5681_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = "มีบางอย่างกำลังตื่นขึ้นที่หน้าอก...อุ่นไปทั่ว น้ำตาของลิลลี่ ก็แทบจะ...\nแม่ เราควรเฉลิมฉลองด้วยกัน"
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5682_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "เมื่ออยู่กับแม่ จะรู้สึกอบอุ่นและมีความสุข"
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5683_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = "กินไม่ไหวแล้ว...ท้องอิ่มมาก \n หลังจากพิธีจบลง ลิลลี่จะแข็งแกร่งขึ้นไหม?"
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5684_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "ฉันชอบทะเล มันจะเป็นเรื่องน่าขันไหม? เพราะทุกอย่างที่ฉันมี ได้จมลงสู่ทะเลลึกแล้ว.."
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5686_AwakerVoiceContent = {
    Text = "ระวังหน่อย!"
  },
  Voice_5686_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5687_AwakerVoiceContent = {
    Text = "สิ่งที่น่ารังเกียจ......? ไม่มีหรอกค่ะ คุณจะเกลียดฝุ่นหนึ่งเม็ด หรือใบไม้หนึ่งใบได้ไหม?"
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "ฉันปฏิเสธคำเชิญไปงานเลี้ยงของคุณหนูเมดหลายครั้งแล้ว เธอดูเหมือนจะรู้สึกผิดหวังอยู่บ้าง... แต่เมื่อเปรียบเทียบกับการสนุกสนาน ความปลอดภัยของท่านเจ้านายสำคัญกว่าอย่างแน่นอน!"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับคาเรน"
  },
  Voice_5688_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างที่ถูกปลุก「คาเรน」"
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "ท่านเจ้านายคือเหตุผลของการมีอยู่ของอัศวิน ดังนั้นโปรดสั่งผมได้ตามใจ！"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "...อันนี้อาจจะต้องใช้ประแจทอร์คมั้ง... เอ่อ ขอโทษนะ เพิ่งเรียกฉันเหรอ?"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5691_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5692_AwakerVoiceContent = {
    Text = "กล้ามากจริงๆ"
  },
  Voice_5692_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5693_AwakerVoiceContent = {
    Text = "(ฮัมอย่างสง่างาม)"
  },
  Voice_5693_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5694_AwakerVoiceContent = {
    Text = "(เสียงครางด้วยความอดทน)"
  },
  Voice_5694_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5695_AwakerVoiceContent = {
    Text = "พอแค่นี้เถอะ"
  },
  Voice_5695_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5696_AwakerVoiceContent = {
    Text = "กรุณาอ่อนโยนกว่านี้หน่อย"
  },
  Voice_5696_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5697_AwakerVoiceContent = {
    Text = "ผลลัพธ์ก็ยังยากที่จะมุ่งมั่นจิตใจ.."
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "เธอมักจะมาอยู่ใกล้ๆ ข้าในยามค่ำคืน เป็นเพราะหัวของข้าเด่นเกินไปหรือเปล่า?"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเวินเค่อ"
  },
  Voice_5698_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับ「เวินเคอร์」"
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "ฉันรอคอยการทำลายมาโดยตลอด แต่ไม่เคยคิดเลยว่ายังมีทางเลือกที่เรียกว่า “การต่อสู้”... คุณยินดีพาข้าผู้มีวิญญาณตื้นเขินข้ามความพินาศไปหรือไม่? ในโลกที่รอดจากความตายแล้ว ยังคงมอบการไถ่บาปให้กับข้า.."
  },
  Voice_5699_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5699_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "เนื่องจากถูกปลุกให้ตื่นในฐานะอัครสาวกของท่าน นอกเหนือไปจากความสงบสุขและความปิติยินดีของท่านแล้ว ข้าไม่ปรารถนาสิ่งอื่นใดเลย นี่คือคำมั่นสัญญาของข้า... อืม... อา... แน่นอนว่า การคงอยู่ การคงอยู่ ขอให้มีชีวิตรอด.."
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5700_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "ไม่ลองจมดิ่งอยู่ในความรักของฉันดูหรือ? ท่านปลุกฉันขึ้นมา ไม่ใช่เพราะต้องการอุณหภูมิจากอ้อมกอดของฉันหรอกหรือ?"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5701_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "ไม่อยากยุ่งเกี่ยวกับผู้หญิงที่มาไม่ชัดเจนใช่ไหม? ได้เลย, ได้เลย. พระมหากษัตริย์ผู้ล่มจมแห่งนีนะเว คนแห่งชินาร์ผู้มีเจตนาทะลุฟ้า สาวน้อยที่ถูกพรากความตั้งใจใต้ต้นศักดิ์สิทธิ์แห่งยูเฟรติส... ท่านอยากฟังเริ่มจากตรงไหน?"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5702_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "คุณทำไมถึงหลบหน้าฉันอยู่เสมอ? คือเขินอายใช่ไหม? น่ารักจริงๆ ท่าทางไม่กล้าเผชิญหน้ากับความปรารถนานั้นของคุณ.."
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5703_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "แย่จริงๆ ที่นี่มันแย่มาก! ทำไมต้องให้คุณหนูอย่างฉันดื่มน้ำชายามบ่ายร่วมกับคนอื่นบนโต๊ะเดียวกันด้วย!... แต่คุกกี้โฮมเมดกลิ่นหอมใช้ได้อยู่นะ ส่งมาที่ห้องนอนหลังมื้อเย็น"
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5705_AwakerVoiceContent = {
    Text = "เฮ้ย!"
  },
  Voice_5705_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5706_AwakerVoiceContent = {
    Text = "รับมือให้ดี!"
  },
  Voice_5706_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_5707_AwakerVoiceContent = {
    Text = "การหลอมกร่อน... ที่บ้านเกิดมีบันทึกเกี่ยวกับเรื่องนี้ในห้องสมุดนะ แต่คาเรนไม่ชอบอ่านหนังสือ เลยลืมไปหมดแล้ว!"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "คุณอยากให้ผมออกเดินทางอีกครั้งหรือไม่? หากคุณไม่ถือโทษที่ผมเคยผิดพลาด ผมจะพยายามทำเช่นนั้น."
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5708_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "สิ่งที่เกลียดเหรอ? นั่นมีเยอะเลย——เจ้านายที่บังคับให้คนงานทำงานจนดึก แม่ชีที่ทำตัวเหนือกว่า ท้องที่ร้องโครกคราก ขนมปังดำเสียบกระจกแตก.."
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5710_AwakerVoiceContent = {
    Text = "เป็นความผิดของไอจิสทั้งหมด... ทุกอย่างเป็นเพราะฉัน.."
  },
  Voice_5710_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5711_AwakerVoiceContent = {
    Text = "จบมันเถอะ!"
  },
  Voice_5711_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5712_AwakerVoiceContent = {
    Text = "ได้รับความกรุณาจากคุณหนูฮันนา ข้าพเจ้าได้เข้าร่วมฟังการฝึกซ้อมของคณะนักร้องประสานเสียง การขับร้องประสานเสียงแตกต่างจากเพลงเรืออย่างมาก ในช่วงเวลาที่ปกป้องเรือเดินทะเล ข้าพเจ้าไม่เคยได้ยินทำนองที่แปลกใหม่เช่นนี้มาก่อน.."
  },
  Voice_5712_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5713_AwakerVoiceContent = {
    Text = "กระบวนท่านี้เป็นอย่างไร!"
  },
  Voice_5713_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5714_AwakerVoiceContent = {
    Text = "กระบวนท่านี้เป็นอย่างไร!"
  },
  Voice_5714_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5715_AwakerVoiceContent = {
    Text = "น่ากลัวจริงๆ~"
  },
  Voice_5715_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5716_AwakerVoiceContent = {
    Text = "อื้อ..."
  },
  Voice_5716_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5717_AwakerVoiceContent = {
    Text = "สวัสดี นายท่านคนใหม่ของฉัน! เมนูวันนี้มีพุดดิ้งทาก ตุ๋นคางคก และเหล้าไฟเขียว เลือกได้ตามใจชอบเลย~"
  },
  Voice_5717_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5718_AwakerVoiceContent = {
    Text = "นั่นคือรูปแบบของการกลับสู่ต้นกำเนิดหรือเปล่า... ไม่ มันแตกต่างจากที่ฉันจินตนาการไว้ แต่ถ้าฉันสามารถกลายเป็นแบบนั้นได้ก็คงจะดี"
  },
  Voice_5718_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับสายเลือดแห่งทะเลลึก"
  },
  Voice_5718_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ตูรู」「มอร์ฟี่」「มิลียาห์ม」「โกลิอัท」หนึ่งในนั้น"
  },
  Voice_5719_AwakerVoiceContent = {
    Text = "รอจังหวะ."
  },
  Voice_5719_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5720_AwakerVoiceContent = {
    Text = "รับมือให้ดี!"
  },
  Voice_5720_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5721_AwakerVoiceContent = {
    Text = "ลูกแกะเอ๋ย ความเมตตาของพระเจ้าจะช่วยไถ่พวกท่าน."
  },
  Voice_5721_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5722_AwakerVoiceContent = {
    Text = "ลูกแกะเอ๋ย ความเมตตาของพระเจ้าจะช่วยไถ่พวกท่าน."
  },
  Voice_5722_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5723_AwakerVoiceContent = {
    Text = "ตายซะ!"
  },
  Voice_5723_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5724_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_5724_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5725_AwakerVoiceContent = {Text = "หึ!"},
  Voice_5725_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5726_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_5726_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5727_AwakerVoiceContent = {
    Text = "เธอก็เป็นคนที่น่าสงสาร ชะตากรรมจะทำลายเธอในไม่ช้า เพราะเมื่อวันที่พระผู้เป็นเจ้าทรงปรากฏอย่างแท้จริง นั่นจะเป็นเวลาที่ข้ามอบความตายให้กับเธอ"
  },
  Voice_5727_AwakerVoiceTitle = {
    Text = "เรื่องราว, เกี่ยวกับมิลียาห์ม"
  },
  Voice_5727_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「มิลียัม」"
  },
  Voice_5728_AwakerVoiceContent = {
    Text = "เปื้อนไปด้วยเลือดเถอะ!"
  },
  Voice_5728_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5729_AwakerVoiceContent = {
    Text = "ล้างแค้น...!"
  },
  Voice_5729_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5730_AwakerVoiceContent = {
    Text = "เจ็บจัง.."
  },
  Voice_5730_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5731_AwakerVoiceContent = {
    Text = "(เสียงครวญที่พยายามอดกลั้น)"
  },
  Voice_5731_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5732_AwakerVoiceContent = {
    Text = "(เสียงครวญที่พยายามอดกลั้น)"
  },
  Voice_5732_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5733_AwakerVoiceContent = {
    Text = "ปวด.."
  },
  Voice_5733_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5734_AwakerVoiceContent = {
    Text = "คุณต้องการจมลงพร้อมกับฉันหรือไม่?"
  },
  Voice_5734_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5735_AwakerVoiceContent = {
    Text = "ไปให้พ้น!"
  },
  Voice_5735_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5736_AwakerVoiceContent = {
    Text = "สิ่งที่น่าเบื่อ...โต๊ะทำงานรกไม่เป็นระเบียบ ตู้เสื้อผ้ากระจุกกระจิก ขอบหน้าต่างเต็มไปด้วยฝุ่น——ใช่แล้ว ฉันกำลังอธิบายห้องของคุณอยู่ ก่อนเจ็ดโมงเช้าพรุ่งนี้ ฉันอยากเห็นมันกลับไปเหมือนตอนก่อนที่คุณย้ายเข้ามา"
  },
  Voice_5736_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5737_AwakerVoiceContent = {
    Text = "(ฮัมเพลงอย่างเพลิดเพลินและสนใจเป็นพิเศษ)"
  },
  Voice_5737_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5738_AwakerVoiceContent = {
    Text = "น่าสนใจ!"
  },
  Voice_5738_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5739_AwakerVoiceContent = {
    Text = "(หัวเราะเยาะด้วยความไม่แยแส)"
  },
  Voice_5739_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5740_AwakerVoiceContent = {
    Text = "หากจำเป็น ฉันสามารถออกจากเปลได้.."
  },
  Voice_5740_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5741_AwakerVoiceContent = {
    Text = "อยากได้ไหม?"
  },
  Voice_5741_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_5742_AwakerVoiceContent = {
    Text = "ดู~ซะ!"
  },
  Voice_5742_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5743_AwakerVoiceContent = {
    Text = "ดับเบิ้ล, ดับเบิ้ล, ดับเบิ้ล!"
  },
  Voice_5743_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5744_AwakerVoiceContent = {
    Text = "ฉันนึกถึงรองเท้าเต้นสีแดงคู่แรกที่ได้รับตอนอายุแปดขวบ ฉันชอบมันมาก ขอบคุณค่ะ ผู้พิทักษ์"
  },
  Voice_5744_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5744_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5745_AwakerVoiceContent = {
    Text = "เพื่อน...เป็นเจ้าของหรือแม่?"
  },
  Voice_5745_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5746_AwakerVoiceContent = {
    Text = "การคุ้มครองของฉัน ก็มีเวลาที่ใช้ไม่ได้ผล.."
  },
  Voice_5746_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5747_AwakerVoiceContent = {
    Text = "(ฮึดฮัด)"
  },
  Voice_5747_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5748_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5748_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5749_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5749_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5750_AwakerVoiceContent = {
    Text = "สิ่งที่ชอบเหรอ? บนสนามรบในเพโลพอนนีส ก็มีคนถามคำถามนี้กับฉันเหมือนกัน... มันสายไปแล้ว ฉันได้ละทิ้งความชอบส่วนตัวแบบนี้ไปนานแล้ว"
  },
  Voice_5750_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5751_AwakerVoiceContent = {
    Text = "ชู่... เรื่องที่ฉันแข็งแกร่งขึ้น โปรดอย่าให้「พวกเธอ」รู้ได้ไหม"
  },
  Voice_5751_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5752_AwakerVoiceContent = {
    Text = "「พวกเธอ」พูดว่า...ขอบคุณมาก"
  },
  Voice_5752_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5753_AwakerVoiceContent = {
    Text = "นั่น... นี่คืออะไร?"
  },
  Voice_5753_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5754_AwakerVoiceContent = {
    Text = "นี่จะทำให้ฉันเข้าใกล้เหวมากขึ้นเท่านั้น."
  },
  Voice_5754_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5754_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5755_AwakerVoiceContent = {
    Text = "เธอเป็นคนสำคัญที่ข้ารักและไว้ใจ เข้าใจว่าพวกเธอเรียกสิ่งนี้ว่าเพื่อน คู่หู หรือพันธมิตร...ไม่เป็นไร ตามใจเธอนะ"
  },
  Voice_5755_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5756_AwakerVoiceContent = {
    Text = "ฉันได้คำตอบแล้ว... แม้ว่ามันจะไม่ใช่คำตอบที่ฉันคาดหวัง แต่ฉันก็ได้คำตอบแล้ว"
  },
  Voice_5756_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5756_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5757_AwakerVoiceContent = {
    Text = "เป็น「ความกลัว」หรือ「ความเศร้า」? ใบหน้าที่เศร้าสร้อยของเธอน่าหลงใหลจริงๆ"
  },
  Voice_5757_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5757_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5758_AwakerVoiceContent = {
    Text = "กลิ่นของความตายและการทำลายล้าง ชัดเจนมาก"
  },
  Voice_5758_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5758_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5759_AwakerVoiceContent = {
    Text = "ชีวิตที่นี่? ค่อนข้าง, ค่อนข้างดีครับ แค่ผมให้ความรู้เกี่ยวกับวิทยาศาสตร์เครื่องจักรและการวิจัยจิตใจกับคุณหนูดอร์ เธอก็อนุญาตให้ผมเปิดไฟไว้ได้ตลอดเลย"
  },
  Voice_5759_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5760_AwakerVoiceContent = {
    Text = "หวังว่าเจนกินและบราวน์จะมีความสุขในโรงเรียน กระดุมข้อมือของพ่อไม่มีความหมายเมื่อเทียบกับความสบายใจของเธอ ฉันเชื่อว่าเขายังมีกระดุมสำรองอีกกล่องเต็ม"
  },
  Voice_5760_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเจนกิน"
  },
  Voice_5760_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「เจนกิน」"
  },
  Voice_5761_AwakerVoiceContent = {
    Text = "ไม่สามารถจากไปได้.."
  },
  Voice_5761_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5762_AwakerVoiceContent = {
    Text = "หลังจากที่ฉันหลุดพ้นจากเชื้อชาติชั้นต่ำแล้ว ฉันไม่มีทางหวาดกลัวผลกระทบแบบนี้เลย แม้ร่างกายจะแตกสลาย แต่สายเลือดที่สูงศักดิ์ก็จะไม่สูญสลาย"
  },
  Voice_5762_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5763_AwakerVoiceContent = {
    Text = "เกลียดคนที่ยิ้มเสแสร้ง! ไม่สามารถขโมยอารมณ์ใดๆ จากพวกเขาได้เลย!"
  },
  Voice_5763_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5764_AwakerVoiceContent = {
    Text = "หืม? ทำไมทุกคนเงียบกันหมดล่ะ? คาเรนไม่ชอบความเงียบ ฉันจะเล่าเรื่องราวให้พวกคุณฟังนะ เคยมีอยู่ครั้งหนึ่ง มีภูเขาแห่งหนึ่ง..."
  },
  Voice_5764_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5765_AwakerVoiceContent = {
    Text = "ลิลลี่จะคว้าอนาคตไว้... Tokuli—Li!"
  },
  Voice_5765_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5766_AwakerVoiceContent = {
    Text = "ลิลลี่จะคว้าอนาคตไว้... Tokuli—Li!"
  },
  Voice_5766_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5767_AwakerVoiceContent = {
    Text = "หากเจ้ามาเพื่อรับรู้ถึงการดำรงอยู่ของพระองค์ ก็จะให้อภัยเจ้าไปก่อน"
  },
  Voice_5767_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5768_AwakerVoiceContent = {
    Text = "ไม่อยากทำแบบนี้.."
  },
  Voice_5768_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5769_AwakerVoiceContent = {
    Text = "อย่าเข้ามา!"
  },
  Voice_5769_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5770_AwakerVoiceContent = {
    Text = "ทีละน้อยๆ, ก็สามารถตามจังหวะการสั่งการของคุณได้แล้ว!"
  },
  Voice_5770_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5771_AwakerVoiceContent = {
