  },
  Voice_57851_AwakerVoiceContent = {
    Text = "จงดูให้ดีเถิด นี่คือพละกำลังที่ชาวฟีลิสเตียพึ่งพา！"
  },
  Voice_57851_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_5785_AwakerVoiceContent = {
    Text = "อ่อนแอจริงๆ"
  },
  Voice_5785_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5786_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_5786_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5787_AwakerVoiceContent = {
    Text = "อืม...ดูเหมือนเจ้านายจะอารมณ์ไม่ค่อยดี? คาเรนจะทำหน้าตลกให้นะ ฮิ้ว—ฮา!\nเป็นไงบ้าง ตอนนี้รู้สึกดีขึ้นแล้วหรือยัง?"
  },
  Voice_5787_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5788_AwakerVoiceContent = {
    Text = "ด้วยสติปัญญาของมนุษย์... เปิดเผยแก่นแท้ของโลก!"
  },
  Voice_5788_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5789_AwakerVoiceContent = {
    Text = "ฉันเจอคนบางคนในทางเดินที่ทำให้ฉันรู้สึกไม่ดี อาจจะเป็นเพราะสถานการณ์บังคับ คุณอาจจำเป็นต้องร่วมมือกับพวกเธอในการต่อสู้ แต่โปรดระวังไว้เสมอ สิ่งที่โหดร้ายยิ่งกว่าสงครามก็คือจิตใจของมนุษย์ การทรยศที่น่ากลัวที่สุดมักจะมาจากแหล่งที่มาภายใน."
  },
  Voice_5789_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับ@2"
  },
  Voice_5789_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับตัวปลุก「ชิโล」หรือ「ลิลลี่」"
  },
  Voice_5790_AwakerVoiceContent = {
    Text = "การบ้านของคุณเสร็จแล้วใช่ไหม สามารถไปกับฉันที่เขตเมืองลอนดีเนี่ยนได้หรือเปล่า... เอ๋? ยังไม่เสร็จการบ้านเลขเหรอ?!\nอา... ขอโทษนะ ฉันไม่คิดว่าจะมีใครไม่เข้าใจเรื่องแคลคูลัส... ให้ฉันช่วยเธอดีไหม?"
  },
  Voice_5790_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับการเรียนรู้"
  },
  Voice_5791_AwakerVoiceContent = {
    Text = "ข้าขอสาบานกับท่านว่า เจ้าของร้านคนนั้นต้องเคยปรากฏตัวในห้องรับรองของฟงตันบลอง... อย่างนี้นี่เอง ตั้งแต่นั้นมาเธอก็ยังคงเป็นเช่นนี้ใช่ไหม ไม่รู้ว่าจากมือของเธอ จะสามารถแลกเปลี่ยนได้มากเท่าไรสำหรับความลับเหล่านั้น..."
  },
  Voice_5791_AwakerVoiceTitle = {
    Text = "เรื่องราวเกี่ยวกับดาฟเดล"
  },
  Voice_5791_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「ดาฟเดล」ที่ถูกปลุก"
  },
  Voice_5792_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_5792_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5793_AwakerVoiceContent = {
    Text = "ระวังอย่าให้แตกนะ"
  },
  Voice_5793_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5794_AwakerVoiceContent = {
    Text = "ออรีตาชอบเล่นกับทุกคน! คุณจะมาด้วยหรือเปล่า? เด็กคนนี้ชื่อเจลลี่ แล้วคนนั้นชื่อเฮล่า ส่วนคนนั้นชื่อเจลลี่...เอ๋?"
  },
  Voice_5794_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5795_AwakerVoiceContent = {
    Text = "ความอับอาย ข้าจะล้างมันด้วยกระบวนท่านี้!"
  },
  Voice_5795_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5796_AwakerVoiceContent = {
    Text = "ร้านค้าของดาฟเดลเปิดแล้ว เด็กๆ ที่ยังไม่พร้อม อย่าเพิ่งเข้ามาดีกว่านะ?"
  },
  Voice_5796_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5796_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5797_AwakerVoiceContent = {
    Text = "อย่าแตะต้องที่คอของฉันเลย... มองไม่เห็น ไม่ได้หมายความว่าไม่มี"
  },
  Voice_5797_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5798_AwakerVoiceContent = {
    Text = "ฉันชอบคนที่มีความเชื่อมั่น ไม่ว่าจะเป็นสัตว์ ร่างกายที่ตื่นขึ้น หรือมนุษย์ ก็ตาม ถ้าคนพวกนี้มีทักษะการต่อสู้ยอดเยี่ยมด้วยแล้ว ก็ยิ่งดีเลย"
  },
  Voice_5798_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5799_AwakerVoiceContent = {
    Text = "ไปเถอะ."
  },
  Voice_5799_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5800_AwakerVoiceContent = {
    Text = "อย่ากังวล!"
  },
  Voice_5800_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5801_AwakerVoiceContent = {
    Text = "รามอน่าเกลียดการสูญเสีย... ขอโทษนะ ที่จริงแล้วหมายถึงว่า ฉันไม่ชอบการจากลา มันทำให้รู้สึกเศร้ามาก"
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "ฉันไม่ถนัดในการอยู่ร่วมกับพวกนักบวช พวกเขาไร้ความสนุกและเคร่งครัด อีกทั้งยังมอบเข็มขัดให้กับ「พระเจ้า」ที่พวกเขารักยิ่ง น่าเสียดายจริงๆ คุณเอลซัลวาดอร์กลับมีกลิ่นหอมหวานเหลือเกิน.."
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับเอลซัลวาดอร์"
  },
  Voice_5802_UnlockDesc = {
    Text = "ปลดล็อคเมื่อได้รับ「เอลซัลวาดอร์」ร่างกายที่ตื่นขึ้น"
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "การต่อสู้ที่ดุเดือดและเต็มเปี่ยมไปด้วยความมันส์นั้นเหนือกว่าทุกอย่าง รวมถึงผลแพ้ชนะ"
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "ใครบ้างไม่ชอบเตียงนุ่มๆ และระบบท่อน้ำที่ไม่รั่ว... ห้องแบบนี้ไง"
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "...อย่าทำให้ฉันต้องนึกถึงอีกเลย... วันที่ถูกจองจำในเอลวอส..."
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "เผาผลาญทุกอย่าง!"
  },
  Voice_5806_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5807_AwakerVoiceContent = {
    Text = "เผาผลาญทุกอย่าง!"
  },
  Voice_5807_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5808_AwakerVoiceContent = {
    Text = "ฉันตามกลิ่นของเลือดมาพบที่แห่งนี้ ขอถามหน่อย...ที่นี่มีถุงเลือดสดๆ ให้บริการไหม?"
  },
  Voice_5808_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5809_AwakerVoiceContent = {
    Text = "อืม...อักกริปปาก็มีเพื่อนเยอะเหมือนกัน แต่ทุกคนดูเหมือนจะกลัวเธอมาก เธอจะแย่งของกินจากเพื่อนๆ หรือเปล่า?"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับอักกริปปา"
  },
  Voice_5809_UnlockDesc = {
    Text = "เมื่อได้รับตัวปลุก「อักกริปปา」จะปลดล็อก"
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "ในชีวิตของฉันมีแค่การเต้นรำเท่านั้น แม้ว่าจะให้ฉันเรียนรู้สิ่งอื่น ก็ยังยากที่จะพัฒนาได้ แต่ทุกคนล้วนใจดี ไม่มีใครจะขายฉันเพื่อความหรูหราหรือเงินทอง ฉันสามารถสัมผัสได้ถึงความจริงใจนี้"
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "คนขี้ขลาด แม้จะมีพละกำลังที่ทรงพลังเหมือนฉัน แต่กลับกดข่มตัวเองแบบนี้ มันต่างอะไรจากคนที่ใส่ปลอกคอโดยสมัครใจ！"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับลิลลี่"
  },
  Voice_5811_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「ลิลลี่」"
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "ไม่พอ...พละกำลังยังไม่พอ.."
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5813_AwakerVoiceContent = {
    Text = "กลับไปเถอะ."
  },
  Voice_5813_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5814_AwakerVoiceContent = {Text = "ว้า!"},
  Voice_5814_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5815_AwakerVoiceContent = {
    Text = "หมวกทรงสูง หมวกโบเลอร์ หมวกฮันติ้ง หมวกเบเร่ต์... ต้องยอมรับว่าพวกคุณชนชั้นสูงพยายามอย่างมากเพื่อปกปิดศีรษะล้าน จนดูเหมือนพยายามเกินไปและน่าขำจริงๆ"
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับมารยาท"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "ฉันชื่นชมคนคนนั้นมาก เธอขาวบริสุทธิ์และสง่างามเหมือนดอกลิลลี่ เทพเจ้าแห่งการเดินเรือ... ท่านบอกว่าแม้แต่เธอเองก็ไม่สามารถควบคุมชะตาชีวิตของตัวเองได้ และในที่สุดก็จมลงสู่ก้นทะเลใช่ไหม? นี่... ยากแท้จะจินตนาการ.."
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับฮิลีย์สเตอร์"
  },
  Voice_5816_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างตื่น「ฮิลีย์สเตอร์」"
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "ในโลกนี้ไม่มีสิ่งใดที่ยักษ์ไม่สามารถต้านทานได้!"
  },
  Voice_5817_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5818_AwakerVoiceContent = {
    Text = "ในโลกนี้ไม่มีสิ่งใดที่ยักษ์ไม่สามารถต้านทานได้!"
  },
  Voice_5818_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5819_AwakerVoiceContent = {
    Text = "ช่างน่าโมโห ช่างน่าโมโห...! พละกำลังจะทำให้ฉันติดอยู่ในร่างกายของตัวเองอย่างแน่นหนา..."
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5819_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "อยากอยู่ในที่สว่างตลอดไป... ใช่แล้ว ขั้วโลก บนดาวเคราะห์นี้ก็มีแค่ขั้วโลกเท่านั้น"
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5820_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "ฉัน, ฉันไม่สามารถรับผิดชอบอะไรหนักๆ ได้ ได้แต่ไล่ตามแสงไปเท่านั้น ดังนั้น ขอให้คุณอย่าหยุดส่องประกายเลย.."
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5821_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "หากยังสามารถโยกย้ายได้ ฉันอยากจะกลายเป็นดวงดาวสักดวง.."
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5822_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "ไม่ว่าจะคำนวณอย่างไร สูตรสำหรับการย้ายจิตสำนึกก็หาคำตอบไม่ได้.."
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5823_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "ยินดีต้อนรับ มาปาร์ตี้กันเลย!"
  },
  Voice_5824_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5825_AwakerVoiceContent = {
    Text = "เชิญเพลิดเพลินกับมื้ออาหาร!"
  },
  Voice_5825_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5826_AwakerVoiceContent = {
    Text = "ฮูๆ — เป็นออรีตาค่ะ! หนึ่ง สอง สาม... ว้าว! ยินดีต้อนรับ ยินดีต้อนรับ! เพื่อนใหม่เพิ่มแล้ว! เอ๊ะ? เป็นฉันที่กลายเป็นเพื่อนใหม่ของทุกคนเหรอ? ก็คงจะพูดแบบนั้นได้เหมือนกัน!"
  },
  Voice_5826_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5827_AwakerVoiceContent = {
    Text = "พวกเจ้าเรียกของเล็กๆ นี่ว่าปืนพกหรือ? แอบซ่อนในเงาแล้วคอยจู่โจมศัตรู มันช่างเป็นอาวุธของคนขี้ขลาดจริงๆ"
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "ไม่มีความหมายเลย การทำแบบนี้ไม่มีความหมาย"
  },
  Voice_5828_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5829_AwakerVoiceContent = {
    Text = "คุณไม่เข้าใจอะไรเลยจริงๆ"
  },
  Voice_5829_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5830_AwakerVoiceContent = {
    Text = "ยังคิดว่าฉันจะเป็น ‘ผู้ช่วยเหลือโลก’ ของพวกเธองั้นเหรอ?"
  },
  Voice_5830_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5831_AwakerVoiceContent = {
    Text = "เอ่อ คุณเห็นน็อตของฉันไหม? แปลกจริงๆ ทุกครั้งที่มีเด็กที่แต่งตัวเหมือนหนูอยู่ด้วย ฉันกลับลืมไปว่าตัวเองเก็บของไว้ที่ไหนได้ง่ายขึ้น.."
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเจนกิน"
  },
  Voice_5831_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「เจนกิน」"
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "ฉันจะไม่ลืมทุกอย่างที่เธอได้เสียสละเพื่อการพบกันอีกครั้งของฉันและเจ้านายของฉัน.."
  },
  Voice_5832_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5833_AwakerVoiceContent = {
    Text = "การแกะสลักที่ไพเราะ!"
  },
  Voice_5833_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5834_AwakerVoiceContent = {
    Text = "คุณยอมรับความปรารถนาของฉันแล้วหรือยัง?"
  },
  Voice_5834_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5835_AwakerVoiceContent = {
    Text = "หวังว่าคำสั่งของคุณจะไม่ทำให้ใครก็ตามผิดหวัง"
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "สิ่งที่ได้รับการยกระดับคือ ร่างนี้หรือจิตสำนึกของฉันกันแน่? หัวข้อที่น่าติดตามจริงๆ"
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5836_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5837_AwakerVoiceContent = {
    Text = "ถอยหลัง."
  },
  Voice_5837_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5838_AwakerVoiceContent = {
    Text = "หลีกไป"
  },
  Voice_5838_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5839_AwakerVoiceContent = {
    Text = "ในเส้นเลือดของฉันเต็มไปด้วยพลังแห่งการเอาชีวิตรอด มันกรีดร้องและผลักดันให้ฉันโปรยเลือดลงบนทุกตารางนิ้วของดาวเคราะห์ดวงนี้... อะอา ขอโทษที่คุณต้องฟังเรื่องราวเหล่านี้มากเกินไป ขำๆ นะ ฉันคือไทอีส คุณเรียกหาฉัน เพราะคุณพร้อมที่จะหลอมรวมกับฉันแล้วใช่ไหม?"
  },
  Voice_5839_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5840_AwakerVoiceContent = {
    Text = "ถ้าไอจิสสามารถรับของเหลวสีดำนี้แทนทุกคนได้ก็คงจะดี... ท้ายที่สุดแล้ว ไอจิสไม่เคยมีตัวตนมาก่อน น่าจะดีสำหรับโลกใบนี้ จริงไหม?"
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "ความชอบคือสมมุติฐานของรีมันน์——นี่คือคำพูดปากประจำของนกยูง ไม่ใช่ของฉัน.เมื่อเปรียบเทียบแล้ว ฉันสนใจการวิจัยเกี่ยวกับปริมาณมาตรฐานของอะตอมมากกว่า."
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "รสชาติของการถูกขับไล่ออกจากบ้านและลี้ภัยไปยังทะเล......สัมผัสแค่ครั้งเดียวก็พอแล้ว"
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5844_AwakerVoiceContent = {
    Text = "ดูให้ดี!"
  },
  Voice_5844_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5845_AwakerVoiceContent = {
    Text = "ดูให้ดี!"
  },
  Voice_5845_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5846_AwakerVoiceContent = {
    Text = "ตราบใดที่เธอยังคงรักษาความยุติธรรมนี้ ฉันจะรับหน้าที่เป็นคมดาบเช่นเคย"
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "คุณเคยได้ยินเรื่องราวเกี่ยวกับ「ผู้วาด」ที่เล่าขานกันในที่นี้ไหม? จากสไตล์กราฟฟิตีแบบเอกซ์เพรสชั่นนิสต์เหล่านั้น ฉันรู้สึกถึงความคุ้นเคยบางอย่าง.."
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "เจ็บจัง ตื่นเต้นจริงๆ——"
  },
  Voice_5848_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5849_AwakerVoiceContent = {
    Text = "รู้จักกับความโกรธของฉันซะ！"
  },
  Voice_5849_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5850_AwakerVoiceContent = {
    Text = "ลองบันทึกชัยชนะครั้งนี้ด้วยบทกวี"
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5851_AwakerVoiceContent = {
    Text = "เติบโตเถอะ——"
  },
  Voice_5851_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5852_AwakerVoiceContent = {
    Text = "รับมือให้ดี!"
  },
  Voice_5852_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5853_AwakerVoiceContent = {Text = "เอ้!"},
  Voice_5853_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5854_AwakerVoiceContent = {
    Text = "บางทีเมื่อโตขึ้น ฉันอาจจะสามารถควบคุมตัวเองได้ ไม่ดึงชีวิตของคนอื่นออกจนหมด... เพียงแค่นิดเดียวก็พอให้ฉันอยู่รอดแล้ว"
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5854_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "ดูเหมือนจะหนักขึ้นเล็กน้อย เปลยังรับน้ำหนักของฉันได้หรือเปล่า?"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5855_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "พละกำลังจะล้นออกมารู้สึกคันๆ ที่หลังแบบนี้ แสดงว่ากำลังจะเติบโตขึ้นหรือเปล่า?"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_5856_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "แม้ว่าฉันจะยังดูเหมือนเด็ก แต่ตอนนี้ฉัน...ได้มีพละกำลังที่จะปกป้องคุณแล้ว"
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5857_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "ฉันจะพยายามเติบโตให้มากขึ้น."
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_5858_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "คนที่ไม่รู้จักคุณค่า ทำไมถึงยังคงยืนกรานที่จะปลุกข้า?"
  },
  Voice_5859_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5860_AwakerVoiceContent = {
    Text = "ฉันจะกลายเป็นแม่ของพระเจ้า!"
  },
  Voice_5860_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5861_AwakerVoiceContent = {
    Text = "นี่เป็นครั้งที่กี่แล้วที่ถูกเรียก... มนุษย์ เจ้าควรเตรียม「อาหาร」ให้เพียงพอ หากไม่เช่นนั้นข้าไม่อาจรับรองอะไรได้เลย"
  },
  Voice_5861_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5862_AwakerVoiceContent = {
    Text = "นอกประตู!"
  },
  Voice_5862_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5863_AwakerVoiceContent = {Text = "โง่."},
  Voice_5863_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5864_AwakerVoiceContent = {
    Text = "ฮ่าๆ"
  },
  Voice_5864_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5865_AwakerVoiceContent = {
    Text = "ฮึ ไม่เลวเลย ครั้งหน้าเราจะสู้กันอย่างเต็มที่"
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5866_AwakerVoiceContent = {
    Text = "คนไร้มารยาท!"
  },
  Voice_5866_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_5867_AwakerVoiceContent = {
    Text = "บางครั้ง ความงามของศิลปะก็คือความงามของความพินาศ และความล้มเหลวของคุณ... ชัดเจนว่าไม่ได้อยู่ในข่ายนี้"
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "คุณเป็นผู้ฟังที่สำคัญที่สุดของฉัน ไม่ว่าเมื่อใด ฉันจะเตรียมพร้อมเสมอที่จะร้องเพลงให้คุณฟัง และทุกสิ่งทุกอย่างที่ฉันมี"
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "ชอบอะไร? สาหร่ายน้ำ, ฝูงปลา, เสาโถง, แล้วก็เขาวงกต... ฉันเคยเห็นแน่นอน! ในหนังสือของลุงโอเน้นมีทุกอย่าง!"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "นี่คือการเตรียมตัวสำหรับภารกิจสอบสวนใช่ไหม? ฉันเข้าใจแล้ว."
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5870_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "ชื่อของฉันคือฮิลีย์สเตอร์ ตราบใดที่คุณยังต้องการฉัน ฉันจะอยู่ที่นี่เสมอ"
  },
  Voice_5871_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5872_AwakerVoiceContent = {
    Text = "ลองดูบทเรียนนี้!"
  },
  Voice_5872_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5873_AwakerVoiceContent = {
    Text = "ให้เกียรติผู้อาวุโสกว่า ผู้น้อย การปฏิบัติตามลำดับชั้นในกองทัพเป็นสิ่งสำคัญ และการกระทำที่เกินขอบเขตเช่นนี้จะต้องได้รับโทษ"
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "ฉันยินดีที่จะให้บริการหลังการขายสำหรับ「ของเล่นชิ้นเล็กๆ」เหล่านั้น แต่ปัญหาคือพวกคุณกล้าที่จะรับบริการของฉันหรือเปล่า?"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับสิ่งประดิษฐ์"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "ท่านเป็นเจ้าของที่นี่ แต่ก็เป็นแขกคนสำคัญในงานเลี้ยงของฉันเช่นกัน ฉันจะเตรียมการต้อนรับที่ดีที่สุดสำหรับท่าน——ท่านชอบกระโปรงสีแดงสดใส หรือชุดนอนสีขาวดอกกุหลาบมากกว่ากัน?"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "ขอโทษนะ แสงแดดที่นี่จ้าตาไปมากเลย...หนูที่มาจากถ้ำมืดๆ ยังไม่ชินกับสภาพแบบนี้"
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "สามารถกัดกร่อนทุกสิ่ง ทำลายล้างทุกอย่าง... มันเป็นอาวุธที่น่ากลัวมาก หากตอนนั้นฉันรู้... หึ่"
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "มีข่าวลือว่าร่างกายของคนที่กำลังกระตุกในเปลวไฟเหมือนกับการเต้น"
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับเปลวไฟ"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "อย่าออกไปข้างนอกในตอนกลางคืน แม้ว่าจะพกแหล่งกำเนิดแสงขนาด 2000 ลูเมน ก็ไม่ได้หมายความว่าจะปลอดภัยร้อยเปอร์เซ็นต์... เมื่อใดที่ก้าวเข้าสู่ความมืด ปีศาจที่ซ่อนตัวอยู่นอกสายตาจะไล่ล่าและกลืนกินคุณซ้ำแล้วซ้ำเล่า จนไม่มีอะไรเหลือ"
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับราตรี"
  },
  Voice_5881_AwakerVoiceContent = {
    Text = "ร้องไห้เถอะ."
  },
  Voice_5881_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5882_AwakerVoiceContent = {
    Text = "ได้รับแล้ว"
  },
  Voice_5882_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5883_AwakerVoiceContent = {
    Text = "นั่นคือความปรารถนาของชีวิต ที่ขับเคลื่อนหงส์ให้ดิ้นรนเพื่อกลับคืนสู่ท้องฟ้าไกล"
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5883_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "เริ่มเปลี่ยนแล้ว!"
  },
  Voice_5884_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5885_AwakerVoiceContent = {
    Text = "ช่วยด้วย!"
  },
  Voice_5885_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5886_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_5886_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_5887_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5887_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5888_AwakerVoiceContent = {Text = "อ้า"},
  Voice_5888_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5889_AwakerVoiceContent = {
    Text = "อ่า บราวน์วิ่งผ่านไปแล้ว! ฉัน... ฉันควรจะหลีกเลี่ยงเธอหน่อยดีกว่า...\nทั้งที่อยากจะเป็นเพื่อนกับเธอ แต่สุดท้ายกลับกลายเป็นฝันร้ายของเธอ... เธอคงไม่อยากเจอฉันแน่.."
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเจนกิน"
  },
  Voice_5889_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「เจนกิน」"
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "โบสถ์? ขอบคุณมากครับ แต่ในความเป็นจริง ผมไม่ได้ถือแบบโบราณขนาดนั้น เพียงแค่จดจำคำสอนของพระผู้ทรงเมตตาในใจเสมอ และปฏิบัติตามพระประสงค์ของพระองค์ทุกขณะ วิญญาณของผมก็จะไม่ห่างไกลจากพระสิริของพระองค์"
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับโบสถ์"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "ชื่อของข้าคือโอกีล ตามสัญญากับท่าน ข้าจะถวายความซื่อสัตย์ของอัศวิน ปกป้องท่านจากภัยอันตราย และขจัดศัตรูของท่าน คำสาบานในวันนี้ จะไม่มีวันลืมเลือน"
  },
  Voice_5891_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5892_AwakerVoiceContent = {
    Text = "ผู้หญิงตาสองชั้นที่ซูบผอมคนนั้น มีกลิ่นเหมือนแมลงสาบสายพันธุ์สปาด้าไม่มีผิด"
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับอักกริปปา"
  },
  Voice_5892_UnlockDesc = {
    Text = "เมื่อได้รับตัวปลุก「อักกริปปา」จะปลดล็อก"
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "สิ่งที่ชอบเหรอ? แน่นอนว่าเป็นโชคดีแล้ว ทุกวันก่อนออกจากบ้านต้องขอพรให้เจอแต่เรื่องดีๆ นะ"
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "กรุณา กรุณาอย่าบอกคุณหนาน่าว่าฉันซ่อนอยู่ที่นี่ ฉันยังไม่พร้อม.."
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "เรื่องราว: เกี่ยวกับฮันนา"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "เป็นอย่างไรบ้าง?"
  },
  Voice_5895_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5896_AwakerVoiceContent = {
    Text = "ท่านเป็นแขกผู้มีเกียรติของฉัน โปรดทราบว่า ฉันอนุญาตให้ท่านเป็นคนเดียวที่สามารถค้างชำระได้ เพราะไม่เคยเห็นหัวที่สมบูรณ์แบบขนาดนี้มานาน.."
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5897_AwakerVoiceContent = {
    Text = "โอ๊ย!"
  },
  Voice_5897_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5898_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_5898_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5899_AwakerVoiceContent = {
    Text = "โอ๊ย!"
  },
  Voice_5899_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5900_AwakerVoiceContent = {
    Text = "สิ่งที่ชอบ... พระมหากษัตริย์ไม่ควรมีลักษณะเช่นนี้ แต่หากสามารถหลีกเลี่ยงฎีกาและคำอธิษฐานที่น่าเบื่อได้ แล้วขดตัวอยู่บนเตียงนุ่มๆ ข้าก็ย่อมจะได้พักผ่อนอย่างสบายใจ"
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "ข้าจะมองการกระทำที่ขาดความเคารพของพวกเจ้าว่าเป็นคำขอให้หลับใหลตลอดกาล"
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "เกลียดไหม? ฉันเกลียดชะตากรรมที่ไม่อาจหลีกหนีได้และโศกนาฏกรรมที่ต้องเกิดขึ้นอย่างหลีกเลี่ยงไม่ได้"
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5903_AwakerVoiceContent = {Text = "หึ!"},
  Voice_5903_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5904_AwakerVoiceContent = {
    Text = "(เสียงฮัมที่เก็บกด)"
  },
  Voice_5904_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5905_AwakerVoiceContent = {
    Text = "อย่าเข้ามา!"
  },
  Voice_5905_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5906_AwakerVoiceContent = {
    Text = "โอ้ อยากรู้ความลับของฉันหรือ? ชื่อนี้ ร่างกายนี้ ใบหน้านี้ เสียงนี้ ทั้งหมดมาจากเจ้าของศีรษะหนึ่งในซานเปโดร เธอทำข้อตกลงกับฉัน... หลังจากเธอเสียชีวิต ฉันก็กลายเป็นเธอ ส่วนเธอหายไปไหนน่ะหรือ... นั่นเป็นหนึ่งในคอลเลกชันที่งดงามที่สุดของฉันเลยล่ะ?"
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5906_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "ท่านเป็นแขกที่น่ารื่นรมย์มาก แม้แต่ข้าเองก็ยังหลงใหลในศีรษะอันโดดเด่นไม่เหมือนใครของท่าน... หากท่านมีความสนใจจะโอนเปลี่ยนมัน ต้องมาเยี่ยมชมร้านเล็กๆ ของข้าด้วยนะ ฮ่ะฮ่ะ... แค่ล้อเล่นกับท่านเท่านั้น"
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5907_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "อยากรู้เรื่องตัวตนที่แท้จริงของฉันเหรอ? ยังเร็วไปหน่อยนะตอนนี้ คุณแค่เชื่อสิ่งนี้ก็พอแล้ว: เด็กๆ ที่หลงทางทุกคนสามารถหาที่พักพิงได้ในร้านของฉัน รวมถึงคุณด้วยนะ?"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5908_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "ไม่มีใครจะได้รับความเสียหาย."
  },
  Voice_5909_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5910_AwakerVoiceContent = {
    Text = "ยังไม่จบ!"
  },
  Voice_5910_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5911_AwakerVoiceContent = {
    Text = "เห็นคุณพยายามขนาดนี้ ผมก็รู้สึกเกรงใจที่จะเรียกค่าตอบแทนเร็วเกินไป ดังนั้น ศีรษะของคุณชั่วคราวก็ยังอยู่ที่เดิมก่อนนะ \nแต่อย่าลืมล่ะ มันได้ถูกจองเป็นสมบัติส่วนตัวของผมแล้วนะ"
  },
  Voice_5911_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5911_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "ในอดีตรูปลักษณ์ของข้าไม่ได้เป็นเช่นนี้ เธอคือผู้ที่มอบชีวิตใหม่ให้กับข้า ดังนั้น ท่านก็เป็นผู้มอบชีวิตครั้งที่สองให้กับข้าเช่นกัน ข้าจะเก็บรักษาศีรษะของคุณไว้อย่างดี"
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5912_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "หลบหนีออกจากความมืดอย่างเด็ดขาด"
  },
  Voice_5913_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5914_AwakerVoiceContent = {
    Text = "การผจญภัยนี่อันตรายมากเลย.."
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "แล้วทำไมสาวน้อยคนนั้นเห็นฉันทีไรถึงได้วิ่งหนีล่ะ? คราวหน้าฉันจะลองเหยียบเส้นไหมของเธอ ดูสิว่าเธอจะวิ่งไปไหนได้"
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับไอจิส"
  },
  Voice_5915_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ไอจิส」"
  },
  Voice_5916_AwakerVoiceContent = {Text = "อึก!"},
  Voice_5916_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5917_AwakerVoiceContent = {
    Text = "หึ~ฮาๆๆ!"
  },
  Voice_5917_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5918_AwakerVoiceContent = {
    Text = "ฮ่าฮ่าฮ่าฮ่า!"
  },
  Voice_5918_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5919_AwakerVoiceContent = {
    Text = "เด็กคนนั้นมีความเฉลียวฉลาด การเอาตัวรอดบนท้องถนนก็ต้องใช้ปัญญาแบบนี้ หากฉันยังสืบคดีอยู่ข้างนอก แน่นอนว่าจะต้องสร้างความสัมพันธ์ที่ดีกับเธอ"
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเจนกิน"
  },
  Voice_5919_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「เจนกิน」"
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "พระบิดาผู้ศักดิ์สิทธิ์ไม่สามารถช่วยเหลือทุกคนได้ ท่านอาจจะช่วยชายโชคร้ายคนหนึ่งได้ แต่ไม่สามารถดึงทุกคนออกจากหนองน้ำได้... ฉันเฝ้ารอคอยเขา รอคอยให้ศรัทธาของเขาพังทลาย"
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับเอลซัลวาดอร์"
  },
  Voice_5920_UnlockDesc = {
    Text = "ปลดล็อคเมื่อได้รับ「เอลซัลวาดอร์」ร่างกายที่ตื่นขึ้น"
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "คุณสามารถหาทุกอย่างที่ต้องการได้ในท่อระบายน้ำของลอนดีเนี่ยน: ปลาแซลมอน, สบู่, วิสกี้ที่ดื่มเหลือครึ่งขวด...\nอะไรนะ? คุณถามว่าทำไมฉันถึงรู้เรื่องนี้ดี? ฉันเคยลากศพของพี่ชาย คลานไปห้าหลี่ในนั้น.."
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับท่อระบายน้ำ"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "คุกเข่าให้ฉัน!"
  },
  Voice_5922_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5923_AwakerVoiceContent = {
    Text = "คุกเข่าลงเดี๋ยวนี้!"
  },
  Voice_5923_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5924_AwakerVoiceContent = {
    Text = "หลังจากที่ได้เห็นโลกจริงนอกสนามรบ ฉันเคยสงสัยในคุณค่าของคำว่า “ฮีโร่” แต่โชคดีที่ฉันได้พบกับคุณ ผู้ที่มีความซื่อสัตย์ เด็ดเดี่ยว และบริสุทธิ์ใจ ฉันจะอยู่ภายใต้การนำของคุณ เพื่อทำการต่อสู้เพื่อสันติภาพและความมั่นคงของโลกอย่างเต็มที่ ครั้งนี้ ฉันจะต้องทำให้การไถ่บาปของฉันสำเร็จลุล่วง"
  },
  Voice_5924_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5924_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5925_AwakerVoiceContent = {
    Text = "อาห์! แย่แล้ว.."
  },
  Voice_5925_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5926_AwakerVoiceContent = {
    Text = "ไม่บริสุทธิ์ ความสกปรก ความวุ่นวาย——นี่คือพละกำลังของเรา"
  },
  Voice_5926_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5927_AwakerVoiceContent = {
    Text = "ฉันเกลียดท่าทางเสแสร้งของพวกคุณ คิดว่าฉันบ้า คิดว่าฉันน่าสงสารใช่ไหม? ในสายตาของฉัน พวกคุณเหมือนคนที่ถูกแสงอาทิตย์ทำให้ตาพร่า มองไม่เห็นความจริง พวกคุณต่างหากที่น่าสงสาร"
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "ขอให้ฉันเป็นคนแรกที่ลงมือเถอะ!"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "กลิ่นอายของพวกมันดูแปลกไป พวกเขาไม่ใช่ชีวิตที่เกิดขึ้นเองตามธรรมชาติบนดาวเคราะห์ดวงนี้หรอก"
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับคนจากนอกดวงดาว"
  },
  Voice_5929_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างกายที่ตื่นขึ้น「เวินเค่อ」「ทิงค์เทต」「ฟีนต์」「วันดา」หนึ่งในสี่"
  },
  Voice_5931_AwakerVoiceContent = {
    Text = "(ฮึดฮัด)"
  },
  Voice_5931_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_5932_AwakerVoiceContent = {
    Text = "จงพินาศไป!"
  },
  Voice_5932_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_5933_AwakerVoiceContent = {
    Text = "กรุณาอย่า.."
  },
  Voice_5933_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5934_AwakerVoiceContent = {
    Text = "แม้จะกลายเป็นสัตว์ประหลาดก็ไม่เป็นไร แต่สิ่งที่ฉันต้องการมาตลอดคือพละกำลังแห่งการแก้แค้น"
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5934_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "นอกจากจะกำจัดคู่ต่อสู้แล้ว คุณยังมีอะไรที่ต้องการอีกไหม? เป็นการตอบแทน ฉันจะทำให้ความปรารถนาของคุณเป็นจริง... แน่นอนว่าภายในขอบเขตความสามารถของฉัน"
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_5935_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_5936_AwakerVoiceContent = {
    Text = "(ฮึดฮัด)"
  },
  Voice_5936_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_5937_AwakerVoiceContent = {
    Text = "คู่หูเหรอ? ...ฉันจะพิจารณานะ แต่ก่อนที่ฉันจะตัดสินใจได้ อย่าตายง่ายๆ ล่ะ"
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_5937_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "ตั้งแต่ครั้งแรกที่มีการบันทึกอย่างชัดเจนเป็นต้นมา ปรากฏการณ์หลอมกร่อนได้ส่งผลกระทบต่อชีวิตของผู้คนมากกว่าล้านคน การกระทำของเราส่งผลต่อการอยู่รอดของมนุษยชาติทั้งมวล."
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5939_AwakerVoiceContent = {
    Text = "พละกำลังเต็มที่!"
  },
  Voice_5939_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5940_AwakerVoiceContent = {
    Text = "ระวังคลั่งไคล้แห่งท้องทะเล"
  },
  Voice_5940_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5941_AwakerVoiceContent = {
    Text = "ระวังคลั่งไคล้แห่งท้องทะเล"
  },
  Voice_5941_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5942_AwakerVoiceContent = {Text = "เฮ้!"},
  Voice_5942_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5943_AwakerVoiceContent = {
    Text = "ข้าคือพระธิดาของพระองค์ รวมทั้งเป็นมารดาของพระองค์ด้วย ส่วนท่าน ในสายพระเนตรของพระองค์ ท่านก็แค่มดตัวเล็กน้อยเท่านั้น"
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "ทุกอย่างราบรื่น แล้วกางใบเรือแห่งชัยชนะขึ้นเถอะ"
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "อย่าเข้ามา! คุณอยากกลายเป็นของเล่นขององค์หญิงหรือของขวัญแด่เทพ?"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5945_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "สบายๆ, ชนะอย่างงดงาม!"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "สบายๆ, ชนะอย่างงดงาม!"
  },
  Voice_59464_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_5946_AwakerVoiceContent = {
    Text = "ข้าอนุญาตให้ท่านเป็นผู้สังเกตการณ์ เพื่อสังเกตช่วงเวลาแห่งความรุ่งโรจน์ที่ล้มล้างศีลธรรม"
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5946_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "ว่างเปล่าหรือเปล่า? การหยิบของจากอากาศก็มักจะสร้างช่องว่างแบบนี้เช่นกัน! ช่องว่างที่คาเซียสร้างขึ้นจะลิงก์ไปยังมิติอื่น การหลอมกร่อนก็เป็นแบบเดียวกันหรือเปล่า?"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "ผู้พิทักษ์ ข้าจะใช้พลังแห่งพระมารดาเทพ เพื่อเตรียมที่นั่งให้เจ้าไว้ข้างบัลลังก์ในทะเลลึก เจ้าจะได้เป็นพยานในยุคสมัยที่เกิดใหม่หลังจากการทำลาย จงรู้สึกขอบคุณอย่างเต็มที่เถิด นี่คือคำสัญญาของพระมารดาเทพ！"
  },
  Voice_5948_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5948_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "ด้วยความที่เจ้าแสดงความนอบน้อมเช่นนี้ ข้าจะประทานคำตอบให้เจ้าหนึ่งข้อ ตอนแรกก็มีการดิ้นรนอยู่หรอก แต่บัดนี้ข้าเข้าใจแล้วว่า ชีวิตสุรุ่ยสุร่ายของข้านั้นมาจากพระองค์ การเสียชีวิตไม่ใช่จุดจบ พระองค์จะทรงให้ข้าเกิดใหม่อีกครั้ง และวนเวียนอยู่ในวัฏจักรนี้เพื่อความเป็นอมตะ.."
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5949_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "ความปรารถนาของผู้หญิงคนนั้นช่างน่าขันจริงๆ ไม่มีอะไรสามารถอยู่รอดได้หลังจากถูกทำลายสิ้น แม้แต่ 「เทพ」 ก็เช่นกัน"
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับไทอีส"
  },
  Voice_5950_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「ไทอีส」"
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "ข้าเป็นเพียงผู้ทรงจิต ไม่ใช่ผู้วิเศษที่ทำได้ทุกอย่าง ย่อมมีผิดพลาดได้ การที่หญิงคนนั้นลากทุกคนลงมาด้วยในตอนนี้ ก็เป็นความผิดพลาดโดยไม่ตั้งใจของข้า... เพราะฉะนั้น ข้าจำเป็นต้องมีเจ้าคอยช่วยเหลือ เพื่อตอบสนองการเรียกหาของข้าได้ทันท่วงที เจ้าได้รับอนุญาตให้วางเตียงในห้องบรรทมของข้า"
  },
  Voice_5951_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5951_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "เจ้าต้องแบกรับภารกิจเผชิญหน้ากับภัยพิบัติใช่ไหม สำหรับคนในวัยของเจ้าแล้ว มันช่างหนักหนา หากตั้งแต่แรกก็รู้ว่าไม่อาจเปลี่ยนแปลงอนาคตได้ เจ้าจะยังทำภารกิจนี้ต่อไปไหม? อย่าเพิ่งตอบตอนนี้ ลองคิดดูขณะที่ข้าหลับอยู่ ข้าอยากรู้คำตอบของเจ้า..."
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5952_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "หลังจากที่เจ้าปลุกข้าขึ้นมามันก็ผ่านไปสักพักแล้ว เจ้าไม่มีอะไรที่ต้องการจะขอจากข้าเลยหรือ? คำบอกใบ้จากเทพเจ้า คำทำนายที่แม่นยำอย่างแน่นอน หรือแม้กระทั่งขุมทรัพย์ของทวีปที่จมอยู่ใต้มหาสมุทร—เจ้าไม่อยากรู้จริงๆ หรือ? \n ฮึ...คนแปลกๆ"
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5953_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "ข้าไม่เคยเรียกร้องให้ใครมากราบไหว้ การกระทำของพวกคนไร้เหตุผลที่คิดว่าตัวเองเก่ง มันทำให้ข้าเหนื่อยล้า... ไปพักได้แล้ว ถึงเวลาพักผ่อนแล้ว"
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5954_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "ในตัวท่าน ข้าไม่เห็นคุณสมบัติใดที่คล้ายคลึงกับผู้ใต้บังคับบัญชาของข้าเลย... บางทีนี่อาจเป็นเรื่องดี แค่คิดถึงหญิงคนนั้น ข้าก็รู้สึกอ่อนล้าแล้ว"
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5955_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "พระเจ้าไม่ลำเอียง"
  },
  Voice_5956_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5957_AwakerVoiceContent = {
    Text = "ฉันรู้ว่าคุณเป็นผู้ชมพิเศษ ไม่สามารถส่งคุณไปยังมิติอื่นได้แบบปุบปับเด็ดขาด ไม่อย่างนั้นจะเกิดปัญหาใหญ่แน่ เอ๊ะ เคยทำแบบนี้กับคนอื่นบ้างไหมนะ? แย่จริง อย่าถามสิ เป็นความลับของฉันนะ!"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "อ๋า คุณสนใจรูปลักษณ์นี้หรือเปล่า? ดูเหมือนว่าการสูญเสียบางอย่างอาจนำมาซึ่งโชคดีก็ได้ นี่คงจะเป็นโชคดีของฉัน เลค ละมั้ง?"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "มิซากะเป็นสถานที่ที่ฉันเหลือความทรงจำไว้มากที่สุด และก็เป็น...บ้านที่อบอุ่นที่สุดของฉัน"
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "ไว้ใจฉันเถอะ."
  },
  Voice_5960_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5961_AwakerVoiceContent = {
    Text = "ไร้เดียงสาจริงๆ！"
  },
  Voice_5961_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5962_AwakerVoiceContent = {
    Text = "บทสวดศักดิ์สิทธิ์แห่งทะเลลึก!"
  },
  Voice_5962_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5963_AwakerVoiceContent = {
    Text = "สิ่งที่ข้าได้รับพระราชทาน——"
  },
  Voice_5963_AwakerVoiceTitle = {
    Text = "ทักษะ·หนึ่ง·คลื่นสงบ"
  },
  Voice_5964_AwakerVoiceContent = {
    Text = "หากคุณยังยอมรับว่าฉันคือ「รามอน่า」อยู่ ก็ขอให้เรียกฉันแบบนั้นต่อไปเถอะ."
  },
  Voice_5964_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5965_AwakerVoiceContent = {
    Text = "อย่างไร,     คุณก็อยากใช้ความโกรธของฉันด้วยหรือ?"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_5965_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "ความจริง... ได้รับการชี้แจงที่นี่"
  },
  Voice_5966_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_5967_AwakerVoiceContent = {
    Text = "อาหารที่ได้มาต้องกินทันที นี่คือกติกาในชีวิตบนถนน"
  },
  Voice_5967_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_5968_AwakerVoiceContent = {
    Text = "รู้สึกเหมือนอิ่มแล้ว."
  },
  Voice_5968_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_5969_AwakerVoiceContent = {
    Text = "อืม...คันจัง บราวน์ ช่วยเกาหลังให้หน่อย."
  },
  Voice_5969_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_5970_AwakerVoiceContent = {
    Text = "ชิ้นส่วนกลไกใหม่ล่าสุดจะช่วยให้ระบบของฉันทำงานได้ดีขึ้น นี่ไม่ถือว่าเป็นความชอบหรือเปล่า? ขอโทษนะ แต่ฉันคิดว่าฉันไม่เข้าใจคำถามของคุณ ความชอบไม่มีความหมายใดๆ สำหรับตุ๊กตาเครื่องจักรกล"
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_5971_AwakerVoiceContent = {
    Text = "รับมือซะ!"
  },
  Voice_5971_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5972_AwakerVoiceContent = {
    Text = "รับมือให้ดี!"
  },
  Voice_5972_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5974_AwakerVoiceContent = {
    Text = "คิดให้รอบคอบ."
  },
  Voice_5974_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_5975_AwakerVoiceContent = {
    Text = "คิดอย่างใจเย็น."
  },
  Voice_5975_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_5976_AwakerVoiceContent = {
    Text = "คุณหนูเวินเค่อและผมเหมือนกัน บ้านเกิดของเราไม่ได้อยู่บนดาวเคราะห์นี้... นอกจากทิงค์เทตแล้ว บ้านเกิดของผมไม่มีสิ่งใดให้ผูกพันเลย ไม่รู้ว่าคุณหนูเวินเค่อจะมีความรู้สึกอย่างไรกับบ้านเกิดของเธอ?"
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเวินเค่อ"
  },
  Voice_5976_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับ「เวินเคอร์」"
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "อย่าเข้ามาข้างหลังฉัน เว้นแต่ว่าคุณอยากให้คอถูกบิด"
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_5977_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "ฮาา—— พวกคุณทำไมถึงปล่อยให้แมวป่าวิ่งเล่นในโรงเรียนแบบนี้?! ถ้าสัตว์ไม่มีมารยาทตัวนั้นไปข่วนคนอื่น จะทำยังไง!"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "สายตาของฉันทำให้คนรู้สึกไม่สบายใจหรือเปล่า? ถูกต้องแล้ว ด้วยความดุดันนี้เอง ฉันจึงสามารถเอาชีวิตรอดจากนรกได้."
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_5979_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "คำพูดสวยหรูไม่ต้องพูดหรอก คุณหวังจะได้อะไรจากฉัน? คุณคงมีเหตุผลบางอย่างแน่ ถึงได้พยายามรักษาสติของฉันไว้"
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_5980_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "เป้าหมายแห่งการแก้แค้นของข้ามีเพียงชาวสปาร์ตันเท่านั้น แต่ตอนนี้ แม้กระทั่งเมืองนี้ก็ไม่มีเหลืออยู่แล้ว... ก็ช่างเถอะ การเป็นคมดาบของท่านก็คงจะไม่เลว ข้าขอรับรองท่านในฐานะหุ้นส่วนของข้า แต่หากท่านกล้าทรยศ ข้าจะควักหัวใจของท่านออกมา"
  },
  Voice_5981_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_5981_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "มือของข้าเต็มไปด้วยเลือด พวกพ้องที่อ่อนแอของข้าไม่ยอมรับการแก้แค้นของข้า พวกเขาพูดลับหลังถึงความโหดร้ายของข้า ความไม่รู้จักพอของข้า ความอกตัญญูของข้า... การแก้แค้นนั้น แท้จริงแล้วเป็นเพื่อตัวข้าเองเท่านั้น ไม่เกี่ยวข้องกับใครทั้งสิ้น"
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_5982_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "ต้องใช้เหล็กมากขึ้นแล้ว"
  },
  Voice_5983_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5984_AwakerVoiceContent = {
    Text = "ต้องใช้เหล็กมากขึ้นแล้ว"
  },
  Voice_5984_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5985_AwakerVoiceContent = {
    Text = "ตายซะ."
  },
  Voice_5985_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_5986_AwakerVoiceContent = {
    Text = "ฉันคือ... เรียกฉันว่าเวินเค่อเถอะ ทุกคนเรียกฉันแบบนั้น ใช่ เรียกฉันแบบนั้นเหมือนคนอื่น"
  },
  Voice_5986_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5987_AwakerVoiceContent = {
    Text = "ข้าคือโล่ของท่านผู้เป็นนาย!"
  },
  Voice_5987_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5988_AwakerVoiceContent = {
    Text = "ข้าคือโล่ของท่านผู้เป็นนาย!"
  },
  Voice_5988_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_5989_AwakerVoiceContent = {
    Text = "«The Nutcracker»เดิมทีเป็นเทพนิยายแฟนตาซีแสนโรแมนติกของเด็กสาว แต่เหล่าคนหน้าตาน่าเกลียดนั้นกลับมองเห็นเพียงร่างอันงดงามที่โบยบินไปมาและความปรารถนาทางสรีระที่หยาบคาย... น่าสะอิดสะเอียน"
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "ต้อง...กำจัดให้ได้...!"
  },
  Voice_5990_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_5991_AwakerVoiceContent = {
    Text = "พันเดีย......เธอเรียกสิ่งนี้ว่าการฝึกฝนหรือ? ฮ่าฮ่า......ขอฉันหัวเราะสักหน่อย มนุษย์ยังคงใจดีและอ่อนโยนเกินไป ทำอะไรก็ดูเหมือนเล่นขายของไปเสียหมด"
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับพันเดีย"
  },
  Voice_5991_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「พันเดีย」"
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "อย่าเข้ามา!"
  },
  Voice_5992_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5993_AwakerVoiceContent = {
    Text = "ต้องแนะนำตัวอีกครั้งเหรอ? จริงๆ เอาเธอยังไงดี ผมชื่อเจนกิน ส่วนเด็กคนนี้คือบราวน์ 「จี๊!」\nจำไว้ให้ดีนะ! ถ้าจำชื่อเราผิดละก็ คอยโดนผมตีด้วยตะเกียงเข้าที่*เสียงถูกตัดออก*เลย 「จี๊จี๊?!」"
  },
  Voice_5993_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_5994_AwakerVoiceContent = {
    Text = "กระโดดๆ!"
  },
  Voice_5994_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_5995_AwakerVoiceContent = {
    Text = "กระโดดๆ!"
  },
  Voice_5995_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_5996_AwakerVoiceContent = {
    Text = "ถวายคำสรรเสริญเพื่อเปิดงาน!"
  },
  Voice_5996_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_5997_AwakerVoiceContent = {Text = "หึ"},
  Voice_5997_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_5998_AwakerVoiceContent = {
    Text = "เพียงแค่ต้องการหินเล็กน้อย สองมีดแกะสลัก และสามพุ่มของดอกไอริสที่ชอบแสงอาทิตย์......ฉันสามารถสร้างทุกอย่างให้คุณได้"
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_5998_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_5999_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_5999_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6000_AwakerVoiceContent = {
    Text = "แค่นี้เหรอ?"
  },
  Voice_6000_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6001_AwakerVoiceContent = {Text = "อืม"},
  Voice_6001_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6002_AwakerVoiceContent = {
    Text = "การต่อสู้ที่ไร้ประโยชน์นี้.."
  },
  Voice_6002_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6003_AwakerVoiceContent = {
    Text = "(ฮึดฮัด)"
  },
  Voice_6003_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6004_AwakerVoiceContent = {
    Text = "หลังจากที่ทิเบรียสเสียชีวิต ประชาชนของโรมในที่สุดก็ได้ทำตามความปรารถนาที่พวกเขาใฝ่ฝันมานาน——โยนเขาลงแม่น้ำไทเบอร์ให้ปลาในแม่น้ำกิน แน่นอนว่าพวกเขาต้องจ่ายราคาที่ต้องจ่ายเล็กน้อยสำหรับเรื่องนี้: พวกเขาถูกคาลิกูลาโยนลงไปในลานแข่งขันเพื่อความบันเทิงของข้าพเจ้า."
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6005_AwakerVoiceContent = {
    Text = "(ฮึดฮัด)"
  },
  Voice_6005_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6006_AwakerVoiceContent = {
    Text = "ฉันสามารถรู้สึกได้ว่า เด็กสาวคนนั้นมีพลังที่คล้ายกับฉัน เธอยังไม่เข้าใจเต็มที่ว่าพลังนี้ทรงพลังแค่ไหน เพื่อเธอแล้ว ฉันจะฝึกฝนเธอให้เหมาะสม"
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับลิลลี่"
  },
  Voice_6006_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「ลิลลี่」"
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "ช่างน่าโมโหจริงๆ พวกเธอ, พวกเธอยังดูถูกฉันอยู่อีกหรือเปล่า?!"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "หลักฐานของการมีอยู่"
  },
  Voice_6008_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6009_AwakerVoiceContent = {
    Text = "หลักฐานของการมีอยู่"
  },
  Voice_6009_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6010_AwakerVoiceContent = {
    Text = "ฉันเชื่อว่าทุกอย่างย่อมมีเหตุผลของมัน แต่... การกระทำที่ไร้ความหมายเหล่านั้น ความลำเอียงที่ทำให้พี่น้องต้องแตกคอกันและเกลียดชังกัน ทำให้ฉันรู้สึกเศร้าจนยากจะปิดบัง ถ้าจะมีอะไรที่ทำให้ฉันรู้สึกขยะแขยง ก็คงจะเป็นเรื่องนี้แหละ"
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "จริงๆ แล้วไม่อยากใช้พละกำลังนี้เลย"
  },
  Voice_6011_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6012_AwakerVoiceContent = {
    Text = "อย่าประมาท!"
  },
  Voice_6012_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6013_AwakerVoiceContent = {Text = "หึ"},
  Voice_6013_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_6014_AwakerVoiceContent = {
    Text = "หยุดเถอะ!"
  },
  Voice_6014_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6015_AwakerVoiceContent = {
    Text = "หยุดเถอะ!"
  },
  Voice_6015_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6016_AwakerVoiceContent = {
    Text = "คาเซียเก่งจริงๆ! เธอสามารถ——เสกกระต่ายน้อยออกมาได้ในพริบตา!"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับคาเซีย"
  },
  Voice_6016_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับตัวปลุก「คาเซีย」"
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "มายากล พร้อมแล้ว!"
  },
  Voice_6017_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6018_AwakerVoiceContent = {
    Text = "การหลอมกร่อน... ต้องยอมรับว่าในโลกนี้ยังมีสิ่งที่อำนาจไม่สามารถควบคุมได้จริงๆ"
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6019_AwakerVoiceContent = {
    Text = "อ่า——"
  },
  Voice_6019_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "เต้นรำในเปลวไฟสีเขียวเถอะ"
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "ไม่ต้องเสียใจ แผลเป็นคือตราแห่งความกล้าหาญของนักรบ"
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "จงหวาดผวาต่อพลังของมัน...... มันพร้อมจะตัดศีรษะคุณทุกเมื่อ"
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "เวลาทานอาหาร? หรือเวลาทำกิจกรรม?"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6024_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "อื้ม! ถ้าอย่างนี้ เพื่อนๆ ของออรีตาจะไม่หายไป!"
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6025_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "คุณครูซิลเวียบอกว่า ตอนได้รับอะไรต้องขอบคุณ... ขอบคุณ ขอบคุณ ขอบคุณ ขอบคุณ!"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6026_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "คราวนี้ออรีตาเป็นผี! ให้เวลาเธอซ่อนแค่ 5 วินาทีนะ! 5, 4——"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6027_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "ทุกคนเริ่มเล่นซ่อนหาแล้วก็หายไปหมด ในครั้งนี้ออรีตาจะต้องหาทุกคนให้เจอ!"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6028_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = "เนื่องจากพบกระดูกของยูที่ก้นทะเล จึงคิดว่ายูชอบน้ำ และยังอยากสร้างบ่อน้ำพุไว้หน้าตำหนักที่ยูพักอีกด้วย? \n ฮะ...ตามใจพวกเจ้าเถอะ แต่อย่าเอาเรื่องจุกจิกแบบนี้มารบกวนยูเลย"
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "หยดเล็กๆ ในทะเล ผู้ศรัทธาที่ตื้นเขินและไม่สูญสลาย มิลียาห์ม...ข้าขอคารวะท่าน"
  },
  Voice_6030_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6031_AwakerVoiceContent = {
    Text = "ถึงตาฉันลงมือแล้ว."
  },
  Voice_6031_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6032_AwakerVoiceContent = {Text = "โฮ่!"},
  Voice_6032_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6033_AwakerVoiceContent = {
    Text = "น่าทึ่งจริงๆ......แค่คำพูดธรรมดาของคุณก็ช่วยแก้ปัญหาการสร้างสรรค์ที่ผมกังวลมาหลายเดือนได้"
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6033_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "เมื่อเปรียบเทียบกับคุณหนูขุนนางในงานเลี้ยง นิสัยของมอร์ฟี่ถือว่าน่ารักมาก."
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับมอร์ฟี่"
  },
  Voice_6034_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「มอร์ฟี่」ร่างกายที่ตื่นขึ้น"
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "ผู้เชี่ยวชาญด้านการบำบัดจิตใจ? เด็กๆ พวกนั้นยกยอเกินไปแล้ว ฉันแค่ทำหน้าที่รับฟังอย่างเต็มความสามารถ เพื่อบรรเทาความทุกข์ในใจของพวกเขาเท่านั้น——เหมือนอย่างที่ฉันเคยทำมาตลอด"
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "อย่าดูถูกฉันอีกเลย!"
  },
  Voice_6036_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6037_AwakerVoiceContent = {
    Text = "อย่าดูถูกฉันอีกเลย!"
  },
  Voice_6037_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6038_AwakerVoiceContent = {
    Text = "รู้สึกหิวน้ำไหม? น้ำดื่มสะอาดในคุกเป็นของหายากมาก"
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6038_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "เด็กดีน่ารัก~ อย่าทิ้งกลางทางนะ~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6039_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "คุณต้องตกอยู่ในกับดักความหวานของฉันแล้วใช่ไหม?"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6040_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "พยายามอีกนิดเดียว thôi~ เดี๋ยวเราก็จะถึงจุดสูงสุดที่แสนวิเศษแล้ว~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6041_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "เมื่อฉันอายุสิบสี่ ฉันเข้าเรียนที่โรงเรียน หากตอนนั้นสามารถสำเร็จการศึกษาได้ตามปกติ คุณควรจะเรียกฉันว่า “ผู้อำนวยการโรงเรียน” ในตอนนี้"
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "สมองที่อ่อนแอของนายดูเหมือนจะไม่มีทางจำอะไรได้เลย ฮ่าๆ"
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = "เธอถามว่าความปรารถนาของฉันคืออะไรใช่ไหม? การคุ้มครองการเดินทางและปลอดภัยเมื่อเข้าออก ไม่นับหรือเปล่า? \n ส่วนเรื่องอื่นๆ ฉันยังไม่เคยคิด... แต่ฉันจะลองพิจารณาดูให้ดีแล้วบอกเธออีกที"
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6044_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "“สิ่งที่ฉันปรารถนาคือความลับของฟ้าดิน ฉันต้องการรู้ว่าพละกำลังอะไรกันแน่ที่กำลังควบคุมฉัน” แม้ว่าฉันจะไม่ค่อยพอใจกับเนื้อเรื่องของนิยายเรื่องนี้นัก และวิทยาศาสตร์ในหนังสือก็ดูไร้เดียงสาจนแทบรับไม่ได้ แต่หลังจากอ่านจบแล้ว คุณควรจะเข้าใจฉัน... เดี๋ยวนะ คุณยังไม่ได้อ่านหนังสือเล่มนี้หรือ?"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6045_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "ภารกิจและโชคชะตาเป็นสิ่งที่คล้ายคลึงกัน ไม่สามารถปล่อยวางได้ง่ายๆ และก็ไม่มีความจำเป็นต้องทำเช่นนั้น"
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6046_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "ฉันดูเหมือนจะยุ่งตลอดเวลา? ใช่แล้ว ผู้ช่วยสามารถช่วยแบ่งเบาภาระงานบางส่วนได้เป็นครั้งคราว แต่ในบางการวิจัยนั้น ฉันไม่สามารถถูกแทนที่ได้ คุณอยากช่วยเหลือบ้างเหรอ? งั้นก็มาเช็คดูเป็นครั้งคราวสิ ว่าฉันยังมีชีวิตอยู่ไหม"
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6047_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "คุณคิดว่าฉันกำลังโกรธหรือ? คุณรู้ไหมว่าการยิ้มต้องใช้กล้ามเนื้ออย่างน้อยกี่มัด? ฉันเคยสอนเรื่องนี้ในชั้นเรียน แต่ดูเหมือนจะลื่นไหลผ่านหัวที่โล่งเตียนของคุณไปแล้ว คำตอบคืออย่างน้อยสิบเจ็ดมัด และไม่มีเหตุผลอะไรที่ฉันจะต้องโกรธคุณ"
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6048_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "คุณหนูรามอน่าบอกว่า ฉันไม่จำเป็นต้องเอาใจทุกคน คุณเข้าใจความหมายของคำนี้ไหม?... หมายความว่าไม่ต้องการให้ฉันปกป้องอีกแล้วหรือเปล่า?"
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6049_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "มีรายงานสิบสามฉบับที่รอการอนุมัติ หกเครื่องสื่อสารที่เสียหายรอการซ่อมแซม และในขณะเดียวกันฉันยังต้องสังเกตผลลัพธ์ของห้าการทดลองสกัดเงินใจที่แตกต่างกัน... ดังนั้น แทนที่จะใช้เวลาที่จำกัดมาขัดจังหวะฉัน คุณควรหาวิธีฝึกฝนส่วนที่ใช้คิดในสมองของคุณ"
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6050_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "หวังว่าครั้งหน้า บ้านเกิดที่รักจะตอบสนองต่อเสียงเรียกของฉัน"
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "การล็อกถูกยกเลิก."
  },
  Voice_6052_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6054_AwakerVoiceContent = {
    Text = "ฉันดีใจมาก... คุณเข้าข้างและเอ็นดูฉันจริงๆ"
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6054_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "คนอื่นอาจจะไม่พอใจเพราะความลำเอียงของคุณได้นะ"
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6055_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "หรือคุณก็ปรารถนาผมอยู่ใช่ไหม?"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6056_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "ในที่สุดก็จบลงแล้ว ไม่ต้องเห็นสิ่งพวกนั้นที่เป็นสีดำๆ เหนียวๆ แบบนั้นอีกแล้ว.."
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "ท่านได้เสียสละให้ข้ามากมายเช่นนี้ ความรักของท่านได้หลอมรวมเป็นหนึ่งเดียวกับข้าอย่างลึกซึ้งแล้ว.."
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6058_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6059_AwakerVoiceContent = {Text = "เฮ้!"},
  Voice_6059_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_6060_AwakerVoiceContent = {
    Text = "อันตรายจริงๆ."
  },
  Voice_6060_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6061_AwakerVoiceContent = {
    Text = "ทำมาตั้งเยอะ คุณก็ควรจะได้สนุกกับผลลัพธ์บ้างแล้วนะ? เข้ามาใกล้ๆ สิ ฉันจะไม่ทำให้คุณผิดหวังหรอก~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6061_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "ข้า, ข้าเข้าใจแล้ว ความตั้งใจของท่าน... แม้ว่าจะยังไม่คล่องแคล่วนัก แต่ไอจิสจะทุ่มเทสุดกำลังเพื่อการต่อสู้เพื่อท่าน!"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6062_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "สายตาของท่านทำให้ข้ารู้สึกเจ็บปวด... ไอจิส มีเรื่องอะไรกับท่านรึเปล่า?"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6063_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "ไอจิสรู้สึกหวาดกลัวอย่างมาก... ไม่แน่ใจว่าจะทำให้คุณผิดหวังหรือเปล่า.."
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6064_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "คุณ, คุณจ้องมองฉันแบบนี้ ไอจิสไม่ชิน... คุณไม่กลัวคำสาปหรือ?"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6065_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "กรุณา อย่าจ้องตาของฉันเลย... ไอจิสกลัวว่าจะทำให้คุณได้รับความเสียหาย... หลังจากทั้งหมด ฉันเป็นเพียงสิ่งมีชีวิตประหลาด.."
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6066_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "การดมกลิ่นของสัตว์ป่าน่ะเหรอ แค่โชคดีเท่านั้นแหละ อย่าเข้าใจผิดนะจ้ะ?"
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6067_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "ฉันยังไม่สามารถหยุดได้.."
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "พละกำลัง อย่างไม่หยุดยั้ง!"
  },
  Voice_6069_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_6070_AwakerVoiceContent = {
    Text = "พละกำลังไม่สิ้นสุด"
  },
  Voice_6070_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6071_AwakerVoiceContent = {
    Text = "คุณชอบทะเลไหม? ไม่ว่าอย่างไรก็ตาม ฉันหลงใหลในทะเลมาก ฉันยังจำได้ดี ในวันนั้นเมื่อหลายปีก่อน ทะเลได้โอบอุ้มชีวิตที่โชคร้ายของฉันไว้อย่างแผ่วเบา และมอบความสงบสุขที่ฉันเฝ้ารอมาเนิ่นนาน"
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "ไม่รู้ทำไมถึงเกิดความรู้สึกพึงพอใจที่ไม่เคยมีมาก่อน.."
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "กระแสนี้จะทำลายล้างศัตรูอย่างหมดจด"
  },
  Voice_6074_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6075_AwakerVoiceContent = {
    Text = "กระแสนี้จะทำลายล้างศัตรูอย่างหมดจด"
  },
  Voice_6075_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_6076_AwakerVoiceContent = {
    Text = "ฉันรอคอยใครสักคนมาตลอด คนที่สามารถสอนให้ฉันรู้จักกับความรัก ความเจ็บปวด และความปรารถนาที่แท้จริง คุณสามารถเติมเต็มฉันได้ไหม? ช่วยพาฉันออกจากคุกมืดและช่วยไถ่บาปฉันได้ไหม?"
  },
  Voice_6076_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6076_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "คุณอยากรู้ความจริงหรือเปล่า? ฉันเกลียดคุก เกลียดความมืด จนแทบจะตายได้ ฉันอยากให้ใครสักคนมองมาที่ฉัน อยากให้ตัวเองลุกโชน.."
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6077_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "ทุกอย่างล้วนเพื่ออนาคตอันเป็นนิรันดร์แห่งความสุขและความสงบสุข"
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "อยากลองลิ้มรสฉันไหม? ถ้าอย่างนั้นก็มาเป็นทาสของฉันซะ ฉันจะทำให้คุณร้อนแรงจนทนไม่ไหวเลยล่ะ~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6079_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "ถือเป็นการถวายของข้าพเจ้าแล้ว"
  },
  Voice_6080_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6081_AwakerVoiceContent = {
    Text = "เบื่อแล้ว ถ้าเทียบกับพวกนักโทษร่างใหญ่ที่หวาดกลัว นี่มันเหมือนเล่นสนุกๆ เลย ยังไงเธอก็มาอยู่เป็นเพื่อนฉันนะ~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6081_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "อยากได้คนรับใช้มากกว่านี้ อยากรู้ว่าพวกเขาจะครางและอ้อนวอนยังไง——\nช่วยไปหาคนรับใช้มาเพิ่มให้หน่อยน้า~ นะๆ~"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6082_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "ขอโทษที่ฉันจมอยู่ในอดีตอีกแล้ว โปรดอย่าทำสีหน้าเศร้าเลย เล่าเรื่องราวของคุณให้ฉันฟังบ้างสิ คุณเคยมีแรงบันดาลใจอยากเขียนบทกวีไหม? การผจญภัยของคุณ, สิ่งที่คุณได้เห็น, ความยินดีและความเศร้าโศกของคุณ, มันจะกลายเป็นลำธารที่ไหลจากจิตใจสู่ปลายนิ้วหรือเปล่า?"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6083_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "ข้าพเจ้าเป็นเพียงรอยน้ำที่จะจางหายไปบนม้วนกระดาษหนังแกะ แต่เพราะวาสนาที่ได้พบกับท่าน ข้าพเจ้าจึงได้หยุดอยู่ในขณะนี้ นี่อาจจะเป็นปาฏิหาริย์อย่างหนึ่งกระมัง ข้าพเจ้าจะหวงแหนปาฏิหาริย์นี้ และสร้างบทกวีที่ตราตรึงใจให้กับท่าน"
  },
  Voice_6084_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6084_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "มีคนเคยบอกฉันว่า บทกวีถูกสร้างขึ้นมาเพื่อให้คนได้ชื่นชม... คุณจะแบ่งปันความคิดของคุณกับฉันหน่อยได้ไหม?"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6085_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "คุณเคยมีประสบการณ์แบบนี้หรือไม่? ที่เผชิญกับความผิดของผู้อื่นด้วยใจที่เต็มไปด้วยเมตตาและอภัย แต่สุดท้ายกลับไม่ได้รับผลลัพธ์ตามที่คาดหวัง การมอบดอกกุหลาบให้ผู้อื่น แต่ในมือกลับไม่มีกลิ่นหอมเหลืออยู่ มีเพียงบาดแผลจากหนามแหลมที่ทิ่มแทงจนเลือดออก"
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6086_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6087_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6088_AwakerVoiceContent = {
    Text = "หมึกของฉัน.."
  },
  Voice_6088_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6089_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_6089_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6090_AwakerVoiceContent = {
    Text = "ผิดไปแล้ว..."
  },
  Voice_6090_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6091_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_6091_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6092_AwakerVoiceContent = {
    Text = "นี่คือการคุ้มครองจากสิ่งที่ยิ่งใหญ่!"
  },
  Voice_6092_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6093_AwakerVoiceContent = {
    Text = "การคุ้มครองจากสิ่งศักดิ์สิทธิ์ที่ยิ่งใหญ่และซีดเผือด"
  },
  Voice_6093_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_6094_AwakerVoiceContent = {
    Text = "ฉันไม่มีเวลาพัก ปรากฏการณ์หลอมละลายได้ทำลายร่างกายของฉันไปสองครั้งแล้ว ก่อนที่จะถูกตัวจบสุดท้ายไล่ทัน ยังมีหลายสิ่งที่ฉันต้องการค้นให้กระจ่าง... มาช่วยฉันหน่อย เริ่มจากการเตรียมวัสดุทดลอง ฉันเชื่อว่าคุณคงไม่โง่จนคำนวณสมดุลผิดใช่ไหม?"
  },
  Voice_6094_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6094_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "ฉันชอบหน้าต่างกระจกสีของฟงตันบลอง มันทำให้สีหน้าของผู้คนเปลี่ยนไปเป็นสีต่างๆ: สีม่วงของความสิ้นหวัง, สีน้ำเงินของความประจบประแจง และแน่นอน ยังมีสีแดงแห่งความทะเยอทะยานที่ฉันชอบที่สุด.."
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "ที่นี่ ข้ามักสัมผัสได้ถึงลมหายใจขององค์เจ้านายอยู่เสมอ แต่บางทีข้าอาจยังไม่พร้อมที่จะเผชิญหน้ากับพระองค์... ไม่ว่าจะอย่างไร ขอขอบคุณที่มอบที่พักพิงให้แก่ข้า"
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "การทรยศจะทำให้คนกลายเป็นสัตว์ประหลาด ไม่ว่าจะสำหรับฝ่ายใดก็ตาม ดังนั้นฉันจึงเกลียดคนทรยศ."
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "แฮมลิน ยินดีรับใช้คุณ."
  },
  Voice_60985_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_60986_AwakerVoiceContent = {
    Text = "ฉันเคยเห็นคนที่มีความเข้าใจในดนตรีอย่างลึกซึ้งเหมือนเป็นสัญชาตญาณ คอนแชร์โตและซิมโฟนีที่แต่งโดยคนคนนั้นยากจะลืมเลือน\nนั่นคืออัจฉริยะตัวจริง."
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับคนรู้จักในอดีต"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "ฉันไม่ชอบเสียเวลาไปกับการวางแผนกลอุบาย เมื่อเปรียบเทียบกับดนตรี คุณค่าทางศิลปะของการวางแผนน้อยมาก แต่สำหรับกำจัดอุปสรรคบนเส้นทาง มันเป็นเครื่องมือที่จำเป็น เพื่อไปให้ถึงจุดสูงสุดของดนตรี ฉันไม่รังเกียจที่จะใช้มัน"
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับกลยุทธ์"
  },
  Voice_60988_AwakerVoiceContent = {
    Text = "ไม่มีมารยาท"
  },
  Voice_60988_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_60989_AwakerVoiceContent = {
    Text = "มันมาอีกแล้ว ทำนองนี้คืออะไรกันแน่? ตั้งแต่ครั้งที่ได้ยินครั้งล่าสุด มันก็วนเวียนอยู่ในหัวของฉัน ไม่ยอมหายไป ไม่ยอมหยุด."
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_60989_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6098_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_6098_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_60990_AwakerVoiceContent = {
    Text = "ในแง่ของเทคนิค การวางแผนกลยุทธ์และการควบคุมดนตรีไม่มีความแตกต่างกัน ความเป็นมนุษย์ ความรู้สึก ความปรารถนา... สิ่งเหล่านี้ชัดเจนและเชื่อฟังเหมือนโน้ตบนบรรทัดห้า วางเรียงอยู่ตรงหน้าฉัน พร้อมเต้นตามจังหวะไม้ควบคุม เมื่อเข้าใจดนตรี ก็จะเข้าใจทุกสิ่ง"
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับความเหมือน"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "อีกนิดเดียว แค่นิดเดียว ฉันต้องทำให้เสร็จ ฉันต้องได้ยินมัน！"
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_60991_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_60992_AwakerVoiceContent = {Text = "อืม"},
  Voice_60992_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_60993_AwakerVoiceContent = {
    Text = "ไม่มีมารยาท"
  },
  Voice_60993_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_60994_AwakerVoiceContent = {Text = "อืม"},
  Voice_60994_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_60995_AwakerVoiceContent = {
    Text = "ดนตรีอยู่เหนือภาษา เหนือตัวอักษร และเหนือทุกสิ่ง หากนี่ไม่ใช่ความสมบูรณ์แบบ ฉันไม่รู้ว่าอะไรจะเป็น"
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_60995_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "ใส่ใจจังหวะ"
  },
  Voice_60996_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_60997_AwakerVoiceContent = {
    Text = "จูนเสร็จเรียบร้อยแล้ว"
  },
  Voice_60997_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_60998_AwakerVoiceContent = {
    Text = "ดีใจที่คุณก็เข้าใจถึงความสำคัญของการฝึกฝน."
  },
  Voice_60998_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_60999_AwakerVoiceContent = {
    Text = "ฉันจะมอบการแสดงที่สมบูรณ์แบบ"
  },
  Voice_60999_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6099_AwakerVoiceContent = {
    Text = "อิจฉาไหม? เกล็ดที่แข็งแรงนี้เป็นหลักฐานของสายเลือดสูงศักดิ์"
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = "ข้าก็เคยได้รับคำชื่นชมจากผู้คน แต่...นั่นไม่ใช่พรสวรรค์ที่แท้จริง\nผลงานของข้า เป็นเพียงการลอกเลียนแบบจากสิ่งที่คนรุ่นก่อนได้สร้างไว้เท่านั้น"
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับผลงาน"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "เครื่องลม, เครื่องสาย... สลับกันขึ้นแล้วสลับกันอีก ธีมหลักกลับมา... ฉันจำได้แล้ว นี่คือเพลงเรควิเอ็มที่ฉันแต่ง มันเพื่ออัจฉริยะที่จากไปเร็วเกินไป เพื่อดาวที่ดับแสง"
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_61001_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "ฮืม? เธอมีบทเพลงใหม่จะแสดงให้ฉันดูหรือเปล่า?"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "ด้วยบทเพลงนี้ ข้าขอไว้อาลัยให้กับวิญญาณที่จากไป."
  },
  Voice_61003_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_61004_AwakerVoiceContent = {
    Text = "นักเต้นหญิงชุดเขียวมีท่าทางอันสง่างามพอที่จะเป็นหัวหน้าคณะนักเต้นในราชสำนักได้\nถ้าเป็นไปได้, ฉันอยากจะร่วมงานกับเธอจริงๆ"
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับลิซ"
  },
  Voice_61004_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างกายที่ปลุก「ลิซ」"
  },
  Voice_61005_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_61006_AwakerVoiceContent = {
    Text = "ในวงดนตรีมีคอนเสิร์ตมีสเตอร์ แต่คอนเสิร์ตมีสเตอร์เพียงคนเดียวไม่สามารถสร้างวงที่สมบูรณ์ได้ วงของฉันไม่ต้องการคนที่คิดแค่แสดงตัวเอง"
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "ฉันเหมือนได้ยินทำนองเพลง แถวนี้มีใครกำลังซ้อมอยู่หรือเปล่า?"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_61007_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_61008_AwakerVoiceContent = {
    Text = "ดาล เซกโน"
  },
  Voice_61008_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_61009_AwakerVoiceContent = {
    Text = "ดา คาโป"
  },
  Voice_61009_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6100_AwakerVoiceContent = {
    Text = "ตายซะ!"
  },
  Voice_6100_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_61010_AwakerVoiceContent = {
    Text = "ใช่แล้ว! ใช่แล้ว! นี่คือสุดท้าย นี่คือพิธีมิสซาครั้งสุดท้าย เพลงรำลึกถึงวิญญาณที่ถวายให้กับดนตรีเอง!"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_61010_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "อ่า ผู้พิทักษ์ เธอมาได้ถูกเวลาจริงๆ เล่าให้ฉันฟังหน่อย การจัดการของเธอกับบทเพลงนี้เป็นอย่างไร?"
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "เครื่องสาย，เริ่มเล่น"
  },
  Voice_61012_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_61013_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_61014_AwakerVoiceContent = {
    Text = "มันชัดเจนขึ้นแล้ว ทำนองที่คดเคี้ยวและวกวน ราวกับเสียงโศกเศร้าของวิญญาณ... ฉันแน่ใจว่าเคยได้ยินมันที่ไหนสักแห่ง"
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_61014_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "เหตุผลและระเบียบ ฉันสร้างขั้นบันไดด้วยสิ่งเหล่านี้ ก้าวเดินขึ้นไป และในที่สุด เปิดประตูวิหาร แต่เมื่อพ้นจากประตูนั้นไปแล้ว เหตุผลและระเบียบจะไม่มีอีกต่อไป——ดนตรีที่แท้จริงและเป็นนิรันดร์ จะอยู่เหนือเหตุผล"
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับเหตุผลและระเบียบ"
  },
  Voice_61016_AwakerVoiceContent = {
    Text = "ดูมือของฉัน หนึ่ง,     สอง,     สาม"
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "ฉันได้ฟังการแสดงของวงดนตรีที่พวกคุณเรียกว่า \"วงดนตรี\" ซึ่งเต็มไปด้วยข้อผิดพลาดมากมาย แต่ไม่เป็นไร ฉันได้วางแผนอย่างละเอียดแล้ว และแน่นอนว่าจะสามารถจัดแสดงรายการที่สมบูรณ์แบบได้ก่อนเทศกาลบั้งไฟเงิน"
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "ฉันยังไม่สามารถลืมวันแรกที่ได้ยินบทเพลงจากส่วนลึกของจิตใจได้ ในระหว่างโน้ตและคอร์ดเหล่านั้น ทุกอย่างในโลกจริงหายไป มีเพียงดนตรี ดนตรีที่บริสุทธิ์และศักดิ์สิทธิ์"
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "น่าเสียดาย ดูเหมือนว่าจะต้องซ้อมให้มากขึ้น"
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6101_AwakerVoiceContent = {
    Text = "นี่คือคำสั่ง."
  },
  Voice_6101_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_61020_AwakerVoiceContent = {
    Text = "ปกติฉันไม่ค่อยจะชวนแบบนี้ แต่... คุณอยากลองไหม? จับไม้คทาแล้วมอบชีวิตใหม่ให้กับบทเพลง?"
  },
  Voice_61020_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_61020_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "ฉันชอบแสดงออกผ่านดนตรีมากกว่าคำพูด แต่การสื่อสารกับคุณเหมือนการควบคุมวงออร์เคสตราที่ซ้อมมาแล้วนับครั้งไม่ถ้วน ลื่นไหล และมักจะสร้างความประหลาดใจเสมอ \n ไม่ว่าจะเป็นตัวดนตรีเองหรือสำหรับฉัน คุณคือคนพิเศษ"
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_61021_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = "ในดนตรีซิมโฟนี การประสานงานของเครื่องดนตรีมีความสำคัญมาก วิธีที่แต่ละเสียงเข้าและออก จะสร้างประสบการณ์ที่แตกต่างให้กับบทเพลง\nถ้าการเป็นผู้ควบคุมการปลุกร่างกายที่ตื่นขึ้นเหมือนการแสดง คุณทำได้ยอดเยี่ยมเลย"
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_61022_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "คุณก็ชอบเพลงนี้เหมือนกันหรือเปล่า? ใช้เพียงสี่ห้วงทำนองก็สามารถนำเสนอแรงบันดาลใจได้อย่างครบถ้วน ดนตรีเครื่องลมช่วยผลักดันให้ทำนองไต่ระดับขึ้นไปจนถึงธีม การออกแบบแบบนี้ส่งอิทธิพลต่อคนรุ่นหลังนับไม่ถ้วน...ขอโทษนะ ผมพูดมากเกินไปหรือเปล่า?"
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_61023_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_61024_AwakerVoiceContent = {
    Text = "การบรรเลงที่สมบูรณ์แบบ"
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_61025_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_61026_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_61027_AwakerVoiceContent = {
    Text = "ในใจของพวกเราทุกคนต่างก็ซ่อนทำนองเพลงที่เป็นของตัวเองไว้ ซึ่งมันถูกขังอยู่ในสติและร่างกาย จะเผยความงามออกมาได้ก็ต่อเมื่อจิตใจหลุดพ้นจากความยับยั้งชั่งใจ"
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "มีเพียงดนตรีเท่านั้นที่คู่ควรกับการสรรเสริญ"
  },
  Voice_61028_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_61029_AwakerVoiceContent = {
    Text = "มีเพียงดนตรีเท่านั้นที่คู่ควรกับการสรรเสริญ"
  },
  Voice_61029_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_6102_AwakerVoiceContent = {
    Text = "ไปเถอะ."
  },
  Voice_6102_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_61030_AwakerVoiceContent = {
    Text = "ฟังเถอะ นี่คือเรควีมครั้งสุดท้าย!"
  },
  Voice_61030_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_6103_AwakerVoiceContent = {
    Text = "ขอชีวิตด้วย!"
  },
  Voice_6103_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_61049_AwakerVoiceContent = {
    Text = "ฟังเถอะ นี่คือเรควีมครั้งสุดท้าย!"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_6104_AwakerVoiceContent = {
    Text = "(ฮึดฮัด)"
  },
  Voice_6104_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6105_AwakerVoiceContent = {
    Text = "ท่านก็ปรารถนาจะจบชีวิตลงในเปลวเพลิงสีเขียวหรือไม่?"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6107_AwakerVoiceContent = {
    Text = "กล้าใจลอย?"
  },
  Voice_6107_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6108_AwakerVoiceContent = {
    Text = "ตั้งใจหน่อย!"
  },
  Voice_6108_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_6109_AwakerVoiceContent = {
    Text = "ในมหาวิทยาลัยยังมีเด็กน่ารักแบบนี้อยู่ด้วยเหรอ~ ฉันเพิ่งพูดกับเขาว่า “อยากให้มาช่วยงานฉันไหม” แล้วเขาก็หน้าแดง แถมยังพูดติดๆ ขัดๆ ว่าอะไรประมาณว่า “ผมเป็นอัศวินของผู้พิทักษ์แล้ว”...\n ทั้งที่มันไม่เกี่ยวกันเลยนี่นา~"
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับโอกีล"
  },
  Voice_6109_UnlockDesc = {
    Text = "เมื่อได้รับร่างกายที่ตื่นขึ้น「โอกีล」จะปลดล็อก"
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "อย่าคิดจะเข้าใกล้พระธิดา"
  },
  Voice_6110_AwakerVoiceTitle = {
    Text = "ทักษะ·หนึ่ง·คลื่นกระหน่ำ"
  },
  Voice_6111_AwakerVoiceContent = {
    Text = "ยอมรับชะตากรรมนะ"
  },
  Voice_6111_AwakerVoiceTitle = {
    Text = "ทักษะ·หนึ่ง·คลื่นซัด"
  },
  Voice_6112_AwakerVoiceContent = {
    Text = "ประตูของบ้านเกิดกำลังจากฉันไปไกล... ไม่... อย่าอีกครั้งเลย.."
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "อย่าขวางทาง!"
  },
  Voice_6113_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6114_AwakerVoiceContent = {
    Text = "อย่าขวางทาง!"
  },
  Voice_6114_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_6115_AwakerVoiceContent = {
    Text = "พวกคุณจะต้องชดใช้สำหรับสิ่งที่ทำ"
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6116_AwakerVoiceContent = {
    Text = "อยากตายไหม?"
  },
  Voice_6116_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "ฉันรู้สึกว่าฉันเป็นโรคการหลอมกร่อนอีกแล้ว... ใจของฉันถูกการหลอมกร่อน! เพียงแค่กินยาแอสไพรินสองสามเม็ด พร้อมกับแส้และอาการเจ็บเล็กน้อย ก็น่าจะหายได้..."
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "แม้แต่เธอก็ยังไม่มีวิธีรักษาโรคร้ายนี้เหรอ? แล้วเธอยังไล่ตามการหลอมกร่อนต่อไป ช่างบ้าจริงๆ"
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "ฉันคือนักรบโรมันคนสุดท้าย——ยูวฮะชิ！"
  },
  Voice_6119_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6120_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_6120_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6121_AwakerVoiceContent = {
    Text = "ฉันคือนักรบโรมันคนสุดท้าย——ยูวฮะชิ！"
  },
  Voice_6121_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_6122_AwakerVoiceContent = {
    Text = "การหลอมกร่อน...? ฉันรู้อยู่แล้ว ไม่ใช่แค่หมายถึงการยกเลิกความสัมพันธ์ระหว่างนายและผู้ติดตามหรอกหรือ นี่มันไม่ได้ยากเลย"
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "ข้าได้รับการเรียกตัวแล้ว ขอบเขตระหว่างเทพเจ้าและคนโง่ได้เลือนลางไป."
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6123_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "อืม......น้ำหนักกำลังดี นวดได้สบายๆ~"
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "การตกแต่งที่นี่ดูโบราณไปไหม? บรรยากาศมืดมน ดูเหมือนจะมีผีสิงนะ"
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "ที่นี่เต็มไปด้วยพืชพรรณเขียวชอุ่ม บรรยากาศสบายๆ และยังสามารถรักษาอาการป่วยของพี่สาวได้ สำหรับเราสองคนแล้ว ที่นี่คือบ้านหลังใหม่ที่งดงามและสมบูรณ์แบบที่สุด"
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "ไม่คิดเลยว่าจะได้เจอกันอีกที่นี่... ไม่รู้ว่าหลังจากนั้นพี่สาวใช้ชีวิตอย่างไร ไม่ว่าจะถามเท่าไหร่ เธอก็แค่บอกว่าไม่มีอะไรน่าเป็นห่วง... ขอบคุณมากค่ะที่เข้าใจ และขอขอบคุณด้วยที่ทำให้เราสองพี่น้องได้พบกันอีกครั้ง"
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับฟีนต์"
  },
  Voice_6127_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ปลุก「ฟีนต์」"
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "การถวายแด่พระเจ้าของข้าพเจ้า"
  },
  Voice_6128_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6129_AwakerVoiceContent = {
    Text = "การถวายแด่พระเจ้าของข้าพเจ้า"
  },
  Voice_6129_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6130_AwakerVoiceContent = {
    Text = "ใจเย็นๆ ใจเย็นๆ ใจเย็นๆ.."
  },
  Voice_6130_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6131_AwakerVoiceContent = {
    Text = "ในร่างกายของฉันมี「ฉัน」มากมาย ทั้งที่มีความสุข เศร้าโศก และโกรธ... พวกเธอชอบเค้กฟองน้ำ และเกลียดวันฝนตกในลอนดีเนี่ยน พวกเธอใช้ชื่อเดียวกันว่า「24」 และทุกคนต่างก็เคารพและรักคุณ"
  },
  Voice_6131_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6131_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = "เมื่อก่อนฉันทำงานถึงดึกทุกวัน ทั้งทอผ้า ซักผ้า ทำความสะอาด ดูแลเด็ก  thậm chíเป็นคนเก็บขยะ... อะไรก็ทำหมดขอแค่ได้เงิน ในตอนนั้น การมีชีวิตอยู่ก็คือแค่มีชีวิตอยู่เท่านั้นเอง\nตอนนี้เรามีอาหารสดใหม่ เตียงที่อบอุ่น และยังมีคุณผู้ใจดีแบบท่าน...แทบไม่กล้าฝันถึงเลย"
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6132_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "ไม่ว่าอย่างไร เราแบ่งปันสเต็กหนึ่งชิ้น เตียงหนึ่งหลัง และเราจะไม่ทำให้คุณรู้สึกไม่สะดวกอย่างแน่นอน"
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6133_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = "ฮึฮึ ผู้หญิงคนนั้นกลัวฉันจะออกมา กลางคืนก็ไม่กล้าแม้แต่จะหลับ ผ่อนคลายเถอะ เห็นแก่ของขวัญ ฉันยังไม่อยากฆ่าเธอหรอก \n ฉันเป็นใคร? แน่นอนว่าฉันคือ 「24」 ฮ่าฮ่าฮ่าฮ่า!"
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6134_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "ตอนนี้ฉันรู้สึกดีมากเลย อะไรนะ? คุณว่าจิตใจฉันถูกควบคุมแล้วเหรอ? บ้า บ้า...พูดไร้สาระ...อืม.."
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6135_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "ในฐานะข้ารับใช้ เจ้ายังถือว่ารู้จักกาลเทศะ ในช่วงเวลาที่เหลืออยู่ก่อนจะเข้าสู่การหลับใหลครั้งต่อไป ข้าจะยอมลดศักดิ์ศรีและพำนักอยู่ที่นี่ชั่วขณะ"
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "อืม น้ำทะเลคืนนี้อบอุ่นจริงๆ.."
  },
  Voice_6137_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6138_AwakerVoiceContent = {
    Text = "นกขาวที่โฉบไปมาในความฝัน การปรากฏตัวแล้ว."
  },
  Voice_6138_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6139_AwakerVoiceContent = {
    Text = "ตอนนี้ฉันรู้สึกมีตัวตนชัดเจนมากขึ้นแล้ว"
  },
  Voice_6139_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6140_AwakerVoiceContent = {
    Text = "พอใจมากมาก!"
  },
  Voice_6140_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6141_AwakerVoiceContent = {
    Text = "อร่อยจัง!"
  },
  Voice_6141_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6142_AwakerVoiceContent = {
    Text = "ไว้ใจฉันเถอะ!"
  },
  Voice_6142_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6143_AwakerVoiceContent = {
    Text = "ไว้ใจฉันเถอะ!"
  },
  Voice_6143_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6144_AwakerVoiceContent = {
    Text = "ยินดีต้อนรับสู่——งานเลี้ยงของเรา!"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด ความคลั่ง"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "ในตัวเด็กสาวคนนี้มีสายเลือดของหยูไหลเวียนอยู่อย่างไม่ต้องสงสัย... ไม่ หยูยังอายุน้อยเกินกว่าจะมีทายาท แต่พละกำลังของเธอนั้นเป็นจริงเช่นเดียวกับของหยู..."
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับสายเลือดแห่งเทพ"
  },
  Voice_6145_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างกายที่ตื่นขึ้น「ไอจิส」หรือ「มอร์ฟี่」อย่างใดอย่างหนึ่ง"
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "ความกรุณาของท่านเจ้า คาเรนไม่กล้าลืมแม้แต่นาทีเดียว!"
  },
  Voice_6146_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6147_AwakerVoiceContent = {
    Text = "——หวานจริงๆ น่ากินมาก!"
  },
  Voice_6147_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6148_AwakerVoiceContent = {
    Text = "คาเรนกำลังลดน้ำหนักช่วงนี้ ห้ามกินเยอะเกินไปเลย~"
  },
  Voice_6148_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6149_AwakerVoiceContent = {
    Text = "เป็นคู่ต่อสู้ของฉันน่ะเหรอ พวกนี้ยังไม่คู่ควรเลย"
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "การอธิบายศิลปะก็เหมือนการอธิบายหุ้นรถไฟ——โปรดอย่าทำให้ศิลปินที่น่าสงสารลำบากเลย"
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "ไอจิส... ทำอะไรผิดหรือเปล่า?"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "การสวดมนต์ของคุณ ฉันได้ยินแล้ว."
  },
  Voice_6152_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_6153_AwakerVoiceContent = {
    Text = "การสวดมนต์ของคุณ ฉันได้ยินแล้ว."
  },
  Voice_6153_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6154_AwakerVoiceContent = {
    Text = "หึ คนที่ไร้ความเคารพ"
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "อาห์ คนที่เพิ่งเดินผ่านไปเมื่อกี้ใช่ท่านผู้นั้นหรือเปล่า? ไม่ เป็นไรแล้ว ครั้งสุดท้ายที่ฉันทักทายเขา เขาไม่แม้แต่จะจำฉันได้... ทั้งที่ฉันรออยู่ในคุกตลอดเวลา เพื่อให้เขาพาฉันออกไป แต่จนถึงเหตุจลาจลนั้นเขาก็ยังไม่มา.."
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "เรื่องขำๆ·เกี่ยวกับ「N」"
  },
  Voice_6155_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวนดำเนินการ」บทที่ 7 แล้วปลดล็อก"
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "การตอบสนองต่อการปลุกของมนุษย์และสร้างความร่วมมือเป็นพันธมิตร เพื่อทำหน้าที่ที่ยังไม่สำเร็จของข้า —— หากเจ้าสามารถเติบโตถึงระดับที่สามารถสู้กับข้าได้ ก็คงจะยอดเยี่ยมไม่น้อย"
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = "พี่สาว, บราวน์, เด็กขี้ขลาดจากสถานสงเคราะห์ มีพวกเขาเป็นเพื่อนก็พอแล้ว อืม... ก็ได้ เธอก็นับว่าเป็นหนึ่งด้วย บราวน์ แบ่งลูกอมให้ผู้พิทักษ์สักเม็ดสิ \n「จี๊จ๊ะ?!」"
  },
  Voice_6157_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6157_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "สลัมย่านตะวันออกไม่เหมาะสำหรับการดำรงชีวิตของเด็กๆ หัวหน้างานเก่าที่เจ้าเล่ห์จะใช้สารพัดวิธีหักเงินเดือนของเด็กขายหนังสือพิมพ์ และจู้จี้จุกจิกกับความเร็วของเด็กส่งนม... จับผิดทุกอย่าง! โดยสรุป การเอาชีวิตรอดบนท้องถนนต้องพึ่งพาแค่ตัวเองเท่านั้น ไม่มีใครให้พึ่งพา ไม่มีใครให้เชื่อใจ"
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6158_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "นิสัยเสียของฉันน่ะเปลี่ยนไม่ได้ง่ายๆ หรอก เธอคงเข้าใจใช่ไหม? การนอนใต้สะพานและท่อระบายน้ำ หาอาหารจากขยะเพื่อประทังชีวิต มันยากพอแล้วแค่จะอยู่รอด...เธอไม่ควรคาดหวังให้ฉันปรับตัวให้ชินกับการจัดเตียงหลังตื่นนอนได้ทันทีหรอก! อย่างน้อยก็ต้องใช้เวลาอีกครึ่งเดือนกว่าจะปรับตัวได้!"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6159_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = "ความรู้สึกหลงทางในพื้นที่นั้นมันแย่มากเลย ขอบคุณที่ช่วยฉันออกมาจากที่นั่นนะ ถ้าเธอมีอะไรก็พูดมาตรงๆ ได้เลย แต่ไม่แน่ว่าฉันจะช่วยได้แค่ไหน \n ฉันยังเด็กอยู่เลย เธอคงไม่ทำให้เด็กคนหนึ่งต้องลำบากใช่ไหม~"
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6160_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "เฮ้ พวกจากเขตตะวันตก! เจ้าเห็นบราวน์หรือเปล่า? ไอ้คนตะกละนั่นไม่รู้ว่าได้กลิ่นอะไรแล้ววิ่งไปไหนแล้ว"
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6161_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "“ผู้ที่มีพละกำลังไม่ควรใช้แรงของตนรังแกผู้อื่น เพราะพวกท่านเป็นส่วนหนึ่งของสายเลือดเดียวกันกับข้า”——ข้าจดจำคำสั่งสอนของเทพแห่งความเมตตา และจะใช้พละกำลังนี้เพื่อปกป้องคนรอบข้าง"
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6162_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "อยากรู้ไหมว่าฉันเห็นอะไรที่จุดเริ่มต้นของจักรวาล? ฉันสามารถบอกคุณได้ว่า ที่นั่นไม่มีอะไรเลย"
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6163_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6164_AwakerVoiceContent = {
    Text = "สว่างขึ้นอีก"
  },
  Voice_6164_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6165_AwakerVoiceContent = {
    Text = "แสงไฟที่ไม่มีวันดับ.."
  },
  Voice_6165_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6166_AwakerVoiceContent = {
    Text = "การเชื่อมต่อกับมาตุภูมิแข็งแกร่งขึ้นแล้ว"
  },
  Voice_6166_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6167_AwakerVoiceContent = {
    Text = "หากสามารถทำให้มนุษย์หลุดพ้นจากความทุกข์ได้ ฉันก็จะรู้สึกพึงพอใจแล้ว"
  },
  Voice_6167_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6168_AwakerVoiceContent = {
    Text = "มอบคำสั่งเพิ่มเติมให้ข้าพเจ้าเถิด ผู้ส่งสารแห่งความขาวโพลน ขอให้เปลวไฟของท่านนำทางข้าพเจ้า"
  },
  Voice_6168_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6169_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_6169_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6170_AwakerVoiceContent = {
    Text = "การฝึกฝนของมนุษย์ไม่เพียงแต่ที่ร่างกาย แต่ยังอยู่ที่จิตใจด้วย"
  },
  Voice_6170_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6171_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_6171_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6172_AwakerVoiceContent = {
    Text = "โอ้! ปวดมาก!"
  },
  Voice_6172_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6173_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_6173_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6174_AwakerVoiceContent = {
    Text = "อืม! อุณหภูมิของคุณยังสูงไปหน่อยสำหรับซาน แต่... มันทั้งอบอุ่นและร้อนแรง ฉันชอบมัน."
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "อา... ท่านมีอะไรหรือเปล่าคะ? ถ้าได้โปรด เรามาคุยกันด้านหลังเวทีนะคะ."
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "ไม่เคยบาน แต่กลับเฉาไปเสียก่อน ดุจดอกบัวที่ถูกน้ำกลืนกินอย่างเงียบงัน... ในสายน้ำเย็นเฉียบที่ถาโถมเข้ามา แผ่วเบาและไขว่คว้าหาความสงบ ไม่กล้าแสวงหาความสุขของตนเอง... นั่นคือตัวข้าเอง ผู้พิทักษ์"
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6176_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "ครั้งหนึ่งฉันเคยติดอยู่ในความทุกข์ใจเช่นนี้: ความเจ็บปวดนั้นยาวนานกว่าชีวิตเองหรือไม่? หากเป็นเช่นนั้น การหลับใหลอย่างสงบสุขย่อมดีกว่าการตื่นอยู่ในความทรมานใช่ไหม? หลังฟื้นคืนชีพ ฉันยังคงครุ่นคิดเรื่องนี้ จนกระทั่งท่านนำพาที่หลบภัยแห่งนี้มาให้กับฉัน.."
  },
  Voice_6177_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6177_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "ตอนที่อยู่ในสถานพักฟื้น ผมเคยพยายามหาเพื่อน แต่ไม่มีใครอยากเข้าใกล้ผม... คงเป็นเพราะ “พิษ” ที่รุนแรงนี้สินะ? ถ้าคุณจะเข้ามาใกล้ผม ก็ขอให้ระวังตัวด้วย"
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6178_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "เสียงระฆังที่ลอยมากับสายลมยามราตรีทำให้รู้สึกสงบ ท่านต้องการนั่งฟังบนเก้าอี้หินสักครู่ไหม? ผมจะใช้ผ้าคลุมปูที่นั่งให้ท่าน"
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6179_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "คุณเคยได้ยินเกี่ยวกับ “การฝังศพในทะเล” ไหม? ในเมืองเล็กๆ ที่ฉันอาศัยอยู่ก่อนตาย มีประเพณีอย่างหนึ่งที่ชาวบ้านจะนำร่างของผู้ตายไปจมลงในทะเล ดังนั้นทะเลจึงเป็นที่สุดท้ายของทุกคน ส่วนฉัน เป็นคนหนึ่งที่กลับสู่อ้อมกอดของทะเลเร็วเหลือเกิน.."
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6180_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6181_AwakerVoiceContent = {Text = "หึ!"},
  Voice_6181_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6182_AwakerVoiceContent = {Text = "อ้า"},
  Voice_6182_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6183_AwakerVoiceContent = {Text = "ว้า!"},
  Voice_6183_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6184_AwakerVoiceContent = {Text = "อ้า"},
  Voice_6184_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6185_AwakerVoiceContent = {
    Text = "ได้ทำการเก็บบันทึกการต่อสู้แล้วขอบคุณสำหรับความพยายามของคุณผู้พิทักษ์"
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6186_AwakerVoiceContent = {
    Text = "(ครางด้วยความเจ็บปวด)"
  },
  Voice_6186_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6187_AwakerVoiceContent = {
    Text = "(ครางด้วยความเจ็บปวด)"
  },
  Voice_6187_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6188_AwakerVoiceContent = {
    Text = "(ครางด้วยความเจ็บปวด)"
  },
  Voice_6188_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6189_AwakerVoiceContent = {
    Text = "ยังไปต่อได้"
  },
  Voice_6189_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6190_AwakerVoiceContent = {
    Text = "ผู้มาเยือนห้องรับรองจะได้รับการต้อนรับอย่างดีที่สุด... แต่ในฐานะบัตรเชิญเข้าร่วมงาน ผู้มาเยือนได้เตรียมความลับสำคัญที่เหมาะสมกับงานเลี้ยงใหญ่ครั้งนี้หรือไม่?"
  },
  Voice_6190_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6191_AwakerVoiceContent = {
    Text = "ฉันชอบสิ่งใหม่ๆ ที่แปลกใหม่ ในช่วงการเดินทางยาวนานนับพันปี ฉันได้เห็นการเปลี่ยนแปลงและสิ่งประดิษฐ์ที่น่าสนใจมากมาย เช่น รูปแบบของบทกวี, ภาพในภาพยนตร์ มนุษย์นี่เป็นสิ่งมีชีวิตที่น่าสนใจจริงๆ"
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "อืมลิลลี่รู้จักเธอ เมื่อแม่ไม่อยู่ ลิลลี่ก็อาศัยอยู่ที่บ้านของเธอ"
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "เรื่องราวเกี่ยวกับดาฟเดล"
  },
  Voice_6192_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「ดาฟเดล」ที่ถูกปลุก"
  },
  Voice_6195_AwakerVoiceContent = {
    Text = "คนที่รบกวนการพักผ่อนของข้าคือคุณใช่หรือไม่?"
  },
  Voice_6195_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6196_AwakerVoiceContent = {
    Text = "เทพเจ้า? มีแต่คนโง่ที่ฝากชีวิตไว้กับสิ่งเลื่อนลอยและไม่มีตัวตนแบบนั้น ควรคิดหาวิธีทำให้ตัวเองแข็งแกร่งขึ้นแทน"
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "เจ้าของนักสู้? แค่พวกแมลงต้อยต่ำเท่านั้น"
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับอักกริปปา"
  },
  Voice_6197_UnlockDesc = {
    Text = "เมื่อได้รับตัวปลุก「อักกริปปา」จะปลดล็อก"
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "หลังจากชัยชนะแล้ว ช่วยให้ฉันนำวัสดุที่ใช้สำหรับขยายพันธุ์ไปได้ไหม"
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "เพื่อนใหญ่! เพื่อน! ฮิฮิ จะเป็นเพื่อนกับออรีตาตลอดไปตลอดไปเลยนะ!"
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "ตอนนี้ฉันรู้สึกตื่นเต้นมาก... หากไม่อยากจบชีวิต ทางที่ดีควรอยู่ให้ไกลจากฉันเสียหน่อย"
  },
  Voice_6200_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6201_AwakerVoiceContent = {
    Text = "คนนั้น... ท่าทีแบบนั้นกับคนอื่นๆ จะไม่มีปัญหาจริงๆ หรือ? คุณนายซาร่าบอกว่า เด็กเล็กไม่ควรแสดงอารมณ์โกรธง่ายๆ.."
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับมอร์ฟี่"
  },
  Voice_6201_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「มอร์ฟี่」ร่างกายที่ตื่นขึ้น"
  },
  Voice_6202_AwakerVoiceContent = {
    Text = "แสงแห่งชัยชนะเป็นของท่าน."
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6203_AwakerVoiceContent = {
    Text = "กินไม่ไหวแล้วน้า~"
  },
  Voice_6203_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6204_AwakerVoiceContent = {
    Text = "ช่องว่างในใจได้รับการเติมเต็มแล้วล่ะ~"
  },
  Voice_6204_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6205_AwakerVoiceContent = {
    Text = "ร้อนขึ้นอีกนิดหน่อย~"
  },
  Voice_6205_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6206_AwakerVoiceContent = {
    Text = "ฉันรู้จักเด็กคนนั้น เธอจะยืนดูการแสดงอยู่ไกลๆ เป็นครั้งคราว ไม่เข้ามารบกวนก็ดีแล้ว ไม่อย่างนั้นเด็กๆ คงจะ “เหนื่อยจนแทบรับไม่ไหว” แน่!"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับฟีนต์"
  },
  Voice_6206_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ปลุก「ฟีนต์」"
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "ทิงค์เทตเคยพูดไว้ว่า รู้จักตอบแทนบุญคุณ ดังนั้น ตราบใดที่เป็นสิ่งที่ฉันพอจะทำได้ ฉันจะช่วยเสมอ.."
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "สวัสดี ผู้พิทักษ์ มีอะไรที่สามารถช่วยเหลือได้ไหม?"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "วันหนึ่งในไม่ช้า ฉันจะกลับไปสู่สนามรบในฐานะผู้นำที่นำทัพฝ่าฟันอย่างแน่นอน"
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6209_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "คุณเชื่อไหม? ฉันรู้สึกว่ากระดูกขาที่หักกำลังหายดี."
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6210_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "ข้าขอขอบพระคุณท่านจากใจจริง ที่ได้เชื่อมั่นและอบรมข้าจนถึงขั้นนี้ ดูเหมือนท่านเองก็เป็นผู้ใฝ่หาความยุติธรรม เช่นนั้นแล้วข้าจะต้องสืบทอดเกียรติยศแห่งทหารต่อไปอย่างแน่นอน"
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6211_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "วันที่จะก้าวขึ้นสู่การเดินทางกำลังจะมาถึง เลือดในอกพุ่งพล่าน"
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6212_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "เกียรติยศของนักรบกำลังฟื้นฟู"
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6213_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6214_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_6214_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6215_AwakerVoiceContent = {
    Text = "โอ๊ย!"
  },
  Voice_6215_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6216_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_6216_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6217_AwakerVoiceContent = {
    Text = "แกล้งโง่!"
  },
  Voice_6217_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6218_AwakerVoiceContent = {
    Text = "ขอโทษจริงๆ ครั้งหน้าจะทำให้ดีขึ้นแน่นอน!"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "ฉันได้ยินใครสักคนร้องเรียกชื่อของฉัน อักกริปปา อักกริปปา อักกริปปีนา.."
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6219_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "ฉันเห็น... พระองค์ทรงปีนขึ้นมาจากความมืดมิดใต้บ่อน้ำ ดวงตาจำนวนนับไม่ถ้วนผุดขึ้นจากไข่แห่งเนื้อหนัง พวกมันจ้องมองมาที่ฉัน และเรียกขานฉันว่า... เทพแห่งเขาวงกต"
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6220_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "ฉันมีความอยากที่จะชมการดวลอย่างมาก... หากสถานที่นั้นอยู่ในเขาวงกต ก็ยิ่งดีเลย"
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6221_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "สัญญา... ใช่แล้ว ฉันจะทำสัญญากับเธอ สัญญาผู้รับใช้ที่ไม่มีวันหมดอายุ.."
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6222_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "หึ... ใช้ได้เลย ขออีกหน่อยเถอะ ฉันต้องให้อาหารเหล่าแมงมุมน้อยพวกนี้ให้เต็มท้อง"
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6223_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "สกปรกและน่ารังเกียจเพียงใด! อาา——อย่าพูดถึงมันอีกเลย! ขอร้องล่ะ! อย่าให้ฉันเห็นมัน และอย่าได้พูดถึงมันข้างหูฉันเลย.."
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "อดีตของฉันดำเนินไปอย่างราบรื่น ราวกับทะเลสาบที่สงบเงียบ ไม่มีอะไรที่ควรกล่าวถึง"
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6225_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "อืม...? แม่ โอบกอด... อบอุ่นจัง.."
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "ฝุ่นดาว.."
  },
  Voice_6227_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6228_AwakerVoiceContent = {
    Text = "อ้าว คุณหลงทางหรือเปล่า?"
  },
  Voice_6228_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6229_AwakerVoiceContent = {
    Text = "ไม่มีประโยชน์."
  },
  Voice_6229_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6230_AwakerVoiceContent = {
    Text = "ทุกครั้งที่นึกถึงภาพของพวกคนทรยศที่คุกเข่าลงร้องไห้ขอชีวิต ฉันก็รู้สึกโล่งใจอย่างบอกไม่ถูก ราวกับว่าเปลวไฟในใจลดลงไม่น้อย"
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "เจ้าของเรือพาฉันจากบ้านไป และมอบหมายให้ฉันเป็นหญิงศักดิ์สิทธิ์แห่งเรือ ตั้งแต่นั้นมา ความหมายของชีวิตฉันก็ไม่ได้อยู่ภายใต้การควบคุมของตัวเองอีกต่อไป มีคนบอกฉันว่า อย่างน้อยในชีวิตที่สองนี้ในฐานะร่างกายที่ตื่นขึ้น ควรจะใช้ชีวิตเพื่อความปรารถนาของตัวเอง... คุณจะช่วยฉันไหม? ช่วยให้ฉันเห็นแก่ตัว ช่วยฉันค้นหาความปรารถนาของฉัน"
  },
  Voice_6231_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6231_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "อักกริปปา.ฉันไม่มีอะไรจะพูดกับเธอนัก——แต่ถ้าเธอมีความกล้าพอที่จะขอเป็นนักสู้ใต้การนำของฉัน ก็คงจะต้องพูดกันใหม่."
  },
  Voice_6232_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6233_AwakerVoiceContent = {
    Text = "ทาวี...อันตรายมากกว่าที่เราคิดไว้ หลังจากนี้หากฉันไม่อยู่แล้ว เธอต้องระวังให้มาก"
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับทาวี"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "ด้วยวิธีการวิเคราะห์นี้... ตีความโลก!"
  },
  Voice_6235_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6236_AwakerVoiceContent = {
    Text = "ด้วยวิธีการวิเคราะห์นี้... ตีความโลก!"
  },
  Voice_6236_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_6237_AwakerVoiceContent = {
    Text = "ส่องประกายอย่างเต็มที่！"
  },
  Voice_6237_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6238_AwakerVoiceContent = {
    Text = "เท่าที่ทำได้"
  },
  Voice_6238_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6239_AwakerVoiceContent = {
    Text = "เท่าที่ทำได้"
  },
  Voice_6239_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_6240_AwakerVoiceContent = {
    Text = "จงเน่าเปื่อยไปเช่นนี้."
  },
  Voice_6240_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6241_AwakerVoiceContent = {
    Text = "จงเน่าเปื่อยไปเช่นนี้."
  },
  Voice_6241_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6242_AwakerVoiceContent = {
    Text = "รอยยิ้มและมารยาทเป็นเกราะชั้นหนึ่ง ช่วยให้ฉันและคนอื่น ๆ รักษาระยะห่าง และหลีกเลี่ยงความวุ่นวายที่น่าเบื่อ ส่วนตัวตนที่แท้จริงของฉัน... ฉันไม่แยแสที่จะแสดงให้คุณเห็นหรอกนะ"
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6242_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "ความคิดที่สะสมกลายเป็นแคลเซียมคาร์บอเนตสีขาว แล้วถูกชะล้างให้กลายเป็นซานที่งดงาม พวกมันหลอมรวมเป็นหนึ่งเดียวกับฉัน ภายในนั้นมีชีพจรของฉันเต้นอยู่... ท่านยินดีที่จะมาฟังไหม?"
  },
  Voice_6243_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6243_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "แรงบันดาลใจก็เหมือนฟองอากาศที่ลอยขึ้นจากน้ำทะเลอย่างไม่หยุดยั้ง：สัมผัสเบาๆ ก็หายไปแล้ว คุณก็เป็นแบบนี้หรือเปล่า?"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6244_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "สงคราม,     การปล้นสะดม,     ชื่อเสียงและผลกำไรล้วนเป็นความปรารถนาของมนุษย์ ผู้แกะสลักที่ถ่อมตนไม่สนใจสิ่งที่มนุษย์แสวงหา เธอเพียงปรารถนาที่จะเป็นทาสของความงาม"
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6245_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "ชีวิตที่งดงามอยู่ที่การเพลิดเพลิน บางครั้งคุณไม่ควรเครียดกับตัวเองจนเกินไป"
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6246_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "บาดแผลเล็กน้อยแค่นี้.."
  },
  Voice_6247_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6249_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_6249_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6250_AwakerVoiceContent = {Text = "Damn!"},
  Voice_6250_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6251_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_6251_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6252_AwakerVoiceContent = {
    Text = "ปรากฏการณ์การหลอมกร่อนจะนำมาซึ่งความผิดปกติและภัยพิบัติต่างๆ บางที ประเทศของข้าพเจ้าอาจได้รับผลกระทบจากภัยนี้ และจมลงสู่ทะเลลึก..."
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6253_AwakerVoiceContent = {
    Text = "ดื่ม!"
  },
  Voice_6253_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6254_AwakerVoiceContent = {Text = "ยะ~!"},
  Voice_6254_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "ความน่าเกรงขามของยักษ์."
  },
  Voice_6255_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_6256_AwakerVoiceContent = {
    Text = "ลองชิมดูสิ!"
  },
  Voice_6256_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6257_AwakerVoiceContent = {
    Text = "การเสียสละที่หลีกเลี่ยงไม่ได้"
  },
  Voice_6257_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6258_AwakerVoiceContent = {
    Text = "ก็ไม่เลว นี่แหละคือเกียรติยศของนักรบ."
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "นายคนนี้! ทำไมถึงปล่อยผู้หญิงแบบนั้นเข้ามา! กำหนดเขตหวงห้ามให้ข้าเดี๋ยวนี้! อย่าให้เธอเข้ามาภายในรัศมีห้าสิบก้าวจากข้า!"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "เรื่องราว, เกี่ยวกับมิลียาห์ม"
  },
  Voice_6259_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「มิลียัม」"
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "ทำไมถึงอยากแข็งแกร่ง? ในเผ่าของฉัน ผู้ที่อ่อนแอจะถูกถอดเสื้อผ้าออกจนหมด เหลือแค่ศีรษะโล้น ต้องเผชิญกับความอัปยศที่สกปรกที่สุดเท่าที่คุณจะจินตนาการได้ —— ผลของการเป็นผู้อ่อนแอ ไม่ใช่ทุกคนจะทนได้"
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6260_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "เทพีแห่งโชคชะตา โปรดประทานพรแก่ข้า！"
  },
  Voice_6261_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6262_AwakerVoiceContent = {
    Text = "ผลที่คาดไว้... พละกำลังของมนุษย์ มีขีดจำกัดจริงๆ หรือ.."
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "กล้ามเนื้อและกระดูกผ่อนคลายขึ้นเล็กน้อย."
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6263_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "ให้ความรักของฉันลึกซึ้งยิ่งขึ้น นี่คือการสะท้อนของความปรารถนาของคุณใช่หรือไม่?"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6264_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6265_AwakerVoiceContent = {
    Text = "ทำตามใจเถอะ!"
  },
  Voice_6265_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6266_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_6266_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6267_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_6267_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6268_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_6268_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6269_AwakerVoiceContent = {
    Text = "อาห์ อาห์ ไม่อาจให้อภัยได้.."
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6270_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6271_AwakerVoiceContent = {
    Text = "รีบหน่อย!"
  },
  Voice_6271_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6272_AwakerVoiceContent = {
    Text = "บีบ——"
  },
  Voice_6272_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_6273_AwakerVoiceContent = {
    Text = "รักษาผลงานแบบนี้ไว้ ผลการเรียนปลายภาคของคุณน่าตั้งตารอคอย."
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "ได้ยินว่ามีขโมยจากสลัมมา แถมยังพาหนูตัวอ้วนมาด้วยเหรอ? ฮิฮิฮิฮิ...... ดูนะ ข้าจะลงมือทำตามหลักแห่งสวรรค์ เพื่อกำจัดภัยร้ายให้กับนายท่าน!"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเจนกิน"
  },
  Voice_6274_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「เจนกิน」"
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "มา หายใจลึกๆ ——"
  },
  Voice_6275_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6276_AwakerVoiceContent = {
    Text = "น่าสนใจจริงๆ ความเร็วในการเติบโตของคุณในการต่อสู้เกินกว่าที่ฉันคาดไว้มาก ถ้าเวลาผ่านไปอีกหน่อย บางทีคุณอาจจะกลายเป็น... แปลกจริงๆ... แม้จะข้ามกาลเวลามา ฉันยังคงมีความหวังต่อสิ่งมีชีวิตที่ดูอ่อนแอเช่นคุณ"
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6276_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "บางทีตอนนี้อาจจะเป็นเวลาที่เหมาะสมที่จะพูดเรื่องนี้ คุณฟังให้ดีๆ เลยนะ \nสัตว์ประหลาดแห่งดวงดาว โรแทน ขอยื่นคำเชิญสู่การต่อสู้กับคุณ... แน่นอน ก่อนที่คุณจะเติบโตถึงจุดสูงสุดของพลัง ฉันจะปกป้องความปลอดภัยของคุณเอง ฉันจะไม่ยอมให้คู่ต่อสู้ที่ฉันรับรองไว้ต้องมาจากไปก่อนวัยอันควรแบบนั้นอีกครั้งเด็ดขาด"
  },
  Voice_6277_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6277_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "หึ... จริงๆ แล้วไม่เข้าใจเลย รามอน่าถึงยอมรับนายเป็นคู่หูได้ยังไง ฉันยอมรับว่านายมีแววของผู้แข็งแกร่ง แต่ยังอีกไกลกว่าจะเทียบชั้นเป็นคู่ต่อสู้ของฉันได้"
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6278_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "ใช่แล้ว ทำอย่างนี้แหละ จ้องมองฉันด้วยสายตาชื่นชมเถอะ ข้าคือสิ่งสร้างที่เก่าแก่ที่สุดของดาวเคราะห์นี้ สมควรได้รับความเคารพจากผู้ที่ต้อยต่ำกว่า——ข้าคือผู้พิทักษ์ที่ปกป้องดาวเคราะห์ดวงนี้มานานนับล้านปี การเรียกร้องการต่อสู้ที่ดุเดือดสักครั้งเป็นรางวัล มันไม่เกินไปใช่ไหม?"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6279_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "ฮ่า ฉันไม่มีอารมณ์จะมาเล่นอะไรแบบนี้หรอก ถ้าไม่อยากมีปัญหาก็หาที่มุมไหนสักแห่งนั่งเงียบๆ ไป"
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6280_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "วิญญาณที่ไม่ได้รับการคุ้มครอง ข้าจะมอบความสงบสุขครั้งสุดท้ายให้แก่พวกท่าน."
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6282_AwakerVoiceContent = {
    Text = "ระวัง."
  },
  Voice_6282_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6283_AwakerVoiceContent = {
    Text = "เสียงเตือน"
  },
  Voice_6283_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_6284_AwakerVoiceContent = {
    Text = "มีบางอย่างกำลังครวญครางอยู่ในสมองของฉัน.."
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6284_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "เหมือนมีผ้าขาวบางปกคลุมความคิดของฉัน"
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6285_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "เสียงดังขึ้นเรื่อยๆ ผ้าม่านสีขาวหนาขึ้นเรื่อยๆ"
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6286_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "เสียงเข็มนาฬิกาที่กำลังเดินหรือเปล่า?"
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6287_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "เมื่อเสียงระฆังดังขึ้น ฉันจะยังอยู่ที่นี่หรือเปล่า?"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6288_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "วิธีการที่ไร้ความสามารถเช่นนี้... ฮึ่ม พวกที่ไม่รู้จักฟ้าดิน ข้าจะยอมให้เจ้าควบคุมได้ง่ายๆ ได้อย่างไร?"
  },
  Voice_6289_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6290_AwakerVoiceContent = {
    Text = "ขอถามหน่อย... พวกคุณเคยเห็นเจนกิน น้องสาวของฉันไหม? เธอเป็นผู้หญิงที่พกกับหนูและดูน่ากลัวเล็กน้อย... ฉันไม่มีทางจำผิดแน่"
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเจนกิน"
  },
  Voice_6290_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวนดำเนินการ」บทที่ 2 แล้วปลดล็อก"
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "ขอบคุณสำหรับความเมตตาของท่าน"
  },
  Voice_6292_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6293_AwakerVoiceContent = {
    Text = "ฉันพร้อมแล้ว!"
  },
  Voice_6293_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6294_AwakerVoiceContent = {
    Text = "โปรดติดตามด้วยความคาดหวัง"
  },
  Voice_6294_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6295_AwakerVoiceContent = {
    Text = "ขับกล่อมบทเพลงแด่คุณ"
  },
  Voice_6295_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6296_AwakerVoiceContent = {
    Text = "ผู้พิทักษ์คนใหม่? ใส่เต็มที่เลย! มาดูกันว่าคุณมีคุณสมบัติพอจะเป็นคู่ต่อสู้ของฉันหรือเปล่า"
  },
  Voice_6296_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6297_AwakerVoiceContent = {
    Text = "แม้ว่าฉันจะเป็นพวก пациฟิสต์ แต่「พวกเธอ」ชัดเจนว่าไม่ได้คิดแบบนั้น.."
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6298_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_6298_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6299_AwakerVoiceContent = {
    Text = "ถอยไป!"
  },
  Voice_6299_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6300_AwakerVoiceContent = {
    Text = "กล้าดียังไงมาดูถูกฉันแบบนี้.."
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "พร้อมหรือยัง โชว์มายากลของคาเซียกำลังจะเริ่มแล้ว! อย่าละสายตา อย่าพลาดช่วงเวลาที่น่าตื่นเต้น ถึงเวลาของโชว์แล้ว!"
  },
  Voice_6301_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6302_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6303_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_6303_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_6304_AwakerVoiceContent = {
    Text = "ฉันได้ตารางเวลาของคุณมาจากคุณซิลเวีย มันค่อนข้างเข้มงวดเกินไปสำหรับมือใหม่ ฉันเข้าใจว่าพวกคุณกำลังทำสิ่งที่ถูกต้อง แต่การให้ทหารใหม่แบกรับภาระหนักอาจสร้างปัญหาไม่จำเป็นให้กับทีม \nคุณบอกว่าคุณไม่ใช่มือใหม่? ไม่ ฉันเห็นจากแววตาของคุณ ว่ามีหลายสิ่งที่คุณยังไม่เคยผ่านประสบการณ์."
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6304_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "ฉันเกลียดตัวเองที่ทำหน้าที่ผิดพลาด... อา! คุณไม่จำเป็นต้องปลอบฉัน! อดีตเหล่านั้นได้กลายเป็นแรงผลักดันให้ฉันเติบโต และตอนนี้ฉันได้กลายเป็นผู้ช่วยที่ดีของคุณแล้ว ใช่ไหม?"
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "ฉันคุยกับผู้ชายคนนั้นไม่รู้เรื่องหรอก ชีวิตจะมีเรื่องผิดพลาดหรือโทษอะไรกันมากมาย หาความสุขปัจจุบันน่าจะดีกว่านะ"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับเอลซัลวาดอร์"
  },
  Voice_6306_UnlockDesc = {
    Text = "ปลดล็อคเมื่อได้รับ「เอลซัลวาดอร์」ร่างกายที่ตื่นขึ้น"
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "เวลาเหลือน้อยแล้ว โจมตีเลย."
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "เกลียดเทียนที่ดับง่าย เกลียดขนมปังดำ เกลียดด้ายที่โผล่ออกมาจากชายกระโปรง... ไม่มีเหตุผลอะไรเป็นพิเศษ เกลียดสิ่งพวกนี้ ไม่ใช่เรื่องธรรมดาหรือ?"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "หากเจ้าตั้งข้าว่าเป็นผู้บริสุทธิ์ศักดิ์สิทธิ์แล้ว พวกท่านควรยอมสยบ!"
  },
  Voice_6309_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6310_AwakerVoiceContent = {
    Text = "หากเจ้าตั้งข้าว่าเป็นผู้บริสุทธิ์ศักดิ์สิทธิ์แล้ว พวกท่านควรยอมสยบ!"
  },
  Voice_6310_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_6311_AwakerVoiceContent = {
    Text = "ร้องเพลงนะ"
  },
  Voice_6311_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6312_AwakerVoiceContent = {
    Text = "«ตู้เสื้อผ้าของสุภาพสตรี»,      «คู่มือการตัดเย็บสำหรับผู้หญิง» เป็นหนังสือที่ยอดเยี่ยมทั้งนั้น... แม้จะซื้อไม่ได้ แค่ดูชุดสวยๆ ก็สนุกแล้ว"
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "แปลกมาก ฉันมักจะจำสิ่งอื่นได้ยากมาก แต่พอเป็นเธอ แค่ไม่กี่วันก็จำได้แล้ว...อะไรนะ ผ่านมาสามเดือนแล้วเหรอ? ขอโทษนะ ฉันลืมไปอีกแล้ว"
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6314_AwakerVoiceContent = {
    Text = "ลองชิมดู."
  },
  Voice_6314_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_6316_AwakerVoiceContent = {
    Text = "ลองพัฒนาบุคลิกภาพต่อไปนะ"
  },
  Voice_6316_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6317_AwakerVoiceContent = {
    Text = "ฝึกฝนการฟาดแส้เพิ่มอีก 20 ครั้ง"
  },
  Voice_6317_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6318_AwakerVoiceContent = {
    Text = "การเคลื่อนไหวของฉันแม่นยำพอหรือไม่?"
  },
  Voice_6318_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6319_AwakerVoiceContent = {
    Text = "กรุณา!"
  },
  Voice_6319_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_6320_AwakerVoiceContent = {
    Text = "รีบพาบราวน์ออกไป！"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6321_AwakerVoiceContent = {
    Text = "คุกเข่าลงต่อหน้าบัลลังก์"
  },
  Voice_6321_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6322_AwakerVoiceContent = {
    Text = "คุกเข่าลงต่อหน้าบัลลังก์"
  },
  Voice_6322_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_6323_AwakerVoiceContent = {
    Text = "ความหลากหลายของสีหน้าท่าทางของมนุษย์เมื่อเผชิญกับความปรารถนานั้น ทำให้ฉันรู้สึกประหลาดใจอยู่เสมอ แต่น่าเสียดายที่มนุษย์ยังคงเปราะบางและเล็กน้อยเกินไป... เรื่องนี้เพียงอย่างเดียวทำให้ฉันรู้สึกเหมือนมีแมวมาข่วนที่หัวใจจนทนไม่ได้"
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "จากความทรงจำของเธอ ฉันเห็นเรื่องราวเกี่ยวกับ「การหลอมกร่อน」มากมาย... แต่ทุกครั้งที่อยากจะบอกคุณ จิตสำนึกของฉันก็จะถูกตัดขาด คงเป็นฝีมือของเธอ"
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "หรือว่าแบบนี้มันไม่ดี?"
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "ผู้ติดตามที่ดีต้องอ่อนแอและไร้ความคิด——ฉันชอบลูกแกะที่อ่อนโยน"
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "การที่เราได้พบกันเช่นนี้ คงเป็นคำสัญญาของพระเจ้าต่อผู้ที่กำลังทุกข์ทน——ท่านคือเปลวไฟอันเย็นชาที่จะขจัดภัยพิบัติ และข้าพเจ้าจะเป็นแขนข้างหนึ่งของท่าน อยู่เคียงข้างท่านเสมอ"
  },
  Voice_6327_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6328_AwakerVoiceContent = {
    Text = "ถึงแค่นี้!"
  },
  Voice_6328_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6329_AwakerVoiceContent = {
    Text = "เคยลองฉีดลาวาหลอมละลายเข้าไปในร่างกายไหม? ของเหลวสีดำนั่นมันจะพันรอบหัวใจคุณเหมือนงูกะปอย แล้ว...ปัง！ ร่างกายคุณจะระเบิดกลายเป็นน้ำเมือกร้อนๆ น่าขยะแขยง แต่มันได้ผลดี lắm"
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "หึ ที่พวกอ่อนแอต้องพึ่งพาอาศัยกันเพื่อความอยู่รอด"
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "เป็นระยะๆ เด็กสาวที่ขี่มอเตอร์ไซค์จะมาช่วยฉันดูแลรักษาขาเทียม แต่ช่วงนี้ความถี่ในการตรวจเช็คมันไม่สูงเกินไปหน่อยหรือ?"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "บทสนทนา เกี่ยวกับนอร์ดิลา"
  },
  Voice_6331_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับ「นอร์ดิลา」"
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "ความสัมพันธ์ระหว่างเรา?ยังต้องถามอีกเหรอ?ก็เป็นความสัมพันธ์แบบที่คุณคิดนั่นแหละ?"
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "ไม่ใช่แนวที่ฉันถนัด แต่ถ้าคุณยืนกรานละก็."
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "รอยคล้ำใต้ตาของคุณหนักขึ้นอีกแล้ว......ทำไมถึงต้องเหนื่อยขนาดนี้ล่ะ? คุณควรเรียนรู้ที่จะเพลิดเพลินกับเวลาว่างเหมือนฉัน"
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6334_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "เดี๋ยว... ยังไม่ได้รับอนุญาตจากข้า.."
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6335_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "ดีมาก...เริ่มใกล้เคียงกับสภาพเดิมแล้ว."
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6336_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "นี่คือพละกำลังที่เพียงพอจะต่อต้าน 「การทุจริตสีเขียว」...... เจ้าได้แตะต้องสิ่งที่ไม่ควรแตะต้อง แล้วฉันล่ะ จะไม่มีวันปล่อยเจ้าไปอีก"
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6337_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "ช้า... แสงแรกของอรุณในหุบเขา คงจะเป็นครั้งแรกที่คุณได้เห็นใช่ไหม? นี่คือรางวัลสำหรับความจงรักของคุณ"
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6338_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "หนังสือ«@1@2การตื่นพลัง»นี้มอบให้ท่านละ มันจะช่วยเพิ่มความคิดสร้างสรรค์ หรือทำให้คุณหลับอย่างรวดเร็ว"
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6339_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "โลกีย์ยังคงวุ่นวายเกินไป หากท่านหาที่สงบในสถาบันให้ข้าได้ ก็คงจะดีที่สุดแล้ว... ไม่ ข้าไม่ต้องการเตาผิง การบำเพ็ญเพียรเพียงอย่างเดียว จะทำให้เทพได้ยินคำอธิษฐานของข้า.."
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "นี่คือขี้ผึ้งหรือน้ำผึ้งที่หยดลงบนร่างกาย ถ้าอยากรู้ว่าคืออะไร ก็ลองเลียดูนะ?"
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6341_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "ยินดีที่ได้เจอคุณเป็นครั้งแรก ชื่อของฉันคือไอจิส... โปรดเมตตา ทำเหมือนว่าฉันไม่มีตัวตนก็พอ!"
  },
  Voice_6342_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6343_AwakerVoiceContent = {
    Text = "ตราบใดที่ฉันยังเป็น「รามอน่า」 เราจะยังคงเป็นคู่หูกัน ใช่ไหม?"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "คุณหนูที่มีรอยคล้ำใต้ตาหนักมากคนนั้น เคยมาปรึกษาข้าเรื่องวิธี 「อยู่ภายใต้แสงแดดตลอดไป」... จริงๆ แล้ว แค่เดินทางไปมาระหว่างสองโลกก็ได้ แต่เธอไม่ยอมก้าวเข้าอุโมงค์มิติไม่ว่าจะอย่างไร... ปวดหัวจริงๆ"
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเวินเค่อ"
  },
  Voice_6344_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับ「เวินเคอร์」"
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "ยินดีต้อนรับสู่สวนสนุกของฉัน! พร้อมที่จะถูกเฆี่ยนแล้วหรือยัง?"
  },
  Voice_6345_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6346_AwakerVoiceContent = {
    Text = "เนื่องจากพระองค์ทรงยอมรับคุณแล้ว ฉันจะไม่ถือว่าคุณเป็นศัตรู"
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "อะไรเรียกว่าฉันหยิบไป คุณอย่ากล่าวหาคนบริสุทธิ์นะ! ตอนที่น็อตเก่าๆ ของเธอหายไป ฉันก็——บราวน์!...เฮ้ๆ คุณก็ทำเป็นไม่เห็นอะไรไปเถอะ?"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "บทสนทนา เกี่ยวกับนอร์ดิลา"
  },
  Voice_6347_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับ「นอร์ดิลา」"
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "การผจญภัยนั้นสนุกจริงๆ ตามที่คาดไว้! เรื่องราว...คืออะไรนะ?"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6349_AwakerVoiceContent = {
    Text = "...สะอึก อ่า ขอโทษนะ ไม่ได้ตั้งใจดูดซึมพลังงานมากเกินไปอีกแล้ว"
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "หลังจากเข้าสู่ร่างกายมนุษย์ ฉันก็สูญเสียการติดต่อกับเพื่อนร่วมชาติทั้งหมด ฉันกลัวว่าคนอื่นๆ จะหนีไม่พ้นการไล่ล่าของปีศาจ ฉันกลัวว่าฉันอาจจะเป็นคนสุดท้ายของเผ่าพันธุ์นี้แล้ว... ช่วยฉันด้วย ผู้พิทักษ์ ให้ฉันอยู่ข้างๆ ท่าน อย่าปล่อยฉันไว้ในความมืด..."
  },
  Voice_6350_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6350_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "ในขณะที่ดาวเคราะห์ถูกทำลาย ข้าได้ละทิ้งร่างกายและย้ายจิตใจของข้าไปสู่ร่างมนุษย์... แต่ปีศาจสีดำไล่ล่าข้า มันผูกมัดจิตใจของข้าไว้อย่างแน่นหนา ไม่ให้ข้าหลบหนี! มันจะลากโลกทั้งใบลงไปสู่บ่อโคลนสีดำ!"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6351_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "ได้โปรดเถอะ ผู้พิทักษ์... ขอแค่ให้ฉันอยู่บนเครื่องระบุตำแหน่งโดยไม่ต้องจากไป ยกเว้นการเข้าสู่ความมืดและเผชิญหน้ากับสิ่งนั้น... สีดำนั่น! ฉันยอมทำทุกอย่าง! ฉันไม่สามารถออกจากเครื่องระบุตำแหน่งได้ เดี๋ยวฉันจะสามารถระบุตำแหน่งซากของดาวแม่ได้แล้ว! อีกแค่เพียงหนึ่งหมื่นสองพันล้านครั้งของการคำนวณเท่านั้น!"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6352_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "คุณช่วยขอสารเสริมคาเฟอีนสองถุงให้ฉันได้ไหม โดยใช้ส่วนแบ่งเสบียงของคุณ? ... ฉันไม่สามารถนอนได้ ทำไมต้องนอนด้วยล่ะ? ห้ามนอนเป็นอันขาด! เมื่อหลับตาแล้ว ทุกอย่างจะกลายเป็นความมืด มืด.."
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6353_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "ว้าว! อย่าเข้ามาใกล้ฉัน! ก่อนอื่น...ก่อนอื่นพิสูจน์ให้ฉันเห็นว่าเธอไม่ใช่ลูกสมุนของความมืด! ใช่ ลูกสมุน แค่ถอดเสื้อผ้าออกแล้วให้ฉันดูหน่อย ว่าตัวเธอมีเมือกสีดำที่น่าขยะแขยงนั่นหรือเปล่า แค่นั้นฉันก็จะรู้ได้ว่าเธอเป็นปีศาจหรือไม่.."
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6354_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "อย่าถามอีกเลย อย่าถามอีกเลย...! เธอรู้ดีว่าฉันเกลียดและกลัวอะไรที่สุด! ความมืด ความมืดที่ไม่มีที่สิ้นสุด..."
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "วิธีรักษาการหลอมกร่อน? อะไรแบบนั้นไม่มีอยู่ที่ไหนหรอกนะ \n ถามว่าฉันไม่ติดเชื้อได้ยังไงเหรอ? ฮะฮะ... เพียงแค่「ไม่ถูกมองเห็น」ก็พอแล้วล่ะ?"
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "ขอบคุณเจ้านาย."
  },
  Voice_6357_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6358_AwakerVoiceContent = {
    Text = "พวกมันก็มีความสุขเช่นกัน."
  },
  Voice_6358_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6359_AwakerVoiceContent = {
    Text = "ลิลลี่ เติบโตขึ้นแล้ว."
  },
  Voice_6359_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6360_AwakerVoiceContent = {
    Text = "จะบดทิ้งไหม?"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "เธอเรียกเขาออกมาได้อย่างไร! ไอ้คนขี้เซาที่ไร้ประโยชน์นั่น! ยอมแพ้ชะตากรรม, ไม่คิดจะพัฒนาตัวเอง... ฉันเคยคาดหวังกับเขามากแค่ไหน! เราไปกันเถอะ! ฉันไม่อยากเห็นผู้ชายคนนี้!"
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับตูรู"
  },
  Voice_6361_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ตูรู」"
  },
  Voice_6362_AwakerVoiceContent = {
    Text = "น่ารังเกียจ!"
  },
  Voice_6362_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_6363_AwakerVoiceContent = {
    Text = "รำคาญจริงๆ!"
  },
  Voice_6363_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6364_AwakerVoiceContent = {
    Text = "ครั้งหน้าไปดูทะเลกับคุณนะ ไปเฟฟเฟอร์ก็ได้ ผมจะเป็นไกด์ให้คุณ หรือจะไปที่อื่นไกลๆ ก็ได้ ผมอยากไปทุกที่กับคุณ"
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6364_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = "ทะเลมีภาษาของมันเอง \n ...แบบนี้ ฉันสามารถคุยกับปลาตัวเล็กๆ ในสระน้ำเกี่ยวกับเรื่องบ้านเกิดเป็นครั้งคราว หากคุณอยากรู้ ฉันจะช่วยคุณแปลไหม?"
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6365_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "ที่คุณสามารถช่วยเหลือฉันได้ ฉันมักจะรู้สึกโชคดีจนกลัว... ช่วยบอกฉันหน่อยได้ไหมว่า ที่นี่ไม่ใช่ความฝัน และคุณก็จะไม่หายไปในทะเลอย่างเงียบๆ ใช่ไหม?"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6366_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "ความรู้สึกแบบนี้สามารถเรียกได้ว่าเป็น “ความสุข” ไหม? ฉันเมื่อก่อน... ไม่เคยคาดหวังถึงเรื่องแบบนี้เลย"
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6367_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "ร่างกายอุ่นๆ เหมือนถูกล้อมรอบด้วยน้ำทะเลที่อ่อนโยน จริงๆ แล้วมันช่างน่าอัศจรรย์."
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6368_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "นั่นคือชิ้นส่วนของพระองค์หรือไม่? ดีมาก ดูสง่างามราวกับกษัตริย์แห่งแผ่นดินอย่างแท้จริง"
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับตูรู"
  },
  Voice_6369_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ตูรู」"
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "อย่า, อย่าทำต่อเลย... มันจะหาฉันเจอมันจะหาฉันเจอ!"
  },
  Voice_6370_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6371_AwakerVoiceContent = {
    Text = "อย่างนี้ก็น่าจะตื่นตัวตลอดเลยนะ"
  },
  Voice_6371_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6372_AwakerVoiceContent = {
    Text = "เสร็จแล้วๆๆ แบบนี้ต้องโดนจับได้แน่ๆ.."
  },
  Voice_6372_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6373_AwakerVoiceContent = {
    Text = "เราชนะแล้ว คุณรู้สึกดีใจไหม? “ดีใจ” เป็นความรู้สึกแบบไหน?"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "สิ่งที่ชอบเหรอ? ฉันชอบเพลงกล่อมเด็กของทิงค์เทต... แน่นอนว่าคุณร้องก็ไพเราะมากเหมือนกัน!"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "เขาเป็นนักรบที่ใช้งานได้ดี ผมเคยมองว่าเขาเป็น \"เพื่อนร่วมทาง\"... อะไรนะ? คุณบอกว่าฉันมีปัญหากับคำจำกัดความของ 'เพื่อนร่วมทาง' หรือเปล่า? ยินดีรับฟังรายละเอียดครับ"
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับโกลิอัท"
  },
  Voice_6375_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「โกลิอัท」"
  },
  Voice_6378_AwakerVoiceContent = {
    Text = "ดาวตกนี่.."
  },
  Voice_6378_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6379_AwakerVoiceContent = {
    Text = "อ่า——"
  },
  Voice_6379_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6380_AwakerVoiceContent = {
    Text = "พละกำลังที่ไม่สิ้นสุด ไหลเวียนไปทั่วตัว.."
  },
  Voice_6380_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6381_AwakerVoiceContent = {
    Text = "บินเลย!"
  },
  Voice_6381_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6382_AwakerVoiceContent = {
    Text = "ดีนะ คุณมีประโยชน์มากกว่าที่เห็น"
  },
  Voice_6382_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6383_AwakerVoiceContent = {
    Text = "ยี่สิบ,      ยี่สิบเอ็ด,      ยี่สิบสี่... อ๋า ผิดแล้ว ฉันนับถึงไหนแล้วนะ? หนึ่ง,      สอง,      สาม..."
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6383_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "ฉันเพิ่งจะเข้าใจว่าก่อนหน้านี้มีวัสดุอยู่เท่าไร แบบนี้ฉันก็สามารถซ่อมแซมให้เสร็จได้เร็วขึ้นแล้ว——ฮื่อ พวกนี้มาจากไหนกันนะ?"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6384_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "ช่วงนี้ประสิทธิภาพการซ่อมบำรุงดูเหมือนจะสูงขึ้น ขอบคุณที่ช่วยไว้ แบบนี้คงจะได้ออกไปผจญภัยเร็วๆ นี้แล้วเลย"
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6385_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "ฉันเริ่มจำเรื่องราวได้บ้างแล้ว... เมื่อวานนี้คุณให้ประแจเบอร์ 7 กับฉันใช่ป่ะ?"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6386_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "เสร็จสิ้นอย่างสมบูรณ์! การผจญภัยที่ไม่รู้จัก, โลกที่ลึกลับ, ฉันมาแล้ว!"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6387_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6388_AwakerVoiceContent = {
    Text = "ตูม——"
  },
  Voice_6388_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_6389_AwakerVoiceContent = {
    Text = "อย่าหลอกตัวเองเลย โซ่ตรวนทางจิตใจก็คือโซ่ตรวน ไม่อาจเรียกได้ว่าเป็นธรรม."
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "ถ้าเป็นแบบนี้ ขอบเขตระหว่างฉันและร่างที่ฟื้นคืนก็จะยิ่งเลือนลางมากขึ้น ช่วยจับตาดูฉันหน่อยนะ"
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6390_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6391_AwakerVoiceContent = {
    Text = "ไปกันเถอะ ไปช่วยโลกกัน."
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6391_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "รู้สึกเหมือนอ่านรวดเดียวจนจบแบบลื่นไหลอย่างสดชื่น เหมือนกับ «ต้นกำเนิดแห่งสายพันธุ์»"
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6392_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "แข็งแกร่งขึ้นแล้ว ครั้งหน้าให้ฉันลองทำภารกิจคนเดียวดูได้ไหม?"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6393_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "นอกจากความสามารถในการต่อสู้แล้ว ความทรงจำและความสามารถทางตรรกะดูเหมือนจะไม่ได้พัฒนาขึ้นอย่างชัดเจน แน่นอน ยังต้องคิดเองอยู่ดี"
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6394_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "ฉันจะทำให้พวกเขารู้ว่ารสชาติของการพลิกผันชีวิต ความสูญเสียทั้งหมด และการถูกเหยียดหยามเป็นอย่างไร"
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6395_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "ความอับอายที่ฉันต้องทน ทุกสิ่งที่ฉันสูญเสียไป... ฉันจะให้พวกเขาชดใช้ ให้ทุกคนชดใช้"
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6396_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "ความเกลียดชังที่หอมหวานเพียงใด หากปรุงรสด้วยเลือดของศัตรู ย่อมเป็นอาหารที่ล้ำเลิศที่สุดในโลก"
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6397_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "โอ้โห! อย่าเข้ามาด้านหลังแบบไม่ทันตั้งตัวสิ!"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "เปลวไฟร้อนแรงลุกโชนในอกของฉัน... ใช่แล้ว ฉันไม่เคยลืม และก็ไม่มีวันลืม"
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6399_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "จงลุกโชนเถิด วิญญาณแห่งบทกวี."
  },
  Voice_6400_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6401_AwakerVoiceContent = {
    Text = "(ฮัมเพลงเบาๆ)"
  },
  Voice_6401_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6402_AwakerVoiceContent = {
    Text = "(ฮัมเพลงเบาๆ)"
  },
  Voice_6402_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6403_AwakerVoiceContent = {
    Text = "(ฮัมเพลงเบาๆ)"
  },
  Voice_6403_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6404_AwakerVoiceContent = {
    Text = "(ฮัมเพลงเบาๆ)"
  },
  Voice_6404_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6405_AwakerVoiceContent = {
    Text = "คันจังเลย! เหมือนตอนที่สาวใช้แกล้งแหย่เท้าด้วยขนนก คุณ*เก็บเสียง*คงไม่ได้ตั้งใจใช่ไหม"
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6405_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "ขอให้คุณมีฝันที่ดี."
  },
  Voice_6406_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6407_AwakerVoiceContent = {
    Text = "ขอให้คุณมีฝันที่ดี."
  },
  Voice_6407_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6408_AwakerVoiceContent = {
    Text = "ประทานความสงบ...!"
  },
  Voice_6408_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_6409_AwakerVoiceContent = {
    Text = "จงเคลื่อนไหวอย่างสง่างาม."
  },
  Voice_6409_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6410_AwakerVoiceContent = {
    Text = "ได้ยินไหม? เสียงของฉัน"
  },
  Voice_6410_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_6411_AwakerVoiceContent = {
    Text = "ได้ยินไหม? เสียงของฉัน"
  },
  Voice_6411_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6412_AwakerVoiceContent = {
    Text = "ฝนตกแล้ว น้ำฝนจะชะล้างทุกอย่างออกไป อาหารที่เสียไป สิ่งสกปรกที่ฝังแน่น และคนอย่างฉัน... คนที่ไม่มีความหมาย.."
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "คลื่นแห่งการล้างแค้นถาโถมไม่หยุด"
  },
  Voice_6413_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6414_AwakerVoiceContent = {
    Text = "เลือด อาบตัวทั้งร่าง!"
  },
  Voice_6414_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6415_AwakerVoiceContent = {Text = "ว้า!"},
  Voice_6415_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6416_AwakerVoiceContent = {
    Text = "ดูทางนี้!"
  },
  Voice_6416_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6417_AwakerVoiceContent = {
    Text = "ฉันไม่กลัวเลย"
  },
  Voice_6417_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_6418_AwakerVoiceContent = {
    Text = "ระวัง!"
  },
  Voice_6418_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6419_AwakerVoiceContent = {
    Text = "โลกที่ไม่เคยประสบความทุกข์ ไม่เคยถูกความเศร้าโศกเข้าคืบคลาน ไม่เคยถูกความเจ็บป่วยทรมาน และไม่เคยถูกความทุกข์ยากสีดำครอบงำ——นี่อาจเป็นเพียงภาพลวงตาที่ไม่มีวันพบเจอ แต่เป็นอุดมคติที่ข้าพเจ้าแสวงหามาตลอดชีวิต."
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "ยอมแพ้ต่อความงดงามของอาณาจักรนิรันดร์เถอะ!"
  },
  Voice_6420_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_6421_AwakerVoiceContent = {
    Text = "ยอมแพ้ต่อความงดงามของอาณาจักรนิรันดร์เถอะ!"
  },
  Voice_6421_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6422_AwakerVoiceContent = {
    Text = "มาถวายเครื่องบรรณาการอีกแล้วเหรอ? ช่างทำตามคำสั่งอย่างว่าง่ายจริงๆ"
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6422_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6423_AwakerVoiceContent = {
    Text = "เจ็บไหม?"
  },
  Voice_6423_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_6424_AwakerVoiceContent = {
    Text = "ตั้งใจหน่อยนะ"
  },
  Voice_6424_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6425_AwakerVoiceContent = {
    Text = "เวลาพันปีทำให้ข้าเผลอไป"
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "วันนั้น ทะเลเพลิงแห่งความอิจฉาและโกรธแค้นแผ่ขยาย เหมือนกุหลาบสีเลือดที่บานสะพรั่ง... บทกวีทั้งหมด ถูกเปลวไฟสีเลือดกลืนกินจนกลายเป็นเศษขี้เถ้าที่แหลกสลาย.."
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6426_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "ได้เรียนรู้เทคนิคใหม่แล้ว！"
  },
  Voice_6427_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6428_AwakerVoiceContent = {
    Text = "ระวังนะ."
  },
  Voice_6428_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6429_AwakerVoiceContent = {
    Text = "ไม้กายสิทธิ์อยากเต้นแล้ว!"
  },
  Voice_6429_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6430_AwakerVoiceContent = {
    Text = "อืม ความรู้สึกว่างเปล่านี้ที่คุ้นเคย!"
  },
  Voice_6430_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6431_AwakerVoiceContent = {
    Text = "ข้อต่อเคลื่อนไหวได้ลื่นไหลขึ้น"
  },
  Voice_6431_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6432_AwakerVoiceContent = {
    Text = "สีดำที่ดูไม่เป็นมงคลนั้น ดูคล้ายกับดาบและโล่ไร้รูปทรงของข้า... อ่า! ขอให้ท่านผู้เป็นนายวางใจ! ดาบแห่งการพิทักษ์ของข้าจะไม่มีวันทำร้ายท่าน!"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6433_AwakerVoiceContent = {
    Text = "มาเลย."
  },
  Voice_6433_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6434_AwakerVoiceContent = {
    Text = "ผ่านไปได้แบบหวุดหวิด"
  },
  Voice_6434_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6435_AwakerVoiceContent = {
    Text = "ฉันจะทำอย่างเต็มที่."
  },
  Voice_6435_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6436_AwakerVoiceContent = {
    Text = "วันนี้จะเล่นที่นี่ไหม?"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "ในห้องใต้ดินมีน้ำจำนวนมาก นุ่มนวล เย็นเฉียบ ดังนั้น ร่างกายของฉันจึงถูกล้อมรอบด้วยไอน้ำเสมอ... เหมือนกับว่าระหว่างฟ้ากับดิน ฉันคือเนื้อหนังเพียงหนึ่งเดียว บางครั้ง ฉันอยากจะละลายไปกับน้ำเสียจริงๆ \nแต่หากเป็นเช่นนั้น ฉันก็จะไม่มีตัวตนอีกต่อไป และจะไม่มีโอกาสได้พบกับเธอ"
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6437_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = "บอกคุณความลับ... จริงๆ แล้วฉันเกลียดเลือด เกลียดทั้งสีและรสชาติของมัน แต่ฉันไม่สามารถแยกตัวเองออกจากมันได้ \n... ฉันกลืนเลือดเข้าไป แล้วอาเจียนออกทั้งหมด... ฉันรังเกียจตัวเอง"
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6438_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "อืม! โลหิตของท่าน... มีกลิ่นเหมือนเหล้าหวานน้ำผึ้ง ฉันคิดว่าตัวเองคงเป็นคนเดียวที่รู้ความลับนี้ใช่ไหม?"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6439_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "ในจินตนาการของฉัน อัศวินผู้กล้าหาญจะดึงฉันออกมาจากความมืด แล้วใช้โซ่ตรวนล่ามฉันไว้ เขาสามารถตีฉัน ด่าฉัน ทำอะไรก็ได้กับฉัน——ความเจ็บปวดคือสิ่งที่ยืนยันว่าฉันยังมีชีวิตอยู่ \nท่านยินดีที่จะเป็นอัศวินของฉันหรือไม่?"
  },
  Voice_6440_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6440_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "เลือดไหลเหมือนสายน้ำ ข้าเป็นของท่าน——ความรู้สึกนี้ไม่เคยชัดเจนเท่านี้มาก่อน"
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6441_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "นี่คือคำสั่งของเทพีแห่งการแก้แค้นทั้งสาม!"
  },
  Voice_6442_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6443_AwakerVoiceContent = {
    Text = "คมดาบถูกชักออก."
  },
  Voice_6443_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_6444_AwakerVoiceContent = {
    Text = "ไม่ได้นะ!"
  },
  Voice_6444_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6445_AwakerVoiceContent = {
    Text = "สกปรกมาก สกปรกมาก!"
  },
  Voice_6445_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_6446_AwakerVoiceContent = {
    Text = "...ไอจิส เห็นแล้ว!"
  },
  Voice_6446_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_6447_AwakerVoiceContent = {
    Text = "...ไอจิส เห็นแล้ว!"
  },
  Voice_6447_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6448_AwakerVoiceContent = {
    Text = "ทิปสินะ แน่นอนว่ามันคือทิป ลองไปดูพวกพนักงานเสิร์ฟในโรงอาหารของโรงเรียนสิ ช่างดูไม่ค่อยฉลาดเลย! ขนาดเก้าอี้เอนก็ไม่เตรียมไว้ล่วงหน้า แบบนี้ยังจะหวังเงินเพิ่มอีกหรือ ฝันไปเถอะ!"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6449_AwakerVoiceContent = {
    Text = "สีดำ."
  },
  Voice_6449_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_6450_AwakerVoiceContent = {
    Text = "ให้ฉันออกไป!"
  },
  Voice_6450_AwakerVoiceTitle = {
    Text = "ทักษะ·หนึ่ง·บ้าคลั่ง"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "อย่าเพิ่งทำแบบนี้เลย......"
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "ทักษะ·หนึ่ง·เศร้าหมอง"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "ไม่จำเป็นต้องสุภาพมากเกินไป ผู้ส่งสารที่ซีดเซียว ระหว่างท่านและข้าไม่ควรมีระยะห่าง เพราะเราล้วนเป็นสิ่งสร้างของพระเจ้า และกำลังเดินบนเส้นทางที่เต็มไปด้วยโคลนและบททดสอบร่วมกัน"
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6452_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "ฉันไม่กลัวพวกเขาหรอก บรรดาผู้ที่ถูกคำสาปแห่งการละลายทรมานอยู่นั้น เป็นเพียงสิ่งมีชีวิตที่น่าสงสาร ข้ารู้สึกเศร้าใจแทนพวกเขา ข้ารู้ว่าข้าไม่สามารถแบกรับความทุกข์ของพวกเขาได้ แต่ข้าสามารถให้สิ่งที่ข้ามีแก่พวกเขาได้ หากสามารถบรรเทาทุกข์ของพวกเขาได้บ้าง"
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6453_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "จะอธิษฐานร่วมกับฉันไหม เปลวไฟซีด? เพื่อผู้ที่ทนทุกข์ซึ่งเสียชีวิตจากการต่อสู้ของเราในวันนี้ อธิษฐานเถอะ แม้ว่าพวกเขาจะบ้าคลั่งเพราะคำสาปแห่งการละลาย พวกเขาก็ยังคงเป็นสิ่งสร้างของพระเจ้าแห่งความเมตตา และเป็นพี่น้องของเรา ขอให้พวกเขาได้รับความสงบสุขที่สมควรได้รับ"
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6454_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "แม้ว่าเปลวไฟสีแดงจะทำให้ฉันรู้สึกตึงเครียด แต่เพื่อเธอ ฉันยินดีที่จะก้าวขึ้นไปบนแท่นไม้ที่ลุกโชนอีกครั้ง ไม่จำเป็นต้องใส่ใจเรื่องนี้เลย เปลวไฟขาวของฉัน เมื่อเทียบกับความสุขที่เธอสามารถนำมาให้ การเสียสละของฉันเพียงคนเดียวไม่มีความหมายใดๆ"
  },
  Voice_6455_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6455_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "เสียใจไหม? ไม่หรอก แน่นอนว่าไม่ การตายของฉันช่วยลดความทุกข์ให้พวกเขา และแลกกับเวลาที่มากขึ้น แค่นั้นก็เพียงพอแล้ว แต่... เธอเปิดเผยความจริงกับฉัน ดังนั้นฉันจะไม่ปิดบังเธอเช่นกัน: การถูกเผาในวันนั้นยังคงทิ้งบาดแผลลึกในใจฉันอยู่"
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6456_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "คุณสามารถทำข้อตกลงกับฉันได้ไหม? อืม... เราตกลงกันว่า ไม่ว่าจะเกิดอะไรขึ้น คุณจะต้องจำ「รามอน่า」ตลอดไป ดีไหม?"
  },
  Voice_6457_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6457_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "ฉันไม่เสียใจที่เลือกจะเป็นแบบนี้ ถ้าให้เริ่มใหม่อีกครั้ง ฉันก็ยังจะทำแบบนี้อยู่ดี แต่ผู้พิทักษ์ ฉันกลัว...กลัวว่า「รามอน่า」จะไม่เหลือร่องรอยใดๆ ไว้บนโลกนี้"
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6458_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "ไม่ต้องห่วง ผ้าปิดตาไม่ได้ทำให้ฉันมองไม่เห็น กลับกัน แบบนี้ฉันถึงจะไม่ต้องเก็บทุกอย่างมาใส่ใจมากเกินไป"
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6459_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "สีหน้าของฉันดูแปลกไปหรือเปล่า? ฉันพยายามควบคุมมันแล้ว... แต่ดูเหมือนเธอกำลังมีอิทธิพลมากขึ้นเรื่อยๆ"
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6460_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "ปริศนาที่ยังไม่ได้รับการแก้ไข และผู้คนที่รอคอยการช่วยเหลือนั้นมีมากเกินไป ฉันไม่รู้ว่าฉันยังสามารถดำเนินการต่อไปได้นานแค่ไหน และฉันก็ไม่สามารถปกป้องทุกคนได้... นี่มันช่างยากจริงๆ นะ"
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6461_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "ยังจะเพิ่มเดิมพันบนตัวฉันอีกเหรอ? ดูเหมือนว่าการใช้ชีวิตตามใจตัวเองอย่างแท้จริงนั้นไม่ง่ายเลย แต่ไม่ต้องห่วง ฉันจะช่วยแก้ปัญหาให้โดยไม่ต้องเหนื่อยเกินไป"
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6462_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "ถึงขั้นนี้แล้ว จะไม่ใช้ฝีมือจริงๆ ได้ยังไง? ที่เกิดเหตุอยู่ที่ไหน? แม้ว่าจะต้องเสียโชคทั้งหมดของฉันไป แต่ฉันจะนำตัวผู้ต้องสงสัยกลับมาให้ได้ภายในกำหนดเวลาแน่นอน!"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6463_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "เฮ้อ รับของดีจากเธอมากมายขนาดนี้ ไม่บอกความลับบางอย่างกับเธอคงไม่ได้แล้ว：ที่จริงนะ ฉันอาจจะเป็นคนที่โชคร้ายที่สุดในโลกก็ได้."
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6464_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "คุณดูเหมือนจะไม่ใส่ใจในสิ่งที่ฉันพูด... เอาเถอะ ฉันก็ยังจะช่วยคุณฉีกศัตรูอยู่ดี อย่างไรเสียกรงเล็บและเขี้ยวนี้ก็ได้มาโดยบังเอิญใช่ไหม?"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6465_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "โชคของฉันไม่แน่ว่าจะถ่ายทอดให้เพื่อนได้หรือเปล่า คุณคงเคยได้ยินสิ? “เท้ากระต่ายนำโชค แต่สำหรับเจ้ากระต่ายเองแล้ว มันไม่มีประโยชน์เลย”"
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6466_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "หวังว่าจะประทับตราของฉันไว้ในวิญญาณของคุณไหม?"
  },
  Voice_6467_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6468_AwakerVoiceContent = {
    Text = "ต้องการพละกำลังของข้าขนาดนั้นเลยหรือ?"
  },
  Voice_6468_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6469_AwakerVoiceContent = {
    Text = "อย่าดูแค่ภายนอกของฉันแบบนี้เลย แต่ก่อนฉันก็เคยเป็นสุภาพสตรีนะ... ฉันสามารถปักผ้าได้ อ่านบทกวีของ Tennyson ออก... ใช่แล้ว ฉันยังร้องเพลงได้ด้วย: เธอเหมือนสายน้ำที่ไม่เคยหยุดไหล หล่อเลี้ยงในสายเลือดของฉัน~"
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "พิกมานและฉันกำลังร่วมมือกันสร้างผลงานศิลปะเครื่องจักรที่น่าสนใจ สำรวจวิธีการผ่านการถอดโครงสร้างภาพต้นแบบเพื่อสร้างลัทธิความเป็นนามธรรมใหม่... ออรีตาเป็นอะไร ทำไมถึงได้สลบไป?"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับออรีตา"
  },
  Voice_6470_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ออรีตา」"
  },
  Voice_6471_AwakerVoiceContent = {
    Text = "คุณอยากให้ฉันยิ้มหน่อยเหรอ?\nลิลลี่ กำลังยิ้มอยู่ไหม?"
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับรอยยิ้ม"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = "แปลกจริงๆ ฉันกลับได้รับมิตรภาพที่เท่าเทียมกันเสียอย่างนั้น \nแต่ว่า... ฉันขอเก็บสิทธิ์ในการควบคุมเธอนะ เพื่อความสนุกเล็กๆ ระหว่างเราสองคน คืนนี้มาที่ห้องนอนของฉันหน่อย เรื่องความรู้สึกของมนุษย์ยังมีอีกหลายอย่างที่ฉันต้องเรียนรู้.."
  },
  Voice_6472_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6472_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "คุณรู้ไหมว่าสิ่งที่น่ารักที่สุดของคุณอยู่ที่ไหน? ตอนที่คุณบอกว่า「ไม่」กับฉัน จมูกของคุณจะย่นขึ้น คิ้วจะยกขึ้นเล็กน้อย... ใช่ แบบที่เป็นอยู่ตอนนี้..."
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6473_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "ฉันรักผู้ติดตามของฉัน พวกเขาเป็นพวกหนุ่มน้อยหน้าตาดี ที่ถูกการหลอมกร่อนทำให้กลัวจนตัวสั่น และซ่อนตัวอยู่ข้างหลังฉัน ดูน่าสงสารจริงๆ น้ำตาของคนสวยมักทำให้ใจหวั่นไหว แล้วเธอล่ะ เธอกลัวการหลอมกร่อนไหม?"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6474_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "ผู้พิทักษ์ คุณมีใครที่เกลียดบ้างไหม? เป็นการตอบแทน ฉันสามารถช่วยสั่งสอนเขาให้หน่อยได้นะ ไม่เกินหนึ่งอาทิตย์ ฉันจะทำให้เขาเปลี่ยนตัวเองและยอมทำตามที่คุณต้องการ"
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6475_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = "ฮืม... ถึงเจ้าจะช้าไปหน่อย แต่ก็ไม่ได้น่ารำคาญอะไร เริ่มพรุ่งนี้มาดูแลข้าซะ \n ไม่เต็มใจเหรอ? นี่ไม่ใช่คำถาม แต่เป็นคำสั่ง!"
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6476_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "นานแล้วที่ไม่ได้รู้สึกแบบนี้ ฉันจะขึ้นสู่เวทีด้วยสภาพที่พร้อมที่สุด เพื่อมอบคลื่นเสียงที่สะท้านทั่วจักรวาลให้กับคุณ"
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6477_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "คุณต้องรู้ว่า นี่ไม่มีความหมายอะไร."
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6478_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "หลังจากเก็บดอกไม้แห่งชัยชนะแล้ว ฉันอยากขอค่าตอบแทนเล็กน้อย.."
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6480_AwakerVoiceContent = {Text = "อ้า"},
  Voice_6480_AwakerVoiceTitle = {
    Text = "ถูกโจมตี·ซึมเศร้า·3"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "ยานเหาะลำนั้นคับแคบและอึดอัด ราวกับโลงศพโลหะที่ลอยเคว้งในอวกาศ ฉันกำลังรอคอยดวงดาวนำทางของฉัน จนกระทั่งคุณได้ปรากฏตัวขึ้น"
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6481_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "ทำไมล่ะ!?"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "โจมตี·คลั่ง·หนึ่ง"
  },
  Voice_6483_AwakerVoiceContent = {
    Text = "อืม..."
  },
  Voice_6483_AwakerVoiceTitle = {
    Text = "ถูกโจมตี·เศร้า·หนึ่ง"
  },
  Voice_6484_AwakerVoiceContent = {
    Text = "ปวด.."
  },
  Voice_6484_AwakerVoiceTitle = {
    Text = "โดนโจมตี·เศร้า·สอง"
  },
  Voice_6485_AwakerVoiceContent = {
    Text = "การลงโทษจากสวรรค์!"
  },
  Voice_6485_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6486_AwakerVoiceContent = {
    Text = "การลงโทษจากสวรรค์!"
  },
  Voice_6486_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6487_AwakerVoiceContent = {
    Text = "น่าเบื่อ.."
  },
  Voice_6487_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_6488_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_6488_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6489_AwakerVoiceContent = {
    Text = "ยังไหวอยู่"
  },
  Voice_6489_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6490_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_6490_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6491_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_6491_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6492_AwakerVoiceContent = {
    Text = "ผู้ไร้ความเคารพ จงถูกเผาผลาญในความเงียบที่ร้อนแรงเถอะ"
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "ระวังหน่อย ถ้าเอามือยื่นเข้าไปในอีกมิติหนึ่ง อาจจะเอาคืนไม่ได้นะ！"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "พวกที่ไม่มีประโยชน์ ถ้าไม่อยากกลายเป็นเนื้อบดกระป๋อง ครั้งหน้าก็ต้องระวังให้มากกว่านี้นะ"
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "อ๊ะ กำลังทำตัวอ้อนฉันอยู่หรือเปล่า?\nน่าปวดหัวจริงๆ ถ้าเป็นแบบนี้ต่อไป ฉันคงอดใจรอไม่ได้จนกว่าผู้พิทักษ์จะเติบโตเต็มที่แล้ว.."
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "ดำดิ่งสู่เสรีภาพแห่งเจตจำนง!"
  },
  Voice_6496_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6497_AwakerVoiceContent = {
    Text = "สิ่งที่น่ารังเกียจจริงๆ แล้ว... ก็คงเป็นคนที่ชอบเลิกทำอะไรไปเสียดื้อๆ สินะ เพียงแค่นึกถึงคนแบบนั้น ข้าวเย็นเมื่อวานก็แทบจะอาเจียนออกมา..."
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "กะโหลกนับไม่ถ้วนเอ๋ย จงแสดงโฉมหน้าของเจ้าให้ข้าได้เห็น!"
  },
  Voice_6498_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6499_AwakerVoiceContent = {
    Text = "กะโหลกนับไม่ถ้วนเอ๋ย จงแสดงโฉมหน้าของเจ้าให้ข้าได้เห็น!"
  },
  Voice_6499_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_6500_AwakerVoiceContent = {
    Text = "ดื่ม!"
  },
  Voice_6500_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6501_AwakerVoiceContent = {
    Text = "ดื่ม!"
  },
  Voice_6501_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6502_AwakerVoiceContent = {
    Text = "เชื่อใจฉันขนาดนั้นเลยหรือ?"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6502_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6503_AwakerVoiceContent = {
    Text = "กลับมาเถอะ"
  },
  Voice_6503_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6504_AwakerVoiceContent = {Text = "ดี!"},
  Voice_6504_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_6505_AwakerVoiceContent = {
    Text = "ฉันรู้อยู่แล้ว นั่นคืออีกด้านของฉัน แต่ทำไมเธอถึงต่อต้าน? การยอมรับชะตากรรมของการเป็นผู้ที่ถูกเลือก ไม่ใช่ว่าสิ่งที่ปรารถนาจะได้มาง่ายๆ เหรอ?"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับ「มอร์ฟี่」"
  },
  Voice_6505_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「มอร์ฟี่」ร่างกายที่ตื่นขึ้น"
  },
  Voice_6506_AwakerVoiceContent = {
    Text = "สวัสดีค่ะ ฉันชื่อดาฟเดล เคยแลกเปลี่ยนกับแขกคนหนึ่ง และเขาขอให้ฉันมาช่วยเหลือคุณ งั้นลองบอกความต้องการของคุณมาสิ \n โอ้โห... สิ่งที่คุณต้องการนั้นมีราคาแพงไม่น้อยเลยนะคะ?"
  },
  Voice_6506_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6507_AwakerVoiceContent = {
    Text = "*ปิดเสียง* ทำอะไร! คุณเชื่อไหมว่าฉันจะตัดมือของคุณ!"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6508_AwakerVoiceContent = {
    Text = "ฮ่าฮ่าฮ่าฮ่า!"
  },
  Voice_6508_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6509_AwakerVoiceContent = {
    Text = "ฮ่าฮ่าฮ่าฮ่า!"
  },
  Voice_6509_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6510_AwakerVoiceContent = {
    Text = "กุหลาบบาดนิ้ว ลื่นไหลเป็นบทกลอน"
  },
  Voice_6510_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6511_AwakerVoiceContent = {
    Text = "ค้อมลงใต้หมึกแห่งความโศกเศร้าเข้มข้นนี้ กลายเป็นบทเพลงแห่งการไว้อาลัย.."
  },
  Voice_6511_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_6512_AwakerVoiceContent = {
    Text = "ดูของฉัน...!"
  },
  Voice_6512_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6513_AwakerVoiceContent = {
    Text = "เอิ่ม..."
  },
  Voice_6513_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6514_AwakerVoiceContent = {
    Text = "ภัยพิบัติได้ปรากฏแล้ว!"
  },
  Voice_6514_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6515_AwakerVoiceContent = {
    Text = "ให้ฉันเถอะ."
  },
  Voice_6515_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_6516_AwakerVoiceContent = {
    Text = "...ชื่อ อ่า ฉันจำไม่ได้ \n ใช่แล้ว 「24」 พวกเขาเรียกฉันแบบนั้น... ไม่! ห้ามออกมา! คุณไม่ได้ ตอนนี้ไม่ได้..."
  },
  Voice_6516_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6517_AwakerVoiceContent = {
    Text = "รอยหมึกที่ทอดยาว.."
  },
  Voice_6517_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_6518_AwakerVoiceContent = {Text = ".."},
  Voice_6518_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6519_AwakerVoiceContent = {
    Text = "ฉันคงไม่เหมาะกับคำยกย่องแบบนี้... ขอแค่คุณชอบเสียงเพลงของฉันก็พอแล้ว"
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับการร้องเพลง"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "เสื้อผ้าที่เลอะเทอะ ต้องเปลี่ยนก่อนงานเลี้ยงครั้งต่อไป"
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "มันกำลังจะตามทันฉันแล้ว ความมืดมิดนิรันดร์... ไม่มีใครหนีพ้น.."
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "ทุกครั้งที่เห็นคุณ ฉันก็จะนึกถึงพันธนาการที่มองไม่เห็นซึ่งคุณใส่ไว้กับฉัน การที่ยังปล่อยให้คุณมีชีวิตอยู่นั้นเป็นความอดทนสูงสุดของฉันแล้ว"
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "ไม่ว่าจะเริ่มใหม่กี่ครั้ง ฉันก็จะเดินไปพร้อมกับคุณ"
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "ขอให้ความเมตตาของพระเจ้าอบอุ่นวิญญาณของท่าน"
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "ฉันชอบเดินเล่นแบบไม่มีจุดหมาย เดินเล่นไปเรื่อยๆ ทั้งในหนองน้ำ สุสาน หอผู้ป่วย ปราสาทร้าง... ในสถานที่เหล่านี้ ฉันมักจะได้พบกับความประหลาดใจที่ไม่คาดคิดเสมอ"
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "รู้สึกเป็นเกียรติสิ ประตูสู่อาณาจักรนิรันดร์คือที่นี่"
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "ฮ่าๆ——คันจังเลย! ออรีตาต้องเกาคืนด้วย!"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "«การตายของหงส์» เป็นละครที่นักเต้นใช้ภาษากายเพื่อถ่ายทอดความปรารถนาและการดิ้นรนของชีวิต ท่าทางที่บิดเบี้ยวในเปลวเพลิงก็สะท้อนความจริงเช่นกัน"
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "หั่นออก หั่นออก ฉีกให้แหลก ก็เหมือนที่คนพวกนั้นเคยทำกับฉัน...ฮะ...ฮะฮะ!"
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "คุณอย่าเข้าใกล้คุณหนูไทอีสเกินไปเลย... ไม่ใช่ว่าฉันหึงนะ แค่กลัวว่าจะมีใครโดนหลอกโดยผู้หญิงแบบนั้นเท่านั้นเอง"
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับไทอีส"
  },
  Voice_6530_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「ไทอีส」"
  },
  Voice_6531_AwakerVoiceContent = {
    Text = "...ขอบคุณมาก"
  },
  Voice_6531_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6531_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "ดีมาก...คุณมีสายตาที่สามารถมองคนออก."
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6532_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "บ้านเกิดของคาเรนสวยงามมาก! เป็นเมืองหินที่ตั้งอยู่กลางทะเลสาบจริงๆ! \nทุกครั้งที่ถึงคืนพระจันทร์เต็มดวง เราจะเต้นรำอย่างเงียบเชียบในเปลวไฟและทำพิธีบูชา... \nพูดจริงๆ นะ ตอนที่คาเรนเพิ่งเข้ามหาวิทยาลัย คิดถึงบ้านทุกคืนเลย ยังแอบร้องไห้ในผ้าห่มบ่อยๆ แต่ตอนนี้ คาเรนมีบ้านใหม่และครอบครัวใหม่แล้ว ทุกอย่างดีขึ้นมาก!"
  },
  Voice_6533_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6533_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "ยะ~ยังไม่พอใจอีกเหรอ? มาเถอะ ให้ฉันแนะนำเธอนิดหน่อย~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "กล้ามเนื้ออ่อนแอ ใบหน้าซูบผอม ดวงตาคู่นี้ที่เหมือนคนตายยังพอมีค่าบ้าง——ควักออกมาให้แมงมุมกินเสียเถอะ"
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "ขอบคุณ... ขอบคุณท่านมากสำหรับทุกอย่างที่ทำเพื่อไอจิส ไอจิสจะพยายามอย่างเต็มที่... ไม่ทำให้ท่านผิดหวัง!"
  },
  Voice_6536_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6537_AwakerVoiceContent = {
    Text = "(เสียงร้องด้วยความหวาดกลัว)"
  },
  Voice_6537_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6538_AwakerVoiceContent = {
    Text = "อย่า!"
  },
  Voice_6538_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6539_AwakerVoiceContent = {
    Text = "ปล่อยฉันเถอะ.."
  },
  Voice_6539_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6540_AwakerVoiceContent = {
    Text = "(เสียงร้องด้วยความหวาดกลัว)"
  },
  Voice_6540_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6541_AwakerVoiceContent = {
    Text = "ทักษะการใช้ดาบของคุณรามอน่าแตกต่างจากที่ข้าพเจ้าถนัดมาก หากท่านเจ้านายอนุญาต ข้าพเจ้าอยากลองประลองฝีมือกับเธอ... ถะ แต่นี่เพื่อพัฒนาตนเองเท่านั้น!"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6541_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "ท่านถามข้าว่าทำไมไม่เล่นกับเด็กคนอื่นๆ หรือ? มันยากเหลือเกินที่จะเอ่ยถึง... เมื่อยังมีชีวิต ข้าแทบไม่มีโอกาสได้เล่นเลย เพื่อนเล่นเพียงคนเดียวของข้าคือองค์เจ้าหญิงที่ข้าเคยรับใช้... อา! ข้าดันเอ่ยถึงพระมหากษัตริย์อีกองค์ต่อหน้าท่านเจ้านาย โปรด โปรดอภัยโทษให้ข้าด้วย.."
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6542_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "คุณเป็นผู้พิทักษ์ที่ได้รับการยอมรับจากมหาวิทยาลัยมิซากะ ดังนั้นฉันจะเปิดสิทธิ์ฟังก์ชันที่เกี่ยวข้องให้คุณ"
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับ「ตัวเอก」"
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "ท่านสนใจใน “ทักษะเจ็ดประการของอัศวิน” ที่ข้าพเจ้าได้เรียนรู้หรือไม่? ยอดเยี่ยมมาก! อ่า... ฮืม... เมื่อครู่นี้ข้าพเจ้าเสียมารยาทไป ที่หมายถึง หากท่านยินดีฝึกฝนการขี่ม้าและยิงธนู ข้าพเจ้ารู้สึกเป็นเกียรติอย่างยิ่งที่จะเป็นคู่ฝึกของท่าน!"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6544_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "ข้าไม่ใช่อัศวินที่สมบูรณ์แบบ ไม่ว่าจะเป็นจากโรคระบาดชั่วร้ายนั้น หรือศัตรูที่เข้ามารุกราน ข้าก็ไม่สามารถปกป้องนายท่านในอดีตได้ ทว่าบัดนี้ ท่านยังคงมอบความไว้วางใจให้แก่ข้าเช่นนี้ ถือเป็นเกียรติอันสูงสุดของข้า... ข้าขอสาบานด้วยเกียรติยศของอัศวินและชีวิตที่แสนเล็กน้อยนี้ว่า ข้าจะปกป้องเส้นทางการเดินหน้าของท่านตลอดไป"
  },
  Voice_6545_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6545_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "อย่าทำร้าย."
  },
  Voice_6546_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6547_AwakerVoiceContent = {
    Text = "อย่าเลยนะ~"
  },
  Voice_6547_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6548_AwakerVoiceContent = {Text = "ตุบ!"},
  Voice_6548_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_6549_AwakerVoiceContent = {
    Text = "อย่าสังหาร"
  },
  Voice_6549_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_6550_AwakerVoiceContent = {
    Text = "สบายจัง~!"
  },
  Voice_6550_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6551_AwakerVoiceContent = {
    Text = "ตอนนี้ เราเป็นแค่น้ำกับน้ำมันที่ไม่เข้ากัน"
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "ฉันไม่มีสิ่งที่ชอบเป็นพิเศษ ถ้าให้พูดจริงๆ ก็คงเป็นความรู้สึกตอนออกไปทำภารกิจข้างนอกที่ค่อนข้างดี"
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "ทำไม ทำไมถึงขังฉันไว้ที่นี่? ฮึฮึ... พวกนายจะไม่มีวันสำเร็จหรอก! ฉันจะทำลายข้อจำกัดนี้ ฉีกคุกนี้ออกเป็นชิ้นส่วน!"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "ช่วยปกป้องทุกคน"
  },
  Voice_6554_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6555_AwakerVoiceContent = {
    Text = "พวกเธอนี่ทุกครั้งก็มาดูการแสดงมายากล ไม่เบื่อกันบ้างหรือไง? ต้องนั่งให้เรียบร้อยนะ ถ้าวิ่งขึ้นไปบนเวทีอีกล่ะก็ ฉันจะโยนพวกเธอไปยังมิติวิปลาสเลย!"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับเด็กๆ"
  },
  Voice_6555_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้ร่างกายที่ตื่นขึ้น「ไอจิส」「เจนกิน」「ลิลลี่」「มอร์ฟี่」「คาเรน」「ออรีตา」หนึ่งในนั้น"
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "ของขวัญของคุณ ผมขอรับด้วยความเคารพ."
  },
  Voice_6556_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6557_AwakerVoiceContent = {
    Text = "ของขวัญตอบแทนแบบใดจึงจะคู่ควรกับความพยายามของคุณ?"
  },
  Voice_6557_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6558_AwakerVoiceContent = {
    Text = "งดงามเพียงใด.."
  },
  Voice_6558_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6559_AwakerVoiceContent = {
    Text = "ตรวจพบกระแสไฟฟ้าแรงสูง กำลังจะทำการบำรุงรักษาเครื่องจักร...แก้ไขใหม่ ส่วนเหตุผลที่ไม่มีความร้อนเกินคืออะไร?"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6559_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "ตั้งแต่พิธีการตื่นพลังครั้งล่าสุด ขณะที่ฉันอยู่ในสถานะการหลับลึก มักจะเห็นภาพที่แตกร้าว ในนั้น ฉันมีร่างกายเหมือนมนุษย์ทั่วไป และก็มีน้ำตาหยดลง นี่คือความฝันหรือเปล่า?"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6560_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "หลังจากพิธีกรรมแต่ละครั้ง จะตรวจพบความร้อนสูงบริเวณหน้าอก แต่ที่นั่นไม่มีชิ้นส่วนที่เกี่ยวข้องกับพลังงาน คุณรู้ไหมว่าทำไม?"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6561_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "ฉันเห็นแล้ว ทุกอย่าง<Del:ควรจะตายในกระแสไฟฟ้าที่เป็นนิรันดร์> ขอโทษทีๆๆ โมดูลดูเหมือนจะ—— เตือน เตือน กิจกรรมของจิตสำนึกที่ไม่ใช่เอริกาเพิ่มขึ้น กรุณทำลายทำลาย... สวัสดีค่ะ มีอะไรให้ช่วยเหลือไหมคะ?"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6562_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "หลังจากวิเคราะห์อย่างละเอียด ผมสรุปได้ว่าสิ่งที่ผมเห็นในขณะที่อยู่ในสถานะการนอนหลับไม่ใช่ความฝันในความหมายดั้งเดิม แต่เป็น<Del:ร่างกายเนื้อและเลือดที่น่าสงสารของผมสมควรถูกทำลาย> ความทรงจำของผม ส่วนความร้อนที่แผดเผาเหมือนกับการล้นเกินนั้น อาจเป็นความรู้สึกที่เรียกว่า「ความไม่ยอมรับ」"
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6563_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "ถ้าอยากดูการแสดง ก็นั่งอยู่ที่เก้าอี้ผู้ชมดีๆ เลย!"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6564_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "เปลวไฟแห่งความเกลียดชังลุกโชนและคงอยู่ตลอดไป"
  },
  Voice_6565_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6567_AwakerVoiceContent = {
    Text = "ความตั้งใจที่ฉันหลอมรวมเป็นคนพูดมาก ยิ่งเพิ่มขึ้น เสียงของ「เขา」ก็ยิ่งชัดเจน... เหมือนเป็ดในตลาดนัดที่ส่งเสียงดัง ค่อนข้างรบกวนเลยล่ะ"
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6567_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "ฉันจะใช้พละกำลังนี้กลืนกินการทรยศ."
  },
  Voice_6568_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6569_AwakerVoiceContent = {
    Text = "...ขอบคุณมาก"
  },
  Voice_6569_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6570_AwakerVoiceContent = {
    Text = "ผู้พิทักษ์? ขำขันจริงๆ ความฝันที่ไม่มีวันเป็นจริงนี้ ถึงเวลาตื่นแล้ว"
  },
  Voice_6570_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6571_AwakerVoiceContent = {
    Text = "เลือดแห่งการแก้แค้นกำลังเดือดพล่าน.."
  },
  Voice_6571_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6572_AwakerVoiceContent = {
    Text = "ขยับตัวได้แล้ว ทาส!"
  },
  Voice_6572_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6573_AwakerVoiceContent = {
    Text = "อย่าจมน้ำล่ะ!"
  },
  Voice_6573_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6574_AwakerVoiceContent = {
    Text = "วิ้ววิ้ว!"
  },
  Voice_6574_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6575_AwakerVoiceContent = {
    Text = "ฉันทิ้งกับดักหนูที่หลังประตูโรงอาหารแล้ว มันอันตรายเกินไป ถ้าบราวน์คนขี้ลืมเหยียบเข้าจะทำยังไง！"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "มันรู้สึกแปลกจริงๆ... ฉันกำลังจะตายหรือเปล่า? ไม่ ช่วยฉันด้วย! อย่าทิ้งฉัน!"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6576_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "ฉันอยากได้โคมไฟที่ไม่มีวันดับ แต่เธอดันบอกว่าให้ใช้ “ตัวอย่างสิ่งมีชีวิตไฮดราที่บินได้ทั้งที่ไม่มีปีก” มาแลกเปลี่ยน ฉันจะไปหาสิ่งมีชีวิตประหลาดแบบนี้จากที่ไหนได้ล่ะ！"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "เรื่องราวเกี่ยวกับดาฟเดล"
  },
  Voice_6579_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「ดาฟเดล」ที่ถูกปลุก"
  },
  Voice_6582_AwakerVoiceContent = {
    Text = "อันตราย."
  },
  Voice_6582_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6583_AwakerVoiceContent = {
    Text = "คำเตือน."
  },
  Voice_6583_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6584_AwakerVoiceContent = {
    Text = "ถูกโจมตี."
  },
  Voice_6584_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6585_AwakerVoiceContent = {
    Text = "สมบัติที่เปล่งประกายเหมือนกระดาษห่อขนม... ไอจิสจะเก็บรักษาไว้อย่างดี"
  },
  Voice_6585_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6586_AwakerVoiceContent = {
    Text = "ได้รับความเสียหาย."
  },
  Voice_6586_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6587_AwakerVoiceContent = {
    Text = "ร้านเล็กของฉันสามารถอยู่ในมิติใดๆ ตำแหน่งใดๆ ในจักรวาลได้ และแน่นอนว่าที่นี่ก็เป็นหนึ่งในนั้น นอกจากนี้ ฉันยังชอบเด็กๆ ของมิซากะที่ไม่ค่อยระมัดระวังเท่าไหร่ด้วยนะ?"
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "เกลียด...พริกเขียวกินยากมาก"
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "ความสัมพันธ์ระหว่างผมและคุณ เปรียบเสมือนความสัมพันธ์ระหว่างใบเรือและตัวเรือ หากไม่มีเรือ ใบเรือก็ไม่มีเหตุผลที่จะอยู่ และหากไม่มีใบเรือ เรือก็ยากจะแล่นไปได้ไกล มันไม่ใช่เช่นนั้นหรือ?"
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "ผู้ที่ภักดีต่อการเต้นรำตายไปแล้ว ผู้ที่ดูหมิ่นศิลปะก็ตายไปแล้ว พวกเขาตายอยู่ในเปลวเพลิงที่เต็มไปด้วยกลิ่นควันจากยางมะตอย การตายไม่ใช่จุดจบ แต่เป็นจุดเริ่มต้น เพราะสิ่งที่จะตายไปได้มีแค่มนุษย์เท่านั้น การเต้นรำและศิลปะนั้นเป็นนิรันดร์"
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6590_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "ขอบคุณสำหรับความเข้าใจของคุณ บางทีตอนนี้อาจเป็นเวลาที่จะปรองดองกับตัวเองในอดีตแล้ว... ผมเชื่อว่าสิ่งที่ผมทำอยู่นั้นถูกต้อง ผมไม่เคยทำให้ชื่อเสียงของครอบครัวนักเต้นต้องเสื่อมเสีย ผมจะขึ้นสู่เวทีที่คุณเตรียมไว้ให้ และจะส่องประกายตามที่คุณปรารถนา..."
  },
  Voice_6591_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6591_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6592_AwakerVoiceContent = {
    Text = "ระวังนะ."
  },
  Voice_6592_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6593_AwakerVoiceContent = {
    Text = "เธออยากให้ฉันขึ้นเวทีแล้วส่องประกายบนนั้นหรือเปล่า? \n นี่มันไม่มีทางเป็นไปได้อีกแล้ว ดวงตาคู่นี้ถูกความเกลียดชังกลืนกินจนหมดสิ้น นอกจาการทำลายล้างทุกอย่าง ฉันไม่สามารถทำอะไรได้อีก"
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6593_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "คุณเข้าใจความรู้สึกนั้นไหม? หมุนๆ หมุนไปเรื่อยๆ ไม่มีวันหยุด หัวเข่าที่เกร็งจนปวดล้า ปลายเท้ามีเลือดสีดำซึมออกมา ทำให้รองเท้าบัลเล่ต์เปียกชุ่ม แต่ก็ยังไม่หยุดเลยสักครั้ง... ก็เพราะว่าฉันไม่ยอมรับชะตากรรมที่จะกลายเป็นเครื่องมือของคนอื่น"
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6594_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "คนที่ฉันเผาจนตายไม่ใช่นักเต้นในราชสำนักที่เชี่ยวชาญ ไม่ใช่ผู้ดูแลที่สง่างามแห่งวิหารบัลเลต์ ไม่ใช่ชนชั้นสูงที่รู้จักชื่นชมความสูงส่งและความงาม แต่เป็นคนไร้ความสามารถที่ขายร่างกาย เป็นนายหน้าประจบประแจงที่ไม่แยแสผู้อื่น และเป็นพวกหมกมุ่นในกิเลสตัณหา... เธอจะเข้าใจฉันใช่ไหม?"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6595_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "ฉันไม่ชอบคนที่มีหนวดรยางค์เหนียวๆ แล้วก็ไม่ชอบใต้ทะเล... อย่าทำสีหน้าเหมือนเข้าใจนะ! ฉันไม่ใช่เด็กที่กลัวผู้ปกครอง!"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6596_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "ท่านใจดีมาก ข้ารู้สึกซาบซึ้งอย่างยิ่ง.."
  },
  Voice_6597_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6598_AwakerVoiceContent = {
    Text = "หายไปเถอะ!"
  },
  Voice_6598_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6599_AwakerVoiceContent = {
    Text = "หายไปเถอะ!"
  },
  Voice_6599_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6600_AwakerVoiceContent = {
    Text = "รีบพาบราวน์ออกไป！"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6601_AwakerVoiceContent = {
    Text = "อย่า..."
  },
  Voice_6601_AwakerVoiceTitle = {
    Text = "การป้องกัน·ซึมเศร้า"
  },
  Voice_6602_AwakerVoiceContent = {Text = "ไป!"},
  Voice_6602_AwakerVoiceTitle = {
    Text = "การป้องกัน·คลุ้มคลั่ง"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "เรย่าคือใคร?โอ้ ผู้หญิงที่ขอร้องให้ฉันต่อยเธอ ฮ่าๆ น่าสนใจจริงๆ... ที่นี่ก็ไม่ได้น่าเบื่อไปซะทั้งหมด"
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเรย่า"
  },
  Voice_6603_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「เรย่า」"
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "พระอาทิตย์ตกบนเนินเขาเล็กๆ มักทำให้ฉันนึกถึงวันเวลาที่คลีฟแลนด์... คลีฟแลนด์ ฉันยังจำชื่อนี้ได้อยู่เลย สถานที่ที่ทำให้ฉันมีรอยแผลเป็นเหล่านี้.."
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับยามเย็น"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "อา...ดวงดาวนับพัน...ตกลง.."
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "ไม่มีข้อสงสัยเลยว่าเป็นมนุษย์ มีสิ่งมีชีวิตใดบ้างที่จะสกปรกกว่ามนุษย์ได้?"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6607_AwakerVoiceContent = {
    Text = "ตอนนี้แหละ!"
  },
  Voice_6607_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6608_AwakerVoiceContent = {Text = "เฮ้!"},
  Voice_6608_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_6609_AwakerVoiceContent = {
    Text = "การหลอมกร่อน? ฮืม... ใช่แล้ว! ไอศกรีมจะละลาย! แต่ถ้าเราแบ่งกันกิน ก็สามารถกินให้หมดก่อนที่มันจะกลายเป็นครีมได้นะ!"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "ผมจะใช้พละกำลังนี้ปกป้องคุณ."
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6610_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "อ้าว สินค้าที่ขายออกจากทางร้านนี้ไม่สามารถคืนหรือเปลี่ยนได้นะ? ถ้าอยากจะดำดิ่งสู่ทะเลลึก จริงๆ แล้วก็ต้องใช้เรือดำน้ำใช่ไหม?"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเคคอส"
  },
  Voice_6611_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่น「เคคอส」"
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "เวทีที่ยอดเยี่ยมที่สุด! คณาจารย์และนักศึกษาในมหาวิทยาลัยมิซากะต่างเข้าใจว่า การแสดงของฉันคือเวทมนตร์ที่แท้จริง! นี่คงจะเป็นความเข้าใจอันดีของผู้ชมสำหรับนักมายากลใช่ไหม?"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "ระเบียบของจักรวาลเปลี่ยนแปลงที่นี่；อนาคตแห่งการทำลายคือความเชื่อของผู้ใช้เวทมนตร์!"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_6613_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "สามารถให้ไอจิสอยู่ที่นี่อีกสักครู่ได้ไหม? ฉันจะเงียบ ๆ ไม่ทำเสียงใด ๆ และจะไม่รบกวนคุณเลย.."
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6614_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "ด้วยสติปัญญาของมนุษย์... เปิดเผยแก่นแท้ของโลก!"
  },
  Voice_6615_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6616_AwakerVoiceContent = {
    Text = "ในความฝันของฉัน มักจะได้ยินเสียงคลื่น ซึ่งเสียงนั้นไกลออกไปเรื่อยๆ ไกลออกไปเรื่อยๆ ฉันรู้ว่า บางทีฉันอาจจะต้องอยู่ที่นี่ตลอดไปแล้ว มนุษย์ที่ข้ารัก."
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับทะเลลึก"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "ความทรงจำมากขึ้น อารมณ์มากขึ้น ความฝันมากขึ้น——"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6617_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6618_AwakerVoiceContent = {
    Text = "เริ่มเปลี่ยนแล้ว!"
  },
  Voice_6618_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6619_AwakerVoiceContent = {
    Text = "อย่ากระพริบตาล่ะ!"
  },
  Voice_6619_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_6620_AwakerVoiceContent = {
    Text = "เมื่อพระองค์ประสูติ... ข้าก็จะไม่ต้องทนทุกข์กับความอัปยศนี้อีกต่อไป.."
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "เลือกฉัน เลือกฉัน！ที่ไหนมีปาร์ตี้ ที่นั่นมีคาเรน！"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "อืม? สนใจในตัวฉันเหรอ? คิดว่า...คุณคงพร้อมที่จะจ่ายราคาที่ต้องจ่ายแล้วสินะ?"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "ไม่ให้อภัย ไม่ให้อภัย...!"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "ยังขับขานถึงสีสันอันลี้ลับจากดวงดาว"
  },
  Voice_6624_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6625_AwakerVoiceContent = {
    Text = "ร้องเพลงเถอะ ร้องเพลงเถอะ！"
  },
  Voice_6625_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_6626_AwakerVoiceContent = {
    Text = "ชอบแม่!"
  },
  Voice_6626_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6627_AwakerVoiceContent = {
    Text = "มาเลย."
  },
  Voice_6627_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6628_AwakerVoiceContent = {
    Text = "ระวังนะ."
  },
  Voice_6628_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_6629_AwakerVoiceContent = {
    Text = "ร่างกายที่ตื่นขึ้นอาจกินอาหารเพราะความอยากรู้อยากเห็น แต่อาหารไม่ใช่สิ่งจำเป็นสำหรับการคงอยู่ของเรา ดังนั้นไม่ต้องเรียกฉันทุกครั้งที่มีน้ำชาตอนบ่าย การบริโภคน้ำตาลจะทำให้ข้อต่อทรงกลมของร่างกายเสื่อมสภาพเร็วขึ้น"
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "เรื่องสนทนา·เกี่ยวกับน้ำชายามบ่าย"
  },
  Voice_6632_AwakerVoiceContent = {
    Text = "โปรดไว้ชีวิตนายท่านด้วย! คาเรน... คาเรนยอมให้พวกท่านทำอะไรก็ได้!"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "เหล่านี้ ลิลลี่สามารถกินได้ทั้งหมดไหม?"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6633_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "เกลียดเหรอ? ฉันพูดได้ไหม ไอจิสรู้สึกแย่ที่ไม่สามารถทำอะไรได้ตลอดเวลา... แต่ถ้าฉันพูดแบบนี้ เจนกินจะโกรธมาก ๆ.."
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "กลายเป็นเถ้าถ่านเสีย"
  },
  Voice_6635_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_6636_AwakerVoiceContent = {
    Text = "กลายเป็นเถ้าถ่านเสีย"
  },
  Voice_6636_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6637_AwakerVoiceContent = {
    Text = "ทำได้ดีมาก ผู้พิทักษ์ เอาล่ะ ครั้งนี้จะให้ฉันไปฆ่าใครแทนเธอ?"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6637_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "การหลอมกร่อนคือเหตุผลที่สถาบันนี้ถูกก่อตั้งขึ้น และก็เป็นเหตุผลที่เราได้พบกัน เพื่อช่วยชีวิตมนุษยชาติจากเงื้อมมือของการหลอมกร่อน สู้ๆ นะ คู่หู."
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "ฉันสัมผัสได้ถึงความเป็นศัตรูจากคุณหนูคนนั้น คงเป็นเพราะความรักที่ข้ามีต่อท่านทำให้เธออิจฉากระมัง... ท่านดูสิ แม้แต่นกทะเลใหญ่ยังอ้าปากอิจฉาเลย"
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับโรแทน"
  },
  Voice_6639_UnlockDesc = {
    Text = "ปลดล็อกหลังจากรับร่างกายที่ตื่น「โรแทน」"
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "เจ้านาย! วันนี้คาเรนเห็นเข็มกลัดคาเมโอที่สวยมากๆ——ที่ห้างฮาร์โรลด์เลย! เจ้านายจะซื้อให้คาเรนได้ไหม? นี่คือคำขอครั้งเดียวในชีวิตของฉัน!"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "ฉันจะเป็นเหมือนเข็มทิศในความมืดให้กับคุณ แต่ระยะเวลาดังกล่าวนี้ไม่ใช่ตลอดไป"
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "แม่ ปวดมากเลย แม่.."
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "ยอมแพ้ซะ! ชัยชนะเป็นของฉันอยู่แล้ว!"
  },
  Voice_6643_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_6644_AwakerVoiceContent = {
    Text = "ยอมแพ้ซะ! ชัยชนะเป็นของฉันอยู่แล้ว!"
  },
  Voice_6644_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6645_AwakerVoiceContent = {
    Text = "การหลอมกร่อน... ความจุสมองของฉันมีจำกัด ไม่สามารถเข้าใจโรคที่ซับซ้อนขนาดนั้นได้... ถ้ามีเครื่องจักรที่ต้องซ่อมแซมค่อยมาหาฉันนะ!"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "อ๊ะ! ออรีตาถูกพบแล้ว! ในฐานะที่เป็นการลงโทษสำหรับการแพ้ คุณสามารถขอให้ออรีตาทำอะไรก็ได้หนึ่งอย่าง —— แต่อย่าให้ออรีตาไปเรียนนะ ขอร้องจริงๆ ——"
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "เพื่อเปิดทางสำหรับการเสด็จมาของพระองค์อีกครั้ง.."
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "สักวันหนึ่ง ลุงอาอินจะมาต้อนรับฉันกลับบ้านใต้ทะเล ในระหว่างนี้ ถ้าจำเป็นก็ยินดีคบหาเป็นเพื่อนกับเธอก่อน"
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6648_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = "“ในตระกูลของเราไหลเวียนไปด้วยโลหิตที่ยิ่งใหญ่ ผู้ที่ถูกเลือกโดยพรหมลิขิตจะได้รับความสงบสุขตลอดนิรันดร์ในทะเลลึก” \n ไม่นึกเลยว่าหลังจากออกจากทะเลมาเรียนที่สถาบัน ฉันกลับพบกับความสงบสุขนี้ คุณต่างจากคนที่เคยกลั่นแกล้งฉัน ดังนั้นฉันจะไม่ยอมให้ใครมาทำร้ายคุณเด็ดขาด"
  },
  Voice_6649_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6649_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "วัสดุพิเศษที่แข็งมาก!"
  },
  Voice_6650_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6651_AwakerVoiceContent = {
    Text = "การติดอยู่ในเปลือกที่ผสมด้วยส่วนของมนุษย์นี่ทำให้ฉันรู้สึกไม่สบายใจจริงๆ เพิ่งจะหลุดพ้นจากอดีตได้ แต่ตอนนี้กลับต้องระลึกถึงมันอีกแล้ว.."
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6651_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "ฉันรู้ว่าผู้สืบสายเลือดศักดิ์สิทธิ์ได้กลายเป็นทาสรับใช้มนุษย์อีกครั้ง แต่คุณก็อย่าหวังว่าจะสามารถควบคุมฉันได้ตามใจชอบ"
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6652_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "หึ มนุษย์ที่ดูบอบบางอย่างเจ้ากลับมีความสามารถในการสั่งการไม่น้อย แต่ร่างกายที่ไม่สมบูรณ์นี้ทำให้ข้าใช้พลังไม่เต็มที่"
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6653_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "ร่างกายร้อนขึ้นเรื่อยๆ."
  },
  Voice_6654_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6655_AwakerVoiceContent = {
    Text = "หนี...ต้องหนี! ต้องหนีออกไปจากที่นี่!"
  },
  Voice_6655_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6656_AwakerVoiceContent = {
    Text = "หนี...ต้องหนี! ต้องหนีออกไปจากที่นี่!"
  },
  Voice_6656_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_6657_AwakerVoiceContent = {
    Text = "ขอบคุณสำหรับความพยายามของคุณ งั้นขอให้ฉันมอบรางวัลพิเศษให้กับคุณด้วยเถอะ"
  },
  Voice_6657_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6658_AwakerVoiceContent = {
    Text = "ไม่เป็นไร"
  },
  Voice_6658_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6659_AwakerVoiceContent = {
    Text = "(เสียงครางด้วยความเจ็บปวด)"
  },
  Voice_6659_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6660_AwakerVoiceContent = {
    Text = "มนุษย์ เจ้าแม้จะอ่อนแอ แต่ความเชื่อมั่นของเจ้าทำให้ข้าประทับใจ ข้ายินดีเป็นอาวุธของเจ้า ไปสร้างความวุ่นวายด้วยกันเถอะ!"
  },
  Voice_6660_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6660_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "นี่คือสถานที่พบปะสังสรรค์ของฉัน"
  },
  Voice_6662_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6664_AwakerVoiceContent = {
    Text = "สถาบันที่ทุกคนเท่าเทียมกัน... ไม่รู้ว่าพวกคุณมีความฝันที่โง่แค่ไหน แม้ว่าคุณจะไม่ได้ทำผิดอะไรเลย พวกเขาก็จะเหยียบคุณไว้ใต้ฝ่าเท้า ผมรู้ดีว่าความรู้สึกนั้นมันเป็นอย่างไร"
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "นี่คือรากเหง้าของความไม่บริสุทธิ์ทั้งมวล.."
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·ซึมเศร้า"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "ฉันเคยถูกลงโทษเพราะไม่สามารถปกป้องลูกเรือได้ พวกเขาบอกว่า เนื่องจากความประมาทของฉัน ลูกเรือที่หายไปจะไม่มีวันได้กลับไปพบครอบครัวอีก... การหลอมกร่อนก็เป็นเช่นนี้หรือ?"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "เข้าใกล้ผู้เป็นนายของข้ามากขึ้นอีกหน่อย.."
  },
  Voice_6667_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6668_AwakerVoiceContent = {
    Text = "ทำไม? ท่านทำไม...ไม่ยอมตื่นขึ้นมา?"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "ฉันคือออร์ล่าแห่งสีไค นามปากกา... เคยสัญญากับใครคนหนึ่งว่าจะไม่บอกชื่อจริง ขอโทษนะ แต่เรียกฉันว่าออร์ล่าก็พอ"
  },
  Voice_6669_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6670_AwakerVoiceContent = {
    Text = "ฉันต่อต้านทุกการกระทำที่ไม่ยุติธรรม โดยเฉพาะอย่างยิ่ง การทรยศ ในการรับราชการทหาร หากไม่สามารถหรือไม่กล้าส่งหลังให้เพื่อนร่วมทีมได้ ทั้งกองกำลังจะกลายเป็นดินทรายที่ไม่มีความเป็นหนึ่งเดียว"
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "ทำไมคุณถึงดูมืดสนิท แต่กลับสว่างมากเช่นนี้?...ไม่ เปล่าหรอก แค่คิดว่าฉันคงพูดเพ้อเจ้อไปเท่านั้น."
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_6672_AwakerVoiceContent = {
    Text = "(เสียงร้องเจ็บปวด)"
  },
  Voice_6672_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6673_AwakerVoiceContent = {
    Text = "(เสียงครางอย่างอดทน)"
  },
  Voice_6673_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6674_AwakerVoiceContent = {
    Text = "อะไรนะ?!"
  },
  Voice_6674_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6675_AwakerVoiceContent = {
    Text = "ฉันรักชีวิต รักแสงสว่าง อยากให้ฟีนต์ก้าวออกมาจากเปลือกที่ปิดล้อม ใช้ประสาทสัมผัสทั้งหมดของเขาเพื่อรับรู้โลกใบนี้"
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "มองไม่เห็นฉัน!"
  },
  Voice_6676_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6677_AwakerVoiceContent = {
    Text = "งานบำรุงรักษาจำเป็นต้องดำเนินการต่อหรือไม่?"
  },
  Voice_6677_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6678_AwakerVoiceContent = {
    Text = "การจัดเตรียมชิ้นส่วนได้เสร็จสิ้นแล้ว."
  },
  Voice_6678_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6679_AwakerVoiceContent = {
    Text = "มนุษย์อาจมีใจที่จะทรยศ แต่เครื่องมือไม่มี. หากใช้ให้ถูกวิธี การหลอมกร่อนก็เป็นเครื่องมือสำหรับการแก้แค้นได้เช่นกัน."
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "การรอคอยที่ซ่อนตัวอยู่เป็นเวลาพันปี ในที่สุดก็มาถึงในขณะนี้... ข้าคือผู้ปกครองเพียงหนึ่งเดียวของชาวฟีลิสเตีย！"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_6680_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "เมื่อกี้ที่เดินผ่านไปนั่นคือลูกผสมจากทะเลลึกหรือเปล่า? ฮืม... ดูสิ หลังตรงเชียว คืนนี้ข้าจะต้องเห็นเขาทรุดลงกับพื้นแน่"
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเคคอส"
  },
  Voice_6681_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่น「เคคอส」"
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "พละกำลังค่อยๆ กลับมาสู่มือของฉัน... ขั้นต่อไป ฉันจะยึดอำนาจที่เป็นของฉันกลับมาอย่างแน่นอน!"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6682_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "ค่อนข้างดี ขยับเข้าใกล้อีกก้าวในการกระชากผ้าคลุมหน้าปลอมของผู้หญิงคนนั้นอย่างแรง"
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_6683_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "ใจเย็นๆ ใจเย็นๆ ใจเย็นๆ.."
  },
  Voice_6684_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_6685_AwakerVoiceContent = {
    Text = "ไม่ต้องกังวล ผมทนความเจ็บปวดได้มากกว่าที่พวกคุณคิด"
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6685_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "ถ้าให้ฉันพูดนะ ของสวยๆ ที่น่ารักแต่ขี้เล่นน่ะดีที่สุดแล้ว เสียดายที่ที่นี่เต็มไปด้วยสมองที่ฉลาดแต่ไร้ประโยชน์"
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "ใช้ปฏิกิริยานิวเคลียร์ฟิวชันของดาวยักษ์แดงเป็นพลังงาน รวมกับพลังงานที่เกิดขึ้นเมื่อดาวฤกษ์ยุบตัว ก็จะสามารถเริ่มต้นเครื่องยนต์ทำงานตลอดกาลและจุดไฟดวงนิรันดร์ได้... เอ๋? เธอบอกว่า ที่นี่ไม่มีเงื่อนไขในการสร้างเครื่องยนต์ทำงานตลอดกาล และก็ไม่มีดาวยักษ์แดงเหรอ? อืม.."
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "เลือดของศัตรูยังไม่หมดสิ้น"
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "มอบพวกมัน...ให้ข้าทั้งหมด!"
  },
  Voice_6689_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6690_AwakerVoiceContent = {
    Text = "มอบพวกมัน...ให้ข้าทั้งหมด!"
  },
  Voice_6690_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6691_AwakerVoiceContent = {
    Text = "ถึงเวลาแล้วที่จะไปสู่สนามรบ."
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6692_AwakerVoiceContent = {
    Text = "ถึงเวลาแล้ว!"
  },
  Voice_6692_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_6693_AwakerVoiceContent = {
    Text = "ขณะที่หยูหลับอยู่ ความฝันที่ล้นออกจะทำให้วิญญาณปั่นป่วน เพราะฉะนั้น อย่าเข้าใกล้ตอนที่หยูหลับสนิท และอย่าปลุกหยูแบบไม่คิด"
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับการหลับใหล"
  },
  Voice_6694_AwakerVoiceContent = {
    Text = "ถึงเวลาแล้ว!"
  },
  Voice_6694_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6695_AwakerVoiceContent = {
    Text = "แม้ว่าเฮอร์เบิร์ตจะเป็นคนที่น่ากลัว แต่แมวของเขาช่างอ่อนโยน... ไม่สิ ถ้าพูดให้ถูกต้องควรจะเป็นแมวสองตัวใช่ไหม?"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับเฮอร์เบิร์ต"
  },
  Voice_6695_UnlockDesc = {
    Text = "ผ่านด่าน「การสอบสวนดำเนินการ」บทที่ 2 แล้วปลดล็อก"
  },
  Voice_6696_AwakerVoiceContent = {
    Text = "ผู้หญิงที่ชื่อมอร์ฟี่นี่แต่งตัวอลังการไปหน่อยไหม... ไม่ได้การแล้ว คาเรนห้ามแพ้เธอเด็ดขาด!\nหรือว่าจะฆ่าทิ้งไปเลยดีกว่า.."
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับมอร์ฟี่"
  },
  Voice_6696_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「มอร์ฟี่」ร่างกายที่ตื่นขึ้น"
  },
  Voice_6697_AwakerVoiceContent = {Text = "ยา~"},
  Voice_6697_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6698_AwakerVoiceContent = {
    Text = "สบายไหม?"
  },
  Voice_6698_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6699_AwakerVoiceContent = {
    Text = "ตอนที่ทำข้อตกลงกับมหาวิทยาลัยมิซากะ บอกชัดเจนแล้วว่าจะไม่ให้ฉันไปการต่อสู้.."
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6699_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "อย่าเหลิงจนลืมตัวเลย บางครั้งความสูงส่งกับความต่ำช้าอาจใกล้กันแค่เพียงก้าวเดียว"
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_6700_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "ฟาร์โรสขอทักทายท่าน มาเรียกข้ามาที่นี่ แสดงว่าคงจะเตรียมพร้อมสำหรับการเดินทางแล้วใช่ไหม."
  },
  Voice_6701_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_6702_AwakerVoiceContent = {
    Text = "ยี้ฮู——เหนื่อยมากเลย ไปเล่นได้ไหม!"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "อาห์... แสงสว่างของเขาช่างร้อนแรงและเจิดจ้าจนไม่อาจละสายตาได้ มันคือความหลงผิดที่บดบังสติของข้า... ไม่ ข้าไม่ควรหาเหตุผลมาแก้ตัวให้กับความโง่เขลาของตนเอง.."
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับตูรู"
  },
  Voice_6703_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ตูรู」"
  },
  Voice_6705_AwakerVoiceContent = {
    Text = "ดวงดาวในความฝันที่หลับลึก ไปยังที่ควรไป และชี้ทางสู่ดินแดนสวรรค์!"
  },
  Voice_6705_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6706_AwakerVoiceContent = {
    Text = "เธอไม่คิดเหรอว่า การนำพาทุกสรรพสิ่งไปสู่จุดจบ และหยุดยั้งกฎเกณฑ์ของโลกไม่ให้ดำเนินต่อไป มันช่างน่าทึ่งไม่น้อยเลยใช่ไหม?"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6707_AwakerVoiceContent = {
    Text = "ดื่มสิ！"
  },
  Voice_6707_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6708_AwakerVoiceContent = {
    Text = "สะใจ!"
  },
  Voice_6708_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_6709_AwakerVoiceContent = {
    Text = "กรุณาป้อนคำสั่งการต่อสู้."
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "ในวันที่ฉันลอยเคว้งระหว่างดวงดาว ฉันฝันถึงวันนี้นับครั้งไม่ถ้วน... ขอบคุณที่ทำให้ฉันได้พบกับทิงค์เทตอีกครั้ง"
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับทิงค์เทต"
  },
  Voice_6710_UnlockDesc = {
    Text = "หลังจากได้รับร่างกายที่ตื่นขึ้น 「ทิงค์เทต」แล้ว จะปลดล็อก"
  },
  Voice_6711_AwakerVoiceContent = {
    Text = "มหาวิทยาลัยมิซากะเป็นสถานที่ที่ดีจริงๆ เลยนะ โดยเฉพาะคาสิโนใต้ดินที่เปิดทุกสัปดาห์...\nเฮ้ คุณไม่รู้เหรอ? โอ้ ฉันเผลอพูดออกไปหรือเปล่า.."
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "「การต่อต้านวิกฤตการหลอมกร่อน」 ฮะ ความพึงพอใจในตัวเองของมนุษย์ ตลกจนน่าขันจริงๆ"
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับมหาวิทยาลัยมิซากะ"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "พูดในที่สุดแล้ว มนุษย์ก็เป็นเพียงสัตว์ที่ตื้นเขินชนิดหนึ่งเท่านั้น แค่ไม่กี่คำพูด นัยบางอย่าง ก็สามารถกระตุ้นให้เกิดการต่อสู้กันได้... เฮ้อ ระดับนี้ไม่อาจทำให้ใครรู้สึกจิตใจตื่นเต้นได้หรอก"
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับมนุษย์"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "บางที การมองว่าเธอเป็นมนุษย์ธรรมดาอาจเป็นเพราะสายตาของฉันคับแคบและตัดสินไปก่อนแล้ว ฉันอยากรู้จริงๆ ว่าคนอย่างเธอที่ไม่มีศรัทธาสามารถยึดมั่นในป้อมปราการของตัวเองได้อย่างไร? นี่ไม่ใช่การซักถามของพระแม่แห่งท้องทะเล แต่เป็นคำถามของมิลียาห์ม เธอจะ...ตอบคำถามนี้ให้ฉันได้ไหม?"
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6714_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "เธอที่พิเศษเช่นนี้ จะไม่รู้สึกเบื่อหน่ายกับโลกที่วุ่นวายและไร้สาระหรือ? ข้าเชื่อจากใจจริงว่า ดินแดนนิรันดร์คือที่พำนักของเธอ เธอจะได้เดินบนผืนดินของเทพ ล่องลอยในสระแห่งวิญญาณศักดิ์สิทธิ์ และหยั่งรากในแผ่นดินอันอุดมสมบูรณ์... มาร่วมในศีลธรรมอันบริสุทธิ์ของข้า แล้วเราจะอยู่เหนือโลกีย์ร่วมกัน ในเวลานั้น เราจะยืนเคียงข้างบัลลังก์ และแบ่งปันความยินดีในการสร้างสวรรค์ใหม่.."
  },
  Voice_6715_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_6715_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "ท่านและข้าพเจ้าต่างก็เป็นเพียงคนธรรมดาที่ไร้ความสามารถในโลกีย์ แต่ผู้ศักดิ์สิทธิ์นั้นไม่ใช่เช่นเรา ท่านคือผู้แทนของเทพ และเป็นการปรากฏของเทพเจ้าบนโลกมนุษย์ คำแนะนำของท่านช่างเหมือนถ้อยคำจากสวรรค์ ปลุกให้โลกตื่นรู้ และนำพาอารยธรรมไปสู่ความเป็นอมตะ ข้าพเจ้าไม่ได้หวังว่าท่านจะเข้าใจความศรัทธานี้ในตอนนี้ แต่วันหนึ่งท่านจะยอมสยบต่อใต้บัลลังก์แห่งท่าน"
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6716_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "ผู้ที่ได้รับการอัญเชิญนั้นเป็นผู้ที่โชคดี คุณไม่คิดเช่นนั้นหรือ? พวกเขาได้รับพลังแห่งเทพ และมีชีวิตที่ยืนยาวขึ้น เมื่ออาณาจักรของพระเจ้าการปรากฏตัวอีกครั้ง และพระประสงค์ของพระองค์ได้ดำเนินบนโลกใบนี้ พวกเขาจะกลายเป็นผู้ศรัทธาที่ทรงเกียรติ นี่ไม่ใช่ความโชคดีและความสุขอย่างยิ่งสำหรับมนุษย์ที่อ่อนแอหรอกหรือ?"
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6717_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "ความปีติยินดีที่ได้รับแสงสว่างจากพระเจ้านั้น ผู้ที่ไร้ศรัทธาเช่นเธอย่อมไม่อาจเข้าใจได้... ขอพระเจ้าของข้าทรงอภัยให้เธอ โปรดอภัยความไร้การรู้และความหยาบคายของเธอ..."
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6718_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "รีบจบเร็วเข้าเถอะ ผู้พิทักษ์."
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6720_AwakerVoiceContent = {
    Text = "เอ๋ย——"
  },
  Voice_6720_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_6720_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "ไปตายซะ ไอ้แมลงสาบสปาร์ตา"
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "คุณหนูดอร์บอกว่า ฉันสามารถหลีกเลี่ยงการหลอมกร่อนชั่วคราวได้เหมือนเธอ โดยการทิ้งร่างกายไป... ทำไม่ได้ ทำไม่ได้ ทำไม่ได้ ตอนผ่าตัดจะสลบไป และความมืดจะเข้ามา.."
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับดอร์"
  },
  Voice_6722_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ดอร์」"
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "หึ... อะไร? อยากให้ชะตากรรมแห่งการลืมเลือนมาถึงแล้วหรือ?"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "เจ้านายยังคงมีปัญหาเรื่องการนอนไม่หลับอยู่หรือเปล่า? คาเรนเตรียมยานอนหลับสูตรพิเศษไว้ให้แล้วนะ~! ถึงแม้ว่าปริมาณยาจะเกินกว่ากำหนดไปหน่อย แต่การนอนหลับที่ดีต่างหากที่สำคัญที่สุด!"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_6724_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "ตอนนั้นพวกเราดื่มเหล้าเล็กน้อย ร้องเพลงไปพลางๆ แล้วอยู่ดีๆ ก็ถูกเปลี่ยนเป็นสัตว์ประหลาดซะงั้น! แต่ไม่เป็นไร ผิวเขียวๆ ก็ดูสนุกดีนะ!"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_6725_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "ความฝันของคาเรน? อืม... ซื้อสร้อยไข่มุกสวยๆ แล้วใส่มันไปงานเต้นรำ เป็นดาวเด่นที่สุด!"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_6726_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "ตัวตนที่ใฝ่หาอย่างทิฟเฟรเยส์โซด์ เธอก็ได้แสวงหาหนทางแห่งการคงอยู่ของตนเอง ในหน้าของสิ่งที่ไม่รู้จัก ไม่มีใครสามารถตัดสินได้ว่าแนวทางนั้นสูงส่งหรือต่ำช้า"
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับมวลแห่งความปรารถนา"
  },
  Voice_67276_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「ไทอีส」"
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "ข้ามผ่านประตูแห่งกุญแจเงิน สู่บัลลังก์ของพระองค์"
  },
  Voice_67277_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_67278_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_67279_AwakerVoiceContent = {
    Text = "อย่าทำให้ความรู้และความทรงจำของพระองค์ต้องสูญเปล่า"
  },
  Voice_67279_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6727_AwakerVoiceContent = {
    Text = "ซ้ายเช็ดๆ ขวาเช็ดๆ ปัดฝุ่นปัญหาให้หมดสิ้น——"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_6727_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_67280_AwakerVoiceContent = {
    Text = "ฉันไม่อยู่ที่นี่"
  },
  Voice_67280_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_67281_AwakerVoiceContent = {
    Text = "ชิ้นส่วนหนึ่งในกาลเวลาและปริภูมิที่ไม่มีที่สิ้นสุดได้ปรากฏตัวในจิตสำนึกของข้า"
  },
  Voice_67281_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_67282_AwakerVoiceContent = {
    Text = "ฉันได้เห็นภาพรวมทั้งหมดแล้ว."
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "ทุกอย่างอยู่ในความว่างเปล่า"
  },
  Voice_67283_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_67284_AwakerVoiceContent = {
    Text = "คุณได้เดินทางมาลึกซึ้งและไกลโพ้นแล้ว อีกไม่นาน คุณจะได้สัมผัสกับความมหัศจรรย์ที่ไม่ธรรมดา หวังว่าตอนนั้นคุณจะยังคงรักษาสติและความสงบอย่างที่เป็นอยู่ในตอนนี้ได้"
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_67284_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "「ความไม่รู้」 ไม่เลย การค้นหาอย่างไม่รู้จักเหน็ดเหนื่อยโดยเนื้อแท้แล้วไม่ใช่ความไม่รู้ ผู้ที่แท้จริงไร้การศึกษานั้นใช้ชีวิตอยู่ในความคลุมเครือ จนกระทั่งไม่อาจรับรู้ได้แม้แต่ว่าตนเองไม่รู้อะไร"
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "ฉันจะแสดงความฝันของฉันให้คุณดู สิ่งที่คุณเห็นในความฝัน ทั้งความแปลกประหลาดและความวุ่นวาย ล้วนใกล้เคียงกับแก่นแท้ของโลกมากกว่าสิ่งที่คุณรับรู้ว่าเป็นความจริง."
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_67286_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "นี่คือคำแนะนำให้ท่าน: อย่าใจร้อน หากท่านรู้สึกเหนื่อยล้า ให้พักผ่อนทันทีและรักษาพลังงานไว้ มิฉะนั้น ท่านอาจหลงทาง และไม่สามารถกลับจากความฝันได้"
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_67287_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "จักรวาลหมุนเวียนไม่หยุด."
  },
  Voice_67288_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_67289_AwakerVoiceContent = {
    Text = "การประสานจูนระหว่างเธอกับฉันไม่จำเป็นต้องใช้เวลานานขนาดนี้ แต่เพื่อปกป้องสติปัญญาของเธอจากภาพลวง ฉันจะค่อยๆ ทำไปทีละขั้น"
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_67289_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "การหลอมกร่อนนั่นน่ะ... บังเอิญว่าฉันก็เคยรับผิดชอบคดีที่เกี่ยวข้องกับมันเหมือนกัน แต่จะว่าอย่างไรดี? ฉันคิดว่าการหายไปก็เป็นเรื่องธรรมชาติอย่างหนึ่งนะ สุดท้ายแล้ว ทุกคนล้วนจะต้องหายไปในที่สุด"
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "ประตูแรก จักรวาลไร้ขอบเขตเกิดขึ้นจากจุดหนึ่ง."
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_67290_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "ประตูที่สอง จุดที่เส้นลากยาวออกไป สู่ขั้วสองด้านอันไม่มีที่สิ้นสุด"
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_67291_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "ประตูที่สี่ ต้นแบบนิรันดร์แข็งตัวอยู่ในมิติแห่งหนึ่ง."
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_67292_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "ประตูที่สาม ระนาบเป็นคำสรรพนามที่จำกัดและไม่สมบูรณ์"
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_67293_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "ประตูสุดขอบฟ้า ลิงก์จักรวาลนับหมื่นนับพัน สู่ความว่างเปล่าอันเป็นที่สุด การก้าวข้ามประตูสุดขอบฟ้า ความลับสุดท้ายของโลกจะเผยต่อหน้าคุณ."
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_67294_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "ประตูที่ห้า การเปลี่ยนแปลงของเวลาเป็นเพียงภาพลวงตาของคุณ โลกนี้ไม่เคยมีจุดเริ่มต้น จึงไม่มีจุดสิ้นสุด"
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_67295_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "ข้าควรจะเป็นเพียงผู้ชี้แนะของเจ้า หลังจากนำทางให้เจ้าเริ่มต้นการเดินทางครั้งนี้แล้ว ข้าก็จะหลับใหลในสระน้ำที่เลือนลางนั้น บัดนี้ เจ้าคือผู้ลิงก์ของข้า ความสัมพันธ์ระหว่างเราทั้งสองได้ถักทอจนแน่นแฟ้นและซับซ้อน ยากที่จะตัดขาด.."
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "เธอต้องการยืนยันอะไรหรือเปล่า? น่าเสียดายที่ร่างกายนี้ถูกจำกัดและควบคุมด้วยข้อจำกัดมากมาย หากเราพบกันในเหว ข้าจะพาเธอไปสัมผัสสิ่งที่มากกว่านี้.."
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "เธอก็เป็นหนึ่งในชิ้นส่วนของฉัน มาจากมิติอื่น โลกที่ถูกทำลายไปตลอดกาล แม้เธอจะเข้าใจวิธีย้อนเวลา แต่ไม่อาจเข้าใจแก่นแท้ของการก้าวข้ามเวลาและพื้นที่ได้ ทำให้จมอยู่ในความทุกข์ซ้ำๆ นี่คือความผิดของฉัน"
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับการเดินทางรอบรามอน่า"
  },
  Voice_67298_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างตื่น「ฮวนนิ่ง·รามอน่า」"
  },
  Voice_67299_AwakerVoiceContent = {
    Text = "ฉันรู้."
  },
  Voice_67299_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_6729_AwakerVoiceContent = {
    Text = "คุณกังวลเรื่องร่างกายนี้อยู่หรือเปล่า? โปรดอย่าคิดมาก ผมเกิดมาพร้อมกับใบหน้ามนุษย์นะ"
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_67300_AwakerVoiceContent = {
    Text = "ฉันเห็น."
  },
  Voice_67300_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_67301_AwakerVoiceContent = {
    Text = "ช่างเล็กน้อยจริงๆ"
  },
  Voice_67301_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_67302_AwakerVoiceContent = {
    Text = "จงรักษาสติ"
  },
  Voice_67302_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_67303_AwakerVoiceContent = {
    Text = "ลิงก์โดยตรงกับพลาสมาจะทำลายสติปัญญาของคุณ... แต่ เนื่องจากเจ้ามั่นใจเช่นนี้ ข้าจะตอบรับเสียงเรียกของเจ้าอย่างแน่นอน"
  },
  Voice_67303_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_67304_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_67305_AwakerVoiceContent = {
    Text = "เด็กคนนั้น ได้แบกรับชิ้นส่วนของจิตสำนึกของฉันไปมากเกินกว่าที่เธอควรจะรับไหว โชคดีที่วิญญาณของเธอยังคงใสสะอาดเหมือนเงินที่ไหลลื่น.."
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "เกร็ดเล็กเกร็ดน้อย·เกี่ยวกับรามอน่า"
  },
  Voice_67305_UnlockDesc = {
    Text = "ปลดล็อคเมื่อได้รับร่างกายที่ตื่นขึ้น「รามอน่า」"
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "เยี่ยมชมความฝันของพระองค์ เพื่อค้นพบความลับแห่งจักรวาลที่เป็นข้อห้าม."
  },
  Voice_67306_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_67307_AwakerVoiceContent = {Text = "อืม"},
  Voice_67307_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_67308_AwakerVoiceContent = {
    Text = "ประตูสุดท้ายได้เปิดออกสำหรับคุณแล้ว เตรียมพบกับโลกที่เงียบงันหลังจากประตูนั้น"
  },
  Voice_67308_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_67308_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "จุดประสงค์ที่ฉันและพวกเขาสร้างโรงเรียนนี้ขึ้นมาคือเพื่อ「เก็บรักษาไว้」สิ่งที่พวกคุณทำได้นั้นเกินกว่าที่ฉันคาดการณ์ไว้"
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "การหลอมกร่อนคือของขวัญจากพระเจ้า มันนำมาซึ่งความเจ็บปวดพอดี แค่พอจะทำให้ประสาทของเราชาบ เพลิดเพลินอย่างเต็มที่ไปกับอาหารและไวน์ จากนั้นเราจะร่วมกันเฉลิมฉลอง และก้าวสู่หายนะ."
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "เรื่องราว·เรื่องการหลอมกร่อน"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "อดีต, ปัจจุบัน และอนาคต แสงแห่งความรุ่งโรจน์นับล้านล้วนรวมกันอยู่ที่นี่!"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "อดีต, ปัจจุบัน และอนาคต แสงแห่งความรุ่งโรจน์นับล้านล้วนรวมกันอยู่ที่นี่!"
  },
  Voice_67311_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_67312_AwakerVoiceContent = {
    Text = "ประตูสุดท้ายได้เปิดออกแล้ว ณ ที่นี้ สรรพสิ่งกลับคืนเป็นหนึ่งเดียว!"
  },
  Voice_67312_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_67313_AwakerVoiceContent = {
    Text = "ประตูสุดท้ายได้เปิดออกแล้ว ณ ที่นี้ สรรพสิ่งกลับคืนเป็นหนึ่งเดียว!"
  },
  Voice_67313_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_67314_AwakerVoiceContent = {
    Text = "ฟังเสียงแห่งปัญญา."
  },
  Voice_67314_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·2"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "ไม่มีที่สิ้นสุด,      ไม่จบสิ้น,      ไร้ขีดจำกัด,      ไร้ขอบเขต."
  },
  Voice_67315_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·สาม"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "นั่นคือพระประสงค์ของพระองค์... ไม่สิ แทนที่จะเรียกว่าพระประสงค์ ควรกล่าวว่าเป็นสัญชาตญาณมากกว่า การจ้องมองโดยไม่รู้ตัวของพระองค์จะดึงทุกสรรพสิ่งเข้าสู่ลมหายใจของพระองค์"
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "ไม่สามารถตรวจสอบได้โดยละเอียด... ร่องรอยเล็กๆ น้อยๆ.."
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "ฉันจะแสดงความจริง."
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "「คำตอบ」.ข้าเฝ้ามองประตูนี้ด้วยความรัก และด้วยความรักเดียวกัน ข้าได้มอบกุญแจของประตูนี้ไว้ในมือของท่าน"
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6731_AwakerVoiceContent = {
    Text = "ต้อง...กลับไปให้ได้.."
  },
  Voice_6731_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_6732_AwakerVoiceContent = {
    Text = "สรรพสิ่งในสวรรค์และโลก, วัฏจักรแห่งกรรม!"
  },
  Voice_6732_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6733_AwakerVoiceContent = {
    Text = "สรรพสิ่งในสวรรค์และโลก, วัฏจักรแห่งกรรม!"
  },
  Voice_6733_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6734_AwakerVoiceContent = {
    Text = "คมดาบยังไม่หมองคล้ำ"
  },
  Voice_6734_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6735_AwakerVoiceContent = {
    Text = "การฝึกฝนก็ไม่ควรผ่อนคลายเช่นกัน"
  },
  Voice_6735_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6736_AwakerVoiceContent = {
    Text = "ยืดหยุ่นมากขึ้นแล้ว."
  },
  Voice_6736_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6737_AwakerVoiceContent = {
    Text = "สิ่งที่ไร้รูปทรง พร้อมให้คุณใช้สอย"
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_6737_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "รู้สึกถึงลมหายใจที่ลุกโชน——"
  },
  Voice_6738_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6739_AwakerVoiceContent = {
    Text = "เราทุกคนจะกลายเป็นส่วนหนึ่งของ...เปลวไฟสีเขียว.."
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_6740_AwakerVoiceContent = {
