  Voice_6746_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6747_AwakerVoiceContent = {
    Text = "เวลาที่ได้อยู่กับทุกคนมักจะทำให้รู้สึกผ่อนคลาย .."
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "โซ่เลือดแห่งการสังหาร, ทูตของทีฟอน, ใบมีดแห่งความเกลียดชัง... พวกเขาเป็นคนตั้งฉายาเหล่านี้ให้ฉัน แน่นอนว่าฉันก็ไม่ได้รังเกียจที่จะเป็นคนแบบนั้นหรอก"
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับตัวเอง"
  },
  Voice_6749_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_6749_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_6750_AwakerVoiceContent = {Text = "ALL-IN!"},
  Voice_6750_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_6751_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_6751_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_6752_AwakerVoiceContent = {
    Text = "อุทาน"
  },
  Voice_6752_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_6753_AwakerVoiceContent = {
    Text = "ไปเล่นที่ไกลกว่านี้ได้ไหม? ไปทะเลกันเถอะ!"
  },
  Voice_6753_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_6754_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_6755_AwakerVoiceContent = {
    Text = "ว้าว — ขอบคุณเพื่อน~"
  },
  Voice_6755_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_6756_AwakerVoiceContent = {
    Text = "เพื่อน~เพื่อนมากขึ้น~"
  },
  Voice_6756_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_6757_AwakerVoiceContent = {
    Text = "ยูวฮะชิ... เขาเป็นคนพิเศษมาก เธอคิดว่าชีวิตที่รุ่งโรจน์ของครอบครัวฉันมาได้ยังไง? ทั้งหมดนี้ก็เพราะเขาฆ่าคนในสนามแข่งเหมือนสุนัขบ้า เขาเป็นแหล่งรายได้หลักของครอบครัวฉัน"
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "เรื่อยเปื่อย·เกี่ยวกับยูวฮะชิ"
  },
  Voice_6757_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ยูวฮะชิ」"
  },
  Voice_6758_AwakerVoiceContent = {Text = "โง่!"},
  Voice_6758_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_6759_AwakerVoiceContent = {Text = "หึ"},
  Voice_6759_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_6760_AwakerVoiceContent = {
    Text = "ไปเลย! สั่งการต่อสู้!"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "เหว...จะมีแสงแห่งความยุติธรรม."
  },
  Voice_6761_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_6762_AwakerVoiceContent = {
    Text = "แสงแห่งความยุติธรรมจุดประกายขึ้นแล้ว!"
  },
  Voice_6762_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6763_AwakerVoiceContent = {
    Text = "ความรู้สึกของมนุษย์เป็นสิ่งที่เปราะบางเหมือนดอกไม้ และมีค่าดุจดอกไม้.."
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "บทสนทนา·เกี่ยวกับโคเล็ตต์"
  },
  Voice_6764_AwakerVoiceContent = {
    Text = "Hit, Stand, Black·Jack!"
  },
  Voice_6764_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_6765_AwakerVoiceContent = {
    Text = "Hit, Stand, Black·Jack!"
  },
  Voice_6765_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_67754_AwakerVoiceContent = {
    Text = "อย่าต่อต้าน อย่าร้องไห้ อย่ามีชีวิตรอด！"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_67756_AwakerVoiceContent = {
    Text = "อย่าต่อต้าน อย่าร้องไห้ อย่ามีชีวิตรอด！"
  },
  Voice_67756_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_67772_AwakerVoiceContent = {
    Text = "ประตูเอ๋ย โปรดเปิดออกเถอะ"
  },
  Voice_67772_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_79297_AwakerVoiceContent = {Text = "อ๋อ"},
  Voice_79297_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_79298_AwakerVoiceContent = {
    Text = "เอ๋...?"
  },
  Voice_79298_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_80092_AwakerVoiceContent = {
    Text = "การบำบัดน้ำ การบำบัดด้วยไฟฟ้า การบำบัดด้วยการขัง นี่ไม่ใช่การรักษา แต่เป็นการทรมาน ดังนั้นในช่วงเวลาที่มีการตรวจสุขภาพ ฉันจะรักษาผู้ป่วยในโรงพยาบาลจิตเวชในแบบของตัวเอง และในที่สุดพวกเขาก็จะหายดีและพบกับเสรีภาพที่แท้จริง."
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_80092_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "น่าสงสารไวท์ เพราะสถานสงเคราะห์ใกล้ ๆ เต็ม เขาถูกครอบครัวขังในคอกหมู ฉันได้ทำการรักษาให้เขาฟรี หลังจากนั้นเขาในที่สุดก็เข้าใจว่าเขาคือมนุษย์ ไม่ใช่สัตว์ และได้ค้นพบเกียรติยศในฐานะมนุษย์ด้วยตัวเอง"
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_80093_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "ช่างทอผ้า ทนายความ บาร์อน.... ฉันจะไม่ปฏิเสธผู้ป่วยเพราะค่าใช้จ่าย ในสายตาฉัน พวกเขาคือผู้ป่วยที่ต้องการการรักษาเท่านั้น."
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_80094_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "ฉันยอมรับว่าฉันประเมินคุณต่ำไป,     การมีอยู่ของคุณคือตัวความเจ็บปวดเอง ครั้งนี้ไม่ต้องมาทำสำรวจหลังการเยี่ยม,     ฉันจะยืนเคียงข้างคุณเพื่อเป็นพยานความสิ้นสุดอย่างเต็มตา."
  },
  Voice_80095_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_80095_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "ผู้ป่วยเหล่านี้ได้มอบความทรงจำที่ดีให้กับฉัน ตอนนี้เป็นคราวของคุณ ผู้พิทักษ์ ฉันได้เลือกตอนจบให้คุณแล้ว มันจะเป็นการปรึกษาที่น่าจดจำที่สุดในอาชีพของฉัน"
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_80096_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "การปฏิเสธความช่วยเหลือจากหมอไม่ได้เป็นประโยชน์กับคุณเลย อาจจะครั้งหน้า เราต้องลองใช้การสะกดลึก."
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "ห้องมืดที่มีคนเพียงคนเดียว กับเสียงกระซิบที่ไม่หยุดหย่อนของความเจ็บปวดในหัวใจ นี่คือวิธีที่ดีที่สุดในการใช้เวลา"
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "แม้พูดแบบนี้จะไม่สุภาพ แต่การพูดคุยกับเด็กคนนั้นทำให้ฉันรู้สึกเบื่อหน่าย — คุณจะเห็นแค่สีหน้าเดียว นั่นคือรอยยิ้ม."
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับออรีตา"
  },
  Voice_81140_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ออรีตา」"
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "ขออภัยที่เข้ามาโดยไม่ได้นัดหมาย ฉันเพียงแค่รู้สึกถึงพลังจิตที่ต่ำต้อยของคุณ，จึงมาคอยใส่ใจ ตอนนี้ ผู้พิทักษ์，คุณต้องการเริ่มต้นการเดินทางทางจิตใจไหม?"
  },
  Voice_81141_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_81143_AwakerVoiceContent = {
    Text = "วิธีการรักษาผู้ป่วยของจิตแพทย์คือการเจาะกระโหลกศีรษะของผู้ป่วยด้วยเทคนิคเจาะวงแหวน — ผ่อนคลายเถอะ นั่นเป็นเรื่องนานมาแล้ว ปัจจุบันเรามีวิธีการมากมายในการวัดและเข้าสู่จิตใจของผู้ป่วย."
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_81143_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "ต้องการเข้าใจกันและกัน เพียงเปิดใจ——สัมผัสที่นี่ หัวใจเงินของฉันจะเปิดให้คุณ"
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "หากคุณต้องการฟังความคิดเห็นของฉัน คุณอาจจะผิดหวังได้ เพราะฉันเก่งในการฟังมากกว่าการพูด."
  },
  Voice_81145_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_81146_AwakerVoiceContent = {
    Text = "อ้า ฉันได้ยินเสียงของพระองค์ เสียงกระซิบที่เต็มไปด้วยความเจ็บปวดที่สุด!"
  },
  Voice_81146_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_81147_AwakerVoiceContent = {
    Text = "ฉันจะจดจำความเจ็บปวดในช่วงเวลานี้ไว้ในใจ กลับไปนึกถึงรสชาติ..."
  },
  Voice_81147_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_81148_AwakerVoiceContent = {
    Text = "ในฐานะที่เป็นเสี้ยวของการดำรงอยู่ คุณมีลมหายใจของเขา，ลมหายใจที่เต็มไปด้วยความทุกข์ซึ่งทำให้ความทรงจำนั้น ลิ้มรสได้อร่อยยิ่งนัก"
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "จำความกลัวเหล่านั้น จำรายละเอียดทางความรู้สึกเจ็บปวดของตัวเอง ปัจจุบันความจริงของการบำบัดคือการเผชิญหน้ากับความเจ็บปวดและเอาชนะมัน มา เช็ดน้ำตาออก และพูดความทรงจำเหล่านั้นให้ฉันฟังทีละน้อย..."
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_81149_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "ขอแสดงความยินดี คุณหายดีแล้ว— ใช่ ภาพหลอน และเสียงหลอนทั้งหมดเป็นปรากฏการณ์ปกติ พวกมันเป็นหลักฐานการฟื้นตัวของคุณ."
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_81150_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "สมองของคุณเต็มไปด้วยภาพที่แปลกประหลาด ไม่ต้องกังวล ทุกอย่างเป็นเรื่องปกติ วาดมันออกมา จิตใต้สำนึกและสัญชาตญาณของคุณจะเผยทุกอย่างให้คุณเห็น"
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_81151_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "ต่อไปคือ \"การบำบัดทางศีลธรรม\" โดยฟิลิปป์ ปีเนล คุณจำเป็นต้องกล่าวถึงความปรารถนาและความกลัวที่ลึกที่สุดของคุณ นี่คือกระบวนการสำคัญในการปลดล็อคจิตใจและฟื้นฟูความเป็นมนุษย์ที่หลับใหล"
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_81152_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "ผู้พิทักษ์,     ช่วยฉันทำการทดสอบเล็กน้อยได้ไหม?แค่การทดสอบหมึกวอร์ชอว์เท่านั้น ผ่านมันไป ฉันจะเห็นภายในลึกซึ้งที่ไม่มีใครรู้จักของเธอ กลายเป็นผู้ปลุกเสกเพียงคนเดียวที่เปิดเผยความลับในใจของผู้พิทักษ์."
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "สนทนา·เกี่ยวกับการวิเคราะห์จิตวิทยา"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "ก่อนอื่น ให้เรามาฟังเพลงกันก่อน ได้ยินไหม เสียงเพลงที่ไพเราะและนุ่มนวล ตอนนี้ให้ร่างกายและจิตใจของคุณสั่นคลอนร่วมกับเสียงเพลง และเข้าสู่การผ่อนคลายทางจิตวิญญาณ..."
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_81154_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "มอง Pendulum และให้ตาติดตามมันหมุน..."
  },
  Voice_81155_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_81156_AwakerVoiceContent = {
    Text = "ชู——เงียบ แล้วเดินไปสู่จุดจบที่ฉันนำทาง"
  },
  Voice_81156_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_81157_AwakerVoiceContent = {
    Text = "จิตใจที่เฉยชาไม่สร้างความสนใจใดๆ กับฉัน วิญญาณของพวกเขาตายไปแล้ว ไม่ว่าจะยุยงอย่างไร ก็ไม่เกิดคลื่นใดๆ"
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_81158_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_81159_AwakerVoiceContent = {
    Text = "ฉันฟังอยู่ กรุณาต่อไป"
  },
  Voice_81159_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_81160_AwakerVoiceContent = {
    Text = "โปรดรักษาความเงียบสงัด."
  },
  Voice_81160_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_81161_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_81162_AwakerVoiceContent = {
    Text = "ไว้ใจฉันอีกนิด."
  },
  Voice_81162_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_81163_AwakerVoiceContent = {
    Text = "แสดงให้เห็นถึงความทุกข์ทรมานมากยิ่งขึ้นเถอะ!"
  },
  Voice_81163_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_81164_AwakerVoiceContent = {
    Text = "ไม่จำเป็นต้องปิดบัง ไม่ต้องอาย ฉันคือผู้ฟังที่คุณไว้วางใจเพียงคนเดียว มา บอกฉันถึงความเจ็บปวดที่ลึกที่สุดของคุณ..."
  },
  Voice_81164_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_81165_AwakerVoiceContent = {
    Text = "ตอนนี้เออิจิสดูสดใสขึ้นมาก แน่นอนว่าถ้าผู้มาเยือนตัวน้อยของฉันต้องการ ฉันยินดีที่จะให้ความช่วยเหลือ ฉันหมายถึง, ความช่วยเหลือที่แท้จริง"
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับไอจิส"
  },
  Voice_81165_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「ไอจิส」"
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "แสดงด้านที่แท้จริงที่สุดของคุณให้ฉันเห็น."
  },
  Voice_81166_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_81168_AwakerVoiceContent = {
    Text = "ฉันจะค่อยๆ ลิ้มลองความเจ็บปวดที่หวานนี้"
  },
  Voice_81168_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_81169_AwakerVoiceContent = {
    Text = "ไม่จำเป็นต้องปิดบัง ไม่ต้องอาย ฉันคือผู้ฟังที่คุณไว้วางใจเพียงคนเดียว มา บอกฉันถึงความเจ็บปวดที่ลึกที่สุดของคุณ..."
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "โรคทางจิตไม่ใช่สิ่งที่เฉพาะเจาะจงในยุคนี้ มันอยู่เหนือกาลเวลาและอวกาศ การย่อยสลายก็เช่นกัน ทั้งสองสิ่งนี้ได้ก้าวข้ามขีดจำกัดของการรับรู้ของมนุษย์ จริงไหม?"
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "ชู——เงียบ แล้วเดินไปสู่จุดจบที่ฉันนำทาง"
  },
  Voice_81171_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_81172_AwakerVoiceContent = {
    Text = "ที่นี่เต็มไปด้วยร่องรอยของประวัติศาสตร์ ซึ่งในระดับหนึ่ง ประวัติศาสตร์หมายถึงความทรงจำ——ความทรงจำที่เจ็บปวดของผู้ที่จากไป"
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_81173_AwakerVoiceContent = {
    Text = "หายใจลึกๆ..."
  },
  Voice_81173_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_81174_AwakerVoiceContent = {
    Text = "ความทุกข์ทรมาน ความสิ้นหวัง ความตาย...ความทรงจำเหล่านี้ รสชาติเหมือนไอศกรีมหลังอาหาร"
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "ไม่ต้องตื่นตระหนก แค่การปรึกษาทางจิตวิทยาทั่วไปเท่านั้น"
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "ฟังคำแนะนำของฉัน"
  },
  Voice_81176_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_84185_AwakerVoiceContent = {
    Text = "พิธีเกิดเหตุไม่คาดคิด โปรดให้อภัยทีมงานที่ใช้ธงตีแขนของคุณ ฉันต้องให้คุณมีความตื่นตัว"
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_84185_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "ที่นี่คุณจะเห็นโครงสร้างเรือที่แตกต่าง สามารถเข้าถึงอุปกรณ์นำทางที่ทันสมัยมากขึ้น ฉันชอบมาก และที่สำคัญที่สุด ฉันเชื่อว่า 「เรือ」 นี้กำลังเดินในประวัติศาสตร์มนุษย์อย่างถูกต้อง"
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "พิธีเสร็จสิ้นแล้ว ขอบคุณสำหรับความร่วมมือของคุณ ครั้งหน้าฉันจะสร้างสัญญาณธงพิเศษเพื่อช่วยให้เราทำพิธีให้อย่างปลอดภัยและราบรื่นมากขึ้น"
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_84187_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "ฉันไม่รู้ว่าทำไมมันถึงมีอยู่ ฉันแค่รู้ว่าฉันต้องนำทางอย่างสำเร็จเพื่อพานักเดินเรือและผู้โดยสารทั้งหมดกลับมาได้อย่างปลอดภัย"
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "โปรดมั่นใจ ฉันจะใช้พลังนี้เพื่อให้การเดินเรือของเรือสู่ความปลอดภัย จะไม่ใช้ในทางที่ผิด"
  },
  Voice_84189_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_84190_AwakerVoiceContent = {
    Text = "โปรดหยุดต่อต้าน"
  },
  Voice_84190_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_84191_AwakerVoiceContent = {
    Text = "ฉันมีแต่ความเคารพต่อคุณ และจะใช้ชีวิตแลกเหรียญกับคำสั่งทุกข้อที่คุณมอบหมาย"
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "ขอโทษ ฉันไม่เข้าใจคน แต่เข้าใจเรือ กรุณาให้อภัยที่ใช้การเปรียบเทียบนี้: กระดูกงูของคุณไม่ใช่ไม้หรือเหล็ก แต่เป็นเหล็กกล้า แข็งแกร่งและมั่นคง น่าชื่นชม."
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_84192_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_84193_AwakerVoiceContent = {
    Text = "ยอมแพ้เถอะ"
  },
  Voice_84193_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_84194_AwakerVoiceContent = {
    Text = "แทนที่จะชอบ ฉันมักใช้คำว่า「การกลับมา」 เมื่อเผชิญหน้ากับพระเจ้าที่ไม่อาจตั้งชื่อได้ สมองของฉันสูญเสียสติดำดิ่งสู่ความสุข ใช่ ฉันควรกลัวพระองค์ แต่ฉันไม่สามารถควบคุมตัวเองได้."
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "ฉันจะไม่ถูกพายุโค่น"
  },
  Voice_84195_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_84196_AwakerVoiceContent = {
    Text = "หากไม่มีระเบียบ โลกนี้จะเหลืออะไร? มีแต่ความโกลาหลและความวุ่นวายเท่านั้น"
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "ในการเดินทางครั้งถัดไป ฉันต้องการขึ้นเรือในฐานะผู้ที่จะนำทางนอกเหนือจากนักนำทางนั้น...หมายความว่า ฉันยินดีที่จะทำตามการชี้แนะของคุณ คุณมีความไว้วางใจจากฉันอย่างเต็มที่."
  },
  Voice_84197_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_84197_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "ฉันแค่ทำหน้าที่ในฐานะนักนำทาง และไม่จำเป็นต้องรายงานเพื่อให้ได้รับคำชมเชย"
  },
  Voice_84198_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_84199_AwakerVoiceContent = {
    Text = "ระบบประภาคารสามารถช่วยลดความเครียดในการเดินเรือได้อย่างมาก และแสงของเธอก็สว่างสดใส ผมยินดีที่จะเดินเรือร่วมกับฟารอส."
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับฟาร์โรส"
  },
  Voice_84199_UnlockDesc = {
    Text = "ปลดล็อคเมื่อได้รับผู้ปลุกเสก「ฟาโรส」"
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "ทะเลสอบๆ ตามที่ฉันแนะนำ เราจะถึงท่าเรืออย่างปลอดภัยแน่นอน"
  },
  Voice_84200_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_84201_AwakerVoiceContent = {
    Text = "การเชื่อมโยงวิญญานประสบความสำเร็จ ฉันรู้สึกได้ถึงจิตสำนึกของคุณ...นี่เป็นครั้งแรกที่ฉันทำทิศทางในที่ว่าง หากมีปัญหาล่อง ให้คุณรีบชี้เพื่อ."
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_84201_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "สังเกตความเปลี่ยนแปลงของเมฆและบารอมิเตอร์ หวังว่าทั้งหมดจะได้เตรียมการเพราะเรือจะพบกับพายุ"
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "ความยุ่งเหยิงครั้งนี้เกิดจากการวางแผนเส้นทางผิดพลาด ฉันยินดีที่จะรับผิดตามกฎ"
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "การวัดมุมสูงของดวงดาว."
  },
  Voice_84204_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_84205_AwakerVoiceContent = {
    Text = "ความรู้สึกวิงเวียนศรีษะนี้เกือบเหมือนเป็นอาการเมาเรือ โปรดหลับตา จับมือฉัน และมาอยู่ข้างๆ ฉัน จะรู้สึกดีขึ้น"
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_84205_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "เก็บธงสูงขึ้น，ซ้ายเรือกดคลื่น，เรือมือจะปรับเส้นทางตามการคำนวณของฉัน"
  },
  Voice_84206_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_84207_AwakerVoiceContent = {
    Text = "ประสบการณ์เหล่านี้มีค่ามาก ฉันจะบันทึกไว้อย่างละเอียดในบันทึกการเดินทาง เพื่อให้กับลูกเรือที่มาทีหลัง"
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "พิธีเสริมลิงค์มีความเสี่ยงและผลลัพธ์ที่ไม่ทราบ แต่ว่าเชื่อใจฉันเถอะ ฉันจะนำทางให้คุณให้พิธีมีความราบรื่น"
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_84208_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "ปรับจุดศูนย์ถ่วงใหม่."
  },
  Voice_84209_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_84210_AwakerVoiceContent = {
    Text = "โปรดระวังการปกป้องเรือ"
  },
  Voice_84210_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_84211_AwakerVoiceContent = {
    Text = "มีบางคนเป็นเรือไอน้ำ ที่ตอบสนองช้าแต่เร็ว บางคนเป็นเรือดีเซล เปิดตัวแรงแต่มีกำลังจำกัด. แล้วคุณล่ะ ผู้พิทักษ์?"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_84211_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "ฉันมั่นใจว่าสิ่งที่ให้ไปจะได้รับการตอบแทนในพื้นฐานนี้ และในอนาคตฉันจะทำงานหนักขึ้น"
  },
  Voice_84212_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_84213_AwakerVoiceContent = {
    Text = "จากการทำภารกิจหลายครั้ง คุณได้พิสูจน์ตัวเองแล้ว ฉันคิดว่าคุณเป็นนักนำทางที่ยอดเยี่ยมเช่นเดียวกับฉัน ไม่ อาจจะคุณดีกว่าฉันมาก"
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_84213_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_84214_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_84215_AwakerVoiceContent = {
    Text = "ขอเพียงคุณต้องการ คลพาร์ซานจะคอยให้บริการตลอดเวลา"
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_84215_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "ทะเลสอบๆ ตามที่ฉันแนะนำ เราจะถึงท่าเรืออย่างปลอดภัยแน่นอน"
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_84217_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_84218_AwakerVoiceContent = {
    Text = "นักนำทางเค็ปเปิ้ลซานมารายงานตัว! ธงพร้อมแล้ว สภาพส่วนตัวดี สมควรให้ผู้พิทักษ์ออกเรือได้"
  },
  Voice_84218_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_84219_AwakerVoiceContent = {
    Text = "ฉันจะนำเรือไปสู่เส้นทางที่ถูกต้อง"
  },
  Voice_84219_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_84220_AwakerVoiceContent = {
    Text = "หมวกเบี้ยวไปหรือ?ขอโทษ ฉันไม่เข้าใจความตั้งใจของคุณ กรุณาให้คำสั่งที่ชัดเจน."
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "ธงเป็นภาษาของผู้นำทาง และยังเป็นคำจารึกบนหลุมศพของผู้นำทาง. เมื่อเรือจม ผู้ค้นหาจะอ่านสัญญาณสุดท้ายที่ฉันฝากไว้จากเศษซากของธง."
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "สนทนา·เกี่ยวกับธง"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "รับรู้จุดสมดุลของตัวเรือ"
  },
  Voice_84222_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_84223_AwakerVoiceContent = {
    Text = "เก็บธงสูงขึ้น，ซ้ายเรือกดคลื่น，เรือมือจะปรับเส้นทางตามการคำนวณของฉัน"
  },
  Voice_84223_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_84224_AwakerVoiceContent = {
    Text = "ธง E ส่งคำสั่ง."
  },
  Voice_84224_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_84225_AwakerVoiceContent = {
    Text = "ในช่วงเวลาที่จำเป็น นักนำทางที่เรียนรู้การทำงานร่วมกันในห้องเครื่องยนต์ก็สามารถทำหน้าที่เป็นคนควบคุมได้ แต่เพื่อให้แน่ใจว่ามีความปลอดภัยสำหรับเรือ ฉันก็หวังว่าจะมอบหมายงานนี้ให้กับผู้ที่เชี่ยวชาญในเรื่องนี้"
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "เรื่องเล่า·เกี่ยวกับฮิลีย์สเตอร์"
  },
  Voice_84225_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างตื่น「ฮิลีย์สเตอร์」"
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "รู้สึกถึงน้ำหนักหายไป ต่อไปคือความรู้สึกสั่นสะเทือนเหมือนเรือสั่นแรง ตามการเคลื่อนไหวของฉันรู้สึกถึงจุดศูนย์ถ่วงของร่างกาย รักษาสมดุล"
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_84226_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "เริ่มต้นการแก้ไขหมุดทะเล"
  },
  Voice_84406_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_84407_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·สาม"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "คำสั่งตอบสนองธง C"
  },
  Voice_84408_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·2"
  },
  Voice_84409_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·สาม"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "อย่าหวังว่าจะผ่านฉันไปได้"
  },
  Voice_90333_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_90334_AwakerVoiceContent = {
    Text = "อย่างไรเพื่อนควรปฏิบัติตัวกัน? โปลุคซ์ชอบจะสั่งให้ฉันทำหลายสิ่ง แม้ว่าเขาเองก็ทำได้ และฉันก็ยินดีจะช่วยเขาทำสิ่งนั้น นั่นคือการเชื่อมโยงระหว่างเรา ถ้าคุณต้องการ ฉันก็จะทำอะไรให้คุณบ้าง"
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_90334_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "ด้วยร่างกายที่ไม่สามารถดับ ได้รับความยากลำบากทั้งหมด!"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "ถึงแม้ว่าเราจะเห็นหนังสือเล่มนั้นมาแล้ว ก่อนหน้านี้เราก็เคยสงสัยเกี่ยวกับโลกภายนอกและวิวทิศน์นอกเกาะกลางทะเลสาบและกำแพงสีแดงเข้ม แต่เมื่อโพลลักซ์ถูกทรมาน ฉันไม่เคยคิดจะต่อต้านเลย เมื่อเทียบกับโพลลักซ์ ฉันรู้สึกว่าตัวเองอ่อนแอกว่ามาก โง่เง่ามากกว่า"
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_90336_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "ฉันดูโง่หรือ? ขอโทษค่ะ ขอให้คุณยกโทษให้ฉันด้วยความไม่รู้ของฉัน ฉันไม่รู้จริงๆ นอกจากความรู้เกี่ยวกับพระเจ้า ที่โคมสอนฉันจะเรียนเร็วขึ้นค่ะ ว่าคุณชอบอะไรและไม่ชอบอะไร กรุณาบอกฉันหน่อยค่ะ ฉันจะจดจำไว้เป็นอย่างดี"
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_90337_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "โปรดเป็นสักขีพยานเถิด นี่คือเจตจำนงที่แสวงหาเสรีภาพ"
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "ร้านค้าที่สามารถทำให้ความปรารถนาใดๆเป็นจริงได้ สินค้าที่มีอยู่ทุกอย่าง ทำให้ผู้คนหลีกเลี่ยง...ไม่ ฉันไม่ได้สงสัยในพลังของสุภาพสตรีคนนั้น แต่ “อยากได้สิ่งใด ต้องจ่ายในราคาที่สมควร” เป็นหลักการที่ฉันและโพลุกซ์ได้เรียนรู้หลายครั้งแล้ว"
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "เรื่องราวเกี่ยวกับดาฟเดล"
  },
  Voice_90339_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「ดาฟเดล」ที่ถูกปลุก"
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "ปีกที่ถูกสาปนี้ ยังสามารถโบยบินบนฟากฟ้าได้ไหม"
  },
  Voice_90340_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_90341_AwakerVoiceContent = {
    Text = "พวกคุณไม่สามารถทำลายฉันได้!"
  },
  Voice_90341_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_90342_AwakerVoiceContent = {
    Text = "คุณอยากจะสัมผัสขนเหล่านี้ไหมค่ะ? ได้เลย ต้องการให้ฉันกางปีกให้เยอะหน่อยไหมคะ?"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "เมื่อได้รับความช่วยเหลือจากผู้อื่น ฉันมักคิดว่าความดูแลพิเศษนั้นและหนังสือมีค่าที่คุณให้มาภายหลังจะมีค่าใช้จ่ายอื่น ๆ หรือไม่ ขอโทษ ฉันไม่ควรสงสัยคุณแบบนี้"
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_90343_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "ในที่สุดนกก็จะบินสูงเหนือท้องฟ้า"
  },
  Voice_90344_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_90345_AwakerVoiceContent = {
    Text = "เป็นนักทำอาหารเลิศรสจริงๆ...ความรู้ในการทำอาหารก็สำคัญมาก แม้ฉันจะมีความต้องการในการกินไม่สูง แต่โปลุคซ์เกินไปหน่อย ดูเหมือนควรหาเวลาศึกษาเพิ่มเติมหน่อย...ไม่อยากไป? ทำไม? แต่ของที่ท่านนั้นทำดูน่ากินมากเลย"
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "เรื่องทั่วไป · เกี่ยวกับดูเลเซน"
  },
  Voice_90345_UnlockDesc = {
    Text = "ได้รับผู้ปลุกเสก「ดุลเซน」หลังจากปลดล็อก"
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "ตามที่คิด ในสมัยโคมไฟ แม่บ้านก็ไม่ได้ต่างจากฉันและโปลุคซ์มากนัก เราทุกคนเป็นเครื่องมือที่สวมใส่เชื่อไว้ในวิถีชีวิต และพวกเขายอมรับเสมอ แต่แม่บ้านที่เป็นสีเขียวนั้นดูไม่เหมือนกัน เธอ...มีพลังและรักที่จะทำสิ่งเหล่านี้ ดูเหมือนเธอจะมีเสรีภาพที่ล้ำค่าที่สุดแล้ว"
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "เรื่องราว·เกี่ยวกับคาเรน"
  },
  Voice_90346_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างที่ถูกปลุก「คาเรน」"
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "พวกคุณไม่สามารถทำลายฉันได้!"
  },
  Voice_90347_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_90348_AwakerVoiceContent = {
    Text = "ก็ยังไม่...บินออกไปได้หรือ..."
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "จงแปรเป็นลมลอยไป!"
  },
  Voice_90349_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·2"
  },
  Voice_90350_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_90351_AwakerVoiceContent = {
    Text = "สวัสดี,      ยินดีที่ได้พบกันครั้งแรก,      ฉันคือ คาสเตอร์...ยังมีอะไรที่ต้องพูดอีกไหม? ขอโทษ,      ฉันไม่ค่อยชำนาญในการพูด ถ้าคุณต้องการอะไรให้ฉันรู้ โปรดเรียกฉันได้ตลอดเวลา"
  },
  Voice_90351_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_90352_AwakerVoiceContent = {
    Text = "ก็แค่นี้เอง..."
  },
  Voice_90352_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_90353_AwakerVoiceContent = {
    Text = "ตกลงไปเถอะ!"
  },
  Voice_90353_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_90354_AwakerVoiceContent = {
    Text = "มีสิ่งที่ฉันไม่เคยเห็นมาก และยังไม่เคยทำ สระน้ำสีเขียวลึกนั่นและสายหมอกหนาน้ำท่วมที่ไม่สิ้นสุด พระสมุทร มหานคร เมืองเล็ก ภาพที่พูดถึงในมือนั้น ฉันต้องการไปชมและฉันและโพลลักซ์กับคุณรวมกัน"
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_90354_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "เมื่อคุณได้ยินใบไม้บนต้นไม้ขยับเสียงกราวกราวคุณจะรู้ว่าฉันอยู่ข้างคุณแล้วค่ะ"
  },
  Voice_90355_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_90355_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "ขนนกมืดนี้กลายเป็นเข้มขึ้นกว่าเดิม"
  },
  Voice_90356_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_90357_AwakerVoiceContent = {
    Text = "จริง ๆ แล้วสิ่งที่ฉันอิจฉาที่สุดคือ ความไว้วางใจและไม่มีความสงสัยระหว่างคุณและเพื่อนร่วมของคุณ ความรู้สึกที่ถูกลืมและถูกหักหลัง...มันเจ็บปวดเกินไป"
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "นักล้วงผู้บอกฉันว่าเธอสามารถสอนเทคนิคการเอาตัวรอดบนถนนที่เก่งกาจที่สุดให้ฉันได้ เพียงแค่ฉันจ่ายเธอห้าร้อยเก้าเรโอบาร์...ฉันถูกหลอกใช่ไหม? ไม่,      ฉันเห็นว่านี่เป็นความรู้ที่คุ้มค่าที่ต้องเรียนรู้ นี่คือสิ่งที่ฉันกับโปลลักซ์ขาด...หรือเป็นปัญหาเรื่องเงิน? ฉันเข้าใจแล้ว งั้น ฉันจะไปตกลงกับเธอ จ่ายสี่ร้อยห้าสิบแต่พอไหวไหม?"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเจนกิน"
  },
  Voice_90358_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「เจนกิน」"
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "ฉันยังทนอีกได้..."
  },
  Voice_90359_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_90360_AwakerVoiceContent = {
    Text = "ตอนเด็ก ๆ การควบคุมการที่เราถือโคมยังไม่เคร่งครัดนัก บางครั้งโพลลักซ์ก็ไม่รู้ว่าเขาอาจพูดอะไร อาจได้รับลูกอมชุดหนึ่ง ลิ้มรสลูกอมนั่น... เหมือนกับตอนนี้เลย"
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_90360_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "ด้วยร่างกายที่ไม่สามารถดับ ได้รับความยากลำบากทั้งหมด!"
  },
  Voice_90361_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_90362_AwakerVoiceContent = {
    Text = "คุณช่วยสอนเรื่องการแลกเปลี่ยนกับมนุษย์ให้ฉันได้ไหมคะ? วิธีแลกเปลี่ยนสิ่งต่าง ๆ กับผู้คน วิธีจัดการเงินตามที่ได้รับ เป็นหนึ่งในหัวข้อที่ซับซ้อนจริง ๆ การได้รับอิสระเป็นเพียงแค่จุดเริ่มต้นเท่านั้น ฉันและโพลลักซ์ยังมีอะไรต้องเรียนรู้อีกมาก ต่อไปต้องรบกวนคุณบ่อย ๆ แล้วค่ะ"
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "จงแปรเป็นลมลอยไป!"
  },
  Voice_90363_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "ลม,จงเหวี่ยงมันสู่ปากแห่งความตาย!"
  },
  Voice_90364_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_90365_AwakerVoiceContent = {
    Text = "โปลุคซ์...แม้ว่าเขาจะถูกชักชวนให้มีความคิดไม่ดีมากมาย แต่ใจที่แท้จริงของเขาไม่เลวร้าย เขาเพียงต้องการอย่างยิ่งยวดที่จะได้รับการยอมรับจากโคมไฟ จากเจ้าคณะ ดังนั้นเขาจึงแคร์ความต้องการของพวกเขามาก ชี้ให้กล่าวว่าเขามักจะกลัวการสูญเสีย “ตัวเขาเอง”"
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "เรื่องราวไร้สาระ·เกี่ยวกับโปลลักซ์"
  },
  Voice_90365_UnlockDesc = {
    Text = "เมื่อได้รับร่างกายที่ตื่นขึ้น「โพลิกซ์」จะปลดล็อก"
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "ขอโทษค่ะ ไม่ได้ตั้งใจจะเหม่อ...คุณถามว่าขนปีกนี่เป็นอะไร? นี่คือ...สิ่งที่สำคัญที่สุดของเขา และก็สำคัญที่สุดของฉันด้วย มันสวยใช่มั้ย?"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "ตอนนั้นเราทุกคนต้องเรียนเทววิทยาทุกวันจากอัลบิโน่หรือคนดูแลที่เข้มงวด ตอนนั้นความหวังที่ยิ่งใหญ่ที่สุดของฉันคือวันหนึ่งพวกคัมภีร์เหล่านั้นจะถูกแก้ไขให้สั้นและน้อยลง เพื่อที่ฉันจะไม่ต้องถูกต่อว่าจากคนดูแลที่ฉลาด"
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_90367_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "ขอบคุณท่าน ให้กุญแจที่ฉันควบคุมอิสระแก่ฉัน"
  },
  Voice_90368_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_90369_AwakerVoiceContent = {
    Text = "ปีกคู่นี้ที่สุดก็โตเต็มที่แล้ว แข็งแรงและมีพลังอย่างมาก ตอนนี้ฉันสามารถพาคุณและโพลุกซ์ได้ครั้งเดียว หากคุณต้องการบินขึ้นสวรรค์ ขอแค่เรียกฉันเสียงดังนะ"
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_90369_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "แอบซ่อนหลังปีกนี่!"
  },
  Voice_90370_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_90371_AwakerVoiceContent = {
    Text = "ในที่สุดก็เห็นดวงดาวที่บอกว่าใหญ่ในหนังสือ"
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "ครั้งเมื่อท่านเซอราฟิม...จูเลียตเคยมีช่วงเวลาที่อบอุ่นกับเราเสมอ เธอไม่เคยขี้เหนียวที่จะแสดงรอยยิ้มที่อบอุ่นนั้นต่อทุกคน จนทำให้กลัวที่จะทำให้เธอผิดหวัง เพียงแค่เธอยิ้มและสัมผัสศีรษะของคุณ คุณก็จะไม่สามารถพูดคำที่ปฏิเสธได้ อืม ตอนนี้ไม่มีแล้ว คุณสามารถสัมผัสศีรษะของฉันได้ตามที่คุณต้องการ"
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_90372_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "ฉันเคยถูกแช่อยู่ในน้ำเหนียวสีดำนั้นนานมาก ๆ นานจนลืมเวลาไปแล้ว นานมาก... แม้แต่โพลลักซ์ก็ลืมฉัน มันไม่ก่อให้เกิดความเจ็บปวดทางร่างกาย แต่เป็นความกลัวทางวิญญาณที่ต้องดูตนเองหายลับไป"
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "เราถูกห้ามไม่ให้พบปะกับคนอื่นเยอะตั้งแต่วัยเด็ก, คำว่าเพื่อนก็นึกถึงในตอนหลัง ๆ ฉันกับโพลลักซ์ยกเว้นหน้าที่เดียวกันเป็นสิ่งเดียวที่เรามี ทั้งพี่น้องทั้งเพื่อนนักโทษที่อยู่ในคุกเดียวกัน มีแต่พวกเราตามที่เราเป็น ตอนนี้ถึงเวลาที่จะมีเพื่อนใหม่แล้ว"
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_90374_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_90375_AwakerVoiceContent = {
    Text = "ถอยหลัง!"
  },
  Voice_90375_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_90376_AwakerVoiceContent = {
    Text = "โรงเรียนที่ทุกคนสามารถสื่อสารอย่างอิสระ ทำความรู้จักเพื่อนใหม่ได้ตามใจเหรอ? คุณบอกว่านี่ไม่เรียนเทววิทยา และยังสามารถเลือกคอร์สต่าง ๆ ได้...แม้กระทั่งโดดเรียนได้? อืม นี่เป็นที่ที่ยอดเยี่ยมจริง ๆ เลย"
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_90377_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_90378_AwakerVoiceContent = {
    Text = "หลีกไป!"
  },
  Voice_90378_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_95050_AwakerVoiceContent = {
    Text = "ผู้ที่ไม่เคารพ... จำเป็นต้องมีการลงโทษ..."
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_95051_AwakerVoiceContent = {
    Text = "ฉันมีใจสว่าง!"
  },
  Voice_95051_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_95052_AwakerVoiceContent = {
    Text = "สิ่งสกปรก."
  },
  Voice_95052_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_95053_AwakerVoiceContent = {
    Text = "ผู้ศรัทธาที่เข้มข้น คนอาจมองว่าเธอเป็นคนบ้า แม้ว่าเธอจะเคยหลงผิด แต่ความตั้งใจในการยอมเสียทุกอย่างเพื่อพระเจ้าของเธอเป็นสิ่งที่คนทั่วไปไม่สามารถทำได้ ฉันมีเพียงความเศร้าโศกในการพบกันของชนชั้นเดียวกันกับเธอ..."
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "เรื่องทั่วไป：เกี่ยวกับมิรียำ"
  },
  Voice_95053_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「มิลียัม」"
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "ฉันจะนำการนำทางและการพิพากษา แสงสว่างในคืนขาวจะขับไล่ความชั่วร้ายของพวกคุณ!"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "หืม... เวลาผ่านไปนานขนาดนี้ เขาก็ยังไม่เปลี่ยนแปลงเลย ตัวฉันในวัยเด็กอาจไม่เคยคิดเลยว่าในวันหนึ่ง ฉันจะทำร้ายและเป็นหนี้พี่ชายขนาดนี้ ถึงแม้โชคชะตาอันน่าเศร้านี้จะไม่อยู่ในอำนาจของเรา เราเคยผ่านการแยกจากไปมากมายแต่ ตอนนี้ที่ฉันกลับมาอีก มันก็จะไม่มีอะไรที่สามารถแบ่งเราได้ แม้แต่ความตาย."
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "เรื่องทั่วไป：เกี่ยวกับคาสโตร์"
  },
  Voice_95055_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับร่างตื่น「คาสตอร์」"
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "ในอดีตฉันเกลียดสิ่งมากมาย คนใช้ที่ไม่รู้เรื่องมารยาท คนรับใช้ที่ไม่เคารพผู้มีอำนาจ คนที่ดูหมิ่นพระเจ้า...แต่ตอนนี้ มีแต่โคมไฟ เพียงแต่โคมไฟ! จูเลียตและนิกายของเธอเป็นสาเหตุที่ทำให้ฉันและพี่ชายของฉันเจ็บปวดอย่างแสนสาหัส สาบานด้วยนามของลูกศิษย์ว่า ฉันจะไม่ให้ความเจ็บปวดนี้เกิดขึ้นอีกในผู้คนอื่น!"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "ฉันจะเดินตามเส้นทางแห่งแสงสว่าง จนกระทั่งหมดชีวิตของฉัน"
  },
  Voice_95057_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_95058_AwakerVoiceContent = {
    Text = "แสงสว่างของผู้ถือแลมป์จะส่องสว่างคืนที่ยาวนาน!"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "ท่านมักจะใจดีและเอื้อเฟื้อเสมอ ฉันจะตั้งใจเรียนรู้ถึงความอบอุ่นของความสว่างนี้."
  },
  Voice_95059_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_95060_AwakerVoiceContent = {
    Text = "อัครสาวกแห่งผู้ถือแลมป์ ที่กำเนิดจากผู้คนในคืนขาว ผู้ขับไล่ความมืด สายใจศักดิ์สิทธิ์ ฉัน โบลิโคซ จะตอบสนองต่อเรียกของคุณ และมอบพลังแห่งความมืดและวิญญาณแห่งแสงให้กับคุณ"
  },
  Voice_95060_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_95061_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_95062_AwakerVoiceContent = {
    Text = "ชำระบาปของคุณให้หมดสิ้น!"
  },
  Voice_95062_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_95063_AwakerVoiceContent = {
    Text = "เมื่อก่อนทุกคนบอกว่าความมืดอันเหมือนเหวลึกนี้คือความเชื่อของฉัน เป็นพรที่ฉันจะมอบให้ผู้ติดตาม แต่บัดนี้ ความมืดนี้ได้กัดกินฉัน โดยกลายเป็นส่วนหนึ่งของฉัน... แต่ใจที่เต้นอยู่ในร่างกายของบาปนี้คือที่ที่ไม่สามารถถูกกัดกินตลอดไป. คุณก็วางใจเถอะ,      ฉันจะใช้พลังที่มอบให้จากสีดำนี้ในการนำความสุขที่แท้จริงมาสู่วิสัยทัศน์ของผู้คน!"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "ฉันจะเผยแพร่ชื่อเสียงอันยิ่งใหญ่ของคุณ ทุกสิ่งที่ไม่บริสุทธิ์จะถูกแสงสว่างชำระ"
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "บาปในอดีตที่ได้กระทำไปแล้วไม่ควรหลบหนี ฉันต้องแก้ไขข้อผิดพลาดที่ทำกับตะเกียงและนำคนที่หลงผิดกลับสู่เส้นทางที่ถูกต้อง ให้ฉันรับผิดชอบบาปของฉันเถอะ แล้วฉันจะตอบรับแสงนั้น ตอบรับการอัญเชิญของท่าน และก้าวเข้าสู่เส้นทางที่แท้จริง ที่เป็นของพระบุตร"
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_95065_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "หัวใจที่มีเมตตานั้น ยอมที่จะอภัยให้กับผู้ที่เต็มไปด้วยบาปเช่นนี้ ฉันสามารถรู้สึกได้ ว่าความบริสุทธิ์ในวิญญาณของคุณนั้นสว่างกว่าเปลวไฟ แม้กระทั่งคุณอาจนำทางใจที่หลงทางของฉัน..."
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_95066_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "ความมืดนั้น ความมืดที่แพร่กระจายจากบทสวดของอูหลีเอต กำลังปกคลุมจิตใจของฉัน... แต่ตอนนี้ มีแสงสว่างปรากฏในความมืดนั้น！จุดแสงอันสลัวนั้น มันต้องการบอกอะไรกับฉันหรือเปล่า?"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_95067_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "ได้ยินมาว่าเธอเคยเป็นหญิงสาวศักดิ์สิทธิ์ แต่ทว่าท่าทางหยาบคายและคำพูดอันหยาบกร้านของเธอนั้น......อะไรนะ? เธอไม่สามารถท่องบทสวดคำภาวนาได้แม้แต่บทเดียว? ในท่าทีที่ไร้เคารพแบบนี้ ทำให้รู้สึกอับอายแทนเทพของเธอจริงๆ"
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "เรื่องทั่วไป：เกี่ยวกับเมอร์ฟี่"
  },
  Voice_95068_UnlockDesc = {
    Text = "ปลดล็อกหลังจากได้รับ「มอร์ฟี่」ร่างกายที่ตื่นขึ้น"
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "ผู้ที่สามารถนำผู้คนออกจากหมอกนั้นคือผู้ถือโคมไฟที่มีรูปร่างบริสุทธิ์อย่างแท้จริง ที่ดินแห่งความบริสุทธิ์ที่จูเลียตกล่าวถึง กลับถูกสร้างขึ้นจากซากศพของผู้ศรัทธา ในฐานะที่เป็นพระบุตร ฉันจะเผยแพร่ข่าวสารใหม่ไปยังผู้ศรัทธาที่สมควรได้รับการช่วยเหลือ"
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "โอ ผู้ที่นำทางฉัน และให้แสงสว่างแก่ฉัน เคยมีครั้งหนึ่งที่ฉันถูกบดบังในความหมายปลอม ตอนนี้ภายใต้การชี้นำของคุณ ฉันได้ค้นพบภารกิจที่แท้จริงของตัวเองแล้ว——นำคนนิ่งบอดที่เงียบงันกลับมาเป็นปกติ และนำความสว่างที่ไม่เสื่อมสลายมาสู่โลก ฉันทราบถึงความไม่เห็นแก่ตัวของคุณ คุณไม่ได้ต้องการความอุทิศหรือการเครื่องบูชาของฉัน ดังนั้นขอให้ฉันติดตามคุณ เพื่อบันทึกคำพูดและการกระทำของท่านทุกคำ ตั้งไว้เป็นแนวทางในค่ำคืนที่จะนำทางไปข้างหน้า"
  },
  Voice_95070_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_95070_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "ติดอยู่กับโซ่ตรวน อาบน้ำในความมืด เดินไปในแสงนั้นอย่างแน่วแน่...นี่คือสิ่งที่คุณต้องการบอกฉันใช่ไหม?"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_95071_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "ข้ารับใช้ผู้มีแสงสว่างได้สูญเสียไฟในมือของเขา ความเจ็บปวดที่มองไม่เห็นนี้ทำให้ใจของฉันมีแต่ความกังวล ฉันขอร้องอย่างจริงใจว่าขอให้คุณช่วยชีวิตจิตวิญญาณที่หลงทางนี้ กรุณาจับมือของฉัน ใกล้ชิดกับหัวใจศักดิ์สิทธิ์นี้ กรุณาประทานความสว่างให้กับฉัน..."
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_95072_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "เด็กน้อยที่โชคร้าย แต่เมื่อเธอได้ลงทุนในกิจการของคุณ ก็ย่อมได้รับการช่วยเหลือขั้นสุดท้าย แต่ทำไมเพื่อนแบบลิงของเธอถึงได้รับความโปรดปรานจากคุณ? เด็กน้อยที่ชั่วร้ายคนนั้นถึงแม้จะขโมยเครื่องรางของขวัญจากการสวดมนต์ของฉัน! วิญญาณของเธอที่ซ่อนบาปเช่นน้ำท่วม นี่มันไม่เคารพ! ไม่เคารพ!"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "เรื่องทั่วไป：เกี่ยวกับเอจิซและเจนกิน"
  },
  Voice_95073_UnlockDesc = {
    Text = "ได้รับผู้ปลุกเสก「ไอจิส」และผู้ปลุกเสก「เจนกิน」หลังจากปลดล็อก"
  },
  Voice_95074_AwakerVoiceContent = {
    Text = "รีบออกไปเถอะ."
  },
  Voice_95074_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_95075_AwakerVoiceContent = {
    Text = "แสงสว่างของผู้ถือแลมป์จะส่องสว่างคืนที่ยาวนาน!"
  },
  Voice_95075_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_95076_AwakerVoiceContent = {
    Text = "อ๊ะ... ฉันได้เห็นแล้ว ความแข็งแกร่งอันมหาศาล ความจริงของโลก... ฉันได้เข้าใจเส้นทางที่ผิดในอดีตแล้ว คุณคือผู้ถือไฟที่แท้จริง! ขออนุญาตให้ฉันเป็นสาวกที่ซื่อสัตย์ของคุณ หัวใจนี้ที่เกิดมาเพื่อผู้ถือไฟ จะกระโดดจังหวะแล้วสั่นสะเทือนภักดีต่อคุณ..."
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_95076_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "การไถ่บาปอย่างบอดของบาทหลวงนั้นถือเป็นการกระทำที่ไม่สามารถยอมรับได้ พระคำสอนของพระเจ้าก็สามารถมอบให้แก่ธรรมิกชนที่เคร่งครัดเท่านั้น หากแม้ผู้ส่งสารของพระเจ้ายังไม่มีตาที่มองเห็นเพื่อที่จะแยกแยะ คนบาปที่ไม่รู้สำนึกจะได้รับรางวัลและทำให้บริสุทธิ์ของพระเจ้าเสียหาย นี่ไม่ใช่การหักหลังพระเจ้าและผู้ที่ทำความดีหรือ?"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "เรื่องทั่วไป：เกี่ยวกับซัลวาดอร์"
  },
  Voice_95077_UnlockDesc = {
    Text = "ปลดล็อคเมื่อได้รับ「เอลซัลวาดอร์」ร่างกายที่ตื่นขึ้น"
  },
  Voice_95078_AwakerVoiceContent = {
    Text = "ฉันมีใจสว่าง!"
  },
  Voice_95078_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_95079_AwakerVoiceContent = {
    Text = "ดื่ม!"
  },
  Voice_95079_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_95080_AwakerVoiceContent = {
    Text = "ตอนเด็ก ๆ ฉันมีแต่ต้องการบินออกจากกรงขัง ตอนนั้นฉันคิดว่าที่นี่คงไม่มีค่าอะไรให้คิดถึงเลย แต่หลังจากผ่านชีวิตไปสองครั้ง ฉันจึงเข้าใจว่าความเป็นอิสระไม่ใช่สิ่งเดียวที่ฉันปรารถนา การได้เห็นผู้ศรัทธาทั้งหลายเมื่อรู้ว่าจะได้รับการช่วยให้รอดนั้น ความรู้สึกที่เต็มไปด้วยความจริงใจ ความหวังและความขอบคุณนั้นแหละที่เป็นความหมายที่แท้จริงของการเป็นพระบุตร"
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "ช่วงเวลาที่อยู่กับจูเลียตนั้น ฉันทำผิดหลายอย่าง ไม่ควรได้รับความไว้วางใจแบบนี้ แต่คุณยังเลือกฉันอยู่...โปรดวางใจ ฉันจะค้นหาศรัทธาของตัวเองอีกครั้ง พระโอรสจะไม่ทำให้ประชาชนผิดหวัง และจะไม่ทำให้ท่านผิดหวัง"
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_95081_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "สิ่งที่ท่านมอบให้ ฉันจะใช้มันด้วยความขอบคุณ."
  },
  Voice_95082_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_95083_AwakerVoiceContent = {
    Text = "ไร้มารยาท!"
  },
  Voice_95083_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_95084_AwakerVoiceContent = {
    Text = "น่ารังเกียจ"
  },
  Voice_95084_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_95085_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_95086_AwakerVoiceContent = {
    Text = "ในนามของฉัน!"
  },
  Voice_95086_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_95087_AwakerVoiceContent = {
    Text = "ฉันเห็นแล้ว! แสงนั้น แสงที่ส่องสว่างอยู่ในจิตสำนึก มันเริ่มสว่างขึ้นเรื่อยๆ! มันกำลังเรียกหาฉัน..."
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_95087_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "ในวัยเด็ก คาสเตอร์และฉันทำหน้าที่เป็นพระเยซูร่วมกัน ตอนนั้นฉันคิดว่าเขาโง่เขลาและทำอะไรไม่ถูก ต้องให้ฉันชี้นำทิศทางในอนาคต เมื่อเข้าใจถึงเส้นทางที่คุณต้องพบเจอ ฉันจึงเข้าใจว่า ฐานของโลกนั้นถูกสร้างและขยายโดยคุณและผู้ที่ซื่อสัตย์เช่นเขา"
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_95088_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "โคมไฟของฉัน ตั้งแต่ได้คำแนะนำจากท่าน ฉันคิดว่าฉันได้เดินมาถึงเส้นทางที่ถูกต้องอย่างสมบูรณ์ จากนี้ไปผู้ติดตามที่โง่เขลาของท่านยังมีข้อสงสัยอยู่ ว่าสุญญากาศบริสุทธิ์นั่น ก็อยู่ภายใต้การควบคุมของท่านไหม? ไม่มีสิ่งนี้เหรอ? หรือท่านเต็มใจจะบอกว่า... สุญญากาศบริสุทธิ์นั้นอยู่ในโลกมนุษย์ อยู่ในใจบริสุทธิ์ของคนดี?"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "หัวใจที่รับฟังสวรรค์นี้，เข้าใกล้คุณมากขึ้นแล้ว"
  },
  Voice_95090_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_95091_AwakerVoiceContent = {
    Text = "ท่าน... ท่านมีคำสั่งที่อยากจะสื่อให้ฉันไหม? ผู้สื่อสารของท่านพร้อมที่จะฟังคำสั่งของท่านเสมอ."
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "จงส่องสว่างให้ฉัน ช่วยนำทางที่เคยหลงทาง! ด้วยแสงของท่าน ฉันได้เห็นทุกสิ่งที่ฉันควรเห็น...ฉันจะใช้ร่างกายที่ถูกสาปนี้ ทำให้ทุกสิ่งในอดีตได้ถูกชำระล้าง และทุกสิ่งในอนาคต ตกอยู่ภายใต้แสงนี้!"
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_95092_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "ร้องอึงอังแสงสว่าง!"
  },
  Voice_95093_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_95391_AwakerVoiceContent = {
    Text = "ในโลกที่โหดร้ายแสวงหาการปกป้องงั้นเหรอ? สู้ต่อไปนะ เจ้าหนูน้อยที่เต็มไปด้วยความหวัง"
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_95391_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = "มาเถอะ เอาเหล่านี้ไปเล่นเถอะ บอกว่าขุดมาจากโบราณสถานเป็นของต้องห้าม ฉันไม่สนใจสิ่งเหล่านี้ที่มีกลิ่นอายของพวกเขา ตั้งใจจะเผาทิ้ง แต่คิดว่ามันอาจจะเป็นประโยชน์กับคุณ ก็เลยนำมามอบให้นะ.\nคุณถามฉันว่ามาได้ยังไง? แน่นอนว่าบางคน 「ยินดี」 ส่งมาให้ฉัน สบายใจเถอะ รับรองว่ามาอย่าง 「สะอาด」"
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_95392_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "การล่าครั้งนี้เสร็จสิ้นแล้ว ให้รางวัลเป็นรอยยิ้มของเด็กน้อยเถอะ"
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = "รู้ไหมเด็กน้อย สองปืนนี้ไม่ได้ยิงกระสุน แต่ยิงความปรารถนาและความมุ่งร้ายออกมา\nความโกลาหลที่ไร้ระเบียบสร้างเป็นเปลวเพลิงที่มีเลือดเนื้อ เมื่อเสียงปืนที่เจ็ดดังขึ้น มันจะดึงทุกสิ่งไปสู่ขุมนรกเพื่อไหม้"
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "เรื่องทั่วไป：เกี่ยวกับปืน"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "ไม่จำเป็นต้องบีบตัวเองมากเกินไป，ผู้พิทักษ์ของฉัน แม้ว่าฉันจะรู้ว่านี่คือเส้นทางที่ต้องรีบเร่ง มีแนวโน้มที่ไม่ระมัดระวังอาจนำไปสู่นรกนิรันดร์ แต่หากยังคงเป็นเช่นนี้ สักวันคุณจะหมดแรงและล้มลง หากคุณมีอะไรจำเป็นต้องพูด ก็มาคุยกับฉันได้ ในฐานะสมาชิกในครอบครัว"
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_95395_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "การเผาไหม้ การทำลาย ให้โศกเศร้าเถอะ!"
  },
  Voice_95396_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_95397_AwakerVoiceContent = {
    Text = "จางหายไปเถอะ"
  },
  Voice_95397_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_95398_AwakerVoiceContent = {
    Text = "มุมมองของข้าชัดเจนยิ่งขึ้น ข้าเห็นสิ่งที่ซ่อนอยู่ในเหวลึก...เพื่อพวกท่าน ข้าจำเป็นต้องมีพลังที่แข็งแกร่งขึ้น..."
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_95398_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "มานั่งที่นี่หน่อย เจ้าผู้พิทักษ์ มันดูห่างเหินไปหน่อย\nรู้ไหม เมื่อครั้งแรกที่เห็นเธอ ฉันไม่เคยคิดเลยว่าสักวันหนึ่ง จะได้ปลดเปลื้องเปลือกที่เรียกว่าโหดร้ายและเยือกเย็น ที่นี่ถึงของเธอแบบนี้\nต้องตลกจริงไหม ตัวตนก็เหมือนเจ้าผู้เผาไหม้จะต้องการบางสิ่งที่เป็นจริงที่จะสามารถเล่าอย่างจริงใจ\nสัญญากับฉันเถอะ หากวันนั้นคุณทนไม่ไหว... เพียงเรียกชื่อของฉันในใจ ฉันจะพาท่านไปยังอาณาจักรของฉัน แม้ว่ามันจะเป็นเพียงการเลื่อนเวลาออกไป แต่ในเวลาสุดท้าย คุณสามารถพักผ่อนในอ้อมแขนของฉันได้ดี"
  },
  Voice_95399_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_95399_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_95400_AwakerVoiceContent = {
    Text = "ต้อนรับจุดจบเถอะ"
  },
  Voice_95400_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_95401_AwakerVoiceContent = {Text = "อึก!"},
  Voice_95401_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_95402_AwakerVoiceContent = {
    Text = "ในล้านความปรารถนาและความชั่วร้าย เอาไฟไปเผา!"
  },
  Voice_95402_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_95403_AwakerVoiceContent = {
    Text = "การล่าสัตว์ที่สำเร็จมักจะต้องมีงานเลี้ยงฉลอง มาร่วมกันเถอะ มาลองเนื้ออูฐที่ฉันทำและเตกีลาที่เพิ่งได้มา รอแป๊บหนึ่ง เจ้าตัวเล็กดูเหมือนจะดื่มไม่ได้... งั้นมาลองน้ำผลไม้ที่ฉันทำเป็นพิเศษกันดีกว่า~"
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_95403_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "เกิดอะไรขึ้นน่ะ เจ้าตัวเล็ก? อยากได้การกอดไหม? มานี่เลย ฉันจะแผ่ความรักของฉันให้ตลอดเวลา... ฮ่าๆ อย่าอายเลยนะ การที่พี่สาวเป็นห่วงน้องน่ะ มันเป็นเรื่องปกติใช่ไหม?"
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_95406_AwakerVoiceContent = {
    Text = "ให้ตายสิ"
  },
  Voice_95406_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_95407_AwakerVoiceContent = {
    Text = "ต้อนรับความตายสีAmberเถอะ"
  },
  Voice_95407_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_95408_AwakerVoiceContent = {
    Text = "ถอยกลับไปก่อน ฉันจะเป็นแนวหลัง... สบายใจได้ ฉันจะกลับมามีชีวิตอยู่"
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "มาเถอะ ให้เราจัดการทุกอย่างให้กลายเป็นเถ้าถ่าน!"
  },
  Voice_95409_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_95410_AwakerVoiceContent = {
    Text = "ไฟที่ลุกไหม้จงลุกโชนอีกครั้งที่นี่เถอะ!"
  },
  Voice_95410_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_95411_AwakerVoiceContent = {
    Text = "ไฟกลายเป็นสว่างขึ้นอีกครั้ง เจ้าตัวน้อยต้องการดูดอกไม้ไฟที่ยิ่งใหญ่ไหม?"
  },
  Voice_95411_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_95412_AwakerVoiceContent = {
    Text = "พวกที่เหยียบย่ำมนุษยชาติ ซ่อนในเงา ใช้@1เป็นวัสดุสำหรับการบูชายัญและการวิจัยที่สกปรกของพวกเขา... วันไหนฉันจะจัดการพวกเขาให้หมด."
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_95413_AwakerVoiceContent = {Text = "ปัง!"},
  Voice_95413_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_95414_AwakerVoiceContent = {
    Text = "ฉันจะหาตัวเขา ไม่ว่าเขาจะซ่อนตัวอยู่ที่มุมไหนของจักรวาล ฉันจะหาตัวเขาได้ในที่สุด.\nฉันจะให้หนูสกปรกนี้ชดใช้ทุกอย่าง เมื่อฉันพบตัวเขา ทุกความสุขและความโหดร้ายในโลกจะถูกเผาในนรก.\nไม่ต้องกังวล ในงานศพของเขา ฉันจะให้ที่นั่งพิเศษสำหรับคุณ เพื่อที่เราจะได้ลิ้มรสเสียงร้องสุดท้ายของเขา"
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "เรื่องทั่วไป：เกี่ยวกับ N"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "ฟังสิ เสียงร้องของดาวที่กำลังละลาย"
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_95415_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_95416_AwakerVoiceContent = {
    Text = "ต้อนรับจุดจบเถอะ"
  },
  Voice_95416_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_95417_AwakerVoiceContent = {
    Text = "คุณคือครอบครัวที่ฉันภูมิใจ มากมั่นใจขึ้นเถอะ ผู้พิทักษ์ของฉัน! ไม่ว่าอะไรจะเกิดขึ้น ฉันจะเป็นกำลังใจที่แข็งแกร่งที่สุดของคุณ"
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "สิ่งมีชีวิตที่อธิบายไม่ได้กำลังกัดกร่อนโลกนี้ คุณจะหลีกเลี่ยงการเป็นศัตรูกับมันไม่ได้ แต่ไม่เป็นไร เพราะฉันจะอยู่ข้างหลังคุณ."
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_95418_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "การเผาไหม้ การทำลาย ให้โศกเศร้าเถอะ!"
  },
  Voice_95420_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_95421_AwakerVoiceContent = {
    Text = "รักษาความสงบเอาไว้"
  },
  Voice_95421_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_95422_AwakerVoiceContent = {
    Text = "ถอยหลัง"
  },
  Voice_95422_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_95423_AwakerVoiceContent = {
    Text = "คุณถามฉันว่าเห็นการย่อยสลายยังไง? นี่ก็คือการถามหนูตัวเล็กที่เดินเล่นอยู่ในท่อมืดว่ามองเห็นนายทงสูงได้อย่างไร คำตอบของฉันมีเพียงหนึ่งเดียว: ความเกลียดชังที่มาจากสัญชาติญาณในร่างกาย ถ้าเป็นไปได้ ฉันจะนั่งจิบเครื่องดื่มนมอูฐที่อร่อยขณะชมเสียงกรีดร้องของพวกมันที่กำลังตายอยู่ใต้ปืนของฉัน"
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "อยากให้เปลวไฟรุนแรงขึ้นไหม?"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_95424_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "ฉันจะมาที่นี่เฉพาะเมื่อได้รับการมอบหมายเท่านั้น หากเจ้าต้องการหาฉัน ใช้เวทมนตร์นี้มานะ มา อ่านตามฉัน:......... Ia! KathiguRa!"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "เมื่อครั้งที่ผ่านมาเรายังอยู่ในเมืองเก่าแก่ที่ร้าวราน,      ดิ้นรนโดยพฤติกรรมโหดร้ายและเจ้าเล่ห์ แม้จะกลายเป็นที่กล่าวขวัญในกลุ่มคนมีอำนาจ แต่เมื่อเผชิญกับนายใหญ่,      ทีมรักษาความปลอดภัยและ \"ท่านอัศวิน\"ที่ไม่ต้องการถอนตัวจากเวที ประวัติศาสตร์ เราต้องมีสติพร้อมที่สุด แต่ตอนนี้ต่างออกไป ทุกคนกลายเป็น \"ครอบครัว\"ของฉัน ไม่ต้องมองหน้าคนอื่นอีกแล้ว. แบบว่า,      ยังมีเด็กน้อยคนหนึ่งที่ถูกทิ้งขว้าง แต่ฉันเชื่อว่าเขาจะปลอดภัย,      เพราะทุกครั้งที่ฉันยุ่งอยู่ข้างนอก,      เขาคือคนที่ดูแลคนอื่น."
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "เรื่องทั่วไป：เกี่ยวกับครอบครัว"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "นี่คือศัตรูของตัวน้อย? ถ้างั้น—งานล่าเริ่มขึ้น"
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "ข้า คือ เจ้าแห่งการเผาไหม้ที่ไม่มีวันลืม! ประกาศ! ทุกสิ่งจะดับสูญ!"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = "การเผาไหม้และการทำลายคือทุกสิ่ง ฉันหลงใหลในความตายที่การล่ามาพร้อมกับ... คุณคิดว่าฉันจะพูดแบบนี้เหรอ? \nฮ่าฮ่า เวลาพูดเล่น สำหรับฉันแล้ว สิ่งที่สำคัญที่สุดก็คือทุกคนที่อยู่ข้างๆ ไม่มีอะไรสำคัญกว่าทุกคน แม้กระทั่ง... ตัวฉันเองก็เช่นกัน."
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "เจ้าตัวน้อยมีปัญหาหรอ? ถ้าอย่างนั้นตามเสียงอัญเชิญ เคทีคูล่าจะมาพร้อมกับการทำลายล้าง ให้ปัญหาทั้งหมด—“กระแทก” หายไปในอากาศ"
  },
  Voice_95430_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_95431_AwakerVoiceContent = {
    Text = "รสชาติของพลัง ต้องลองหาคนโชคร้ายสักคนมาทดสอบดูไหม?"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_95431_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "ข้า คือ เจ้าแห่งการเผาไหม้ที่ไม่มีวันลืม! ประกาศ! ทุกสิ่งจะดับสูญ!"
  },
  Voice_95432_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_95433_AwakerVoiceContent = {
    Text = "ราชินีอารัน ผู้ยิ่งใหญ่ผู้เป็นสาระด้านความปรารถนา เทฟเรเยโซเด ฉันเคยพบเธอครั้งหนึ่งเมื่อไล่ล่าN ถึงแม้ว่าฉันจะไม่เห็นด้วยกับสิ่งที่เธอทำ แต่ถ้าจะว่ากันตามตรง ถ้านั่นคือวิธีเดียวที่สามารถทำให้ทุกคนรอดพ้นจากการจ้องมองของ「พระองค์」...ฉันก็จะเลือกทำเช่นเดียวกัน จากมุมมองนี้ ฉันและเธอไม่ได้แตกต่างกันเลย"
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "เรื่องทั่วไป：เกี่ยวกับคนไทย"
  },
  Voice_95433_UnlockDesc = {
    Text = "ปลดล็อคหลังจากได้รับร่างกายที่ตื่นขึ้น「ไทอีส」"
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "สัมผัสยอดเยี่ยมเลย อาวุธมีการดูแลที่ดีนะ."
  },
  Voice_95434_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_95435_AwakerVoiceContent = {
    Text = "ข้าก็คือไฟ,      เปลวไฟ,      ความโกลาหลที่ไม่หยุดนิ่ง...ข้าจะพาทุกคนไป...กลับบ้าน..."
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_95435_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "หอระฆังแนวโกธิกที่นี่ให้กลิ่นอายแบบคลาสสิก และผู้ปลุกเสกที่นี่มีรสชาติที่ฉันไม่เคยได้ลิ้มรส มีทั้งกลิ่นหอมของผู้ตายและมีกลิ่นของชีวิตที่รื่นเริงจริง ๆ... ทำให้ฉันอยากลองสักหน่อย."
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "เรื่องราวทั่วไป·เกี่ยวกับมิซากะ"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "คนที่แสวงหาความตาย ฉันจะทำให้ความปรารถนาของคุณเป็นจริง"
  },
  Voice_96362_AwakerVoiceTitle = {
    Text = "คลั่งไคล้ถึงขีดสุด·2"
  },
  Voice_96363_AwakerVoiceContent = {
    Text = "ฉันเริ่มจะอดใจรอไม่ไหวที่จะเริ่มแล้ว."
  },
  Voice_96363_AwakerVoiceTitle = {
    Text = "วิญญาณตื่นรู้"
  },
  Voice_96364_AwakerVoiceContent = {
    Text = "รู้สึกใจเต้นใช่ไหม? มาเถอะ แขกที่รักของฉัน มาเป็นแขกของฉัน มาสนุกกับงานเลี้ยงนี้กันเถอะ ให้ฉันพาคุณไปชิมรสชาติที่ละเอียดอ่อนจากวิญญาณแต่ละดวง."
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·บานออก"
  },
  Voice_96364_UnlockDesc = {
    Text = "การตื่นพลังระดับ 15 จะปลดล็อก"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "ชู่ว นะอย่าพูด ให้เรานั่งเงียบๆ และฟังเสียงของบรรพบุรุษกันเถอะ"
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·หนึ่ง"
  },
  Voice_96365_UnlockDesc = {
    Text = "ปลดล็อกเมื่ออัตราการประสานถึงระดับ 2"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "ความงามนิรันดร์คือศรัทธาของเรา การบรรเทาอันช้าๆที่ถูกใช้ที่ตัวผู้มีชีวิตเป็นการลบล้างร่องรอยทั้งหมดของการดำรงอยู่...ซึ่งไม่เพียงพอสำหรับชีวิต มันเป็นความทรมานที่บริสุทธิ์และโหดร้าย."
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "เรื่อง·เกี่ยวกับวิกฤติ"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "และฉันก็ตามที่ว่าผู้ได้รับศิลปะอมตะอย่างฮอรลา เราควรจะเป็นเพื่อนที่ดีกว่านี้ แต่เขากลับมองว่าการบริโภคเป็นการทำลายอมตะ แนวคิดศิลปะนี้ช่างแคบเหลือเกิน"
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "เรื่องราวเกี่ยวกับผิวหนัง"
  },
  Voice_96367_UnlockDesc = {
    Text = "ปลดล็อคเมื่อได้รับร่างกายที่ปลุก「พิกมัน」"
  },
  Voice_96368_AwakerVoiceContent = {Text = "ฮา!"},
  Voice_96368_AwakerVoiceTitle = {
    Text = "โจมตี·1"
  },
  Voice_96369_AwakerVoiceContent = {
    Text = "คำบรรยายใด ๆ ก็ยากที่จะอธิบายถึงกลิ่นที่ดึงดูดใจที่อยู่บนตัวคุณ ได้ทั้งเปรี้ยวและรสอันอุดมสมบูรณ์เหมือนไวน์บอร์โดซ์ และเข้มข้นเหมือนฟองน้ำครีม อา...อาจกลายเป็นวันนั้นที่คุณเสียชีวิตจะเป็นเรื่องที่สำคัญที่สุดในชีวิตของฉัน"
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "เรื่องราว · เกี่ยวกับผู้พิทักษ์"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "ฉันเคยเห็นที่เกิดเหตุอาชญากรรม ผู้ชายคนหนึ่งกำลังเฉือนผิวหนังของเด็กสาวทีละน้อย มือและเท้าของเธอ ขณะเดียวกันก็กำลังรักษาเธอ เขาไม่ต้องการให้เธอตาย และแน่นอนว่าไม่อยากให้เธอมีชีวิตอยู่ ฉันแน่นอนว่าไม่สามารถให้ความตายที่สงบสุขแก่เขาได้ ฉันทำให้เขาได้สัมผัสประสบการณ์ที่เหมือนกับเด็กสาวนั้น เค้าคิดว่ามันก็น่าจะมีหลายปีแล้ว... สำหรับคนที่ดูหมิ่นความตายนี่เป็นเรื่องที่ยุติธรรมใช่ไหม?"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ไม่ชอบ"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "ฉันคือพระเจ้าแห่งความตาย แต่กรุณาอย่าเข้าใจผิด ฉันไม่สร้างความตาย ฉันเพียงติดตามรอยเท้าของความตายและเก็บเกี่ยวผลไม้ที่สุกงอม."
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การมองไกล"
  },
  Voice_96371_UnlockDesc = {
    Text = "ปลดล็อกเมื่อถึงระดับการตื่นพลัง 1"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "คุณก็รู้สึกกระหายในรสชาติของฉันหรือเปล่า ท่านผู้พิทักษ์?"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "เรื่องราว·สัมผัส"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "วันนี้ควรส่งใครขึ้นโต๊ะอาหารดี?"
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "การสอบสวนเริ่มต้นขึ้น"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "ฉันจะอวยพรให้ท่านได้รับเกียรติในงานเลี้ยงมื้อค่ำในวันนี้."
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "สอบสวนสำเร็จ"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "มันไม่สง่างามเลย"
  },
  Voice_96375_AwakerVoiceTitle = {
    Text = "การโจมตี·3"
  },
  Voice_96376_AwakerVoiceContent = {
    Text = "ฉันจะมอบความสงบสุขที่บริสุทธิ์แก่คุณ."
  },
  Voice_96376_AwakerVoiceTitle = {
    Text = "ทักษะ·ขั้นแรก"
  },
  Voice_96377_AwakerVoiceContent = {
    Text = "ทุกครั้งก่อนการบริโภค ฉันจะสนทนากับวิญญาณ สำหรับพวกเขา การถูกบริโภคอย่างจริงจัง เป็นการยืดอายุและเป็นความรุ่งเรืองในที่สุด เหมือนที่เราอยากได้พวกเขา พวกเขาก็ต้องการเราเช่นกัน"
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·3"
  },
  Voice_96377_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับการประสานถึง 6"
  },
  Voice_96378_AwakerVoiceContent = {
    Text = "เงียบหน่อย"
  },
  Voice_96378_AwakerVoiceTitle = {
    Text = "การโจมตี·4"
  },
  Voice_96379_AwakerVoiceContent = {
    Text = "จงสลายตัวไปในเงาเถอะ!"
  },
  Voice_96379_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_96380_AwakerVoiceContent = {
    Text = "เราควรรักษาระยะห่างไว้จะดีกว่า."
  },
  Voice_96380_AwakerVoiceTitle = {
    Text = "การป้องกัน·แรก"
  },
  Voice_96381_AwakerVoiceContent = {
    Text = "จงสลายตัวไปในเงาเถอะ!"
  },
  Voice_96381_AwakerVoiceTitle = {
    Text = "ทักษะ·4"
  },
  Voice_96382_AwakerVoiceContent = {
    Text = "ทำไมถึงระวังฉันขนาดนี้?คุณไม่ควรและไม่จำเป็นต้องตกใจ การกัดกินคนเป็นสิ่งที่ตรงกันข้ามกับความสุนทรีย์ของฉัน."
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "เรื่องราวเกี่ยวกับอาหาร"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "คนที่แสวงหาความตาย ฉันจะทำให้ความปรารถนาของคุณเป็นจริง"
  },
  Voice_96383_AwakerVoiceTitle = {
    Text = "ระเบิดพลัง"
  },
  Voice_96384_AwakerVoiceContent = {
    Text = "มันไม่สง่างามเลย"
  },
  Voice_96384_AwakerVoiceTitle = {
    Text = "การโจมตี·1"
  },
  Voice_96385_AwakerVoiceContent = {
    Text = "ระวังหน่อยนะ."
  },
  Voice_96385_AwakerVoiceTitle = {
    Text = "การป้องกัน·2"
  },
  Voice_96386_AwakerVoiceContent = {
    Text = "ความมุ่งมั่นของคุณสาวน้อยนั้นน่าขนลุกอย่างยิ่ง แต่กลิ่นของเธอกลับมีความชื้นที่ดูเหมือนออกมาจากการหมักจนเกินไป แม้ว่าเธอจะขอให้ฉันลองสักครั้ง แต่ก็นับว่าไม่ใช่รสนิยมที่ฉันชอบจริงๆ"
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "เรื่องราว เกี่ยวกับเรย่า"
  },
  Voice_96386_UnlockDesc = {
    Text = "ปลดล็อกเมื่อได้รับร่างกายที่ตื่นขึ้น「เรย่า」"
  },
  Voice_96387_AwakerVoiceContent = {
    Text = "คุณรู้ไหม? ชีวิตแต่ละชีวิตที่จางหายไปมีเสียงสะท้อนที่ยาวนาน มันมีความสูงต่ำแตกต่างกัน จะยืดออกทีละน้อยตั้งแต่ช่วงเวลาแห่งความตาย จนกระทั่งค่อยๆ จางหายตรงระหว่างฟ้ากับดิน เหมือนเสียงร้องที่ถอนหายใจ"
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·2"
  },
  Voice_96387_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเท่ากับ 4"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "โปรดไว้วางใจนะ ผู้พิทักษ์ ฉันจะอยู่เคียงข้างคุณตลอดไป จนกว่าชีวิตของคุณจะมาถึงวันที่ไม่สามารถหลีกเลี่ยงการสูญเสีย ฉันจะใช้พิธีกรรมที่ยิ่งใหญ่ที่สุดในการกลืนร่างกายของคุณอย่างครบถ้วน ฉันจะเก็บวิญญาณของคุณไว้ในร่างกายตลอดไป"
  },
  Voice_96388_AwakerVoiceTitle = {
    Text = "อัตราการประสาน·5"
  },
  Voice_96388_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสานเป็นระดับ 10"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "คุณไม่ได้กลิ่นของตัวเองเหรอ? น่าเสียดายจริง ๆ ที่คุณพลาดโอกาสในการสัมผัสความหวานหวานที่สุดในโลกนี้ และ...อ๊ะ ทำไมต้องหลบหลีกด้วยล่ะ?"
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "อัตราการประสาน สี่"
  },
  Voice_96389_UnlockDesc = {
    Text = "ปลดล็อกเมื่อระดับอัตราการประสาน 8"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "ฉันสามารถเห็นความตายมากขึ้น ภาพที่อยู่ฝั่งตรงข้ามนั้นชัดเจนขึ้นเรื่อย ๆ......"
  },
  Voice_96390_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·สาม"
  },
  Voice_96391_AwakerVoiceContent = {
    Text = "เชิญฝากร่างกายไว้กับฉันเถอะ ให้ฉันได้ลิ้มรสร่างกายของคุณ ทุกหยดเลือด ทุกชิ้นส่วนของเนื้อ ทุกชิ้นส่วนกระดูก."
  },
  Voice_96391_AwakerVoiceTitle = {
    Text = "เกินขีดจำกัดคลั่งไคล้ถึงขีดสุด"
  },
  Voice_96392_AwakerVoiceContent = {
    Text = "วัตถุดิบต่าง ๆ จะต้องผ่านการจัดการที่แตกต่างกัน อวัยวะภายในจะต้องทำการดอง เอ็นบริเวณขาจะต้องเคี่ยวให้สุก ส่วนที่มีไขมันเหมาะสำหรับการหมักให้สุก ส่วนที่มีรสสัมผัสพิเศษสามารถทอดหรือย่างได้ หรือแม้แต่ทำเป็นเยลลี่เนื้อรูปทรงสวยงาม ซึ่งทั้งหมดนี้จำเป็นต้องมีการเลือกสรรที่พิถีพิถัน แน่นอนว่าการรักษาและเน้นรสชาติดั้งเดิมของวัตถุดิบเป็นสิ่งที่ต้องเคารพ."
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การหยั่งรู้"
  },
  Voice_96392_UnlockDesc = {
    Text = "ปลดล็อกเมื่อตื่นพลังระดับ 7"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "อาจจะมีหนาวสักหน่อย"
  },
  Voice_96393_AwakerVoiceTitle = {
    Text = "การโจมตี·ครั้งที่สอง"
  },
  Voice_96394_AwakerVoiceContent = {
    Text = "การจับคู่ของจานอาหารมีความสำคัญมาก การเปรี้ยวกับหวาน กรอบกับนุ่ม สดชื่นกับหนัก แน่นอนกับหยาบ ช่วงชั้นของรสชาติและเนื้อสัมผัสที่ตรงกันข้ามรวมกันเข้าเมื่อเข้าปาก เคี้ยว ลิ้มรสก็ให้ความรู้สึกที่แตกต่างกัน นี่แหละคือความสุขที่ไม่มีที่สิ้นสุดและมหัศจรรย์ที่อาหารคุณภาพดีสามารถมอบให้มนุษย์"
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การสร้าง"
  },
  Voice_96394_UnlockDesc = {
    Text = "ปลดล็อคเมื่อการตื่นพลังถึงระดับ 11"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "ขอบคุณมากสำหรับความกระตือรือร้นของคุณ ฉันรู้สึกเป็นเกียรติ"
  },
  Voice_96395_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·2"
  },
  Voice_96396_AwakerVoiceContent = {
    Text = "อาหารอร่อยมักจะคุ้มค่ากับการรอคอยที่นานขึ้น"
  },
  Voice_96396_AwakerVoiceTitle = {
    Text = "สอบสวนถูกยุติ"
  },
  Voice_96397_AwakerVoiceContent = {
    Text = "แน่นอนว่าฉันไม่ใช่สัตว์ประหลาดที่กินดิบดื่มเลือด การเพลิดเพลินกับความตายคือความเป็นระเบียบและงดงาม คุณต้องสื่อสารและเข้าใจรสชาติที่เป็นเอกลักษณ์ของแต่ละวัตถุดิบอย่างเต็มใจ."
  },
  Voice_96397_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การเพ่งมอง"
  },
  Voice_96397_UnlockDesc = {
    Text = "เมื่อถึงระดับการตื่นพลัง 2 จะปลดล็อก"
  },
  Voice_96398_AwakerVoiceContent = {
    Text = "ผู้ที่หลับไปอย่างสงบสุขนั้นสวยงามและมีกลิ่นหอม ไม่ใช่เพราะร่างกายของพวกเขาจะมีความแตกต่างระหว่างชีวิตกับความตาย แต่เป็นที่วิญญาณของพวกเขา — วิญญาณที่เข้าใจความตาย ความรักชีวิต ความปรารถนาที่จะถูกจดจำ นั่นล่ะคือของกำนัลที่ฉันใฝ่ฝัน."
  },
  Voice_96398_AwakerVoiceTitle = {
    Text = "เรื่องราว·สิ่งที่ชอบ"
  },
  Voice_96399_AwakerVoiceContent = {
    Text = "น้ำหอมใด ๆ ก็ไม่อาจเทียบเท่ากับกลิ่นธรรมชาติของมนุษย์ การรับรู้กลิ่นเป็นการติดต่อที่ดีที่สุดที่เกิดขึ้น"
  },
  Voice_96399_AwakerVoiceTitle = {
    Text = "การตื่นพลัง·การครุ่นคิด"
  },
  Voice_96399_UnlockDesc = {
    Text = "ปลดล็อคเมื่อถึงเลเวล 3"
  },
  Voice_96400_AwakerVoiceContent = {
    Text = "อาห์ กลิ่นหอมแสนตราตรึงใจ... ฉันแทบรอไม่ไหวที่จะต้อนรับเธอสู่วิหารของฉันแล้ว"
  },
  Voice_96400_AwakerVoiceTitle = {
    Text = "ปลุกตื่น"
  },
  Voice_96401_AwakerVoiceContent = {
    Text = "เชิญฝากร่างกายไว้กับฉันเถอะ ให้ฉันได้ลิ้มรสร่างกายของคุณ ทุกหยดเลือด ทุกชิ้นส่วนของเนื้อ ทุกชิ้นส่วนกระดูก."
  },
  Voice_96401_AwakerVoiceTitle = {
    Text = "ความคลั่งถึงขีดสุด·สอง"
  },
  Voice_96402_AwakerVoiceContent = {
    Text = "ฉันจะมอบความสงบสุขที่บริสุทธิ์แก่คุณ."
  },
  Voice_96402_AwakerVoiceTitle = {
    Text = "ทักษะ·2"
  },
  Voice_96403_AwakerVoiceContent = {
    Text = "เงียบหน่อย"
  },
  Voice_96403_AwakerVoiceTitle = {
    Text = "การโจมตี·2"
  },
  Voice_96404_AwakerVoiceContent = {
    Text = "กลิ่นหอมของคุณช่างทำให้เคลิบเคลิ้ม"
  },
  Voice_96404_AwakerVoiceTitle = {
    Text = "ได้รับการยกระดับ·1"
  },
  Voice_98324_AwakerVoiceContent = {
    Text = "ในล้านความปรารถนาและความชั่วร้าย เอาไฟไปเผา!"
  },
  Voice_98324_AwakerVoiceTitle = {
    Text = "ทักษะพิเศษ·ลำดับแรก"
  }
})
